// Verifier probe (closing round 2), scratch only: Lean jobs cancelled just as they start must never leave a telelean-*
// unit (active, failed or otherwise) or a process behind. Three levels:
//   1 runLean: AbortSignal 0..40 ms after the call (3 passes), cancelRun 0..30 ms after, timeouts of 1..30 ms;
//   2 a real board refresh (refreshLeanFacts on a copy of mental_model, .lake removed first so Lake really builds),
//     aborted 0..60 ms after the call;
//   3 a RunManager run (FakeBackend) cancelled 0..320 ms after start() was called (its base check is a Lean job).
import { execFileSync } from 'node:child_process';
import { cpSync, rmSync, writeFileSync } from 'node:fs';
import path from 'node:path';

import { cancelRun, checkSandboxSupport, runLean } from '/tmp/claude-1002/-home-zhengyew-telelean/03a29d54-7342-40e3-b5f0-2697a62c93ef/scratchpad/turn9/closing-verify-2/repo/packages/runner/src/lean/runLean.ts';
import { createShadow } from '/tmp/claude-1002/-home-zhengyew-telelean/03a29d54-7342-40e3-b5f0-2697a62c93ef/scratchpad/turn9/closing-verify-2/repo/packages/runner/src/lean/shadow.ts';
import { refreshLeanFacts } from '/tmp/claude-1002/-home-zhengyew-telelean/03a29d54-7342-40e3-b5f0-2697a62c93ef/scratchpad/turn9/closing-verify-2/repo/packages/runner/src/semantic/index.ts';
import { makeTempDir, MENTAL_MODEL } from '/tmp/claude-1002/-home-zhengyew-telelean/03a29d54-7342-40e3-b5f0-2697a62c93ef/scratchpad/turn9/closing-verify-2/repo/packages/runner/test/run/helpers/env.ts';
import { result, setup } from './common.ts';

const OUT = '/tmp/claude-1002/-home-zhengyew-telelean/03a29d54-7342-40e3-b5f0-2697a62c93ef/scratchpad/turn9/closing-verify-2/probes/out';
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const units = (pattern: string): string[] =>
  execFileSync('systemctl', ['--user', 'list-units', '--all', '--plain', '--no-legend', '--no-pager', pattern], { encoding: 'utf8' })
    .split('\n')
    .map((l) => l.trim())
    .filter((l) => l !== '');
const failedUnits = (): string => execFileSync('systemctl', ['--user', '--failed', '--plain', '--no-legend', '--no-pager'], { encoding: 'utf8' }).trim();
const procs = (re: string): string[] =>
  execFileSync('bash', ['-c', `pgrep -af '${re}' | grep -v pgrep || true`], { encoding: 'utf8' })
    .split('\n')
    .filter((l) => l.trim() !== '');
/** Stops and resets every listed unit (so the probe never leaves anything behind, whatever it found). */
const clean = (lines: string[]) => {
  for (const line of lines) {
    const unit = line.split(/\s+/)[0] ?? '';
    if (unit === '') continue;
    try {
      execFileSync('systemctl', ['--user', 'stop', unit], { encoding: 'utf8' });
    } catch {
      /* gone */
    }
    try {
      execFileSync('systemctl', ['--user', 'reset-failed', unit], { encoding: 'utf8' });
