it('CANCEL-AT-START-2: no telelean-* unit or process is left at any level, whatever the moment of the cancel', async () => {
  const dir = makeTempDir('probe-cancelstart2');
  expect(await checkSandboxSupport()).toBeUndefined();
  const before = units('telelean-*');
  const failedBefore = failedUnits();
  const report: Record<string, unknown> = { unitsBefore: before, failedBefore };
  const statuses: Record<string, number> = {};
  const count = (s: string) => (statuses[s] = (statuses[s] ?? 0) + 1);

  // ---- 1. runLean
  const shadow = await createShadow(MENTAL_MODEL, path.join(dir, 'shadow'), { copyBuild: false });
  const runId = `vcz${process.pid}`;
  const marker = `${31 + (process.pid % 89)}.47`;
  const rows1: Array<Record<string, unknown>> = [];
  for (let pass = 0; pass < 3; pass++) {
    for (let d = 0; d <= 40; d++) {
      const c = new AbortController();
      const job = runLean({ shadowDir: shadow.dir, argv: ['sleep', marker], runId, signal: c.signal });
      setTimeout(() => c.abort(), d);
      const r = await job;
      count(`runLean-abort:${r.status}`);
      rows1.push({ kind: 'abort', d, status: r.status, ms: r.durationMs, unit: r.unit });
    }
  }
  for (let d = 0; d <= 30; d++) {
    const id = `${runId}c${d}`;
    const job = runLean({ shadowDir: shadow.dir, argv: ['sleep', marker], runId: id });
    if (d > 0) await sleep(d);
    await cancelRun(id);
    const r = await job;
    count(`runLean-cancelRun:${r.status}`);
    rows1.push({ kind: 'cancelRun', d, status: r.status, ms: r.durationMs, unit: r.unit });
  }
  for (let t = 1; t <= 30; t++) {
    const r = await runLean({ shadowDir: shadow.dir, argv: ['sleep', marker], runId, timeoutMs: t });
    count(`runLean-timeout:${r.status}`);
    rows1.push({ kind: 'timeout', t, status: r.status, ms: r.durationMs, unit: r.unit });
  }
  await sleep(1500);
  const left1 = units(`telelean-${runId}*`);
  const strays1 = procs(`sleep ${marker.replace('.', '\\.')}`);
  clean(left1);
  report['level1'] = { jobs: rows1.length, left: left1, strays: strays1, rows: rows1 };

  // ---- 2. real board refreshes aborted right after their start
  const root = path.join(dir, 'model');
  cpSync(MENTAL_MODEL, root, { recursive: true, filter: (src) => !src.includes(`${path.sep}.lake`) && !src.endsWith(`${path.sep}.git`) });
  const refreshId = `vcr${process.pid}`;
  const rows2: Array<Record<string, unknown>> = [];
  for (let d = 0; d <= 60; d += 2) {
    rmSync(path.join(root, '.lake'), { recursive: true, force: true });
    const c = new AbortController();
    const t0 = Date.now();
    let phase = 'none';
    const job = refreshLeanFacts({ root, runId: refreshId, signal: c.signal, onPhase: (p) => (phase = p) });
    setTimeout(() => c.abort(), d);
    const facts = await job;
    count(`refresh-abort:${facts.status}`);
    rows2.push({ d, status: facts.status, phase, ms: Date.now() - t0 });
  }
  // and one refresh left alone, to show the copy really builds
  rmSync(path.join(root, '.lake'), { recursive: true, force: true });
  const full = await refreshLeanFacts({ root, runId: refreshId });
  await sleep(1500);
  const left2 = units(`telelean-${refreshId}*`);
  clean(left2);
  report['level2'] = { jobs: rows2.length, uncancelledRefresh: full.status, left: left2, rows: rows2 };

  // ---- 3. RunManager runs cancelled during their start
  const rows3: Array<Record<string, unknown>> = [];
  const runIds: string[] = [];
  for (const d of [0, 2, 5, 10, 20, 40, 80, 160, 320]) {
    const p = await setup(`cancel${d}`, [{ match: 'Run: "These suffice"', steps: [result()] }, { steps: [result()] }]);
    const t0 = Date.now();
    const starting = p.manager.start({ subject: 'Spyro', target: 'cynder-not-good', premises: ['cynder-dark-past', 'new-spyro-pg', 'pg-no-dark-past'] });
    let id: string | undefined;
    while (id === undefined && Date.now() - t0 < 30_000) {
      id = p.manager.current()?.runId;
      if (id === undefined) await sleep(1);
    }
    if (d > 0) await sleep(d);
    const stateAtCancel = p.manager.current()?.state;
    const cancelled = id !== undefined ? await p.manager.cancel(id) : { ok: false, error: 'no run id' };
    const started = await starting;
    await sleep(300);
    const end = p.manager.current();
    if (id !== undefined) runIds.push(id);
    rows3.push({ d, runId: id, stateAtCancel, cancelled, started, endState: end?.state, ms: Date.now() - t0 });
    await p.manager.dispose();
  }
  await sleep(2500);
  const left3 = runIds.flatMap((id) => units(`telelean-${id}*`));
  clean(left3);
  report['level3'] = { runs: rows3.length, left: left3, rows: rows3 };

  const allAfter = units('telelean-*');
  const failedAfter = failedUnits();
  report['statuses'] = statuses;
  report['allTeleleanUnitsAfter'] = allAfter;
  report['failedAfter'] = failedAfter;
  clean(allAfter.filter((l) => !before.includes(l)));
  writeFileSync(path.join(OUT, 'cancelstart2-result.json'), `${JSON.stringify(report, null, 2)}\n`);
  console.log(`[cancelstart2] statuses ${JSON.stringify(statuses)} left1 ${JSON.stringify(left1)} strays1 ${strays1.length} left2 ${JSON.stringify(left2)} left3 ${JSON.stringify(left3)} allAfter ${JSON.stringify(allAfter)} failedAfter ${JSON.stringify(failedAfter)}`);
  expect(left1).toEqual([]);
  expect(strays1).toEqual([]);
  expect(left2).toEqual([]);
  expect(left3).toEqual([]);
  expect(allAfter.filter((l) => !before.includes(l))).toEqual([]);
  expect(failedAfter).toBe(failedBefore);
});

