// Lake's repair of a used seed that is not one complete build: build the mirror (the run's own sources), then the
// outputs must equal a clean build of those sources, and `lake build --no-build` must find nothing to do.
const repairs: Array<Record<string, unknown>> = [];
const repair = (label: string, s: Awaited<ReturnType<typeof start>>) => {
  const ref = s.sources === 'AA' ? refA : s.sources === 'BB' ? refB : undefined;
  const out = lakeBuild(s.mirror);
  const built = out.split('\n').filter((l) => /Built|Replayed|error/u.test(l)).map((l) => l.replace(/^.*?(Built|Replayed|error)/u, '$1').slice(0, 80));
  const after = moduleSig(path.join(s.mirror, '.lake', 'build'));
  const mismatches = ref === undefined ? ['no reference for sources ' + s.sources] : Object.keys(ref).filter((k) => !k.endsWith('.trace') && after[k] !== ref[k]);
  let noBuild = 'ok';
  try {
    execFileSync(`${TOOLCHAIN_BIN}/lake`, ['build', '--no-build'], { cwd: s.mirror, env: LAKE_ENV, encoding: 'utf8', timeout: 120_000 });
  } catch (e) {
    noBuild = `FAILED ${(e as Error).message.slice(0, 120)}`;
  }
  const row = { label, runId: s.runId, cls: s.cls?.verdict, sources: s.sources, failed: out.startsWith('FAILED'), built, mismatches, noBuild };
  repairs.push(row);
  if (out.startsWith('FAILED') || mismatches.length > 0 || noBuild !== 'ok') problems.push(`repair ${label} ${s.runId}: Lake did not repair the seed: ${JSON.stringify(row)}`);
};

