// Verifier probe (closing round 2), scratch only: the run panel's "Accepted" / "Recorded" outcome comes from the run's
// record (RunView.accepted) or this board's own Accept, never from the wording of the runner's notices.
import { readFileSync, writeFileSync } from 'node:fs';

import { acceptChangedFiles, endedOutcome, ENDED_TEXT } from '/tmp/claude-1002/-home-zhengyew-telelean/03a29d54-7342-40e3-b5f0-2697a62c93ef/scratchpad/turn9/closing-verify-2/repo/packages/webview/src/model/run.ts';

const W = '/tmp/claude-1002/-home-zhengyew-telelean/03a29d54-7342-40e3-b5f0-2697a62c93ef/scratchpad/turn9/closing-verify-2/repo/packages/webview';
const OUT = '/tmp/claude-1002/-home-zhengyew-telelean/03a29d54-7342-40e3-b5f0-2697a62c93ef/scratchpad/turn9/closing-verify-2/probes/out';
const RECORDED = 'Recorded: Self-evident? → not proved: Cynder would not be a good addition to the new Spyro game (no file changed).';
const ACCEPTED = 'Accepted: These suffice → proved: Cynder would not be a good addition to the new Spyro game.';
const notice = (text: string) => ({ id: 'n1', at: '2026-11-02T00:00:00Z', level: 'info', kind: 'info', text });
// eslint-disable-next-line @typescript-eslint/no-explicit-any
const run = (extra: Record<string, unknown>): any => ({ runId: 'run_1', state: 'accepted', notices: [], ...extra });

it('ACCEPTED-DISPLAY: the outcome never depends on the notice wording', () => {
  const rows: Array<[string, unknown, unknown]> = [];
  const check = (label: string, got: unknown, want: unknown) => {
    rows.push([label, got, want]);
    expect(got, label).toEqual(want);
  };
  check('record false, notice says Accepted', endedOutcome(run({ accepted: { changedFiles: false }, notices: [notice(ACCEPTED)] }), null), 'recorded');
  check('record true, notice says Recorded (no file changed)', endedOutcome(run({ accepted: { changedFiles: true }, notices: [notice(RECORDED)] }), null), 'accepted');
  check('no record, notice says Recorded, board did not accept: not parsed (cannot tell -> accepted wording)', acceptChangedFiles(run({ notices: [notice(RECORDED)] }), null), null);
  check('no record, notice says Recorded: outcome', endedOutcome(run({ notices: [notice(RECORDED)] }), null), 'accepted');
  check('no record, this board accepted an empty round', endedOutcome(run({ notices: [notice(ACCEPTED)] }), { runId: 'run_1', changedFiles: false }), 'recorded');
  check('record wins over this board', endedOutcome(run({ accepted: { changedFiles: true } }), { runId: 'run_1', changedFiles: false }), 'accepted');
  check('another run\'s board Accept is ignored', acceptChangedFiles(run({}), { runId: 'run_2', changedFiles: false }), null);
  check('discarded stays discarded', endedOutcome(run({ state: 'discarded', notices: [notice(RECORDED)] }), null), 'discarded');
  const source = readFileSync(`${W}/src/model/run.ts`, 'utf8');
  const panel = readFileSync(`${W}/src/run/RunPanel.tsx`, 'utf8');
  const bundle = readFileSync(`${W}/../extension/dist/webview/webview.js`, 'utf8');
  const report = {
    rows,
    sourceMentionsNoFileChanged: source.includes('no file changed'),
    sourceHasRecordedNoticeRegex: /RECORDED_NOTICE/u.test(source),
    panelReadsNoticesForOutcome: /notices[^\n]*(Recorded|Accepted)/u.test(panel),
    bundleMentionsNoFileChanged: bundle.includes('no file changed'),
    recordedText: ENDED_TEXT.recorded,
  };
  writeFileSync(`${OUT}/accepted-result.json`, `${JSON.stringify(report, null, 2)}\n`);
  console.log(`[accepted] ${JSON.stringify({ ...report, rows: rows.length })}`);
  expect(report.sourceHasRecordedNoticeRegex).toBe(false);
  expect(report.bundleMentionsNoFileChanged).toBe(false);
});

