it('POISON: a save during one outside lake build, then Undo: recorded, seeded with copyBuild, trusted in the mirror', async () => {
  const dir = makeTempDir('probe-poison');
  const root = path.join(dir, 'model');
  cpSync(MENTAL_MODEL, root, { recursive: true, filter: (src) => !src.includes(`${path.sep}.lake`) && !src.endsWith(`${path.sep}.git`) });
  const A = new Map([VOCAB, MAIN].map((rel) => [rel, readFileSync(path.join(root, rel), 'utf8')]));
  const B = new Map([
    [VOCAB, A.get(VOCAB)!.replace(/end Spyro\s*$/u, 'theorem probe_variant_b_vocab : True := trivial\n\nend Spyro\n')],
    [MAIN, `${A.get(MAIN)!}\ntheorem ${MARK} : True := trivial\n`],
  ]);
  const put = (v: Map<string, string>) => {
    for (const [rel, text] of v) writeFileSync(path.join(root, rel), text);
  };
  const report: Record<string, unknown> = {};
  put(A);
  expect(lakeOk(root, ['build'])).toBe(true);

  // 1. Outside builds, one at a time: start with sources B, save A while it compiles, then back to B? No: start with A
  //    on disk, save B while Lake compiles, and finally put A back (the Undo). Stop at the first state where Lake
  //    considers A up to date while Main.olean holds version B.
  let tries = 0;
  let poisoned = false;
  while (!poisoned && tries < 40) {
    tries++;
    put(B); // make Lake rebuild Main in the next build (its trace is for A now)
    lakeOk(root, ['build']);
    put(A);
    const child = spawn(`${BIN}/lake`, ['build'], { cwd: root, env: LAKE_ENV, stdio: 'ignore' });
    const exited = new Promise((r) => child.once('exit', r));
    await sleep(100 + Math.floor(Math.random() * 700));
    put(B); // the user saves the other version while the build runs
    await exited;
    put(A); // ... and undoes it
    poisoned = lakeOk(root, ['build', '--no-build']) && mainOleanIsB(root);
  }
  report['outsideBuildTries'] = tries;
  report['poisonedState'] = poisoned;
  report['lakeNoBuildPassesWithSourcesA'] = lakeOk(root, ['build', '--no-build']);
  report['userMainOleanFromB'] = mainOleanIsB(root);
  report['userMainSourceHasMark'] = readFileSync(path.join(root, MAIN), 'utf8').includes(MARK);
  expect(poisoned).toBe(true);

  // 2. The board's refresh (telelean's own Lean job) and its record.
  const refresh = await runExclusive(async () => {
    const facts = await refreshLeanFacts({ root, runId: `vpz${process.pid}` });
    const notRecorded = await noteRefreshOutput(root, facts);
    return { status: facts.status, modules: facts.modules.map((m) => `${m.file}:${m.state}`), notRecorded, boardFactsHaveMark: facts.decls.some((d) => d.name.endsWith(MARK)) };
  });
  report['boardRefresh'] = refresh;

