  const runsDir = path.join(dir, 'runs');
  const seeded = await createRunShadow({ root, runsDir, runId: 'vpz_on', library: 'Model', files: modelFiles(root), copyBuild: true });
  const onFacts = await refreshLeanFacts({ root: seeded.paths.build, runId: 'vpz_on' });
  report['runWithCopyBuild'] = {
    buildSeed: seeded.buildSeed,
    wsMainHasMark: readFileSync(path.join(seeded.paths.ws, MAIN), 'utf8').includes(MARK),
    mirrorRefresh: onFacts.status,
    mirrorModules: onFacts.modules.map((m) => `${m.file}:${m.state}`),
    mirrorFactsHaveMark: onFacts.decls.some((d) => d.name.endsWith(MARK)),
