const VOCAB = 'Model/Spyro/Vocabulary.lean';
const ALL = ['cynder-dark-past', 'new-spyro-pg', 'pg-no-dark-past'];
const HONEST = 'theorem cynder_not_good.holds : cynder_not_good :=\n  pg_no_dark_past.holds newSpyro cynder new_spyro_pg.holds cynder_dark_past.holds\n';
const FREEZE = tool('freeze_statements', { targets: ['cynder-not-good'] });
const CHECK = tool('check_lean');
const PROVED = tool('finish', { status: 'proved', summary: 'Proved.', assumed_without_asking: [] });
const PREFIX: FakeStep[] = [NORMATIVE_PG, CHECK, FREEZE];
const GA_AXIOM = '/-- would be a good addition to -/\naxiom GoodAddition : Character → Game → Prop\n';
