// Phase 5 (synthetic "late writer"): an outside build of version B that finishes while the board's refresh of A runs,
// simulated by writing B's Vocabulary outputs into .lake/build as Lake does (each file to a temporary name and
// renamed, the trace last) at a chosen moment of the refresh. Sources stay A throughout (the refresh sees no change).
{
  const wDir = path.join(dir, 'wbuild');
  cpSync(root, wDir, { recursive: true, filter: (src) => !src.includes(`${path.sep}.lake`) });
  for (const [rel, text] of B) writeFileSync(path.join(wDir, rel), text);
  const wb = lakeBuild(wDir);
  if (wb.startsWith('FAILED')) throw new Error(`late-writer build B failed: ${wb}`);
  const wBuild = path.join(wDir, '.lake', 'build');
  const wFiles = filesBelow(wBuild).filter((rel) => rel.includes('Model/Spyro/Vocabulary.'));
  const ordered = [...wFiles.filter((rel) => !rel.endsWith('.trace')), ...wFiles.filter((rel) => rel.endsWith('.trace'))];
  const lateWrite = () => {
    for (const rel of ordered) {
      const dst = path.join(buildDir, rel);
      mkdirSync(path.dirname(dst), { recursive: true });
      writeFileSync(`${dst}.vw`, readFileSync(path.join(wBuild, rel)));
      renameSync(`${dst}.vw`, dst);
    }
  };
  writeVariant(A);
  const rows: Array<Record<string, unknown>> = [];
  for (let k = 0; k < 24; k++) {
    writeVariant(A);
    const delay = 150 + ((k * 431) % 2600);
    let phaseAtWrite = 'unknown';
    const t0 = Date.now();
    const refreshing = runExclusive(async () => {
      const facts = await refreshLeanFacts({ root, runId: `vrl${process.pid}`, onPhase: (p) => (phaseAtWrite = p) });
      const notRecorded = await noteRefreshOutput(root, facts);
      return { status: facts.status, notRecorded, ms: Date.now() - t0 };
    });
    await sleep(delay);
    const during = phaseAtWrite;
    const before = Date.now() - t0;
    lateWrite();
    const r = await refreshing;
    const writtenDuring = before < r.ms;
    const s = await start(true);
    rows.push({ k, delay, writtenDuring, phase: writtenDuring ? during : 'after', refresh: r.status, refreshMs: r.ms, recorded: r.notRecorded === undefined, notRecorded: r.notRecorded?.replace(/\.lake\/build\/\S+/gu, '<p>'), used: s.used, skipped: s.buildSeed?.skipped?.replace(/\.lake\/build\/\S+/gu, '<p>'), cls: s.cls?.verdict, ...(s.cls && s.cls.verdict !== 'A' && s.cls.verdict !== 'B' ? { detail: s.cls.detail } : {}) });
    if (s.used && s.cls?.verdict !== 'A' && s.cls?.verdict !== 'B') problems.push(`phase5 round ${k}: a ${s.cls?.verdict} seed was used (late write ${writtenDuring ? `during the refresh's ${during} phase` : 'after the refresh'})`);
  }
  report['phase5'] = {
    rounds: rows.length,
    recorded: rows.filter((r) => r['recorded']).length,
    used: rows.filter((r) => r['used']).length,
    usedVerdicts: rows.filter((r) => r['used']).map((r) => `${String(r['cls'])}@${String(r['phase'])}`),
    rows,
  };
}
