    for (const [rel, text] of [...options.files].sort(([a], [b]) => (a < b ? -1 : 1))) {
      for (const base of [layout.ws, layout.build]) {
        await mkdir(path.dirname(path.join(base, rel)), { recursive: true });
        await writeFile(path.join(base, rel), text, 'utf8');
