    if (!file) return [];
    let table = byKey.get(file);
    if (!table) {
      table = new Map();
      for (const block of file.blocks) {
        const k = keyOf(ids, block);
        const list = table.get(k) ?? [];
        list.push(block);
        table.set(k, list);
