// rebuilds the user's project in place, alternating two versions of Vocabulary.lean and Main.lean, while the REAL
// createRunShadow seeds the run's mirror again and again with version A's texts (what the board read).
// Integrity check, after the loop has stopped: every shadow whose seed was USED is built in its mirror with the same
// toolchain, and each module's .olean must equal the .olean of a clean reference build of version A. A stale or mixed
// seed that Lake trusted would show up as a mismatch. Starts must never be refused.
import { execFileSync, spawn } from 'node:child_process';
import { createHash } from 'node:crypto';
