import { makeTempDir, MENTAL_MODEL } from '/tmp/claude-1002/-home-zhengyew-telelean/03a29d54-7342-40e3-b5f0-2697a62c93ef/scratchpad/turn9/m2verify-r3/repo/packages/runner/test/run/helpers/env.ts';

