const TOOLCHAIN_BIN = '/home/zhengyew/.elan/toolchains/leanprover--lean4---v4.35.0/bin';
const LAKE_HOME = `${S}/lake-home`;
const LAKE_ENV = {
  PATH: `${TOOLCHAIN_BIN}:/usr/bin:/bin`,
  HOME: LAKE_HOME,
  XDG_CACHE_HOME: `${LAKE_HOME}/.cache`,
  XDG_CONFIG_HOME: `${LAKE_HOME}/.config`,
  XDG_DATA_HOME: `${LAKE_HOME}/.local/share`,
  LEAN_NUM_THREADS: '4',
  TMPDIR: `${S}/tmp`,
};
const VOCAB = 'Model/Spyro/Vocabulary.lean';
const MAIN = 'Model/Spyro/Main.lean';

function modelFiles(root: string, rel = '', out = new Map<string, string>()): Map<string, string> {
  for (const name of readdirSync(path.join(root, rel))) {
    if (name.startsWith('.')) continue;
    const child = rel === '' ? name : `${rel}/${name}`;
    if (statSync(path.join(root, child)).isDirectory()) modelFiles(root, child, out);
    else if (child.endsWith('.lean') || ['lakefile.toml', 'lean-toolchain', 'lake-manifest.json'].includes(child)) out.set(child, readFileSync(path.join(root, child), 'utf8'));
  }
  return out;
}

function filesBelow(dir: string, rel = ''): string[] {
  if (!existsSync(path.join(dir, rel))) return [];
  const out: string[] = [];
  for (const e of readdirSync(path.join(dir, rel), { withFileTypes: true })) {
    const childRel = rel === '' ? e.name : `${rel}/${e.name}`;
    if (e.isDirectory()) out.push(...filesBelow(dir, childRel));
    else out.push(childRel);
  }
  return out.sort();
}

const sha = (file: string): string => createHash('sha256').update(readFileSync(file)).digest('hex').slice(0, 16);

/** sha256 (16 hex) of every .olean below <project>/.lake/build/lib/lean, by relative path. */
function oleans(project: string): Record<string, string> {
  const lib = path.join(project, '.lake', 'build', 'lib', 'lean');
  const out: Record<string, string> = {};
  for (const rel of filesBelow(lib)) if (rel.endsWith('.olean')) out[rel] = sha(path.join(lib, rel));
  return out;
}

function lakeBuild(project: string): string {
  try {
    return execFileSync(`${TOOLCHAIN_BIN}/lake`, ['build'], { cwd: project, env: LAKE_ENV, encoding: 'utf8', timeout: 300_000 });
  } catch (e) {
    const err = e as { stdout?: string; stderr?: string; message: string };
    return `FAILED: ${err.message.slice(0, 200)}\n${err.stdout ?? ''}\n${err.stderr ?? ''}`;
  }
}

function writeVariant(root: string, variant: Map<string, string>): void {
  for (const [rel, text] of variant) writeFileSync(path.join(root, rel), text);
}

it('LAKE-RACE: an outside lake build loop rewrites .lake/build while createRunShadow seeds; used seeds must be trustworthy', async () => {
  mkdirSync(LAKE_HOME, { recursive: true });
  const dir = makeTempDir('probe-lakerace');
  const root = path.join(dir, 'model');
  cpSync(MENTAL_MODEL, root, { recursive: true, filter: (src) => !src.includes(`${path.sep}.lake`) && !src.endsWith(`${path.sep}.git`) });
  const A = new Map([VOCAB, MAIN].map((rel) => [rel, readFileSync(path.join(root, rel), 'utf8')]));
  const vocabB = A.get(VOCAB)!.replace(/end Spyro\s*$/u, 'theorem probe_variant_b_vocab : True := trivial\n\nend Spyro\n');
  if (vocabB === A.get(VOCAB)) throw new Error('could not make variant B of Vocabulary.lean');
  const B = new Map([
    [VOCAB, vocabB],
    [MAIN, `${A.get(MAIN)!}\ntheorem probe_variant_b_main : True := trivial\n`],
  ]);
  const files = modelFiles(root); // version A: what the board read, the run's texts

  // References: clean builds of A (twice, to show .olean files are deterministic across directories) and of B.
  const refs: Record<string, Record<string, string>> = {};
  for (const [name, variant] of [['A1', A], ['A2', A], ['B', B]] as const) {
    const ref = path.join(dir, `ref-${name}`);
    cpSync(root, ref, { recursive: true });
    writeVariant(ref, variant);
    const out = lakeBuild(ref);
    if (out.startsWith('FAILED')) throw new Error(`reference build ${name} failed: ${out}`);
    refs[name] = oleans(ref);
  }
  const deterministic = JSON.stringify(refs['A1']) === JSON.stringify(refs['A2']);
  const differs = Object.keys(refs['A1']!).filter((k) => refs['A1']![k] !== refs['B']![k]);

  // The user's project starts with a finished build of A.
  lakeBuild(root);
  const aTxt = path.join(dir, 'A'), bTxt = path.join(dir, 'B');
  for (const [d, v] of [[aTxt, A], [bTxt, B]] as const) for (const [rel, text] of v) { mkdirSync(path.dirname(path.join(d, rel)), { recursive: true }); writeFileSync(path.join(d, rel), text); }
  const loop = `cd '${root}'; n=0; while :; do for v in '${bTxt}' '${aTxt}'; do cp "$v/${VOCAB}" '${VOCAB}'; cp "$v/${MAIN}" '${MAIN}'; '${TOOLCHAIN_BIN}/lake' build >/dev/null 2>&1; n=$((n+1)); echo $n > '${dir}/builds'; done; done`;
