      } catch (e) {
        problems.push(`start ${k} refused: ${(e as Error).message.slice(0, 220)}`);
        records.push({ k, refused: (e as Error).message.slice(0, 220) });
      }
      await new Promise((r) => setTimeout(r, 37 + ((k * 53) % 211)));
    }
  } finally {
    try { process.kill(-builder.pid!, 'SIGKILL'); } catch { /* gone */ }
    await new Promise((r) => (builder.exitCode !== null || builder.signalCode !== null ? r(undefined) : builder.once('exit', r)));
  }
  await new Promise((r) => setTimeout(r, 500));
  const leftovers = execFileSync('bash', ['-c', `pgrep -af '${root}' | grep -v pgrep || true`], { encoding: 'utf8' }).trim();
  const builds = existsSync(path.join(dir, 'builds')) ? readFileSync(path.join(dir, 'builds'), 'utf8').trim() : '0';

  // Verify every used seed (sequentially; the outside builder is gone).
  for (const rec of records) {
    if (typeof rec['seeded'] !== 'number' || rec['seeded'] === 0) continue;
    if ((rec['tmp'] as string[]).length > 0) problems.push(`${String(rec['runId'])}: seeded temp files ${(rec['tmp'] as string[]).join(',')}`);
    const mirror = String(rec['mirror']);
    const before = oleans(mirror);
    const out = lakeBuild(mirror);
    const after = oleans(mirror);
    const rebuilt = (out.match(/Built [A-Za-z.]+/gu) ?? []).map((s) => s.slice(6));
    const wrong = Object.keys(refs['A1']!).filter((k) => after[k] !== refs['A1']![k]);
    rec['verify'] = {
      seededFrom: Object.keys(refs['A1']!).map((k) => `${k.replace('Model/', '')}:${before[k] === undefined ? 'none' : before[k] === refs['A1']![k] ? 'A' : before[k] === refs['B']![k] ? 'B' : 'other'}`).join(' '),
      rebuilt,
      failed: out.startsWith('FAILED') ? out.slice(0, 300) : undefined,
      wrong,
    };
    if (out.startsWith('FAILED')) problems.push(`${String(rec['runId'])}: mirror build failed: ${out.slice(0, 200)}`);
    if (wrong.length > 0) problems.push(`${String(rec['runId'])}: INTEGRITY: mirror .olean differs from the clean build of its sources: ${wrong.join(', ')}`);
  }
