  const summary = { outsideBuilds: builds, starts: records.length, used, skipped: records.length - used - problems.filter((p) => p.includes('refused')).length, skippedReasons, deterministic, oleansThatDifferAB: differs, leftovers, problems };
  writeFileSync(`${DIR}/lakerace-result.json`, JSON.stringify({ summary, records, refs }, null, 2));
  console.log(`[lakerace] ${JSON.stringify(summary)}`);
});

