/** How an ended run ended, as the run panel words it: `recorded` is an Accept that changed no file. */
export type EndedOutcome = 'accepted' | 'recorded' | 'discarded' | 'cancelled' | 'failed';

/** The run panel's sentence per outcome. An Accept that changed no file left no Undo step, so none is offered. */
export const ENDED_TEXT: Readonly<Record<EndedOutcome, string>> = {
  accepted: 'Accepted: Claude’s changes are in your files. Undo (Ctrl+Z) or History reverts them.',
  recorded: 'Recorded: nothing in your files changed; the outcome is in the card’s Attempts.',
  discarded: 'Discarded: your files were not changed.',
  cancelled: 'Cancelled: your files were not changed. The run’s working copy and transcript are kept for the record.',
  failed: 'The run failed; your files were not changed.',
};

/** The runner's notice for an Accept that applied nothing: "Recorded: <label> (no file changed)." */
const RECORDED_NOTICE = /^Recorded\b[^\n]*\(no file changed\)\.?$/;

/**
 * Whether the Accept of an accepted run changed the user's files (null: the board cannot tell). An Accept of a round
 * that changed no file only records the outcome: no Undo step, no history entry. What this board knows from its own
 * Accept comes first (`accepted`: the proposal's `empty`, then the host's answer). A board opened after the Accept
 * reads the run's last notice, the runner's own record of it ("Accepted: … Undo reverts it." or "Recorded: … (no
 * file changed).").
 */
export function acceptChangedFiles(run: Pick<RunView, 'runId' | 'notices'>, accepted: { runId: string; changedFiles: boolean } | null): boolean | null {
  if (accepted !== null && accepted.runId === run.runId) return accepted.changedFiles;
  const latest = run.notices.findLast((notice) => notice.kind === 'info');
  if (latest === undefined) return null;
  if (RECORDED_NOTICE.test(latest.text)) return false;
  return latest.text.startsWith('Accepted') ? true : null;
}

/** How an ended run ended (null while it has not ended), for the run panel's outcome line. */
export function endedOutcome(run: Pick<RunView, 'runId' | 'state' | 'notices'>, accepted: { runId: string; changedFiles: boolean } | null): EndedOutcome | null {
  switch (run.state) {
    case 'accepted':
      return acceptChangedFiles(run, accepted) === false ? 'recorded' : 'accepted';
    case 'discarded':
    case 'cancelled':
    case 'failed':
      return run.state;
    default:
      return null;
  }
}

/**
 * The Accept button's tooltip (review and proposal banner): what Accept does to the user's files (D-21). A round that
 * changed no file is only recorded (no Undo step, no history entry).
 */
export function acceptTitle(proposal: Pick<ProposalView, 'empty' | 'report'>): string {
  if (proposal.empty) return 'Record the outcome: this round changed no file, so there is no Undo step and no history entry';
  return isRunOutcomeVerdict(proposal.report.verdict) ? 'Apply what last passed the checks to your files (one Undo step; a history entry)' : 'Apply the proposal to your files (one Undo step; a history entry)';
}

