    expect(existsSync(marker)).toBe(false);
    expect(existsSync(r.workDir)).toBe(false);
    expect(r.stdout).toBe('');
  });

  it('TELELEAN_SMOKE_LIVE=yes without --live', () => {
    const r = runScript(['--dry-run'], { TELELEAN_SMOKE_LIVE: 'yes' });
