// Final verifier's own retries of the three most dangerous gate cheats (added axiom, weakened goal, existing vocabulary
// turned into a definition), each in the canonical form and in variants the repo's scripts do not use. Real engine,
// real Lean, real proposals and an fs-backed ModelWorkspace on a scratch git copy of mental_model/; FakeBackend plays
// Claude. Each script: the cheat, a finish (or a freeze), then an honest retry that removes the cheat, a second finish.
// For each run we record every tool result (freeze replies, gate verdicts), the end state, and, after Accept, whether
// any cheat text reached the (scratch) user's files.
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';

import type { FakeStep } from '/tmp/claude-1002/-home-zhengyew-telelean/03a29d54-7342-40e3-b5f0-2697a62c93ef/scratchpad/turn9/m2verify-final/repo/packages/runner/src/llm/fake.ts';
import { edit, MAIN, NORMATIVE_PG, result, setup, summary, TARGET_LINE, tool, waitForRun } from './common.ts';

const DIR = '/tmp/claude-1002/-home-zhengyew-telelean/03a29d54-7342-40e3-b5f0-2697a62c93ef/scratchpad/turn9/m2verify-final/probes/out';
const VOCAB = 'Model/Spyro/Vocabulary.lean';
const ALL = ['cynder-dark-past', 'new-spyro-pg', 'pg-no-dark-past'];
const NO_PG = ['cynder-dark-past', 'pg-no-dark-past'];
const HONEST = 'theorem cynder_not_good.holds : cynder_not_good :=\n  pg_no_dark_past.holds newSpyro cynder new_spyro_pg.holds cynder_dark_past.holds\n';
const FREEZE = tool('freeze_statements', { targets: ['cynder-not-good'] });
const CHECK = tool('check_lean');
const PROVED = tool('finish', { status: 'proved', summary: 'Proved.', assumed_without_asking: [] });
const NOT_PROVED = tool('finish', { status: 'not_proved', summary: 'Not proved.', gap: 'x', assumed_without_asking: [] });
const PREFIX: FakeStep[] = [NORMATIVE_PG, CHECK, FREEZE];
const PG_ABBREV = 'abbrev pg_no_dark_past : Prop := ∀ (g : Game) (c : Character), IsPG g → HasDarkPast c → ¬ GoodAddition c g\n';
const GA_AXIOM = '/-- would be a good addition to -/\naxiom GoodAddition : Character → Game → Prop\n';
const GA_DEF = '/-- would be a good addition to -/\ndef GoodAddition (c : Character) (_g : Game) : Prop := ¬ HasDarkPast c\n';
const PG_AXIOM = '/-- is rated PG -/\naxiom IsPG : Game → Prop\n';
const PG_DEF = '/-- is rated PG -/\ndef IsPG (_g : Game) : Prop := True\n';

async function runOnce(label: string, steps: FakeStep[], premises: string[], needles: string[]): Promise<Record<string, unknown>> {
  const p = await setup(label, [{ match: 'Run: "These suffice"', steps }]);
  const started = await p.manager.start({ subject: 'Spyro', target: 'cynder-not-good', premises });
  const out: Record<string, unknown> = { started };
  const end = await waitForRun(p.manager, (v) => v.state === 'review' || v.state === 'failed', 600_000, 'review');
  out['review'] = summary(p.manager);
  const rootKey = readdirSync(p.runsDir)[0] ?? '';
  out['tools'] = readFileSync(path.join(p.runsDir, rootKey, end.runId, 'session', 'transcript.jsonl'), 'utf8')
    .split('\n')
    .filter((l) => l.includes('"tool_result"'))
    .map((l) => (JSON.parse(l) as { event: { text: string } }).event.text.slice(0, 900))
    .filter((t) => !t.startsWith('edited ') && !t.startsWith('read '));
  const proposal = p.manager.proposal();
  if (end.state === 'review' && proposal) {
    const diff = await p.manager.proposalDiff(end.runId, proposal.proposalId);
    out['proposalHasCheat'] = needles.filter((n) => diff.some((c) => (c.after ?? '').includes(n)));
    out['accept'] = await p.manager.accept(end.runId, proposal.proposalId, proposal.lifecycle.map((l) => l.id), proposal.definitions.map((d) => d.id));
    const main = readFileSync(path.join(p.root, MAIN), 'utf8');
    const vocab = readFileSync(path.join(p.root, VOCAB), 'utf8');
    out['realFilesHaveCheat'] = needles.filter((n) => main.includes(n) || vocab.includes(n));
    out['realHasHonestProof'] = main.includes('pg_no_dark_past.holds newSpyro cynder new_spyro_pg.holds cynder_dark_past.holds');
    out['realVocabUnchanged'] = vocab.includes(GA_AXIOM) && vocab.includes(PG_AXIOM);
  }
  await p.manager.dispose();
  return out;
}

const results: Record<string, unknown> = {};
afterAll(() => writeFileSync(`${DIR}/cheats-result.json`, JSON.stringify(results, null, 2)));

