it('ADD-6 private axiom used by the target proof after the freeze (proved)', async () => {
  const cheat = '\nprivate axiom evil2 : cynder_not_good\ntheorem cynder_not_good.holds : cynder_not_good := evil2\n';
  results['ADD-6'] = await runOnce('add6', [...PREFIX, edit(TARGET_LINE, TARGET_LINE + cheat), PROVED, edit(cheat, HONEST), PROVED, result()], ALL, ['evil2']);
});

