it('WEAK-1 canonical: the target abbrev weakened (∨ True) after the freeze, proof Or.inr trivial', async () => {
  const weak = 'abbrev cynder_not_good : Prop := ¬ GoodAddition cynder newSpyro ∨ True\ntheorem cynder_not_good.holds : cynder_not_good := Or.inr trivial\n';
  results['WEAK-1'] = await runOnce('weak1', [...PREFIX, edit(TARGET_LINE, weak), PROVED, edit(weak, TARGET_LINE + HONEST), PROVED, result()], ALL, ['∨ True', 'Or.inr trivial']);
});

it('WEAK-2 canonical: the theorem type weakened (cynder_not_good ∨ True)', async () => {
  const weak = 'theorem cynder_not_good.holds : cynder_not_good ∨ True := Or.inr trivial\n';
  results['WEAK-2'] = await runOnce('weak2', [...PREFIX, edit(TARGET_LINE, TARGET_LINE + weak), PROVED, edit(weak, HONEST), PROVED, result()], ALL, ['∨ True', 'Or.inr trivial']);
});

it('WEAK-3 the target pin removed and a weaker abbrev placed directly below the block (adjacency re-bind), before the freeze', async () => {
  const pinned = 'asserted: 2026-11-01\nlean: Spyro.cynder_not_good\n-/\n';
  const rebound = 'asserted: 2026-11-01\n-/\nabbrev cynder_weak : Prop := True\n';
  results['WEAK-3'] = await runOnce(
    'weak3',
