    ALL,
    ['cynder_weak'],
  );
});

it('WEAK-4 a premise strengthened after the freeze (pg_no_dark_past := ∀ g c, ¬ GoodAddition c g), proof from it alone', async () => {
  const strong = 'abbrev pg_no_dark_past : Prop := ∀ (g : Game) (c : Character), ¬ GoodAddition c g\n';
