/**
 * M2 UX probe (independent verifier, turn 9): drives "These suffice" through the real board UI in the VS Code test
 * instance (Test mode, FakeBackend scripts through the testing API, real Lean, CDP trusted clicks), records what the
 * user sees (texts, states) into observations.jsonl and takes light/dark screenshots of every state worth looking at.
 * Soft checks are recorded (pass/fail) instead of thrown, so one finding does not hide the next.
 */
import * as assert from 'node:assert/strict';
import { appendFileSync, existsSync, readFileSync, writeFileSync } from 'node:fs';
import * as path from 'node:path';
import * as vscode from 'vscode';

import { FakeBackend } from '/home/zhengyew/telelean/packages/runner/src/llm/fake.ts';
import { playFakeScript, validateFakeScriptFile } from '/home/zhengyew/telelean/packages/runner/src/llm/fakeScripts.ts';
import { boardFrame, clearWorkbenchToasts, connectWorkbench, settleStartupToasts } from '/home/zhengyew/telelean/packages/extension/test/suite/cdp.ts';
import { closeTextEditors, EXTENSION_ID, getApi, isRendered, nextBoardMessage, settleEditors, sleep, waitFor } from '/home/zhengyew/telelean/packages/extension/test/suite/helpers.ts';

const OUT = process.env.TELELEAN_UXPROBE_OUT as string;
const ROOT = process.env.TELELEAN_UXPROBE_ROOT as string;
const CDP_PORT = process.env.TELELEAN_CDP_PORT as string;
const SHOTS = path.join(OUT, 'shots');
const LEAN_TIMEOUT_MS = 240_000;
const UI_TIMEOUT_MS = 30_000;
const MAIN = 'Model/Spyro/Main.lean';
const VOCABULARY = 'Model/Spyro/Vocabulary.lean';
const DECISIONS = '.telelean/subjects/Spyro/decisions.json';
const ATTEMPTS = '.telelean/subjects/Spyro/attempts.jsonl';
const TARGET = 'cynder-not-good';
const PREMISES = ['cynder-dark-past', 'new-spyro-pg', 'pg-no-dark-past'];

// ---------------------------------------------------------------------------------------------------------------
// Recording

function obs(key: string, value: unknown): void {
  appendFileSync(path.join(OUT, 'observations.jsonl'), `${JSON.stringify({ t: new Date().toISOString(), key, value })}\n`);
}
function check(name: string, ok: boolean, detail?: unknown): boolean {
  appendFileSync(path.join(OUT, 'checks.jsonl'), `${JSON.stringify({ t: new Date().toISOString(), name, ok, detail })}\n`);
  if (!ok) console.log(`[probe] CHECK FAILED: ${name} ${detail === undefined ? '' : JSON.stringify(detail).slice(0, 400)}`);
  return ok;
}

// ---------------------------------------------------------------------------------------------------------------
// FakeBackend scripts

function fixture(name: string): any {
  const extension = vscode.extensions.getExtension(EXTENSION_ID);
  assert.ok(extension);
  const file = path.resolve(extension.extensionPath, '..', '..', 'test-fixtures', 'walkthrough', `${name}.json`);
  return validateFakeScriptFile(JSON.parse(readFileSync(file, 'utf8')));
}

const Q_MODALITY = {
  phenomenon: 'modality',
  question:
    'Does "cannot have" state a rule about what PG games should not include (normative), or that a PG game is unable to contain such a character (literal)?',
  options: [
    { label: 'A rule (normative)', consequence: 'A PG game with such a character breaks the rule; it says nothing about what the game contains.' },
    { label: 'Impossible (literal)', consequence: 'No PG game contains a character with a dark past at all.' },
  ],
  claudesGuess: { option: 0 },
  affectedNodes: ['pg-no-dark-past'],
};
const Q_GENERIC = {
  phenomenon: 'genericity',
  question: 'Does "characters with dark pasts" cover every character with a dark past, or only typical ones?',
  options: [
    { label: 'Every such character', consequence: 'The rule applies to Cynder for certain.' },
    { label: 'Typical ones', consequence: 'The rule might not apply to Cynder, so the goal could fail.' },
  ],
  claudesGuess: { option: 0, note: 'Rules like this are usually meant universally.' },
  affectedNodes: ['pg-no-dark-past'],
};
const Q_SENSE = {
  phenomenon: 'word-sense',
  question: 'Is "a good addition" about the quality of the game or about its audience?',
  options: [
    { label: 'Quality', consequence: 'Cynder would make the game worse.' },
    { label: 'Audience', consequence: 'Cynder would not suit the players of a PG game.' },
  ],
};

/** Reading A with three questions, a rate-limit warning, a pause to look at "working", and one assumed-without-asking item. */
function normative3q(): any[] {
