async function runOnce(label: string, decl: string, needle: string): Promise<Record<string, unknown>> {
  const steps: FakeStep[] = [NORMATIVE_PG, edit(TARGET_LINE, `${TARGET_LINE}\n${decl}`), tool('check_lean'), NOT_PROVED, result()];
