20	/** Vocabulary kinds whose axioms are signature (not beliefs) when Lean's `typeSort` is unknown. */
21	const SIGNATURE_KINDS: ReadonlySet<VocabKind> = new Set(['sort', 'predicate', 'function', 'constant']);
