23	/** Every non-Prop axiom of the project (sorts, predicates, functions): D-3 rules 1 and 3. */
24	export function signatureAxioms(model: ProjectModel): string[] {
25	  const kinds = new Map(model.vocabulary.map((item) => [item.name, item.kind]));
26	  const out: string[] = [];
27	  for (const [name, facts] of model.declFacts) {
28	    if (facts.kind !== 'axiom') continue;
29	    const sort = facts.typeSort === undefined ? undefined : normalizeWhitespace(facts.typeSort);
30	    if (sort !== undefined ? sort !== 'Prop' : SIGNATURE_KINDS.has(kinds.get(name) ?? 'other')) out.push(name);
31	  }
32	  return out;
33	}
