35	/** Why a selected card cannot be used, or undefined when it contributes axioms (and which). */
36	function contribution(node: TlNode, targetHolds: string | undefined): { selected?: string; footprint?: string[] } | undefined {
37	  const statement = node.lean.statement;
38	  if (statement === undefined || node.lean.justification === undefined || node.status.flags.includes('holds-mismatch')) return undefined;
39	  if (node.lean.justificationKind === 'axiom') return { selected: holdsName(statement) };
40	  const proof = node.status.proof;
41	  if (proof.kind !== 'proved' || node.lean.axioms === undefined) return undefined;
42	  const axioms = node.lean.axioms.filter((a) => a !== SORRY_AXIOM);
43	  if (targetHolds !== undefined && axioms.includes(targetHolds)) return undefined;
44	  return { footprint: axioms };
45	}
