47	/**
48	 * The permitted set. `strict`: unknown target or premise ids throw ActionError `invalid` (computePermittedAxioms);
49	 * otherwise they are skipped (evaluateRules never throws).
50	 */
51	export function permittedAxioms(model: ProjectModel, selection: Selection, strict: boolean): PermittedAxioms {
52	  const nodeOf = (id: string, what: string): TlNode | undefined => {
53	    const entry = model.nodes.get(id);
54	    if (entry && entry.node.subject === selection.subject) return entry.node;
55	    if (strict) throw new ActionError('invalid', `${what} "${id}" is not a card of the subject ${selection.subject}.`);
56	    return undefined;
57	  };
58	  const target = nodeOf(selection.target, 'The target');
59	  const targetHolds = target?.lean.statement !== undefined ? holdsName(target.lean.statement) : undefined;
60	  const chosen = [...new Set([...selection.premises, ...selection.adoptedGhosts])].filter((id) => id !== selection.target);
61	  const selected: string[] = [];
62	  const presuppositions: string[] = [...(target?.lean.presupposes ?? [])];
63	  const derivationFootprints: string[] = [];
64	  const unusable: string[] = [];
65	  for (const id of chosen) {
66	    const node = nodeOf(id, 'The premise');
67	    if (!node) continue;
68	    presuppositions.push(...(node.lean.presupposes ?? []));
69	    const gives = contribution(node, targetHolds);
70	    if (gives === undefined) unusable.push(id);
71	    else if (gives.selected !== undefined) selected.push(gives.selected);
72	    else derivationFootprints.push(...(gives.footprint ?? []));
73	  }
74	  const drop = (names: Iterable<string>) => sortNames([...names].filter((n) => n !== targetHolds && n !== SORRY_AXIOM));
75	  const summary = {
76	    standard: [...STANDARD_AXIOM_NAMES],
77	    signature: drop(signatureAxioms(model)),
78	    selected: drop(selected),
79	    presuppositions: drop(presuppositions),
80	    derivationFootprints: drop(derivationFootprints),
81	    unusable,
82	  };
83	  const all = [...new Set([...summary.standard, ...summary.signature, ...summary.selected, ...summary.presuppositions, ...summary.derivationFootprints])].sort();
84	  return { ...summary, all };
85	}
