 21	export interface DeclTables {
 22	  /** Named declarations, first occurrence wins, files in path order. */
 23	  byName: Map<string, DeclEntry>;
 24	  /** Source texts of the `example`s (they have no name), in file order. */
 25	  examples: Array<{ file: ParsedFile; decl: DeclInfo; text: string }>;
 26	  /** Every name the model knows: syntactic declarations and facts. */
