 36	export function declTables(model: ProjectModel): DeclTables {
 37	  const cached = cache.get(model);
 38	  if (cached) return cached;
 39	  const byName = new Map<string, DeclEntry>();
 40	  const examples: DeclTables['examples'] = [];
 41	  for (const file of [...model.files.values()].sort(byPath)) {
 42	    for (const decl of file.decls) {
 43	      if (decl.keyword === 'mutual') continue;
 44	      const text = file.text.slice(decl.span.start, decl.span.end);
 45	      if (decl.keyword === 'example') {
 46	        examples.push({ file, decl, text });
 47	        continue;
 48	      }
 49	      const name = decl.fullName ?? (decl.keyword === 'instance' ? anonymousInstanceName(file, decl) : undefined);
 50	      if (name === undefined || byName.has(name)) continue;
 51	      byName.set(name, { name, file, decl, text });
 52	    }
 53	  }
 54	  const known = new Set<string>([...byName.keys(), ...model.declFacts.keys()]);
 55	  const tables: DeclTables = { byName, examples, known, vocabulary: new Set(model.vocabulary.map((item) => item.name)) };
 56	  cache.set(model, tables);
 57	  return tables;
 58	}
