  const build = path.join(root, '.lake', 'build');
  for (let i = 0; i < 20; i++) {
    mkdirSync(path.join(build, 'lib', `d${i}`), { recursive: true });
    for (let j = 0; j < 40; j++) writeFileSync(path.join(build, 'lib', `d${i}`, `f${j}.olean`), 'x'.repeat(2048));
