/**
 * Seeding a run's build mirror from the user's `.lake/build` (docs/m2-plan.md section 4.2; fixer round 3).
 *
 * Lake writes the user's `.lake/build` while a run starts: the board's own refresh (a `lake build` in place, after a
 * save, an Undo or the start's own premises declaration) and Lean jobs telelean does not control (the Lean extension
 * building imports, a `lake build` in a terminal). A copy taken meanwhile could miss a file (ENOENT, which refused the
 * start), hold Lake's temporary files instead of the artifacts, or mix artifacts of two builds, which Lake might then
 * trust when it checks the run. So:
 *   - createRunShadow lists, copies and verifies the seed as one of telelean's Lean jobs (`semantic.runExclusive`,
 *     the lock every refresh of the board holds), so telelean's own refresh never writes the tree meanwhile;
 *   - the seed is used only when it is a snapshot of a finished build: no Lake build lock and no fresh temporary file
 *     (`*.tmp`, `*.tmp.*`); no artifact newer than its trace (Lake 4.35 deletes a module's artifacts before rebuilding
 *     it and writes the trace last, verified on the pinned toolchain, so a newer artifact belongs to a build that is
 *     running or was interrupted, beside a trace that describes other sources); every file keeps its identity, size
 *     and times (device, inode, size, mtime, ctime) from the listing through its copy and a second listing after the
 *     copy, and no file appears or disappears meanwhile.
 * Anything else seeds nothing (build/.lake stays absent): always correct, the run's first Lean job is just a full
 * build. Only a symlink or special file refuses the whole shadow, as before (D-24).
 */
import { constants as fsConstants, type BigIntStats, type Dirent } from 'node:fs';
import { copyFile, lstat, mkdir, readdir, rm, utimes } from 'node:fs/promises';
import path from 'node:path';

import { ShadowLayoutError, type BuildSeedOutcome } from './types.js';

/** A temporary file of Lean or Lake (Lean writes an `.olean` under a temporary name and renames it). */
const TEMP_NAME = /\.tmp(?:\.[^/]*)?$/u;
/** The build lock of Lake versions that hold one while building (4.35 holds none); a copied one would stall the mirror's Lake. */
const LAKE_LOCK = 'lake.lock';
/** A temporary file older than this is a leftover of a crashed build, not a write in progress: it is skipped, not copied. */
export const STALE_TEMP_MS = 10 * 60 * 1000;
/**
 * A module's artifacts beside its trace `<leanLibDir>/<M>.trace` (Lake 4.35 `Module.oleanFile` … `irSigFile`) and in
 * `<irDir>/<M>.*` (`cFile`, `bcFile`); Lake's default directories `lib/lean` and `ir`. A target with its own trace
 * `<file>.trace` has the artifact `<file>`. Not compared: `.hash` files (written lazily), `.setup.json` (an input),
 * `.ltar` (packed on demand from the artifacts).
 */
const LIB_ARTIFACTS = ['olean', 'olean.server', 'olean.private', 'ilean', 'ir', 'ir.sig'];
const IR_ARTIFACTS = ['c', 'bc'];
const LIB_DIR = 'lib/lean/';
const IR_DIR = 'ir/';

interface SeedFile {
  /** Relative to `.lake/build`, POSIX. */
  rel: string;
  st: BigIntStats;
}

/** A listing of the user's `.lake/build` (see `listBuildSeed`). */
export interface BuildSeedListing {
  /** The user's `<root>/.lake/build`. */
  buildDir: string;
  /** Regular files, sorted by path. */
  files: SeedFile[];
  /** Set when the tree changed while it was listed (a directory or file vanished, a file changed its type). */
  unstable?: string;
}

/** Test hooks of `copyBuildSeed` (never used by telelean itself). */
export interface CopyBuildSeedHooks {
  /** Called after each file was copied and re-checked, with its path relative to `.lake/build`. */
  afterCopy?: (rel: string) => void | Promise<void>;
  /** The clock for the age of temporary files (default `Date.now`). */
  now?: () => number;
}

const isGone = (error: unknown): boolean => {
  const code = (error as NodeJS.ErrnoException | undefined)?.code;
  return code === 'ENOENT' || code === 'ENOTDIR';
};
const shown = (rel: string): string => (rel === '' ? '.lake/build' : `.lake/build/${rel}`);
const byRel = (a: SeedFile, b: SeedFile): number => (a.rel < b.rel ? -1 : a.rel > b.rel ? 1 : 0);

async function isRealDirectory(p: string): Promise<boolean> {
  try {
    const st = await lstat(p);
    return st.isDirectory() && !st.isSymbolicLink();
  } catch (error) {
    if (isGone(error)) return false;
    throw error;
  }
}

/** Walks `.lake/build` without following symlinks; symlinks and special files go to `refused`. */
async function walk(buildDir: string): Promise<{ files: SeedFile[]; refused: string[]; unstable?: string }> {
  const files: SeedFile[] = [];
  const refused: string[] = [];
  let unstable: string | undefined;
  const stack = [''];
  while (stack.length > 0) {
    const rel = stack.pop() ?? '';
    let entries: Dirent[];
    try {
      entries = await readdir(path.join(buildDir, rel), { withFileTypes: true });
    } catch (error) {
      if (!isGone(error)) throw error;
      unstable ??= `${shown(rel)} disappeared while it was listed`;
      continue;
    }
    for (const entry of entries) {
      const childRel = rel === '' ? entry.name : `${rel}/${entry.name}`;
      if (entry.isSymbolicLink()) refused.push(shown(childRel));
      else if (entry.isDirectory()) stack.push(childRel);
      else if (!entry.isFile()) refused.push(shown(childRel));
      else {
        let st: BigIntStats;
        try {
          st = await lstat(path.join(buildDir, childRel), { bigint: true });
        } catch (error) {
          if (!isGone(error)) throw error;
          unstable ??= `${shown(childRel)} disappeared while it was listed`;
          continue;
        }
        if (st.isFile()) files.push({ rel: childRel, st });
        else if (st.isSymbolicLink()) refused.push(shown(childRel));
        else unstable ??= `${shown(childRel)} changed while it was listed`;
      }
    }
  }
  files.sort(byRel);
  refused.sort();
  return { files, refused, ...(unstable !== undefined ? { unstable } : {}) };
}

/**
 * Lists the user's `<root>/.lake/build`: undefined when there is none, or when `.lake` or `.lake/build` is a symlink
 * (simply not seeded); throws ShadowLayoutError `not-regular` when it holds a symlink or a special file (D-24: the
 * whole shadow is refused, before anything is created).
 */
export async function listBuildSeed(root: string): Promise<BuildSeedListing | undefined> {
  const lake = path.join(root, '.lake');
  const buildDir = path.join(lake, 'build');
  if (!(await isRealDirectory(lake)) || !(await isRealDirectory(buildDir))) return undefined;
  const { files, refused, unstable } = await walk(buildDir);
  if (refused.length > 0) {
    throw new ShadowLayoutError('not-regular', `refusing to seed the build mirror: .lake/build holds symlinks or special files: ${refused.join(', ')}`, refused);
  }
  return { buildDir, files, ...(unstable !== undefined ? { unstable } : {}) };
}

/** Same file, unchanged: device, inode, size, mtime and ctime (ctime moves on every write, rename or utimes). */
function sameFile(a: BigIntStats, b: BigIntStats): boolean {
  return a.dev === b.dev && a.ino === b.ino && a.size === b.size && a.mtimeNs === b.mtimeNs && a.ctimeNs === b.ctimeNs;
}

/** The first artifact newer than its trace (see the module comment), as a reason; undefined when there is none. */
export function artifactNewerThanTrace(files: ReadonlyArray<{ rel: string; st: Pick<BigIntStats, 'mtimeNs'> }>): string | undefined {
  const index = new Map(files.map((f) => [f.rel, f]));
  for (const trace of files) {
    if (!trace.rel.endsWith('.trace')) continue;
    const stem = trace.rel.slice(0, -'.trace'.length);
    const artifacts = [stem, ...LIB_ARTIFACTS.map((ext) => `${stem}.${ext}`)];
    if (stem.startsWith(LIB_DIR)) artifacts.push(...IR_ARTIFACTS.map((ext) => `${IR_DIR}${stem.slice(LIB_DIR.length)}.${ext}`));
    for (const rel of artifacts) {
      const artifact = index.get(rel);
      if (artifact !== undefined && artifact.st.mtimeNs > trace.st.mtimeNs) return `${shown(rel)} is newer than its trace ${shown(trace.rel)} (a build is running or was interrupted)`;
    }
  }
  return undefined;
}

/** Why a listing is not a finished build (a lock, a fresh temporary file, an artifact newer than its trace), or undefined. */
function busyReason(files: readonly SeedFile[], nowMs: number): string | undefined {
  for (const f of files) {
    const name = path.posix.basename(f.rel);
    if (name === LAKE_LOCK) return `Lake's build lock ${shown(f.rel)} exists (a build is running)`;
    if (TEMP_NAME.test(name) && nowMs - Number(f.st.mtimeMs) < STALE_TEMP_MS) return `${shown(f.rel)} is being written (a build is running)`;
  }
  return artifactNewerThanTrace(files);
}

function sameListing(a: readonly SeedFile[], b: readonly SeedFile[]): string | undefined {
  const later = new Map(b.map((f) => [f.rel, f]));
  for (const f of a) {
    const now = later.get(f.rel);
    if (now === undefined) return `${shown(f.rel)} disappeared while the build was copied`;
    if (!sameFile(f.st, now.st)) return `${shown(f.rel)} changed while the build was copied`;
    later.delete(f.rel);
  }
  const [added] = later.keys();
  return added === undefined ? undefined : `${shown(added)} appeared while the build was copied`;
}

/**
 * Copies a listed seed into `<mirror>/.lake/build` when it is a snapshot of a finished build (see the module comment),
 * keeping each file's times; otherwise removes whatever it copied and seeds nothing. Never throws for a build that
 * changed or could not be read: the outcome says why nothing was seeded.
 */
export async function copyBuildSeed(seed: BuildSeedListing | undefined, mirror: string, hooks: CopyBuildSeedHooks = {}): Promise<BuildSeedOutcome> {
  if (seed === undefined) return { files: 0 };
  const lakeDir = path.join(mirror, '.lake');
  const skip = async (reason: string): Promise<BuildSeedOutcome> => {
    await rm(lakeDir, { recursive: true, force: true });
    return { files: 0, skipped: reason };
  };
  if (seed.unstable !== undefined) return skip(seed.unstable);
  const busy = busyReason(seed.files, (hooks.now ?? Date.now)());
  if (busy !== undefined) return skip(busy);
  // Stale temporary files (fresh ones made the build busy above) are never copied.
  const wanted = seed.files.filter((f) => !TEMP_NAME.test(path.posix.basename(f.rel)));
  const target = path.join(lakeDir, 'build');
  for (const f of wanted) {
    const source = path.join(seed.buildDir, f.rel);
    try {
      const destination = path.join(target, f.rel);
      await mkdir(path.dirname(destination), { recursive: true });
      await copyFile(source, destination, fsConstants.COPYFILE_FICLONE);
      if (!sameFile(f.st, await lstat(source, { bigint: true }))) return skip(`${shown(f.rel)} changed while it was copied`);
      await utimes(destination, f.st.atime, f.st.mtime);
    } catch (error) {
      if (isGone(error)) return skip(`${shown(f.rel)} disappeared while it was copied`);
      return skip(`${shown(f.rel)} could not be copied (${(error as Error).message})`);
    }
    await hooks.afterCopy?.(f.rel);
  }
  let again: Awaited<ReturnType<typeof walk>>;
  try {
    again = await walk(seed.buildDir);
  } catch (error) {
    return skip(`.lake/build could not be listed again (${(error as Error).message})`);
  }
  const changed = again.unstable ?? (again.refused.length > 0 ? `${again.refused[0]} appeared while the build was copied` : sameListing(seed.files, again.files));
  if (changed !== undefined) return skip(changed);
  return { files: wanted.length };
}

