/**
 * Seeding the build mirror from the user's .lake/build while Lake may be writing it (fixer round 3; the final
 * verifier's race probe): createRunShadow never refuses because the build changed, never seeds Lake's temporary
 * files, and never seeds a build that was running or changed while it was copied (it seeds nothing instead, which is
 * always correct). Most cases need no Lean; the last one builds the Spyro fixture with the board's real refresh to
 * show that a finished Lake 4.35 build is seeded in full.
 */
import { spawn } from 'node:child_process';
import { existsSync, lstatSync, mkdirSync, readdirSync, readFileSync, renameSync, rmSync, statSync, utimesSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';

import { refreshLeanFacts, runExclusive } from '../../src/semantic/index.js';
import { createRunShadow } from '../../src/shadow/index.js';
import { artifactNewerThanTrace, copyBuildSeed, listBuildSeed, STALE_TEMP_MS } from '../../src/shadow/seed.js';
import { cleanupTempRoot, makeTempRoot, spyroModelFiles, spyroRoot } from '../gate/helpers.js';

/** Regular files below `dir`, as sorted relative POSIX paths ([] when `dir` does not exist). */
function filesBelow(dir: string, rel = ''): string[] {
  if (!existsSync(path.join(dir, rel))) return [];
  const out: string[] = [];
  for (const e of readdirSync(path.join(dir, rel), { withFileTypes: true })) {
    const childRel = rel === '' ? e.name : `${rel}/${e.name}`;
    if (e.isDirectory()) out.push(...filesBelow(dir, childRel));
    else if (e.isFile()) out.push(childRel);
  }
  return out.sort();
}

const T0 = new Date('2026-10-01T10:00:00Z');
const at = (seconds: number): Date => new Date(T0.getTime() + seconds * 1000);

/** Writes `<root>/.lake/build/<rel>` with the given modification time. */
function put(root: string, rel: string, text: string, mtime: Date): string {
  const file = path.join(root, '.lake', 'build', rel);
  mkdirSync(path.dirname(file), { recursive: true });
  writeFileSync(file, text);
  utimesSync(file, mtime, mtime);
  return file;
}

/** A finished Lake 4.35 build of two modules: each module's artifacts, then its hashes, then its trace (verified order). */
function finishedBuild(root: string): string[] {
  for (const [i, m] of ['Model/Spyro/Vocabulary', 'Model/Spyro/Main'].entries()) {
    const t = i * 10;
    put(root, `ir/${m}.setup.json`, `{"m":"${m}"}`, at(t));
    put(root, `lib/lean/${m}.olean`, `olean ${m}`, at(t + 1));
    put(root, `lib/lean/${m}.ilean`, `ilean ${m}`, at(t + 2));
    put(root, `ir/${m}.c`, `c ${m}`, at(t + 3));
    put(root, `lib/lean/${m}.olean.hash`, '0f1532b7cb94125d', at(t + 4));
    put(root, `lib/lean/${m}.trace`, `{"trace":"${m}"}`, at(t + 5));
  }
  return filesBelow(path.join(root, '.lake', 'build'));
}

const seededFiles = (mirror: string): string[] => filesBelow(path.join(mirror, '.lake', 'build'));

describe('seeding the build mirror (fixer round 3)', () => {
  let tmp: string;
  let n = 0;
  const runId = (): string => `seed_${++n}`;
  beforeAll(() => {
    tmp = makeTempRoot('shadow-seed');
  });
  afterAll(() => cleanupTempRoot(tmp));

  it('a finished build is seeded in full with its times; a stale temporary file of a crashed build is not copied', async () => {
    const root = spyroRoot(tmp, 'finished');
    const files = finishedBuild(root);
    const stale = put(root, 'lib/lean/Model/Spyro/Old.olean.tmp.4242', 'half an olean', at(-3600));
    expect(Date.now() - statSync(stale).mtimeMs).toBeGreaterThan(STALE_TEMP_MS);
    const shadow = await createRunShadow({ root, runsDir: path.join(tmp, 'runs'), runId: runId(), library: 'Model', files: spyroModelFiles() });
    expect(shadow.buildSeed).toEqual({ files: files.length });
    expect(seededFiles(shadow.paths.build)).toEqual(files);
    const olean = path.join(shadow.paths.build, '.lake', 'build', 'lib', 'lean', 'Model', 'Spyro', 'Main.olean');
    expect(readFileSync(olean, 'utf8')).toBe('olean Model/Spyro/Main');
    expect(statSync(olean).mtimeMs).toBe(at(11).getTime());
  });

  it('an artifact newer than its trace (a build running or interrupted) seeds nothing, and the run still gets its working copy', async () => {
    const cases: Array<[string, (root: string) => void, RegExp]> = [
      ['olean', (root) => put(root, 'lib/lean/Model/Spyro/Main.olean', 'olean of other sources', at(100)), /lib\/lean\/Model\/Spyro\/Main\.olean is newer than its trace \.lake\/build\/lib\/lean\/Model\/Spyro\/Main\.trace/u],
      ['c', (root) => put(root, 'ir/Model/Spyro/Vocabulary.c', 'c of other sources', at(100)), /ir\/Model\/Spyro\/Vocabulary\.c is newer than its trace/u],
      ['own trace', (root) => {
        put(root, 'ir/Model/Spyro/Main.c.o.export.trace', '{}', at(50));
        put(root, 'ir/Model/Spyro/Main.c.o.export', 'object', at(60));
      }, /Main\.c\.o\.export is newer than its trace/u],
    ];
    for (const [name, mutate, reason] of cases) {
      const root = spyroRoot(tmp, `busy-${name.replace(' ', '-')}`);
      finishedBuild(root);
      mutate(root);
      const shadow = await createRunShadow({ root, runsDir: path.join(tmp, 'runs'), runId: runId(), library: 'Model', files: spyroModelFiles() });
      expect(shadow.buildSeed?.files, name).toBe(0);
      expect(shadow.buildSeed?.skipped, name).toMatch(reason);
      expect(existsSync(path.join(shadow.paths.build, '.lake')), name).toBe(false);
      expect((await shadow.commits()).map((c) => c.kind)).toEqual(['base']);
      expect(filesBelow(shadow.paths.build)).toEqual([...spyroModelFiles().keys()].sort());
    }
    // Equal times are a finished build (coarse file system clocks); the artifacts and hashes are older than the trace.
    expect(artifactNewerThanTrace([{ rel: 'lib/lean/A.olean', st: { mtimeNs: 5n } }, { rel: 'lib/lean/A.trace', st: { mtimeNs: 5n } }])).toBeUndefined();
    expect(artifactNewerThanTrace([{ rel: 'lib/lean/A.olean.hash', st: { mtimeNs: 9n } }, { rel: 'lib/lean/A.trace', st: { mtimeNs: 5n } }])).toBeUndefined();
    expect(artifactNewerThanTrace([{ rel: 'lib/lean/A/B.ilean', st: { mtimeNs: 9n } }, { rel: 'lib/lean/A/B.trace', st: { mtimeNs: 5n } }])).toMatch(/A\/B\.ilean is newer/u);
  });

  it('a fresh temporary file or a Lake build lock (a build is running) seeds nothing', async () => {
    for (const [name, rel] of [
      ['temp', 'lib/lean/Model/Spyro/Main.olean.tmp'],
      ['temp-suffix', 'lib/lean/Model/Spyro/Main.olean.tmp.77'],
      ['lock', 'lake.lock'],
    ] as const) {
      const root = spyroRoot(tmp, `running-${name}`);
      finishedBuild(root);
      put(root, rel, '1234', new Date());
      const shadow = await createRunShadow({ root, runsDir: path.join(tmp, 'runs'), runId: runId(), library: 'Model', files: spyroModelFiles() });
      expect(shadow.buildSeed?.files, name).toBe(0);
      expect(shadow.buildSeed?.skipped, name).toContain(`.lake/build/${rel}`);
      expect(existsSync(path.join(shadow.paths.build, '.lake')), name).toBe(false);
    }
  });

  it('a file Lake replaces or removes between the listing and its copy seeds nothing (the ENOENT that refused the start)', async () => {
    for (const how of ['replaced', 'removed'] as const) {
      const root = spyroRoot(tmp, `between-${how}`);
      finishedBuild(root);
      const seed = await listBuildSeed(root);
      expect(seed?.files.length).toBe(12);
      const victim = path.join(root, '.lake', 'build', 'lib', 'lean', 'Model', 'Spyro', 'Main.ilean');
      rmSync(victim);
      if (how === 'replaced') {
        // The way Lake replaces an artifact: remove, write a temporary file, rename it over.
        writeFileSync(`${victim}.tmp`, 'ilean of other sources');
        renameSync(`${victim}.tmp`, victim);
      }
      const mirror = path.join(tmp, `mirror-${how}`);
      mkdirSync(mirror);
      const outcome = await copyBuildSeed(seed, mirror);
      expect(outcome.files).toBe(0);
      expect(outcome.skipped).toBe(how === 'replaced' ? '.lake/build/lib/lean/Model/Spyro/Main.ilean changed while it was copied' : '.lake/build/lib/lean/Model/Spyro/Main.ilean disappeared while it was copied');
      expect(existsSync(path.join(mirror, '.lake'))).toBe(false);
    }
  });

  it('a copied file that changes later, or a file that appears while the build is copied, seeds nothing', async () => {
    for (const how of ['rewritten', 'appeared'] as const) {
      const root = spyroRoot(tmp, `during-${how}`);
      const files = finishedBuild(root);
      const first = files[0] ?? '';
      const seed = await listBuildSeed(root);
      const mirror = path.join(tmp, `mirror-during-${how}`);
      mkdirSync(mirror);
      let done = false;
      const outcome = await copyBuildSeed(seed, mirror, {
        afterCopy: (rel) => {
          if (done || rel !== files[1]) return;
          done = true;
          // Lake writes trace and hash files in place (IO.FS.writeFile), and new artifacts appear while it builds.
          if (how === 'rewritten') writeFileSync(path.join(root, '.lake', 'build', first), 'rewritten in place');
          else put(root, 'lib/lean/Model/Spyro/New.olean', 'new', new Date());
        },
      });
      expect(done).toBe(true);
      expect(outcome).toEqual({
        files: 0,
        skipped: how === 'rewritten' ? `.lake/build/${first} changed while the build was copied` : '.lake/build/lib/lean/Model/Spyro/New.olean appeared while the build was copied',
      });
      expect(existsSync(path.join(mirror, '.lake'))).toBe(false);
    }
  });

  it('waits for telelean\'s own Lean job writing .lake/build (the board\'s refresh) and then seeds the finished build', async () => {
    const root = spyroRoot(tmp, 'refreshing');
    finishedBuild(root);
    const main = (rel: string) => path.join(root, '.lake', 'build', rel);
    let refreshDone = false;
    // A refresh rebuilding Main in place: its artifacts are deleted, rewritten after a while, and its trace comes last.
    const refresh = runExclusive(async () => {
      for (const rel of ['lib/lean/Model/Spyro/Main.olean', 'lib/lean/Model/Spyro/Main.ilean', 'ir/Model/Spyro/Main.c']) rmSync(main(rel));
      await new Promise((r) => setTimeout(r, 300));
      for (const rel of ['lib/lean/Model/Spyro/Main.olean', 'lib/lean/Model/Spyro/Main.ilean', 'ir/Model/Spyro/Main.c']) writeFileSync(main(rel), `rebuilt ${rel}`);
      writeFileSync(main('lib/lean/Model/Spyro/Main.trace'), '{"trace":"rebuilt"}');
      refreshDone = true;
    });
    const shadow = await createRunShadow({ root, runsDir: path.join(tmp, 'runs'), runId: runId(), library: 'Model', files: spyroModelFiles() });
    await refresh;
    expect(refreshDone).toBe(true);
    expect(shadow.buildSeed).toEqual({ files: 12 });
    expect(readFileSync(path.join(shadow.paths.build, '.lake', 'build', 'lib', 'lean', 'Model', 'Spyro', 'Main.olean'), 'utf8')).toBe('rebuilt lib/lean/Model/Spyro/Main.olean');
  });

  it('the race probe: while a process rewrites .lake/build the way Lake does, every start gets its working copy and no seed is partial', async () => {
    const root = spyroRoot(tmp, 'race');
    const build = path.join(root, '.lake', 'build');
    for (let i = 0; i < 10; i++) for (let j = 0; j < 40; j++) put(root, `lib/lean/d${i}/f${j}.olean`, 'x'.repeat(2048), at(0));
    const victim = put(root, 'zz/victim.olean', 'old', at(0));
    const writer = spawn('bash', ['-c', `while :; do rm -f '${victim}'; printf new > '${victim}.tmp'; mv -f '${victim}.tmp' '${victim}'; done`], { stdio: 'ignore' });
    const outcomes: string[] = [];
    try {
      await new Promise((r) => setTimeout(r, 100));
      for (let k = 0; k < 6; k++) {
        const shadow = await createRunShadow({ root, runsDir: path.join(tmp, 'runs'), runId: runId(), library: 'Model', files: spyroModelFiles() });
        const seeded = seededFiles(shadow.paths.build);
        outcomes.push(shadow.buildSeed?.skipped ?? `seeded ${shadow.buildSeed?.files}`);
        expect(seeded.filter((rel) => /\.tmp(\.|$)/u.test(rel))).toEqual([]);
        if (seeded.length > 0) {
          // A seed is a whole snapshot: every static file, and the victim complete.
          expect(seeded.length).toBe(401);
          expect(['old', 'new']).toContain(readFileSync(path.join(shadow.paths.build, '.lake', 'build', 'zz', 'victim.olean'), 'utf8'));
        } else {
          expect(shadow.buildSeed?.files).toBe(0);
          expect(shadow.buildSeed?.skipped).toMatch(/victim\.olean|\.tmp/u);
        }
        expect((await shadow.commits()).map((c) => c.kind)).toEqual(['base']);
      }
    } finally {
      writer.kill('SIGKILL');
      await new Promise((r) => writer.once('exit', r));
    }
    expect(outcomes).toHaveLength(6);
    expect(lstatSync(build).isDirectory()).toBe(true);
  });

  it('a real finished Lake build (the board\'s own refresh of the Spyro fixture) is seeded in full', async () => {
    const root = spyroRoot(tmp, 'real');
    const facts = await runExclusive(() => refreshLeanFacts({ root, runId: `seed${process.pid}` }));
    expect(facts.status).toBe('ok');
    const built = filesBelow(path.join(root, '.lake', 'build')).filter((rel) => !/\.tmp(\.|$)/u.test(rel));
    expect(built).toContain('lib/lean/Model/Spyro/Main.olean');
    expect(built).toContain('lib/lean/Model/Spyro/Main.trace');
    const shadow = await createRunShadow({ root, runsDir: path.join(tmp, 'runs'), runId: runId(), library: 'Model', files: spyroModelFiles() });
    expect(shadow.buildSeed).toEqual({ files: built.length });
    expect(seededFiles(shadow.paths.build)).toEqual(built);
  });
});

