170	function busyReason(files: readonly SeedFile[], nowMs: number): string | undefined {
171	  for (const f of files) {
172	    const name = path.posix.basename(f.rel);
173	    if (name === LAKE_LOCK) return `Lake's build lock ${shown(f.rel)} exists (a build is running)`;
174	    if (TEMP_NAME.test(name) && nowMs - Number(f.st.mtimeMs) < STALE_TEMP_MS) return `${shown(f.rel)} is being written (a build is running)`;
