180	  const later = new Map(b.map((f) => [f.rel, f]));
181	  for (const f of a) {
182	    const now = later.get(f.rel);
183	    if (now === undefined) return `${shown(f.rel)} disappeared while the build was copied`;
184	    if (!sameFile(f.st, now.st)) return `${shown(f.rel)} changed while the build was copied`;
185	    later.delete(f.rel);
