 * 1.140, workbench.desktop.main.js: `"vscode-"+v.id.replace(".","-")`). The ids therefore have exactly one dot:
 * telelean.formalizedAura -> --vscode-telelean-formalizedAura. (test/unit/theme.test.ts checks this file against
 * the manifest; the fallbacks are the ids' default values, for the Chrome test harness.)
 */
:root {
  --tl-gap: 56px;
  /* Columns never get narrower than this: a narrower board (a file opened beside it) scrolls sideways instead. */
  --tl-col-min: 220px;
  --tl-kind-a: var(--vscode-telelean-kindAssumption, var(--vscode-charts-purple));
  --tl-kind-d: var(--vscode-telelean-kindDerivation, var(--vscode-charts-green));
  --tl-kind-g: var(--vscode-telelean-kindGoal, var(--vscode-charts-orange));
  --tl-aura: var(--vscode-telelean-formalizedAura, var(--vscode-charts-blue));
  /* M1 colours (contributed by the extension; the fallbacks serve the Chrome test harness and older hosts). */
  --tl-vocab: var(--vscode-telelean-vocabulary, var(--vscode-textLink-foreground, #3794ff));
  --tl-highlight: var(--vscode-telelean-highlight, var(--vscode-editor-findMatchHighlightBackground, rgba(234, 92, 0, 0.33)));
  --tl-edge: color-mix(in srgb, var(--vscode-foreground) 50%, transparent);
  --tl-edge-focus: var(--vscode-focusBorder);
  --tl-warn: var(--vscode-editorWarning-foreground, #cca700);
  --tl-error: var(--vscode-errorForeground, #f48771);
  --tl-info: var(--vscode-editorInfo-foreground, #3794ff);
  /* M2 proposal diff marks (03 section 7: colour + glyph + halo, never colour alone): VS Code's own git colours. */
  --tl-diff-added: var(--vscode-gitDecoration-addedResourceForeground, #81b88b);
  --tl-diff-changed: var(--vscode-gitDecoration-modifiedResourceForeground, #e2c08d);
  --tl-diff-removed: var(--vscode-gitDecoration-deletedResourceForeground, #c74e39);
  /* The run panel's width beside the board. */
  --tl-run-width: clamp(320px, 32vw, 460px);
}
[data-diff='added'] { --tl-diff: var(--tl-diff-added); }
[data-diff='changed'] { --tl-diff: var(--tl-diff-changed); }
[data-diff='removed'] { --tl-diff: var(--tl-diff-removed); }

[data-kind='ASSUMPTION'] { --tl-kind: var(--tl-kind-a); }
[data-kind='DERIVATION'] { --tl-kind: var(--tl-kind-d); }
