        { kind: 'callTool', tool: 'ask_user', args: { questions: [Q_MODALITY, Q_GENERIC, Q_SENSE] } },
        ...after,
      ],
    },
  ];
}

/** The normative edits and calls without the question (formalise, check, freeze, prove, check, finish). */
function normativeWork(summary = 'Proved from the three premises under the normative reading.'): any[] {
  const base: any[] = fixture('normative').turns[0].steps;
  return base
    .filter((s) => s.kind === 'edit' || (s.kind === 'callTool' && s.tool !== 'ask_user'))
    .map((s) => (s.kind === 'callTool' && s.tool === 'finish' ? { ...s, args: { ...s.args, summary } } : s));
}

const FEEDBACK_TURN = {
  match: 'Feedback from the person on your previous result',
  steps: [
    { kind: 'text', text: 'I checked the statements again; they stay as they are.' },
    { kind: 'callTool', tool: 'check_lean', args: {} },
    { kind: 'callTool', tool: 'freeze_statements', args: { targets: [TARGET] } },
    { kind: 'callTool', tool: 'finish', args: { status: 'proved', summary: 'Re-frozen unchanged; the proof still holds.', assumed_without_asking: [] } },
    { kind: 'result' },
  ],
};

class ScriptedClaude {
  readonly id = 'fake' as const;
  readonly caps = { builtinFileTools: true, subscriptionAuth: false, resume: true, interrupt: true };
  readonly sessions: any[] = [];
  player: any;
  private backend: FakeBackend | undefined;
  use(turns: any[]): any {
    const player = playFakeScript(turns);
    this.player = player;
    this.backend = new FakeBackend(player.script);
    this.sessions.length = 0;
    return player;
  }
  async startSession(cfg: any): Promise<any> {
    if (!this.backend) throw new Error('no FakeBackend script installed');
    this.sessions.push(cfg);
    return this.backend.startSession(cfg);
  }
}

