  async function shoot(name: string, opts: { panel?: boolean; themes?: Array<'light' | 'dark' | 'hc'>; element?: string } = {}): Promise<void> {
    const themes = opts.themes ?? ['light', 'dark'];
    const n = String(++shotN).padStart(2, '0');
