        if (opts.element) {
          const el = (await frame()).locator(opts.element).first();
          if ((await el.count()) > 0) await el.screenshot({ path: `${base}-el.png` }).catch((e: unknown) => obs('element-shot-failed', String(e)));
        }
      } catch (error) {
        obs('shot-failed', { name, theme, error: String(error) });
