// Drives the Development-mode instance over CDP (loopback): opens the board, presses "These suffice", looks at the
// consent modal (Cancel, then Run with Claude), and records what the board says when Claude cannot be started
// (TELELEAN_NO_REAL_CLAUDE=1, no binary anywhere). usage: node drive.mjs <port> <outdir>
import { chromium } from '/home/zhengyew/telelean/node_modules/playwright-core/index.mjs';
import { appendFileSync, mkdirSync } from 'node:fs';
import * as path from 'node:path';

const [port, out] = process.argv.slice(2);
mkdirSync(out, { recursive: true });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const log = (key, value) => {
  appendFileSync(path.join(out, 'drive.jsonl'), `${JSON.stringify({ t: new Date().toISOString(), key, value })}\n`);
  console.log(key, typeof value === 'string' ? value.slice(0, 600) : JSON.stringify(value).slice(0, 600));
};

let browser;
for (let i = 0; ; i++) {
  try {
    browser = await chromium.connectOverCDP(`http://127.0.0.1:${port}`);
    break;
  } catch (e) {
    if (i > 120) throw e;
    await sleep(500);
  }
}
let page;
for (let i = 0; !page; i++) {
  page = browser.contexts().flatMap((c) => c.pages()).find((p) => p.url().includes('workbench.html'));
  if (!page) await sleep(250);
  if (i > 200) throw new Error('no workbench');
}
page.setDefaultTimeout(30_000);
await sleep(6000);
const shot = async (name) => page.screenshot({ path: path.join(out, `${name}.png`) });
// Clear startup toasts
await page.keyboard.press('Escape');

async function palette(cmd) {
  await page.keyboard.press('F1');
  const input = page.locator('.quick-input-widget input');
  await input.waitFor();
  await input.fill(`>${cmd}`);
  await sleep(600);
  await page.keyboard.press('Enter');
}
async function board() {
  for (let i = 0; i < 160; i++) {
    for (const f of page.frames()) {
      if (f.isDetached() || !f.url().includes('fake.html')) continue;
      try {
        if ((await f.locator('.tl-app [data-testid="subject-picker"]').count()) > 0) return f;
      } catch {}
    }
    await sleep(250);
  }
  throw new Error('no board');
}

await palette('telelean: Open Board');
const f = await board();
// wait for Lean fresh: the Lean badge says up to date
for (let i = 0; i < 240; i++) {
  const t = await f.locator('.tl-app').innerText().catch(() => '');
  if (/up to date/.test(t)) break;
  await sleep(500);
}
await shot('d01-board');
const ids = ['cynder-dark-past', 'new-spyro-pg', 'pg-no-dark-past', 'cynder-not-good'];
for (const [i, id] of ids.entries()) await f.locator(`[data-node-id="${id}"]`).click(i === 0 ? {} : { modifiers: ['Control'] });
await sleep(400);
log('tray', await f.locator('.tl-tray').innerText());

async function dialogText() {
  const d = page.locator('.monaco-dialog-box');
  for (let i = 0; i < 40 && (await d.count()) === 0; i++) await sleep(250);
  return (await d.count()) > 0 ? await d.innerText() : null;
}
async function toasts() {
  return f.getByTestId('toast').allInnerTexts().catch(() => []);
}

// 1. These suffice -> the modal; Cancel
await f.getByTestId('tray-these-suffice').click();
const t1 = await dialogText();
log('consent-dialog-1', t1);
await shot('d02-consent-dialog');
if (t1 !== null) {
  const buttons = await page.locator('.monaco-dialog-box .dialog-buttons a, .monaco-dialog-box .dialog-buttons button').allInnerTexts();
  log('consent-buttons', buttons);
  await page.locator('.monaco-dialog-box').getByRole('button', { name: 'Cancel' }).click();
}
await sleep(1500);
log('after-cancel-toasts', await toasts());
await shot('d03-after-cancel');

// 2. Again: asked again (Cancel is not remembered); Run with Claude
await f.getByTestId('tray-these-suffice').click();
const t2 = await dialogText();
log('consent-dialog-2', t2);
if (t2 !== null) await page.locator('.monaco-dialog-box').getByRole('button', { name: 'Run with Claude' }).click();
for (let i = 0; i < 60; i++) {
  if ((await toasts()).length > 0) break;
  await sleep(250);
}
await sleep(1500);
log('after-run-with-claude-toasts', await toasts());
log('panel', await f.getByTestId('run-panel').innerText().catch(() => '(no run panel)'));
log('tray-after', await f.locator('.tl-tray').innerText().catch(() => ''));
await shot('d04-after-run-with-claude');

// 3. Third time: remembered (no modal)
await f.getByTestId('toast').locator('button').first().click().catch(() => undefined);
await f.getByTestId('tray-these-suffice').click().catch((e) => log('third-click-failed', String(e)));
const t3 = await dialogText();
log('consent-dialog-3', t3);
await sleep(2000);
log('third-toasts', await toasts());
await shot('d05-third');
await browser.close();

