test('02 normative with 3 questions, wide: questions, review, report card; Accept; Undo', async function () {
  this.timeout(LEAN_TIMEOUT_MS * 4);
  claude.use(normative3q());
  api.testing.answerPrompts({ claudeConsent: true });
  const before = files();
  await startFromTray();
  const f = await frame();
  await waitFor(() => run()?.state === 'working' && (run()?.activity ?? []).some((a: any) => /check how the rule is meant/.test(a.text)), LEAN_TIMEOUT_MS, `working (${runText()})`, 100);
  await sleep(600);
  await shoot('wide-working', { panel: true });
  const set = f.getByTestId('question-set');
  await waitFor(async () => (await set.count()) > 0, LEAN_TIMEOUT_MS, `questions (${runText()})`, 200);
  await sleep(500);
  await shoot('wide-questions', { panel: true });
  const qs = set.getByTestId('question');
  await qs.nth(0).getByTestId('option-free-text').click();
  await qs.nth(0).getByTestId('free-text').fill('I mean it as a rule: PG games should not include characters with dark pasts.');
  await qs.nth(1).getByTestId('option-leave-open').click();
  await qs.nth(2).getByTestId('option-decide-for-me').click();
  await qs.nth(2).locator('[data-scope="subject"] input').check();
  await set.getByTestId('send-answers').click();
  await waitFor(() => (run()?.answered ?? []).length === 3, UI_TIMEOUT_MS, 'answered');
  await sleep(500);
  await shoot('wide-answered', { panel: true, themes: ['light'] });
  await waitForReview(1);
  // Where is the review in the panel after the questions were answered?
  const reviewBox = await f.getByTestId('review').boundingBox().catch(() => null);
  const panelBox = await f.getByTestId('run-panel').boundingBox().catch(() => null);
  const scrollTop = await f.locator('.tl-run__body').evaluate((el: any) => el.scrollTop).catch(() => null);
  obs('review-visibility', { reviewBox, panelBox, scrollTop });
  await shoot('wide-review-statement', { panel: true });
  const card = (await frame()).locator('[data-node-id="pg-no-dark-past"]');
  obs('wide-pg-card-box', await card.boundingBox().catch(() => null));
  await shoot('wide-pg-card-diff', { element: '[data-node-id="pg-no-dark-past"]', themes: ['light', 'dark'] });
  await reviewStep('result');
  await shoot('wide-report-card', { panel: true });
  await reviewStep('lifecycle');
  await shoot('wide-lifecycle', { panel: true, themes: ['light'] });
  // Hide the panel, show it again with the badge.
  await f.getByRole('button', { name: 'Hide the run panel' }).click();
  await sleep(400);
  obs('panel-hidden', { panel: await f.getByTestId('run-panel').count(), badge: await text(f.getByTestId('run-badge')) });
  await shoot('wide-panel-hidden', { themes: ['light'] });
  await f.getByTestId('run-badge').click();
  await sleep(400);
  check('the badge shows the panel again', (await f.getByTestId('run-panel').count()) === 1);
  await f.getByTestId('banner-accept').click();
  await waitFor(() => run()?.state === 'accepted', LEAN_TIMEOUT_MS, `accepted (${runText()})`, 250);
  await waitFresh('accepted');
  await sleep(600);
  await shoot('wide-accepted', { panel: true, themes: ['light'] });
  await (await frame()).locator('button.tl-icon-button--toolbar[aria-label="Undo"]').click();
  await waitFor(() => read(MAIN) === before[MAIN], UI_TIMEOUT_MS, 'Undo byte-exact', 100);
  await waitFresh('undo');
  await dismissEnded('accepted');
});

