test('01 a start while the user files have a Lean error: failed, nothing sent, how the board says it', async function () {
  this.timeout(LEAN_TIMEOUT_MS * 2);
  claude.use(fixture('normative').turns);
  const before = files();
  const broken = before[MAIN].replace('end Spyro', 'theorem broken_by_probe : 1 = 2 := rfl\n\nend Spyro');
  writeFileSync(path.join(ROOT, ...MAIN.split('/')), broken);
  await waitFor(() => latestGraph?.semantic.state === 'fresh' && (latestGraph?.diagnostics ?? []).some((d: any) => d.code === 'LEAN' || d.severity === 'error'), LEAN_TIMEOUT_MS, 'the board to see the Lean error', 250).catch((e: unknown) => obs('lean-error-wait', String(e)));
  const f = await frame();
  obs('board-with-error', { badge: await text(f.locator('.tl-lean-badge').first()), tray: await text(f.locator('.tl-tray')) });
  let started = true;
  try {
    await startFromTray();
  } catch (error) {
    started = false;
    obs('start-with-error-refused', { error: String(error), toasts: await toasts(), tray: await text(f.locator('.tl-tray')) });
  }
  if (started) {
    await waitFor(() => run()?.state === 'failed' || run()?.state === 'working', LEAN_TIMEOUT_MS, `failed (${runText()})`, 250);
    await sleep(800);
    obs('failed-run', { state: run()?.state, error: run()?.error, notices: run()?.notices, sessions: claude.sessions.length, panel: await panelText(), toasts: await toasts() });
    check('a base with Lean errors ends the run before any session', run()?.state === 'failed' && claude.sessions.length === 0, { state: run()?.state, sessions: claude.sessions.length });
    await shoot('failed-base-error', { panel: true });
    if (run()?.state === 'failed') await dismissEnded('failed');
  }
  writeFileSync(path.join(ROOT, ...MAIN.split('/')), before[MAIN]);
  await sleep(1500);
  await waitFor(() => latestGraph?.semantic.state === 'fresh' && !(latestGraph?.diagnostics ?? []).some((d: any) => d.severity === 'error'), LEAN_TIMEOUT_MS, 'clean again', 250).catch((e: unknown) => obs('clean-wait', String(e)));
});

test('02 drift far from Claude: Accept merges and keeps the user edit', async function () {
  this.timeout(LEAN_TIMEOUT_MS * 3);
  claude.use(fixture('normative').turns);
  const before = files();
  await startFromTray();
  const f = await frame();
  const set = f.getByTestId('question-set');
  await waitFor(async () => (await set.count()) > 0, LEAN_TIMEOUT_MS, 'question');
  await set.getByTestId('option').nth(0).click();
  await set.getByTestId('send-answers').click();
  await waitForReview(1);
  const edited = read(MAIN).replace('rationale: known from gaming news', 'rationale: known from gaming news sites');
  writeFileSync(path.join(ROOT, ...MAIN.split('/')), edited);
  await sleep(2500);
  obs('drift-merge-review-note', await text(f.getByTestId('review-base-changed')));
  await f.getByTestId('banner-accept').click();
  await waitFor(() => run()?.state === 'accepted' || (run()?.state === 'review' && (posted.at(-1)?.payload?.outcome?.ok === false)), LEAN_TIMEOUT_MS, `accept outcome (${runText()})`, 250);
  await sleep(1500);
  const main = read(MAIN);
  obs('drift-merge', { state: run()?.state, toasts: await toasts(), keptUserEdit: main.includes('gaming news sites'), hasProof: main.includes('theorem cynder_not_good.holds'), lastOutcome: posted.at(-1) });
  check('drift merge: Accept keeps the user edit and applies Claude changes', run()?.state === 'accepted' && main.includes('gaming news sites') && main.includes('theorem cynder_not_good.holds'));
  await shoot('drift-merge-accepted', { panel: true, themes: ['light'] });
  if (run()?.state === 'accepted') {
    await waitFresh('merge accepted');
    await (await frame()).locator('button.tl-icon-button--toolbar[aria-label="Undo"]').click();
    await waitFor(() => read(MAIN) === edited, UI_TIMEOUT_MS, 'Undo back to the user edit', 100).catch((e: unknown) => obs('merge-undo', String(e)));
    obs('merge-undo-state', { backToUserEdit: read(MAIN) === edited });
    await dismissEnded('accepted');
  }
  writeFileSync(path.join(ROOT, ...MAIN.split('/')), before[MAIN]);
  await sleep(1500);
  await waitFresh('restored');
});

test('03 drift next to Claude change: Accept refused as a conflict; files keep the user edit only', async function () {
  this.timeout(LEAN_TIMEOUT_MS * 3);
  claude.use(fixture('normative').turns);
  const before = files();
  await startFromTray();
  const f = await frame();
  const set = f.getByTestId('question-set');
  await waitFor(async () => (await set.count()) > 0, LEAN_TIMEOUT_MS, 'question');
  await set.getByTestId('option').nth(0).click();
  await set.getByTestId('send-answers').click();
  await waitForReview(1);
  const edited = read(MAIN).replace('stance: rule\n', 'stance: rule\nsource: common\n');
  writeFileSync(path.join(ROOT, ...MAIN.split('/')), edited);
  await sleep(2500);
  await f.getByTestId('banner-accept').click();
  await sleep(4000);
  obs('drift-conflict', { state: run()?.state, toasts: await toasts(), filesAreUserEdit: read(MAIN) === edited, lastOutcome: posted.at(-1) });
  check('conflict: Accept refused, files untouched beyond the user edit', run()?.state === 'review' && read(MAIN) === edited);
  await shoot('drift-conflict', { panel: true, themes: ['light'] });
  await f.getByTestId('banner-discard').click();
  await dismissEnded('discarded');
  writeFileSync(path.join(ROOT, ...MAIN.split('/')), before[MAIN]);
  await sleep(1500);
  await waitFresh('restored');
});

