/** The files of the user's `.lake/build` (relative to it), or [] when there is none; any symlink or special file refuses. */
async function collectBuildSeed(root: string): Promise<string[]> {
  const lake = path.join(root, '.lake');
  const buildDir = path.join(lake, 'build');
  if (!(await isRealDirectory(lake)) || !(await isRealDirectory(buildDir))) return [];
  const files: string[] = [];
  const refused: string[] = [];
  const stack = [''];
  while (stack.length > 0) {
    const rel = stack.pop() ?? '';
    for (const entry of await readdir(path.join(buildDir, rel), { withFileTypes: true })) {
      const childRel = rel === '' ? entry.name : `${rel}/${entry.name}`;
      if (entry.isSymbolicLink()) refused.push(`.lake/build/${childRel}`);
      else if (entry.isDirectory()) stack.push(childRel);
      else if (entry.isFile()) files.push(childRel);
      else refused.push(`.lake/build/${childRel}`);
    }
  }
  if (refused.length > 0) {
    refused.sort();
    throw new ShadowLayoutError('not-regular', `refusing to seed the build mirror: .lake/build holds symlinks or special files: ${refused.join(', ')}`, refused);
  }
  return files.sort();
}

