        expect(ok, JSON.stringify(ok)).toMatchObject({ ok: true });
      }
      w.manager.dispose();
      noLeftoverUnits(review.runId);
      expect(existsSync(path.join(w.root, '.telelean'))).toBe(true);
    });
  }
});

