// Probe: does SIGKILLing `systemd-run --user --scope` while it waits for its scope job leave an empty scope that
// stays "active running"? (The leftover telelean-tlws1979697_2_1-23.scope was started 4 ms after its refresh was
// aborted.) Units are named fix3probe-<pid>-<i> (never telelean-*, so no smoke run of another builder sees them)
// and are all stopped at the end. The scope runs `sleep 20` only.
import { spawn, spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const N = Number(process.argv[2] ?? 40);
const prefix = `fix3probe-${process.pid}`;
const show = (unit) => {
  const out = spawnSync('systemctl', ['--user', 'show', `${unit}.scope`, '-p', 'ActiveState', '-p', 'SubState', '-p', 'ControlGroup', '-p', 'TasksCurrent', '-p', 'LoadState'], { encoding: 'utf8' }).stdout;
  return Object.fromEntries(out.trim().split('\n').map((l) => [l.slice(0, l.indexOf('=')), l.slice(l.indexOf('=') + 1)]));
};
const populated = (cg) => {
  try {
    return /populated 1/.test(readFileSync(`/sys/fs/cgroup${cg}/cgroup.events`, 'utf8'));
  } catch {
    return undefined;
  }
};

const results = [];
for (let i = 0; i < N; i++) {
  const unit = `${prefix}-${i}`;
  const delay = i % 8; // 0..7 ms after the spawn
  const child = spawn('systemd-run', ['--user', '--scope', '--quiet', `--unit=${unit}`, '--', 'sleep', '20'], { stdio: 'ignore' });
  await new Promise((r) => setTimeout(r, delay));
  child.kill('SIGKILL');
  await new Promise((r) => child.on('close', r));
  await new Promise((r) => setTimeout(r, 300));
  const p = show(unit);
  results.push({ unit, delay, ...p, populated: p.ControlGroup ? populated(p.ControlGroup) : undefined });
}
// Give systemd time to notice anything it is going to notice.
await new Promise((r) => setTimeout(r, 2000));
const final = results.map((r) => ({ ...r, after2s: show(r.unit) }));
const stuck = final.filter((r) => r.after2s.ActiveState === 'active');
for (const r of final) {
  const p = r.after2s;
  console.log(`${r.unit} delay=${r.delay}ms: ${p.LoadState} ${p.ActiveState} ${p.SubState} tasks=${p.TasksCurrent} cgroup=${p.ControlGroup ? 'yes' : 'none'} populated=${r.populated}`);
}
console.log(`\n${stuck.length} of ${N} scopes still active after 2.3 s; ${stuck.filter((r) => r.populated === false).length} of them with an empty cgroup`);
// Clean up every probe unit (stop, then reset-failed).
spawnSync('systemctl', ['--user', 'stop', `${prefix}-*`], { stdio: 'inherit' });
spawnSync('systemctl', ['--user', 'reset-failed', `${prefix}-*`], { stdio: 'ignore' });
const left = spawnSync('systemctl', ['--user', 'list-units', '--all', '--plain', '--no-legend', '--no-pager', `${prefix}-*`], { encoding: 'utf8' }).stdout.trim();
console.log(`left after cleanup: ${left || '(none)'}`);

