describe('which telelean-* units are the smoke run’s', () => {
  const owners: Owners = { hostPids: new Set([1979697, 1982112]), runIds: new Set(['rmvy6qjztb18158']) };

  it("claims the refresh scopes and default-run scopes of this run's extension hosts, and its Claude runs' scopes", () => {
    // The scope the verifier found left behind: refresh 1 of the 2nd workspace of extension host 1979697, unit 23.
    expect(ownerOf('telelean-tlws1979697_2_1-23.scope', owners)).toBe('run id tlws1979697_2_1, from extension host 1979697 of this run');
    expect(ownerOf('telelean-tlws1982112_14_3-140.scope', owners)).toContain('extension host 1982112');
    expect(ownerOf('telelean-p1979697-5.scope', owners)).toBe('run id p1979697, from extension host 1979697 of this run');
    expect(ownerOf('telelean-rmvy6qjztb18158-21.scope', owners)).toBe('run id rmvy6qjztb18158, a Claude run of this run');
  });

  it('leaves every other unit to whoever made it', () => {
    for (const unit of [
      'telelean-tlws4242_1_1-3.scope', // another process's workspace
      'telelean-tlws197969_2_1-23.scope', // a prefix of a host pid is not that pid
      'telelean-tlws19796971_2_1-23.scope',
      'telelean-p4242-1.scope', // another process's default run id
      'telelean-rsomeoneelse1-4.scope', // a run that is not this run's
      'telelean-tlws1979697_2_1.scope', // no unit counter: not runLean's naming
      'telelean-tlws1979697_2_1-23.service',
      'telelean-tlws1979697-23.scope', // not a refresh run id
      'other-tlws1979697_2_1-23.scope',
    ]) {
      expect(ownerOf(unit, owners), unit).toBeUndefined();
    }
  });

  it('fails on a unit of this run that still runs a process, stops an empty one, and keeps the rest', () => {
    const owner = 'run id tlws1979697_2_1, from extension host 1979697 of this run';
    expect(action({ ownProcess: true, owner: undefined, populated: true })).toBe('fail');
    expect(action({ ownProcess: false, owner, populated: true })).toBe('fail');
    expect(action({ ownProcess: true, owner, populated: true })).toBe('fail');
    // The leftover from the report: active running, no task, cgroup.events "populated 0".
    expect(action({ ownProcess: false, owner, populated: false })).toBe('stop');
    expect(action({ ownProcess: false, owner: undefined, populated: false })).toBe('keep');
    expect(action({ ownProcess: false, owner: undefined, populated: true })).toBe('keep');
  });
});

// End-to-end check of smoke.mjs's new leftover-unit handling. Waits for the first test instance's extension host (the
// "Extension host with pid N started" line in the smoke profile's exthost.log), then makes an empty "active running"
// scope named like a refresh scope of that host, telelean-tlws<N>_99_<k>-99<k>.scope, the way the runner leaves one:
// systemd-run is SIGKILLed while it waits for its scope job, and the killed process is not reaped at once. smoke.mjs
// must claim it as the run's (from the host pid in its logs), stop it and print a WARN line. The scope only ever gets
// `sleep 20`.
//   node inject-stuck-scope.mjs <TELELEAN_TEST_TMP of the smoke run>
import { spawn, spawnSync } from 'node:child_process';
import { readdirSync, readFileSync } from 'node:fs';
import path from 'node:path';

const base = process.argv[2];
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const deadline = Date.now() + 180_000;
let pid;
while (pid === undefined && Date.now() < deadline) {
  for (const profile of readdirSync(base).filter((n) => n.startsWith('vscode-'))) {
    const logs = path.join(base, profile, 'user-data', 'logs');
    let sessions = [];
    try {
      sessions = readdirSync(logs);
    } catch {
      continue;
    }
    for (const session of sessions) {
      try {
        const match = /Extension host with pid (\d+) started/.exec(readFileSync(path.join(logs, session, 'window1', 'exthost', 'exthost.log'), 'utf8'));
        if (match) pid = Number(match[1]);
      } catch {
        // not there yet
      }
    }
  }
  if (pid === undefined) await sleep(250);
}
if (pid === undefined) {
  console.log('no extension host found');
  process.exit(1);
}
console.log(`extension host pid ${pid}`);
const show = (unit) => {
  const out = spawnSync('systemctl', ['--user', 'show', unit, '-p', 'ActiveState', '-p', 'SubState', '-p', 'TasksCurrent', '-p', 'ControlGroup'], { encoding: 'utf8' }).stdout ?? '';
  return Object.fromEntries(out.trim().split('\n').map((l) => [l.slice(0, l.indexOf('=')), l.slice(l.indexOf('=') + 1)]));
};
for (let k = 1; k <= 30; k++) {
  const unit = `telelean-tlws${pid}_99_${k}-99${k}.scope`;
  const child = spawn('systemd-run', ['--user', '--scope', '--quiet', `--unit=${unit}`, '--description=fix3 check: empty scope for the smoke leftover check', '--', 'sleep', '20'], { stdio: 'ignore' });
  await sleep(9 + (k % 10));
  child.kill('SIGKILL');
  const until = Date.now() + 100; // keep the killed systemd-run unreaped for a while, as a busy host does
  while (Date.now() < until);
  await new Promise((r) => child.on('close', r));
  await sleep(500);
  const p = show(unit);
  let populated = '?';
  try {
    populated = /populated 1/.test(readFileSync(`/sys/fs/cgroup${p.ControlGroup}/cgroup.events`, 'utf8')) ? '1' : '0';
  } catch {
    // no cgroup
  }
  console.log(`${unit}: ${p.ActiveState} ${p.SubState} tasks=${p.TasksCurrent} populated=${populated}`);
  if (p.ActiveState === 'active' && populated === '0') {
    console.log(`STUCK ${unit}`);
    break;
  }
  // Not the case under test: clean it up at once.
  if (p.ActiveState === 'failed') spawnSync('systemctl', ['--user', 'reset-failed', unit], { stdio: 'ignore' });
  else if (p.ActiveState === 'active') spawnSync('systemctl', ['--user', 'stop', unit], { stdio: 'ignore' });
}

