51	/**
52	 * Decide one PreToolUse call.
53	 * @param {import('./telelean-path-guard.mjs').HookInput} input
54	 * @param {import('./telelean-path-guard.mjs').GuardPolicy} policy
55	 * @param {Partial<import('./telelean-path-guard.mjs').GuardFs>} [fsImpl]
56	 * @returns {import('./telelean-path-guard.mjs').GuardDecision}
57	 */
58	export function decide(input, policy, fsImpl = {}) {
59	  const toolName = typeof input?.tool_name === 'string' ? input.tool_name : '';
60	  const toolInput = isRecord(input?.tool_input) ? input.tool_input : {};
61	  const base = { tool: toolName, checked: [] };
62	
63	  if (input?.hook_event_name !== undefined && input.hook_event_name !== 'PreToolUse') {
64	    return { ...base, kind: 'pass', reason: `not a PreToolUse event (${String(input.hook_event_name)})` };
65	  }
66	  if (toolName === '') {
67	    return { ...base, kind: 'deny', reason: 'hook input has no tool_name' };
68	  }
69	  for (const prefix of policy.passthroughToolPrefixes ?? []) {
70	    if (toolName.startsWith(prefix)) return { ...base, kind: 'pass', reason: `telelean tool (${prefix}*)` };
71	  }
72	  if ((policy.passthroughTools ?? []).includes(toolName)) {
73	    return { ...base, kind: 'pass', reason: 'tool listed as passthrough' };
74	  }
75	
76	  const ctx = makeContext(policy, input, { ...defaultFs, ...fsImpl });
77	  try {
78	    if (PATH_TOOLS.has(toolName)) {
79	      base.checked.push(checkPath(ctx, 'file_path', toolInput.file_path, { required: true }));
80	    } else if (toolName === 'Glob') {
81	      // Glob passes its pattern to ripgrep as one --glob argument.
82	      checkPattern(ctx, 'pattern', toolInput.pattern, { required: true, negatable: false });
83	      const scope = checkPath(ctx, 'path', toolInput.path, { required: false });
84	      base.checked.push(scope);
85	      assertNoHiddenInScope(ctx, toolName, scope);
86	    } else if (toolName === 'Grep') {
87	      const scope = checkPath(ctx, 'path', toolInput.path, { required: false });
88	      base.checked.push(scope);
89	      for (const token of grepGlobTokens(toolInput.glob)) {
90	        checkPattern(ctx, 'glob', token, { required: false, negatable: true });
91	      }
92	      assertNoHiddenInScope(ctx, toolName, scope);
93	    } else if (policy.unknownTools === 'pass') {
94	      return { ...base, kind: 'pass', reason: 'unknown tool passed through by policy' };
95	    } else {
96	      return { ...base, kind: 'deny', reason: `telelean does not allow the ${toolName} tool in this run` };
97	    }
98	  } catch (err) {
99	    if (err instanceof GuardDenial) {
100	      return { ...base, kind: 'deny', reason: `telelean confinement: ${toolName} ${err.message}` };
101	    }
102	    throw err;
103	  }
104	  return { ...base, kind: 'pass', reason: 'inside the workspace copy' };
105	}
