54	 */
55	export function buildBwrapArgs(profile: SandboxProfile, argv: readonly string[]): string[] {
56	  if (argv.length === 0) throw new TypeError('argv must not be empty');
57	  assertAbsolute('home', profile.home);
58	  assertAbsolute('elanHome', profile.elanHome);
59	  assertAbsolute('toolchainBin', profile.toolchainBin);
60	  assertAbsolute('shadowDir', profile.shadowDir);
61	  if (profile.packagesDir !== undefined) assertAbsolute('packagesDir', profile.packagesDir);
62	  for (const p of profile.roBinds ?? []) assertAbsolute('roBinds entry', p);
63	  for (const p of profile.rwBinds ?? []) assertAbsolute('rwBinds entry', p);
64	  for (const p of profile.maskPaths ?? []) assertAbsolute('maskPaths entry', p);
65	
66	  const shadow = path.resolve(profile.shadowDir);
67	  const dotLake = path.join(shadow, '.lake');
68	  const args: string[] = [
69	    // System, read-only. Merged-/usr layout: /lib, /lib64 and /bin are symlinks into /usr.
70	    '--ro-bind', '/usr', '/usr',
71	    '--ro-bind', '/etc', '/etc',
72	    '--symlink', 'usr/lib', '/lib',
73	    '--symlink', 'usr/lib64', '/lib64',
74	    '--symlink', 'usr/bin', '/bin',
75	    '--proc', '/proc',
76	    '--dev', '/dev',
77	    // Fresh, empty filesystems: no host /tmp, no host /run (D-Bus, keyring, Wayland), no host $HOME.
