86	  for (const p of profile.roBinds ?? []) args.push('--ro-bind', p, p);
87	  args.push('--ro-bind', shadow, shadow, '--bind', dotLake, dotLake);
88	  if (profile.packagesDir !== undefined) {
89	    args.push('--ro-bind', profile.packagesDir, path.join(dotLake, 'packages'));
90	  }
91	  for (const p of profile.rwBinds ?? []) args.push('--bind', p, p);
92	  for (const p of profile.maskPaths ?? []) args.push('--tmpfs', p);
93	  args.push(
94	    '--chdir', shadow,
95	    '--unshare-all', // user, ipc, pid, net (loopback only), uts, cgroup
96	    '--die-with-parent',
97	    '--new-session',
98	    '--clearenv',
99	    '--setenv', 'HOME', profile.home,
100	    '--setenv', 'PATH', sandboxPath(profile.toolchainBin),
101	  );
102	  for (const [name, value] of Object.entries(profile.env ?? {})) {
103	    if (!ENV_NAME.test(name)) throw new TypeError(`invalid environment variable name ${JSON.stringify(name)}`);
104	    if (name === 'HOME' || name === 'PATH') throw new TypeError(`${name} is fixed by the sandbox profile`);
