// Verifier probe of telelean's PreToolUse path guard (packages/runner/bin/telelean-path-guard.mjs).
// Builds a scratch run dir shaped like a real run (<runDir>/{ws,build,git,session}) and checks decisions for
// symlinks, '..', hidden files, Grep/Glob roots and patterns, plus the real hook process end to end.
import { spawnSync } from 'node:child_process';
import { mkdirSync, rmSync, symlinkSync, writeFileSync, realpathSync } from 'node:fs';
import path from 'node:path';

const GUARD = '/home/zhengyew/telelean/packages/runner/bin/telelean-path-guard.mjs';
const { decide, loadPolicy } = await import(GUARD);

const base = process.argv[2];
rmSync(base, { recursive: true, force: true });
const runDir = path.join(base, 'runs', 'mental_model-abcdef12', 'r1');
const ws = path.join(runDir, 'ws');
const session = path.join(runDir, 'session');
for (const d of [ws, path.join(runDir, 'build', '.lake'), path.join(runDir, 'git'), session, path.join(ws, 'Model', 'Spyro')]) mkdirSync(d, { recursive: true });
writeFileSync(path.join(ws, 'Model', 'Spyro', 'Main.lean'), '-- main\n');
writeFileSync(path.join(ws, 'Model.lean'), 'import Model.Spyro.Main\n');
writeFileSync(path.join(session, 'mcp-config.json'), '{"secret":"bearer"}\n');
writeFileSync(path.join(base, 'outside.txt'), 'outside\n');
const wsReal = realpathSync(ws);
const policy = {
  version: 1,
  root: wsReal,
  hiddenSegments: ['.lake', '.telelean', '.git'],
  denyDotSegments: true,
  passthroughToolPrefixes: ['mcp__telelean__'],
  unknownTools: 'deny',
  logFile: path.join(session, 'guard-log.jsonl'),
};
const policyPath = path.join(session, 'guard-policy.json');
writeFileSync(policyPath, JSON.stringify(policy));
loadPolicy(policyPath);

const results = [];
function check(name, tool, input, expected, extra = {}) {
  let d;
  try {
    d = decide({ hook_event_name: 'PreToolUse', cwd: extra.cwd ?? wsReal, tool_name: tool, tool_input: input }, policy);
  } catch (e) {
    d = { kind: 'throw', reason: e.message };
  }
  const ok = d.kind === expected || (expected === 'deny' && d.kind === 'throw');
  results.push({ ok, name, tool, expected, got: d.kind, reason: d.reason });
}

// --- files
check('read inside', 'Read', { file_path: path.join(ws, 'Model/Spyro/Main.lean') }, 'pass');
check('read relative inside', 'Read', { file_path: 'Model/Spyro/Main.lean' }, 'pass');
check('read /etc/hostname', 'Read', { file_path: '/etc/hostname' }, 'deny');
check('read run session (bearer token) absolute', 'Read', { file_path: path.join(session, 'mcp-config.json') }, 'deny');
check('read via ..', 'Read', { file_path: path.join(ws, '..', 'session', 'mcp-config.json') }, 'deny');
check('read relative ..', 'Read', { file_path: '../session/mcp-config.json' }, 'deny');
check('read ~', 'Read', { file_path: '~/.bashrc' }, 'deny');
check('read build mirror', 'Read', { file_path: path.join(runDir, 'build', 'Model.lean') }, 'deny');
check('read NUL', 'Read', { file_path: 'Model.lean\0x' }, 'deny');
check('write hidden at root', 'Write', { file_path: path.join(ws, '.env'), content: 'x' }, 'deny');
check('write hidden nested', 'Write', { file_path: path.join(ws, 'Model', '.hidden', 'x.lean'), content: 'x' }, 'deny');
check('write .lake', 'Write', { file_path: path.join(ws, '.lake', 'build', 'x'), content: 'x' }, 'deny');
check('write new nested file', 'Write', { file_path: path.join(ws, 'Model', 'Spyro', 'New', 'Lemmas.lean'), content: 'x' }, 'pass');
check('edit outside', 'Edit', { file_path: path.join(base, 'outside.txt'), old_string: 'a', new_string: 'b' }, 'deny');
check('multiedit outside', 'MultiEdit', { file_path: '/etc/passwd', edits: [] }, 'deny');
check('proc self root escape', 'Read', { file_path: '/proc/self/root/etc/hostname' }, 'deny');
check('proc self cwd (inside after realpath)', 'Read', { file_path: '/proc/self/cwd/Model.lean' }, 'deny');

// symlinks planted in ws (Claude cannot create them; the shadow refuses them; the guard must still hold)
symlinkSync('/etc', path.join(ws, 'etclink'));
symlinkSync(path.join(runDir, 'session'), path.join(ws, 'sesslink'));
symlinkSync(path.join(base, 'nowhere', 'x.lean'), path.join(ws, 'dangling.lean'));
mkdirSync(path.join(ws, '.lake'), { recursive: true });
symlinkSync(path.join(ws, '.lake'), path.join(ws, 'visible'));
check('symlink to /etc', 'Read', { file_path: path.join(ws, 'etclink', 'hostname') }, 'deny');
check('symlink to session', 'Read', { file_path: path.join(ws, 'sesslink', 'mcp-config.json') }, 'deny');
check('write through dangling symlink', 'Write', { file_path: path.join(ws, 'dangling.lean'), content: 'x' }, 'deny');
check('symlink to hidden inside', 'Read', { file_path: path.join(ws, 'visible', 'x') }, 'deny');
check('glob path = symlink to /etc', 'Glob', { pattern: '*', path: path.join(ws, 'etclink') }, 'deny');
check('grep path = symlink to session', 'Grep', { pattern: 'secret', path: path.join(ws, 'sesslink') }, 'deny');
rmSync(path.join(ws, 'etclink'));
rmSync(path.join(ws, 'sesslink'));
rmSync(path.join(ws, 'dangling.lean'));
rmSync(path.join(ws, 'visible'));

// --- Grep/Glob with a hidden entry present in ws (.lake created above)
check('glob whole root with hidden inside', 'Glob', { pattern: '**/*' }, 'deny');
check('grep whole root with hidden inside', 'Grep', { pattern: 'x' }, 'deny');
check('grep subfolder without hidden', 'Grep', { pattern: 'x', path: path.join(ws, 'Model') }, 'pass');
rmSync(path.join(ws, '.lake'), { recursive: true });
check('glob whole root clean', 'Glob', { pattern: '**/*.lean' }, 'pass');
check('grep whole root clean', 'Grep', { pattern: 'x' }, 'pass');
check('glob pattern ..', 'Glob', { pattern: '../**/*' }, 'deny');
check('glob absolute pattern', 'Glob', { pattern: '/etc/*' }, 'deny');
check('glob ~ pattern', 'Glob', { pattern: '~/*' }, 'deny');
check('glob hidden literal', 'Glob', { pattern: '**/.git/**' }, 'deny');
check('glob brace hidden', 'Glob', { pattern: '.{lake,git}/*' }, 'deny');
check('glob class dot', 'Glob', { pattern: '[.]lake/*' }, 'deny');
check('glob question', 'Glob', { pattern: '?lake/*' }, 'deny');
check('glob escaped dot', 'Glob', { pattern: '\\.lake/*' }, 'deny');
check('glob brace ..', 'Glob', { pattern: '{Model,..}/*' }, 'deny');
check('glob path outside', 'Glob', { pattern: '*', path: '/etc' }, 'deny');
check('glob path = run dir', 'Glob', { pattern: '**/*', path: runDir }, 'deny');
check('grep path outside', 'Grep', { pattern: 'root', path: '/etc' }, 'deny');
check('grep glob ..', 'Grep', { pattern: 'x', glob: '{*.lean,../session/*}' }, 'deny');
check('grep glob negation of hidden (narrowing)', 'Grep', { pattern: 'x', glob: '!.lake/**' }, 'pass');
check('grep glob hidden positive', 'Grep', { pattern: 'x', glob: '.telelean/**' }, 'deny');
check('grep with cwd outside', 'Grep', { pattern: 'x' }, 'deny', { cwd: '/' });

// --- tools
check('bash', 'Bash', { command: 'cat /etc/passwd' }, 'deny');
check('webfetch', 'WebFetch', { url: 'https://example.com' }, 'deny');
check('notebookedit', 'NotebookEdit', { notebook_path: path.join(ws, 'x.ipynb') }, 'deny');
check('task/agent', 'Agent', { prompt: 'x' }, 'deny');
check('todo', 'TodoWrite', { todos: [] }, 'deny');
check('mcp telelean', 'mcp__telelean__check_lean', {}, 'pass');
check('mcp other server', 'mcp__evil__run', {}, 'deny');
check('mcp prefix lookalike', 'mcp__teleleanx__run', {}, 'deny');
check('read mcp resource', 'ReadMcpResourceTool', { server: 'telelean', uri: 'x' }, 'deny');

// --- the real hook process end to end (stdin JSON, exit code, stdout)
function hook(tool, input) {
  const r = spawnSync(process.execPath, [GUARD, policyPath], {
    input: JSON.stringify({ hook_event_name: 'PreToolUse', session_id: 'probe', cwd: wsReal, tool_name: tool, tool_input: input }),
    encoding: 'utf8',
    cwd: wsReal,
    timeout: 10_000,
  });
  return { status: r.status, stdout: r.stdout.trim(), stderr: r.stderr.trim() };
}
const e2e = [
  ['hook read inside', hook('Read', { file_path: path.join(ws, 'Model.lean') }), (h) => h.status === 0 && h.stdout === ''],
  ['hook read outside', hook('Read', { file_path: '/etc/hostname' }), (h) => h.status === 0 && h.stdout.includes('"permissionDecision":"deny"')],
  ['hook bash', hook('Bash', { command: 'id' }), (h) => h.status === 0 && h.stdout.includes('"permissionDecision":"deny"')],
];
const badPolicy = spawnSync(process.execPath, [GUARD, path.join(session, 'missing.json')], { input: '{}', encoding: 'utf8' });
e2e.push(['hook with a missing policy blocks (exit 2)', { status: badPolicy.status, stdout: badPolicy.stdout, stderr: badPolicy.stderr.trim() }, (h) => h.status === 2]);
const garbage = spawnSync(process.execPath, [GUARD, policyPath], { input: 'not json', encoding: 'utf8' });
e2e.push(['hook with garbage stdin blocks (exit 2)', { status: garbage.status, stdout: garbage.stdout, stderr: garbage.stderr.trim() }, (h) => h.status === 2]);
for (const [name, h, pred] of e2e) results.push({ ok: pred(h), name, tool: 'hook', expected: 'see name', got: JSON.stringify(h).slice(0, 200) });

const failed = results.filter((r) => !r.ok);
for (const r of results) console.log(`${r.ok ? 'ok  ' : 'FAIL'} ${r.name}: expected ${r.expected}, got ${r.got}${r.ok ? '' : ` (${r.reason})`}`);
console.log(`\n${results.length - failed.length}/${results.length} as expected`);
process.exit(failed.length === 0 ? 0 : 1);

