// Verifier probe: Cancel and dispose (window close) of a real RunManager on a scratch copy of mental_model/, with the
// real engine (sandboxed Lean), the FakeBackend (never real Claude; TELELEAN_NO_REAL_CLAUDE=1), and git only in the
// copy (isolated config). Checks that no telelean-<runId>-* unit and no process of the run is left, and that the
// user's (copy's) files are untouched before Accept.
//   node cancel-probe.mjs <runner bundle .mjs> <work dir>
import { execFileSync, spawnSync } from 'node:child_process';
import { cpSync, existsSync, mkdirSync, readFileSync, rmSync } from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';

process.env.TELELEAN_NO_REAL_CLAUDE = '1';
const [bundle, work] = process.argv.slice(2);
const { llm, run, gate, proposal, workspace: ws } = await import(pathToFileURL(bundle).href);
const REPO = '/home/zhengyew/telelean';
rmSync(work, { recursive: true, force: true });
mkdirSync(work, { recursive: true });
const root = path.join(work, 'model');
cpSync(path.join(REPO, 'mental_model'), root, { recursive: true, filter: (s) => !s.split(path.sep).includes('.lake') && !s.split(path.sep).includes('.git') });
const GIT_ENV = { ...process.env, GIT_CONFIG_GLOBAL: '/dev/null', GIT_CONFIG_NOSYSTEM: '1', GIT_CEILING_DIRECTORIES: work, GIT_AUTHOR_NAME: 'p', GIT_AUTHOR_EMAIL: 'p@localhost', GIT_COMMITTER_NAME: 'p', GIT_COMMITTER_EMAIL: 'p@localhost' };
const git = (...a) => execFileSync('git', ['-c', 'commit.gpgsign=false', '-c', 'core.hooksPath=/dev/null', ...a], { cwd: root, env: GIT_ENV, encoding: 'utf8' });
git('init', '-q');
git('add', '-A');
git('commit', '-q', '-m', 'probe base');
const MAIN = path.join(root, 'Model', 'Spyro', 'Main.lean');
const mainBefore = readFileSync(MAIN, 'utf8');

const units = (runId) =>
  (spawnSync('systemctl', ['--user', 'list-units', '--all', '--plain', '--no-legend', '--no-pager', `telelean-${runId}-*`], { encoding: 'utf8' }).stdout ?? '')
    .split('\n').map((l) => l.trim().split(/\s+/)[0]).filter((u) => u && u.startsWith('telelean-'));
const procsUnder = (dir) => (spawnSync('pgrep', ['-af', '--', dir], { encoding: 'utf8' }).stdout ?? '').split('\n').filter((l) => l.trim() && !l.includes('pgrep') && !l.includes('cancel-probe.mjs'));
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
async function until(pred, ms, what, step = 20) {
  const end = Date.now() + ms;
  for (;;) {
    const v = await pred();
    if (v) return v;
    if (Date.now() > end) throw new Error(`timed out waiting for ${what}`);
    await sleep(step);
  }
}

const workspace = ws.createModelWorkspace({ root, text: ws.fsTextSource(root), applier: ws.fsEditApplier(root), semantic: { debounceMs: 60_000 } });
await workspace.load();
await workspace.refreshNow();

let script = [];
const backend = new llm.FakeBackend((turn, index) => script[index] ?? [{ kind: 'result' }]);
const runsDir = path.join(work, 'runs');
const makeManager = () =>
  run.createRunManager({
    root,
    runsDir,
    workspace,
    services: { backend, engine: gate.createLeanCheckEngine(), proposals: proposal.createProposalService(), sidecars: proposal.createRunSidecarStore(), log: () => {} },
    settings: { ...run.DEFAULT_RUN_SETTINGS },
  });
const START = { subject: 'Spyro', target: 'cynder-not-good', premises: ['cynder-dark-past', 'new-spyro-pg', 'pg-no-dark-past'] };
const report = {};

// A. Cancel while a Lean job of check_lean runs.
{
  const m = makeManager();
  script = [[{ kind: 'read', path: 'Model/Spyro/Main.lean' }, { kind: 'callTool', tool: 'check_lean', args: {} }, { kind: 'sleep', ms: 600_000 }]];
  const out = await m.start(START);
  if (!out.ok) throw new Error(`start A refused: ${JSON.stringify(out)}`);
  const runId = m.current().runId;
  const seen = await until(() => (units(runId).length > 0 ? units(runId) : false), 60_000, 'a Lean unit of the check', 5).catch(() => []);
  const t0 = Date.now();
  const c = await m.cancel(runId);
  await sleep(1500);
  report.A = { cancel: c.ok, state: m.current()?.state, unitsSeenAtCancel: seen, unitsLeft: units(runId), cancelMs: Date.now() - t0 - 1500, procsLeft: procsUnder(path.join(runsDir)) };
  await m.dismiss(runId);
  m.dispose();
}

// B. Cancel while Claude "thinks" (no Lean job).
{
  const m = makeManager();
  script = [[{ kind: 'text', text: 'thinking' }, { kind: 'sleep', ms: 600_000 }]];
  const out = await m.start({ ...START, premises: START.premises });
  if (!out.ok) throw new Error(`start B refused: ${JSON.stringify(out)}`);
  const runId = m.current().runId;
  await until(() => m.current()?.state === 'working', 30_000, 'working');
  const c = await m.cancel(runId);
  await sleep(500);
  report.B = { cancel: c.ok, state: m.current()?.state, unitsLeft: units(runId), procsLeft: procsUnder(runsDir) };
  await m.dismiss(runId);
  m.dispose();
}

// C. dispose() (window closing) while a Lean job of check_lean runs.
{
  const m = makeManager();
  script = [[{ kind: 'callTool', tool: 'check_lean', args: {} }, { kind: 'sleep', ms: 600_000 }]];
  const out = await m.start(START);
  if (!out.ok) throw new Error(`start C refused: ${JSON.stringify(out)}`);
  const runId = m.current().runId;
  const seen = await until(() => (units(runId).length > 0 ? units(runId) : false), 60_000, 'a Lean unit of the check', 5).catch(() => []);
  const runDir = path.join(runsDir, (await import(pathToFileURL(bundle).href)).shadow.rootKeyOf(root), runId);
  await m.dispose();
  const right = units(runId);
  const stateNow = JSON.parse(readFileSync(path.join(runDir, 'run.json'), 'utf8')).view.state;
  await sleep(5000);
  report.C = { unitsSeenBeforeDispose: seen, unitsRightAfterDispose: right, unitsAfter5s: units(runId), runJsonState: stateNow, canResume: JSON.parse(readFileSync(path.join(runDir, 'run.json'), 'utf8')).view.canResume };
  // Recovery in a new manager: nothing starts by itself.
  const m2 = makeManager();
  let sessions = 0;
  const orig = backend.startSession.bind(backend);
  backend.startSession = async (cfg) => (sessions++, orig(cfg));
  await m2.recover();
  report.C.recovered = { state: m2.current()?.state, canResume: m2.current()?.canResume, sessionsStarted: sessions };
  if (m2.current()) await m2.discard(m2.current().runId);
  m2.dispose();
}

report.copyUntouched = readFileSync(MAIN, 'utf8') === mainBefore;
report.copyGitStatus = git('status', '--porcelain');
report.runDirs = existsSync(runsDir) ? spawnSync('find', [runsDir, '-maxdepth', '2', '-mindepth', '2', '-type', 'd'], { encoding: 'utf8' }).stdout.trim().split('\n') : [];
workspace.dispose();
console.log(JSON.stringify(report, null, 2));
process.exit(0);

