/**
 * Who uses a declaration (D-11 kind changes, D-18 deletes): from Lean's references (`DeclFacts.refs`, transitively),
 * plus, while some file is not freshly checked, a syntactic scan for the name in the declarations' text (so a use
 * typed since the last check still counts as a dependent and nothing that others use is removed silently).
 */
import type { DeclInfo, ParsedFile } from '../markup/types.js';
import type { ProjectModel } from '../project/types.js';
import { blankComments, identifierTokens } from '../project/text.js';
import { resolveName } from '../project/vocabulary.js';

export interface UsersOptions {
  /** Also the users of the users, and so on (default true). */
  transitive?: boolean;
}

/** Declarations whose facts refs name one of `targets` (closed under "uses a member" unless not transitive; BFS order). */
export function factUsers(model: ProjectModel, targets: readonly string[], exclude: ReadonlySet<string>, options: UsersOptions = {}): string[] {
  const transitive = options.transitive ?? true;
  const users = new Map<string, string[]>();
  for (const [name, facts] of model.declFacts) {
    for (const ref of facts.refs) {
      const list = users.get(ref.name) ?? [];
      if (!list.includes(name)) list.push(name);
      users.set(ref.name, list);
    }
  }
  const out: string[] = [];
  const seen = new Set<string>([...targets, ...exclude]);
  const queue = [...targets];
  while (queue.length > 0) {
    const name = queue.shift() as string;
    for (const user of users.get(name) ?? []) {
      if (seen.has(user)) continue;
      seen.add(user);
      out.push(user);
      if (transitive) queue.push(user);
    }
  }
  return out;
}

/** The text of a declaration after its name (signature and value), comments and strings blanked. */
function declBody(file: ParsedFile, decl: DeclInfo): string {
  return blankComments(file.text.slice(decl.nameSpan?.end ?? decl.keywordSpan.end, decl.span.end));
}

/**
 * The namespaces opened before each offset of a file (`open A B`, `open A in`, `open scoped A`, `open A (x)`,
 * `open A hiding x`, `open A renaming x → y`), read from the text with comments blanked. Deliberately generous: an
 * `open … in` or an `open` inside a section is taken to apply to everything after it in the file (a possible use
 * found too often only means one more question, a missed one means a `.holds` removed while others use it).
 */
function openedNamespaces(file: ParsedFile): (offset: number) => string[] {
  const clean = blankComments(file.text);
  const opens: Array<{ offset: number; names: string[] }> = [];
  const pattern = /(^|\n)[ \t]*open[ \t]+([^\n]*)/g;
  for (const match of clean.matchAll(pattern)) {
    const offset = (match.index ?? 0) + (match[1] ?? '').length;
    const names: string[] = [];
    for (const word of (match[2] ?? '').split(/[\s()]+/)) {
      if (word === '' || word === 'scoped') continue;
      if (word === 'in' || word === 'hiding' || word === 'renaming' || word.includes('→') || word === '->') break;
      if (/^[\p{L}_«][\p{L}\p{N}_'.!?«»]*$/u.test(word)) names.push(word);
    }
    if (names.length > 0) opens.push({ offset, names });
  }
  return (offset: number) => opens.filter((o) => o.offset < offset).flatMap((o) => o.names);
}

