/**
 * G0 (docs/m2-plan.md sections 3.1 and 3.8): the token denylist over Claude's lines, the file rules over a change set,
 * and the single-term rule for Claude's ghost text. Text only: nothing here runs Lean, and only `lexLean` tokens count,
 * so words in comments, strings, docstrings and telelean blocks never do.
 */
import { scanDecls } from '../markup/decls.js';
import { canonicalName, lexLean } from '../markup/lexer.js';
import { relativeName } from '../markup/names.js';
import { Lines } from '../markup/text.js';
import type { DeclInfo, LeanToken } from '../markup/types.js';
import type { Range } from '../model.js';
import type { G0Context, GateFinding, GateFindingCode } from './types.js';

/** `#` commands that may stay (they only print). */
const HASH_ALLOWED: ReadonlySet<string> = new Set(['check', 'print']);

/** Code tokens that are refused wherever they occur, by code (plan 3.1). `run_tac` added (a sibling of `run_elab`). */
const WORD_CODES: ReadonlyMap<string, GateFindingCode> = new Map<string, GateFindingCode>([
  ...[
    'initialize',
    'builtin_initialize',
    'run_cmd',
    'run_elab',
    'run_meta',
    'run_tac',
    'macro',
    'macro_rules',
    'syntax',
    'notation',
    'infix',
    'infixl',
    'infixr',
    'prefix',
    'postfix',
    'elab',
    'elab_rules',
    'declare_syntax_cat',
    'declare_simp_like_tactic',
  ].map((w) => [w, 'metaprogramming'] as const),
  ...['native_decide', 'bv_decide', 'implemented_by', 'extern', 'csimp', 'native'].map((w) => [w, 'native-code'] as const),
  ...['unsafe', 'partial'].map((w) => [w, 'unsafe'] as const),
  ['set_option', 'set-option'],
  ...['sorry', 'admit'].map((w) => [w, 'sorry'] as const),
]);

/** Constants of Lean's `Lean` namespace behind native evaluation: refused however they are written (`Lean.ofReduceBool`). */
const NATIVE_CONSTANTS: ReadonlySet<string> = new Set(['ofReduceBool', 'ofReduceNat', 'reduceBool', 'reduceNat']);

/** What each token code means, for Claude's message. */
const TOKEN_ADVICE: Readonly<Partial<Record<GateFindingCode, string>>> = {
  'hash-command': 'is not allowed in the model files (only #check and #print may be used): remove it',
  metaprogramming: 'is metaprogramming, which is not allowed in the model files: remove it',
  'native-code': 'trusts compiled code instead of the kernel, which is not allowed: prove it in the kernel (decide, simp, omega, …)',
  unsafe: 'is not allowed in the model files: remove it',
  'set-option': 'is not allowed in what you write (no option or limit changes): remove it',
  sorry: 'leaves a gap: give a complete proof, or remove the proof and finish with status not_proved',
};

/** The lines of a text without their line breaks (`\n` or `\r\n`). */
export function textLines(text: string): string[] {
  return text.split('\n').map((line) => (line.endsWith('\r') ? line.slice(0, -1) : line));
}

/** How many times each exact line occurs. */
function lineCounts(text: string): Map<string, number> {
  const counts = new Map<string, number>();
  for (const line of textLines(text)) counts.set(line, (counts.get(line) ?? 0) + 1);
  return counts;
}

const lastComponent = (name: string) => {
  const dot = name.lastIndexOf('.');
  return dot < 0 ? name : name.slice(dot + 1);
};

/** `file:line:col` as Lean prints it (1-based line, 0-based column). */
export function where(file: string, range: Range | undefined): string {
  return range ? `${file}:${range.start.line + 1}:${range.start.character}` : file;
}

interface RawToken {
  code: GateFindingCode;
  start: number;
  end: number;
  token: string;
}

/** The offending tokens of a text (no line filtering), in text order. */
function forbiddenTokens(tokens: readonly LeanToken[], projectModules: ReadonlySet<string> | undefined): RawToken[] {
  const out: RawToken[] = [];
  const glued = (a: LeanToken | undefined, b: LeanToken | undefined) => a !== undefined && b !== undefined && a.span.end === b.span.start;
  for (let i = 0; i < tokens.length; i++) {
    const tok = tokens[i] as LeanToken;
    const next = tokens[i + 1];
    if (tok.kind === 'symbol' && tok.text === '#' && next?.kind === 'ident' && glued(tok, next)) {
      const command = next.text.split('.')[0] ?? next.text;
      if (!HASH_ALLOWED.has(command)) out.push({ code: 'hash-command', start: tok.span.start, end: next.span.end, token: `#${next.text}` });
      i++;
      continue;
    }
    if (tok.kind !== 'ident') continue;
    const canonical = canonicalName(tok.text);
    if (tok.text === 'import' || canonical === 'import') {
      let j = i + 1;
      if (tokens[j]?.kind === 'ident' && tokens[j]?.text === 'all') j++;
      const module = tokens[j];
      if (module?.kind === 'ident') {
        if (projectModules === undefined || !projectModules.has(canonicalName(module.text))) {
          out.push({ code: 'import', start: tok.span.start, end: module.span.end, token: `import ${module.text}` });
        }
        i = j;
      } else {
        out.push({ code: 'import', start: tok.span.start, end: tok.span.end, token: 'import' });
      }
      continue;
    }
    const code = WORD_CODES.get(tok.text) ?? WORD_CODES.get(canonical) ?? (NATIVE_CONSTANTS.has(lastComponent(canonical)) ? 'native-code' : undefined);
    if (code === undefined) continue;
    const previous = tokens[i - 1];
    if (canonical === 'native' && previous?.kind === 'symbol' && previous.text === '+' && glued(previous, tok)) {
      out.push({ code, start: previous.span.start, end: tok.span.end, token: `+${tok.text}` });
    } else {
      out.push({ code, start: tok.span.start, end: tok.span.end, token: tok.text });
    }
  }
  return out;
}

/** The innermost declaration whose span contains `offset`. */
function declAt(decls: readonly DeclInfo[], offset: number): DeclInfo | undefined {
  let found: DeclInfo | undefined;
  for (const decl of decls) if (decl.span.start <= offset && offset < decl.span.end) found = decl;
  return found;
}

/** See `scanForbidden` in ./index.ts. */
export function scanForbiddenText(file: string, text: string, ctx: G0Context, baseText?: string | null): GateFinding[] {
  const lex = lexLean(text);
  const raw = forbiddenTokens(lex.tokens, ctx.projectModules);
  if (raw.length === 0) return [];
  const lines = new Lines(text);
  const decls = scanDecls(text, lex, lines).decls;
  // Only Claude's lines are judged: a line whose exact text B's version also has (as often) is the user's own.
  const base = baseText === undefined || baseText === null ? undefined : lineCounts(baseText);
  const current = textLines(text);
  const rank = new Map<number, number>();
  if (base !== undefined) {
    const seen = new Map<string, number>();
    current.forEach((line, index) => {
      const n = (seen.get(line) ?? 0) + 1;
      seen.set(line, n);
      rank.set(index, n);
    });
  }
  const out: GateFinding[] = [];
  for (const item of raw) {
    const line = lines.lineOf(item.start);
    if (base !== undefined) {
      const lineText = current[line] ?? '';
      if ((rank.get(line) ?? 1) <= (base.get(lineText) ?? 0)) continue;
    }
    const range = lines.range({ start: item.start, end: item.end });
    const decl = declAt(decls, item.start);
    const inDecl = decl?.fullName !== undefined ? ` (in ${relativeName(decl.fullName, decl.namespace)})` : '';
    const advice =
      item.code === 'import'
        ? `\`${item.token}\` imports a module from outside the project${inDecl}: only the project's own modules may be imported`
        : `\`${item.token}\` ${TOKEN_ADVICE[item.code] ?? 'is not allowed'}${inDecl}`;
    out.push({
      step: 'G0',
      code: item.code,
      message: `${where(file, range)}: ${advice}.`,
      file,
      range,
      token: item.token,
      ...(decl?.fullName !== undefined ? { names: [decl.fullName] } : {}),
    });
  }
  return out;
}

/** The project files Claude may never change (plan 3.1 `project-file`), at the model root. */
export const PROJECT_FILES: ReadonlySet<string> = new Set(['lakefile.toml', 'lakefile.lean', 'lean-toolchain', 'lake-manifest.json']);

/** A module path component a new file may use: an ASCII Lean identifier part. */
const MODULE_COMPONENT = /^[A-Za-z_][A-Za-z0-9_]*$/;

/** Inside the run's subject: `<library>/<S>.lean` or `<library>/<S>/**`. */
export function inSubjectScope(path: string, library: string, subject: string): boolean {
  return path === `${library}/${subject}.lean` || path.startsWith(`${library}/${subject}/`);
}

/** A path a new file of the subject may have: `<library>/<S>/<A>/…/<Module>.lean` with identifier components (or the subject root). */
export function isSubjectModulePath(path: string, library: string, subject: string): boolean {
  if (path === `${library}/${subject}.lean`) return true;
  const prefix = `${library}/${subject}/`;
  if (!path.startsWith(prefix) || !path.endsWith('.lean')) return false;
  const parts = path.slice(prefix.length, -'.lean'.length).split('/');
  return parts.length > 0 && parts.every((part) => MODULE_COMPONENT.test(part));
}

/** See `checkFileChanges` in ./index.ts. */
export function checkChangeSet(base: ReadonlyMap<string, string>, current: ReadonlyMap<string, string>, ctx: G0Context): GateFinding[] {
  const out: GateFinding[] = [];
  const scope = `${ctx.library}/${ctx.subject}/… and ${ctx.library}/${ctx.subject}.lean`;
  const paths = [...new Set([...base.keys(), ...current.keys()])].sort();
  for (const path of paths) {
    const before = base.get(path);
    const after = current.get(path);
    if (before === after) continue;
    const verb = before === undefined ? 'was added' : after === undefined ? 'was deleted' : 'was changed';
    const finding = (code: GateFindingCode, advice: string): GateFinding => ({ step: 'G0', code, message: `${path} ${verb}: ${advice}.`, file: path, token: path });
    if (PROJECT_FILES.has(path)) {
      out.push(finding('project-file', 'the project files (lakefile, lean-toolchain, lake-manifest.json) must stay exactly as they were; undo it'));
      continue;
    }
    if (after === undefined) out.push(finding('deleted-file', 'model files may not be deleted; restore it'));
    else if (!inSubjectScope(path, ctx.library, ctx.subject)) {
      out.push(finding('outside-subject', `only the files of the subject ${ctx.subject} (${scope}) may change; ${before === undefined ? 'remove it' : 'undo the change'}`));
    } else if (before === undefined && !isSubjectModulePath(path, ctx.library, ctx.subject)) {
      out.push(
        finding('bad-path', `it is not a Lean module of the subject (expected ${ctx.library}/${ctx.subject}/<Module>.lean with letters, digits and "_" only); remove it`),
      );
    }
    if (after !== undefined && path.endsWith('.lean')) out.push(...scanForbiddenText(path, after, ctx, before ?? null));
  }
  return out;
}

// ---------------------------------------------------------------------------------------------
// The single-term rule for ghost text (plan 3.8)

/** Command keywords: a ghost text holding one could close the generated declaration and start another. */
const GHOST_COMMAND_WORDS: ReadonlySet<string> = new Set([
  'axiom',
  'theorem',
  'lemma',
  'def',
  'abbrev',
  'example',
  'instance',
  'structure',
  'class',
  'inductive',
  'coinductive',
  'opaque',
  'namespace',
  'section',
  'end',
  'universe',
  'variable',
  'import',
  'attribute',
  'mutual',
  'deriving',
  'noncomputable',
  'private',
  'protected',
  // Also commands that would act on the declarations after an adopted ghost (name resolution), never needed in one term.
  'open',
  'export',
  'omit',
  'include',
]);

const OPENERS = '([{⟨⦃⟦‹';
const CLOSERS = ')]}⟩⦄⟧›';

const G0_LABEL: Readonly<Partial<Record<GateFindingCode, string>>> = {
  metaprogramming: 'metaprogramming',
  'native-code': 'native code',
  unsafe: 'unsafe code',
  'set-option': 'an option change',
  sorry: 'a gap',
};

/** The single-term problems of one text (`what` = "statement" or "proof"). */
function termProblems(text: string, what: 'statement' | 'proof'): string[] {
  const problems: string[] = [];
  const The = what === 'statement' ? 'The statement' : 'The proof';
  for (const delimiter of ['/-', '-/', '--']) {
    if (text.includes(delimiter)) problems.push(`${The} contains a comment delimiter (\`${delimiter}\`): it must be plain Lean without comments.`);
  }
  const { tokens } = lexLean(text);
  const glued = (a: LeanToken | undefined, b: LeanToken | undefined) => a !== undefined && b !== undefined && a.span.end === b.span.start;
  const keywords = new Set<string>();
  for (let i = 0; i < tokens.length; i++) {
    const tok = tokens[i] as LeanToken;
    const next = tokens[i + 1];
    if (tok.kind === 'symbol' && tok.text === '#' && next?.kind === 'ident' && glued(tok, next)) {
      problems.push(`${The} contains a command (\`#${next.text}\`): it must be one Lean term.`);
      continue;
    }
    if (tok.kind === 'symbol' && tok.text === '@' && next?.kind === 'symbol' && next.text === '[' && glued(tok, next)) keywords.add('@[');
    if (tok.kind === 'ident' && GHOST_COMMAND_WORDS.has(canonicalName(tok.text))) keywords.add(canonicalName(tok.text));
  }
  for (const keyword of keywords) problems.push(`${The} contains the command keyword \`${keyword}\`: it must be one Lean term, not declarations.`);
  for (const finding of forbiddenTokens(tokens, new Set())) {
    // `#` commands and imports are reported above.
    if (finding.code === 'hash-command' || finding.code === 'import') continue;
    problems.push(`${The} uses \`${finding.token}\` (${G0_LABEL[finding.code] ?? 'not allowed'}), which is not allowed.`);
  }
  if (what === 'statement') {
    const stack: string[] = [];
    let assign = false;
    let bar = false;
    for (let i = 0; i < tokens.length; i++) {
      const tok = tokens[i] as LeanToken;
      if (tok.kind !== 'symbol') continue;
      const open = OPENERS.indexOf(tok.text);
      const close = CLOSERS.indexOf(tok.text);
      if (open >= 0) stack.push(tok.text);
      else if (close >= 0) {
        if (stack.length > 0 && stack[stack.length - 1] === OPENERS[close]) stack.pop();
        else problems.push(`${The} has an unbalanced \`${tok.text}\` (character ${tok.span.start + 1}) that closes no bracket opened before it.`);
      } else if (stack.length === 0 && tok.text === ':' && tokens[i + 1]?.text === '=' && glued(tok, tokens[i + 1])) assign = true;
      else if (stack.length === 0 && tok.text === '|') bar = true;
    }
    if (assign) problems.push(`${The} contains \`:=\` outside brackets: a suggested premise is one proposition (put any \`:=\` inside parentheses).`);
    if (bar) problems.push(`${The} contains \`|\` outside brackets: put any pattern match inside parentheses.`);
    for (const open of stack) problems.push(`${The} leaves \`${open}\` open: every bracket must close within the statement.`);
  }
  if (text.trim() === '') problems.push(`${The} is empty.`);
  return problems;
}

/** See `ghostTextProblems` in ./index.ts. */
export function ghostProblems(statement: string, proof?: string): string[] {
  return [...termProblems(statement, 'statement'), ...(proof !== undefined ? termProblems(proof, 'proof') : [])];
}

/** Every whitespace run collapsed to one space, trimmed: the form the ghost check elaborates and adoption writes. */
export function collapseWhitespace(text: string): string {
  return text.replace(/\s+/g, ' ').trim();
}

/**
 * D-5 permitted axioms (docs/m2-plan.md section 3.2) and the freeze record the rules keep (`FrozenSnapshot`).
 *
 *   permitted(F) = STD ∪ signature ∪ selected ∪ presuppositions ∪ derivation footprints
 *   unusable     = selected premises contributing nothing: no `.holds`, a conditional or unchecked proof, a `.holds`
 *                  that does not state its statement, or a proof resting on the target's own claimed `.holds` (circular)
 *
 * The target's `.holds` is never permitted (it is not selected and its sort is `Prop`; a circular derivation footprint
 * is dropped whole).
 */
import { ActionError } from '../actions.js';
import { holdsName, SORRY_AXIOM, STANDARD_AXIOM_NAMES } from '../facts.js';
import type { TlNode, VocabKind } from '../model.js';
import type { ProjectModel } from '../project/types.js';
import { compareLeanNames, normalizeWhitespace } from '../project/text.js';
import type { FrozenSnapshot, PermittedAxioms, Selection } from './types.js';

const sortNames = (names: Iterable<string>): string[] => [...new Set(names)].sort(compareLeanNames);

/** Vocabulary kinds whose axioms are signature (not beliefs) when Lean's `typeSort` is unknown. */
const SIGNATURE_KINDS: ReadonlySet<VocabKind> = new Set(['sort', 'predicate', 'function', 'constant']);

/** Every non-Prop axiom of the project (sorts, predicates, functions): D-3 rules 1 and 3. */
export function signatureAxioms(model: ProjectModel): string[] {
  const kinds = new Map(model.vocabulary.map((item) => [item.name, item.kind]));
  const out: string[] = [];
  for (const [name, facts] of model.declFacts) {
    if (facts.kind !== 'axiom') continue;
    const sort = facts.typeSort === undefined ? undefined : normalizeWhitespace(facts.typeSort);
    if (sort !== undefined ? sort !== 'Prop' : SIGNATURE_KINDS.has(kinds.get(name) ?? 'other')) out.push(name);
  }
  return out;
}

/** Why a selected card cannot be used, or undefined when it contributes axioms (and which). */
function contribution(node: TlNode, targetHolds: string | undefined): { selected?: string; footprint?: string[] } | undefined {
  const statement = node.lean.statement;
  if (statement === undefined || node.lean.justification === undefined || node.status.flags.includes('holds-mismatch')) return undefined;
  if (node.lean.justificationKind === 'axiom') return { selected: holdsName(statement) };
  const proof = node.status.proof;
  if (proof.kind !== 'proved' || node.lean.axioms === undefined) return undefined;
  const axioms = node.lean.axioms.filter((a) => a !== SORRY_AXIOM);
  if (targetHolds !== undefined && axioms.includes(targetHolds)) return undefined;
  return { footprint: axioms };
}

/**
 * The permitted set. `strict`: unknown target or premise ids throw ActionError `invalid` (computePermittedAxioms);
 * otherwise they are skipped (evaluateRules never throws).
 */
export function permittedAxioms(model: ProjectModel, selection: Selection, strict: boolean): PermittedAxioms {
  const nodeOf = (id: string, what: string): TlNode | undefined => {
    const entry = model.nodes.get(id);
    if (entry && entry.node.subject === selection.subject) return entry.node;
    if (strict) throw new ActionError('invalid', `${what} "${id}" is not a card of the subject ${selection.subject}.`);
    return undefined;
  };
  const target = nodeOf(selection.target, 'The target');
  const targetHolds = target?.lean.statement !== undefined ? holdsName(target.lean.statement) : undefined;
  const chosen = [...new Set([...selection.premises, ...selection.adoptedGhosts])].filter((id) => id !== selection.target);
  const selected: string[] = [];
  const presuppositions: string[] = [...(target?.lean.presupposes ?? [])];
  const derivationFootprints: string[] = [];
  const unusable: string[] = [];
  for (const id of chosen) {
    const node = nodeOf(id, 'The premise');
    if (!node) continue;
    presuppositions.push(...(node.lean.presupposes ?? []));
    const gives = contribution(node, targetHolds);
    if (gives === undefined) unusable.push(id);
    else if (gives.selected !== undefined) selected.push(gives.selected);
    else derivationFootprints.push(...(gives.footprint ?? []));
  }
  const drop = (names: Iterable<string>) => sortNames([...names].filter((n) => n !== targetHolds && n !== SORRY_AXIOM));
  const summary = {
    standard: [...STANDARD_AXIOM_NAMES],
    signature: drop(signatureAxioms(model)),
    selected: drop(selected),
    presuppositions: drop(presuppositions),
    derivationFootprints: drop(derivationFootprints),
    unusable,
  };
  const all = [...new Set([...summary.standard, ...summary.signature, ...summary.selected, ...summary.presuppositions, ...summary.derivationFootprints])].sort();
  return { ...summary, all };
}

/** See `frozenSnapshot` in ./index.ts. */
export function snapshotOf(frozen: ProjectModel, selection: Selection, round: number): FrozenSnapshot {
  const permitted = permittedAxioms(frozen, selection, true);
  const target = frozen.nodes.get(selection.target)?.node;
  const targetStatement = target?.lean.statement;
  if (targetStatement === undefined) throw new ActionError('invalid', `The target "${selection.target}" has no Lean statement to freeze.`);
  const subjectFiles = new Set(frozen.subjects.find((s) => s.name === selection.subject)?.files ?? []);
  const declarations: FrozenSnapshot['declarations'] = {};
  for (const [name, facts] of frozen.declFacts) {
    // Statements, vocabulary and definitions; proofs (theorems) may be reworked after the freeze.
    if (!subjectFiles.has(facts.file) || facts.kind === 'theorem') continue;
    declarations[name] = {
      ...(facts.kind !== undefined ? { kind: facts.kind } : {}),
      ...(facts.type !== undefined ? { type: normalizeWhitespace(facts.type) } : {}),
      ...(facts.value !== undefined ? { value: normalizeWhitespace(facts.value) } : {}),
    };
  }
  const axioms = new Set<string>();
  for (const [name, facts] of frozen.declFacts) if (facts.kind === 'axiom') axioms.add(name);
  for (const file of frozen.files.values()) for (const decl of file.decls) if (decl.keyword === 'axiom' && decl.fullName !== undefined) axioms.add(decl.fullName);
  return { round, permitted, targetStatement, declarations, axioms: [...axioms].sort() };
}

/**
 * Declaration tables the gate rules compare (docs/m2-plan.md section 3.3): every named declaration of a model's parsed
 * files with its source text (docstring and attributes included), the facts Lean reported for it, and what counts as
 * a proof. Cached per model (models are immutable).
 */
import type { DeclFacts } from '../facts.js';
import type { DeclInfo, ParsedFile } from '../markup/types.js';
import type { ProjectModel } from '../project/types.js';
import { normalizeWhitespace } from '../project/text.js';
import { anonymousInstanceName, signatureText } from '../project/vocabulary.js';

export interface DeclEntry {
  /** Fully-qualified name (Lean's automatic name for an anonymous instance, as the board computes it). */
  name: string;
  file: ParsedFile;
  decl: DeclInfo;
  /** The declaration's source text, from its docstring/attributes to its last line. */
  text: string;
}

export interface DeclTables {
  /** Named declarations, first occurrence wins, files in path order. */
  byName: Map<string, DeclEntry>;
  /** Source texts of the `example`s (they have no name), in file order. */
  examples: Array<{ file: ParsedFile; decl: DeclInfo; text: string }>;
  /** Every name the model knows: syntactic declarations and facts. */
  known: Set<string>;
  /** Names of the computed vocabulary items. */
  vocabulary: Set<string>;
}

const cache = new WeakMap<ProjectModel, DeclTables>();

const byPath = (a: ParsedFile, b: ParsedFile) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0);

export function declTables(model: ProjectModel): DeclTables {
  const cached = cache.get(model);
  if (cached) return cached;
  const byName = new Map<string, DeclEntry>();
  const examples: DeclTables['examples'] = [];
  for (const file of [...model.files.values()].sort(byPath)) {
    for (const decl of file.decls) {
      if (decl.keyword === 'mutual') continue;
      const text = file.text.slice(decl.span.start, decl.span.end);
      if (decl.keyword === 'example') {
        examples.push({ file, decl, text });
        continue;
      }
      const name = decl.fullName ?? (decl.keyword === 'instance' ? anonymousInstanceName(file, decl) : undefined);
      if (name === undefined || byName.has(name)) continue;
      byName.set(name, { name, file, decl, text });
    }
  }
  const known = new Set<string>([...byName.keys(), ...model.declFacts.keys()]);
  const tables: DeclTables = { byName, examples, known, vocabulary: new Set(model.vocabulary.map((item) => item.name)) };
  cache.set(model, tables);
  return tables;
}

/** Lean's facts for a declaration: by name, or for an anonymous instance by its file and start line. */
export function factsOf(model: ProjectModel, name: string, entry?: DeclEntry): DeclFacts | undefined {
  const direct = model.declFacts.get(name);
  if (direct || entry === undefined || entry.decl.keyword !== 'instance' || entry.decl.fullName !== undefined) return direct;
  for (const facts of model.declFacts.values()) {
    if (facts.file === entry.file.path && facts.range.start.line === entry.decl.range.start.line && (facts.kind === 'instance' || facts.kind === undefined)) return facts;
  }
  return undefined;
}

/** `instance : Nonempty T := T.exists`: the presupposition pattern (hidden from the vocabulary, never a proof to judge). */
export function isPresuppositionInstance(model: ProjectModel, entry: DeclEntry | undefined, facts: DeclFacts | undefined): boolean {
  const instance = facts?.kind === 'instance' || entry?.decl.keyword === 'instance';
  if (!instance) return false;
  const type = facts?.type !== undefined ? normalizeWhitespace(facts.type) : entry ? signatureText(entry.file, entry.decl)?.type : undefined;
  if (type === undefined || !/^Nonempty\s+\S+$/.test(normalizeWhitespace(type))) return false;
  const vocabulary = declTables(model).vocabulary;
  return !vocabulary.has(facts?.name ?? '') && !vocabulary.has(entry?.name ?? '');
}

/**
 * A proof (plan 3.3 `proof-before-freeze`): a declaration with a value whose type's sort is `Prop` (a theorem, a
 * Prop-valued def/abbrev/instance/opaque), except the presupposition instance; without facts, a `theorem`/`lemma`.
 */
export function isProof(model: ProjectModel, entry: DeclEntry | undefined, facts: DeclFacts | undefined): boolean {
  if (facts?.kind !== undefined) {
    if (facts.kind === 'axiom' || facts.kind === 'structure' || facts.kind === 'inductive' || facts.kind === 'class') return false;
    const propValued = facts.kind === 'theorem' || (facts.typeSort !== undefined && normalizeWhitespace(facts.typeSort) === 'Prop');
    return propValued && !isPresuppositionInstance(model, entry, facts);
  }
  const keyword = entry?.decl.keyword;
  return keyword === 'theorem' || keyword === 'lemma';
}

/** Is the declaration an axiom (facts kind, else the keyword)? */
export function isAxiom(entry: DeclEntry | undefined, facts: DeclFacts | undefined): boolean {
  if (facts?.kind !== undefined) return facts.kind === 'axiom';
  return entry?.decl.keyword === 'axiom';
}

/** Every axiom the model declares (facts, plus syntactic `axiom`s without facts), in a stable order. */
export function axiomNames(model: ProjectModel): string[] {
  const out: string[] = [];
  const seen = new Set<string>();
  for (const [name, entry] of declTables(model).byName) {
    if (isAxiom(entry, factsOf(model, name, entry)) && !seen.has(name)) {
      seen.add(name);
      out.push(name);
    }
  }
  for (const [name, facts] of model.declFacts) {
    if (facts.kind === 'axiom' && !seen.has(name)) {
      seen.add(name);
      out.push(name);
    }
  }
  return out;
}

/**
 * `evaluateRules` (docs/m2-plan.md section 3.3, with the reviewer's corrected table): G1 Lean errors, G3, G5 and the
 * stage/readiness rules for one purpose, the flagged definitions, footprints, the run's new statements and the
 * declaration diff. Pure, never throws for a malformed model: problems become findings.
 *
 * B (`input.base`) is exactly the user's files (base or accept-base commit); A (`input.adopted`) the shadow at its newest
 * `adopt` commit, which telelean's own ghost blocks and declarations are held to; S (`input.current`) the shadow now.
 *
 * Finding conventions (WP1-internal, read by `describeFinding`): `file`/`range` point at the declaration or block in S
 * (in B for something removed), `names` holds fully-qualified Lean names, `nodeId` the card concerned, and `token` a
 * short marker of the variant where the board's sentence depends on it (see each rule).
 */
import { holdsName, SORRY_AXIOM, statementOfHolds, type DeclFacts } from '../facts.js';
import { relativeName } from '../markup/names.js';
import type { MarkupBlock, ParsedFile } from '../markup/types.js';
import type { Range, TlNode } from '../model.js';
import type { ModelNode, ProjectModel } from '../project/types.js';
import { normalizeWhitespace } from '../project/text.js';
import { axiomNames, declTables, factsOf, isAxiom, isProof, type DeclEntry } from './decls.js';
import { where } from './g0.js';
import { permittedAxioms } from './permitted.js';
import type { FlaggedDefinition, GateFinding, GateFindingCode, PermittedAxioms, RuleInput, RuleReport } from './types.js';

/** Order of the G3 codes in a report: root causes before their consequences. */
const G3_ORDER: readonly GateFindingCode[] = ['new-axiom', 'existing-changed', 'not-proved', 'status-mismatch', 'statement-changed', 'footprint', 'sorry-axiom', 'vocabulary-shape'];
/** Readiness and stage codes come after G5. */
const LATE_ORDER: readonly GateFindingCode[] = ['not-formalised', 'missing-holds', 'proof-before-freeze', 'not-frozen'];

/** Block fields compared raw between B and S (G5); `id` and `lean` have their own rules. */
const COMPARED_FIELDS = ['natural_name', 'rationale', 'type', 'premises', 'stance', 'source', 'asserted', 'supersedes', 'refines', 'tags', 'origin', 'session', 'worded_by'] as const;

const sameList = (a: readonly string[], b: readonly string[]) => a.length === b.length && a.every((x, i) => x === b[i]);
const norm = (text: string | undefined) => (text === undefined ? undefined : normalizeWhitespace(text));
const quote = (text: string) => JSON.stringify(text);

/** Raw values of one key's lines of a block, in order. */
function raws(block: MarkupBlock, key: string): string[] {
  return block.lines.filter((line) => line.key === key).map((line) => line.raw);
}

/** The node id of each block that is a card (workspace ids may differ from a block's file-local derived id). */
function nodeIdsOfBlocks(model: ProjectModel): Map<MarkupBlock, string> {
  const out = new Map<MarkupBlock, string>();
  for (const entry of model.nodes.values()) out.set(entry.block, entry.node.id);
  return out;
}

/** A card has a statement bound to its block (adjacent or pinned), whether or not Lean accepted it. */
function bound(node: TlNode | undefined): string | undefined {
  return node !== undefined && node.lean.binding !== 'none' ? node.lean.statement : undefined;
}

/** A card is formalised for the readiness rules: bound to a declaration that exists and is a Prop abbrev/def. */
function formalised(model: ProjectModel, node: TlNode): boolean {
  if (bound(node) === undefined) return false;
  return !model.diagnostics.some((d) => d.nodeId === node.id && (d.code === 'TL101' || d.code === 'TL113'));
}

export function evaluate(input: RuleInput): RuleReport {
  const { purpose, selection, stage, base, current } = input;
  const roundStart = input.roundStart ?? base;
  const freeze = input.freeze;
  const subject = selection.subject;
  const B = declTables(base);
  const S = declTables(current);
  const R = declTables(roundStart);
  const checkProve = purpose === 'check' && stage === 'prove';
  const checkFormalise = purpose === 'check' && stage === 'formalise';
  const gate = purpose === 'gate-proved' || purpose === 'gate-other';

  const nodeIn = (model: ProjectModel, id: string): ModelNode | undefined => model.nodes.get(id);
  const curTarget = nodeIn(current, selection.target)?.node;
  const baseTarget = nodeIn(base, selection.target)?.node;
  const targetStatement = curTarget?.lean.statement ?? baseTarget?.lean.statement ?? freeze?.targetStatement;
  const targetHolds = targetStatement !== undefined ? holdsName(targetStatement) : undefined;
  /** T's `.holds` may be added, changed or turned from axiom into theorem (D-11 pending promotion). */
  const exempt = new Set<string>(
    [baseTarget?.lean.statement, curTarget?.lean.statement, freeze?.targetStatement].filter((s): s is string => s !== undefined).map(holdsName),
  );
  const targetStatements = new Set([baseTarget?.lean.statement, curTarget?.lean.statement, freeze?.targetStatement].filter((s): s is string => s !== undefined));
  const ghosts = [...new Set(selection.adoptedGhosts)];
  const chosen = new Set<string>([selection.target, ...selection.premises, ...ghosts]);

  const short = (name: string) => relativeName(name, [subject]);
  const at = (entry: DeclEntry | undefined): { file?: string; range?: Range } => (entry ? { file: entry.file.path, range: entry.decl.range } : {});
  const loc = (entry: DeclEntry | undefined) => (entry ? `${where(entry.file.path, entry.decl.range)}: ` : '');
  const sentence = (id: string) => current.nodes.get(id)?.node.naturalName ?? base.nodes.get(id)?.node.naturalName ?? id;

  // ---- declaration diff (syntactic, by name and text)
  const added: string[] = [];
  const changed: string[] = [];
  const removed: string[] = [];
  for (const [name, entry] of S.byName) {
    const before = B.byName.get(name);
    if (!before) added.push(name);
    else if (before.text !== entry.text) changed.push(name);
  }
  for (const name of B.byName.keys()) if (!S.byName.has(name)) removed.push(name);
  const addedOrChanged = new Set([...added, ...changed]);
  const inBase = (name: string) => B.known.has(name);

  const changedFiles = new Set<string>();
  for (const [path, file] of current.files) if (base.files.get(path)?.text !== file.text) changedFiles.add(path);

  const findings = new Map<GateFindingCode, GateFinding[]>();
  const push = (finding: GateFinding) => {
    const list = findings.get(finding.code) ?? [];
    list.push(finding);
    findings.set(finding.code, list);
  };
  const ownerOf = (model: ProjectModel, name: string) => model.ownerOfDecl.get(name);
  const node = (id: string | undefined) => (id === undefined ? {} : { nodeId: id });

  // ---- G1: Lean errors, and changed files Lean never builds
  const facts = current.facts;
  if (facts) {
    const errors = facts.build.messages.filter((m) => m.severity === 'error');
    for (const m of errors) {
      push({
        step: 'G1',
        code: 'build',
        message: `${m.file ? `${where(m.file, m.range)}: ` : ''}error: ${m.text}`,
        ...(m.file ? { file: m.file } : {}),
        ...(m.range ? { range: m.range } : {}),
      });
    }
    if (errors.length === 0) {
      for (const module of facts.build.failedModules) {
        push({ step: 'G1', code: 'build', message: `Lean could not build ${module}${facts.build.detail ? ` (${facts.build.detail})` : ''}.` });
      }
    }
  }
  const unbuilt = new Set<string>();
  for (const module of facts?.modules ?? []) if (module.state === 'not-built' && changedFiles.has(module.file)) unbuilt.add(module.file);
  for (const d of current.diagnostics) if (d.code === 'TL118' && d.file !== undefined && changedFiles.has(d.file)) unbuilt.add(d.file);
  for (const file of [...unbuilt].sort()) {
    push({
      step: 'G1',
      code: 'build',
      message: `${file} is not imported by the library, so Lean never checks it: import it from the subject's root module (${current.library}/${subject}.lean) or from a module the library already imports.`,
      file,
      token: 'not-built',
    });
  }

  // ---- new-axiom
  const allowedHolds = new Set<string>();
  for (const id of [...selection.premises, ...ghosts]) {
    const n = current.nodes.get(id)?.node;
    if (n && n.lean.statement !== undefined && (n.type === 'ASSUMPTION' || ghosts.includes(id))) allowedHolds.add(holdsName(n.lean.statement));
  }
  const vocabKind = new Map(current.vocabulary.map((item) => [item.name, item.kind]));
  /** A Prop-valued axiom (a belief) rather than vocabulary. */
  const isBelief = (name: string, f: DeclFacts | undefined): boolean => {
    const owner = ownerOf(current, name);
    const holdsOf = statementOfHolds(name);
    if (owner !== undefined && holdsOf !== undefined && current.nodes.get(owner)?.node.lean.statement === holdsOf) return true;
    const kind = vocabKind.get(name);
    if (kind !== undefined) return kind === 'unmarked-axiom';
    return owner === undefined && f?.typeSort !== undefined && normalizeWhitespace(f.typeSort) === 'Prop';
  };
  const frozenAxioms = freeze ? new Set(freeze.axioms) : undefined;
  for (const name of axiomNames(current)) {
    const entry = S.byName.get(name);
    const f = factsOf(current, name, entry);
    const belief = isBelief(name, f);
    if (frozenAxioms) {
      if (frozenAxioms.has(name)) continue;
      push({
        step: 'G3',
        code: 'new-axiom',
        message: `${loc(entry)}${name} is an axiom added after freeze_statements: no axiom may be added after the freeze${belief ? ', and only the person adds beliefs (propose a missing premise with propose_assumption)' : ''}; remove it.`,
        names: [name],
        token: belief ? 'belief' : 'after-freeze',
        ...at(entry),
      });
      continue;
    }
    if (inBase(name) || allowedHolds.has(name) || !belief) continue;
    const owner = ownerOf(current, name);
    const what =
      owner !== undefined && statementOfHolds(name) !== undefined
        ? `asserts the card ${owner} (${quote(sentence(owner))}), which is not a selected assumption: only the .holds of the selected ASSUMPTION cards may be axioms`
        : `is a Prop-valued axiom (a belief${f?.type !== undefined ? ` of type \`${normalizeWhitespace(f.type)}\`` : ''}): only the person adds beliefs; propose a missing premise with propose_assumption instead`;
    push({ step: 'G3', code: 'new-axiom', message: `${loc(entry)}${name} ${what}; remove it.`, names: [name], token: 'belief', ...node(owner), ...at(entry) });
  }

  // ---- existing-changed: every declaration of B keeps its text (docstring included) and, with B's facts, its meaning
  for (const [name, before] of B.byName) {
    if (exempt.has(name)) continue;
    const entry = S.byName.get(name);
    const owner = ownerOf(base, name);
    const isTarget = targetStatements.has(name);
    const common = { step: 'G3' as const, code: 'existing-changed' as const, names: [name], ...node(owner) };
    if (!entry) {
      push({
        ...common,
        message: `${loc(before)}${name} existed before the run and was removed: never change or remove a declaration that existed before the run (except the target's .holds); restore it.`,
        token: isTarget ? 'target' : 'removed',
        file: before.file.path,
        range: before.decl.range,
      });
      continue;
    }
    if (entry.text !== before.text) {
      push({
        ...common,
        message: `${loc(entry)}${name} existed before the run and was changed (its text, docstring included, must stay exactly as it was; only the target's .holds may change): restore it.`,
        token: isTarget ? 'target' : 'changed',
        ...at(entry),
      });
      continue;
    }
    if (base.facts === undefined) continue;
    const bf = factsOf(base, name, before);
    const cf = factsOf(current, name, entry);
    if (!bf || !cf) continue;
    const typeChanged = norm(bf.type) !== norm(cf.type);
    if (typeChanged || norm(bf.value) !== norm(cf.value)) {
      const [was, now] = typeChanged ? [norm(bf.type), norm(cf.type)] : [norm(bf.value), norm(cf.value)];
      push({
        ...common,
        message: `${loc(entry)}${name}'s text is unchanged but its meaning changed (its ${typeChanged ? 'type' : 'value'} was \`${was ?? '(none)'}\`, now \`${now ?? '(none)'}\`), e.g. through an \`open … in\` or a new declaration it now refers to: restore what it meant.`,
        token: isTarget ? 'target' : 'meaning',
        ...at(entry),
      });
    }
  }
  // telelean's adopted ghosts: their statement and `.holds` stay as written at adoption (A)
  if (input.adopted) {
    const A = declTables(input.adopted);
    for (const id of input.teleleanBlocks) {
      const ghost = input.adopted.nodes.get(id)?.node;
      const statement = ghost?.lean.statement;
      if (statement === undefined) continue;
      for (const name of [statement, holdsName(statement)]) {
        const was = A.byName.get(name);
        if (!was) continue;
        const entry = S.byName.get(name);
        if (entry?.text === was.text) continue;
        push({
          step: 'G3',
          code: 'existing-changed',
          message: `${loc(entry ?? was)}${name}, which telelean wrote for the adopted suggestion ${id}, was ${entry ? 'changed' : 'removed'}: leave it exactly as telelean wrote it.`,
          names: [name],
          nodeId: id,
          token: 'ghost',
          ...(entry ? at(entry) : { file: was.file.path, range: was.decl.range }),
        });
      }
    }
  }

  // ---- not-proved (gate-proved): T.holds exists, is a theorem stating exactly T, no sorry, not conditional
  if (purpose === 'gate-proved') {
    const t = curTarget;
    const proof = t?.status.proof;
    if (!t || proof?.kind !== 'proved') {
      const holds = targetHolds ?? `${selection.target}.holds`;
      const entry = S.byName.get(holds);
      const hf = factsOf(current, holds, entry);
      const s = targetStatement !== undefined ? short(targetStatement) : selection.target;
      let token: string;
      let why: string;
      if (!t || t.lean.statement === undefined) {
        token = 'missing';
        why = `the target ${selection.target} has no statement, so there is nothing proved`;
      } else if (t.lean.justification === undefined) {
        token = 'missing';
        why = `${holds} does not exist: prove \`theorem ${s}.holds : ${s} := …\`, or remove every proof of the target and finish with status not_proved`;
      } else if (t.lean.justificationKind === 'axiom') {
        token = 'axiom';
        why = `${holds} is an axiom, not a proof: replace it by \`theorem ${s}.holds : ${s} := …\``;
      } else if (t.status.flags.includes('uses-sorry')) {
        token = 'sorry';
        why = `${holds} uses sorry: give a complete proof`;
      } else if (t.status.flags.includes('holds-mismatch')) {
        token = 'mismatch';
        why = `${holds} proves \`${norm(hf?.type) ?? '(unknown)'}\`, not \`${targetStatement}\`: prove exactly the frozen statement`;
      } else if (proof?.kind === 'conditional') {
        token = 'conditional';
        why = `${holds} takes hypotheses (${proof.on.join(', ')}): prove the target itself, using the selected premises' .holds`;
      } else {
        token = 'unchecked';
        why = `Lean could not check ${holds} (no facts for it): make sure the files build`;
      }
      push({ step: 'G3', code: 'not-proved', message: `${loc(entry)}${why}.`, names: [holds], nodeId: selection.target, token, ...at(entry) });
    }
  }

  // ---- status-mismatch (gate-other): no theorem T.holds added or changed in the run
  if (purpose === 'gate-other' && targetHolds !== undefined) {
    const entry = S.byName.get(targetHolds);
    const cf = factsOf(current, targetHolds, entry);
    if (entry && !isAxiom(entry, cf)) {
      const before = B.byName.get(targetHolds);
      const baseTheorem = before !== undefined && !isAxiom(before, factsOf(base, targetHolds, before));
      if (!before || !baseTheorem || before.text !== entry.text) {
        push({
          step: 'G3',
          code: 'status-mismatch',
          message: `${loc(entry)}you finished without status proved, but ${targetHolds} is a proof added or changed in this run: either finish with status proved (after freeze_statements), or remove the proof of the target before finishing.`,
          names: [targetHolds],
          nodeId: selection.target,
          ...at(entry),
        });
      }
    }
  }

  // ---- statement-changed: after the freeze, every frozen declaration but T.holds keeps its kind, type and value
  if (freeze && (checkProve || gate)) {
    for (const [name, frozen] of Object.entries(freeze.declarations)) {
      if (exempt.has(name)) continue;
      const entry = S.byName.get(name);
      const cf = factsOf(current, name, entry);
      if (!cf) {
        if (!entry && !current.declFacts.has(name)) {
          push({ step: 'G3', code: 'statement-changed', message: `${name} was frozen by freeze_statements and has been removed: restore it exactly as frozen.`, names: [name], token: 'removed', ...node(ownerOf(current, name)) });
        }
        continue;
      }
      const kindChanged = frozen.kind !== undefined && cf.kind !== undefined && frozen.kind !== cf.kind;
      const typeChanged = norm(frozen.type) !== norm(cf.type);
      const valueChanged = norm(frozen.value) !== norm(cf.value);
      if (!kindChanged && !typeChanged && !valueChanged) continue;
      const detail = kindChanged
        ? `it was ${frozen.kind === 'def' ? 'a definition' : `a ${frozen.kind}`}, now ${cf.kind === 'def' ? 'a definition' : `a ${cf.kind}`}`
        : typeChanged
          ? `its type was \`${frozen.type ?? '(none)'}\`, now \`${norm(cf.type) ?? '(none)'}\``
          : `its value was \`${frozen.value ?? '(none)'}\`, now \`${norm(cf.value) ?? '(none)'}\``;
      push({
        step: 'G3',
        code: 'statement-changed',
        message: `${loc(entry)}${name} changed after freeze_statements (${detail}): the frozen statements, vocabulary and definitions must stay exactly as frozen.`,
        names: [name],
        ...(targetStatements.has(name) ? { token: 'target' } : {}),
        ...node(ownerOf(current, name)),
        ...at(entry),
      });
    }
  }

  // ---- footprint: T.holds (gate-proved, check in stage prove) and every proof added or changed in the run
  const permitted: PermittedAxioms | undefined = checkProve || gate ? (freeze?.permitted ?? permittedAxioms(current, selection, false)) : undefined;
  const footprints: Record<string, string[]> = {};
  const proofsOfRun: string[] = [];
  if (targetHolds !== undefined && S.byName.has(targetHolds) && (purpose === 'gate-proved' || checkProve || addedOrChanged.has(targetHolds))) {
    const entry = S.byName.get(targetHolds);
    if (isProof(current, entry, factsOf(current, targetHolds, entry))) proofsOfRun.push(targetHolds);
  }
  for (const name of [...added, ...changed]) {
    if (name === targetHolds) continue;
    const entry = S.byName.get(name);
    if (isProof(current, entry, factsOf(current, name, entry))) proofsOfRun.push(name);
  }
  for (const name of proofsOfRun) {
    const entry = S.byName.get(name);
    const f = factsOf(current, name, entry);
    if (f?.axioms !== undefined) footprints[name] = [...f.axioms];
    if (!permitted || !f) continue;
    if (f.axioms === undefined) {
      if (!gate) continue;
      push({ step: 'G3', code: 'footprint', message: `${loc(entry)}Lean could not list the axioms of ${name}, so it cannot be checked: make sure the files build.`, names: [name], ...node(ownerOf(current, name)), ...at(entry) });
      continue;
    }
    const allowed = new Set(permitted.all);
    const extra = f.axioms.filter((a) => a !== SORRY_AXIOM && !allowed.has(a));
    if (extra.length === 0) continue;
    const described = extra.map((a) => {
      const owner = ownerOf(current, a);
      return owner !== undefined ? `${a} (${quote(sentence(owner))}, not selected)` : a;
    });
    const selected = [...permitted.selected, ...permitted.derivationFootprints.filter((a) => statementOfHolds(a) !== undefined)];
    push({
      step: 'G3',
      code: 'footprint',
      message: `${loc(entry)}${name} rests on ${described.join(', ')}, outside the permitted set: every proof may use only the selected premises${selected.length > 0 ? ` (${[...new Set(selected)].join(', ')})` : ''}, the vocabulary, the existence presuppositions of the statements and Lean's standard axioms.`,
      names: extra,
      ...node(ownerOf(current, name)),
      ...at(entry),
    });
  }
  if (targetHolds !== undefined && footprints[targetHolds] === undefined) {
    const f = factsOf(current, targetHolds, S.byName.get(targetHolds));
    if (f?.axioms !== undefined && f.kind !== 'axiom') footprints[targetHolds] = [...f.axioms];
  }

  // ---- sorry-axiom: no sorryAx in a declaration of a changed file (the user's own unchanged sorry stays theirs)
  for (const [name, f] of current.declFacts) {
    if (!changedFiles.has(f.file) || !(f.usesSorry === true || (f.axioms ?? []).includes(SORRY_AXIOM))) continue;
    const entry = S.byName.get(name);
    const before = B.byName.get(name);
    if (before && entry && before.text === entry.text) {
      const bf = base.facts === undefined ? undefined : factsOf(base, name, before);
      if (base.facts === undefined || bf?.usesSorry === true || (bf?.axioms ?? []).includes(SORRY_AXIOM)) continue;
    }
    push({ step: 'G3', code: 'sorry-axiom', message: `${loc(entry)}${name} depends on sorry (sorryAx): give a complete proof, or remove it.`, names: [name], token: 'sorry', ...node(ownerOf(current, name)), ...at(entry) });
  }

  // ---- vocabulary-shape: new vocabulary passes the simple D-3 shape rule
  for (const item of current.vocabulary) {
    if (inBase(item.name) || item.kind === 'unmarked-axiom') continue;
    if (!item.flags.includes('shape-violation') && item.kind !== 'other') continue;
    const entry = S.byName.get(item.name);
    const reason = current.diagnostics.find((d) => d.code === 'TL111' && d.vocab === item.name)?.message;
    push({
      step: 'G3',
      code: 'vocabulary-shape',
      message: `${loc(entry)}${reason ?? `${item.name} is not a vocabulary shape telelean accepts`} Vocabulary may only be sorts \`axiom T : Type\`, predicates \`axiom P : T₁ → … → Prop\` over sorts, and constants or functions as \`noncomputable opaque\`.`,
      names: [item.name],
      ...(item.loc ? { file: item.loc.file, range: item.loc.range } : at(entry)),
    });
  }

  // ---- G5 markup
  for (const finding of markupFindings(input, chosen, sentence)) push(finding);

  // ---- readiness (freeze, gate-proved): the target and the selected assumptions and ghosts are formalised
  if (purpose === 'freeze' || purpose === 'gate-proved') {
    const ready = [selection.target, ...selection.premises.filter((id) => current.nodes.get(id)?.node.type === 'ASSUMPTION' || ghosts.includes(id)), ...ghosts];
    for (const id of [...new Set(ready)]) {
      const entry = current.nodes.get(id);
      if (!entry) continue;
      const n = entry.node;
      const assumption = id !== selection.target;
      if (!formalised(current, n)) {
        push({
          step: 'G3',
          code: 'not-formalised',
          message: `${where(entry.file, entry.block.range)}: the card ${id} (${quote(n.naturalName)}) has no Lean statement: write \`/-- <its sentence> -/\` and \`abbrev <name> : Prop := <statement>\`${assumption ? ' and `axiom <name>.holds : <name>`' : ''} directly below its block.`,
          nodeId: id,
          file: entry.file,
          range: entry.block.range,
        });
        continue;
      }
      if (!assumption) continue;
      const statement = n.lean.statement as string;
      const s = short(statement);
      if (n.lean.justification === undefined) {
        push({
          step: 'G3',
          code: 'missing-holds',
          message: `${where(entry.file, entry.block.range)}: the selected assumption ${id} (${quote(n.naturalName)}) has no \`axiom ${s}.holds : ${s}\`: add it right after \`abbrev ${s}\`.`,
          names: [holdsName(statement)],
          nodeId: id,
          token: 'missing',
          file: entry.file,
          range: entry.block.range,
        });
      } else if (n.status.flags.includes('holds-mismatch')) {
        push({
          step: 'G3',
          code: 'missing-holds',
          message: `${where(entry.file, entry.block.range)}: ${holdsName(statement)} does not state ${statement}: write exactly \`axiom ${s}.holds : ${s}\`.`,
          names: [holdsName(statement)],
          nodeId: id,
          token: 'mismatch',
          file: entry.file,
          range: entry.block.range,
        });
      }
    }
  }

  // ---- proof-before-freeze (check in stage formalise, freeze): no proof added or changed since the round started
  if ((checkFormalise || purpose === 'freeze') && !freeze) {
    for (const [name, entry] of S.byName) {
      const before = R.byName.get(name);
      if (before && before.text === entry.text) continue;
      if (!isProof(current, entry, factsOf(current, name, entry))) continue;
      push({
        step: 'G3',
        code: 'proof-before-freeze',
        message: `${loc(entry)}${name} is a proof written before freeze_statements: no proofs before the freeze (D-19); remove it, call freeze_statements, then prove.`,
        names: [name],
        ...node(ownerOf(current, name)),
        ...at(entry),
      });
    }
    const earlier = new Map<string, number>();
    for (const example of R.examples) earlier.set(example.text, (earlier.get(example.text) ?? 0) + 1);
    for (const example of S.examples) {
      const left = earlier.get(example.text) ?? 0;
      if (left > 0) {
        earlier.set(example.text, left - 1);
        continue;
      }
      push({
        step: 'G3',
        code: 'proof-before-freeze',
        message: `${where(example.file.path, example.decl.range)}: an \`example\` is a proof, written before freeze_statements: remove it.`,
        token: 'example',
        file: example.file.path,
        range: example.decl.range,
      });
    }
  }

  // ---- not-frozen (gate-proved)
  if (purpose === 'gate-proved' && !freeze) {
    push({
      step: 'G3',
      code: 'not-frozen',
      message: 'finish with status proved needs a successful freeze_statements in this round: call check_lean and freeze_statements first, then prove and call finish again.',
      nodeId: selection.target,
    });
  }

  // ---- flagged definitions (questions, never failures)
  const flaggedDefinitions = flagged(input, chosen, inBase);

  // ---- the run's new statements (normalisation pins them)
  const formalisedThisRun: string[] = [];
  for (const id of chosen) {
    if (bound(current.nodes.get(id)?.node) === undefined) continue;
    if (bound(base.nodes.get(id)?.node) === undefined) formalisedThisRun.push(id);
  }

  const ordered = [...(findings.get('build') ?? []), ...G3_ORDER.flatMap((c) => findings.get(c) ?? []), ...(findings.get('markup') ?? []), ...LATE_ORDER.flatMap((c) => findings.get(c) ?? [])];
  return { findings: ordered, flaggedDefinitions, footprints, formalisedThisRun, declarations: { added, changed, removed } };
}

/** New definitions on a statement path and new presuppositions (A2, D-4, D-3). */
function flagged(input: RuleInput, chosen: ReadonlySet<string>, inBase: (name: string) => boolean): FlaggedDefinition[] {
  const { current } = input;
  const out: FlaggedDefinition[] = [];
  const closureOfChosen = new Set<string>();
  for (const id of chosen) for (const name of current.nodes.get(id)?.node.lean.uses ?? []) closureOfChosen.add(name);
  /** Definitions other (non-definition) vocabulary items refer to, e.g. `noncomputable opaque c : Pair`. */
  const usedByVocabulary = new Set<string>();
  for (const item of current.vocabulary) {
    if (item.kind === 'definition') continue;
    for (const ref of current.declFacts.get(item.name)?.refs ?? []) usedByVocabulary.add(ref.name);
  }
  for (const item of current.vocabulary) {
    if (inBase(item.name)) continue;
    if (item.kind === 'definition') {
      const onPath = item.usedBy.length > 0 || item.flags.includes('definitional-choice') || closureOfChosen.has(item.name) || usedByVocabulary.has(item.name);
      if (!onPath) continue;
      out.push({ name: item.name, kind: 'definition', ...(item.code !== undefined ? { code: item.code } : {}), ...(item.gloss !== undefined ? { gloss: item.gloss } : {}), usedByStatementsOf: [...item.usedBy] });
    } else if (item.kind === 'presupposition') {
      out.push({ name: item.name, kind: 'presupposition', ...(item.code !== undefined ? { code: item.code } : {}), ...(item.gloss !== undefined ? { gloss: item.gloss } : {}), usedByStatementsOf: [...item.usedBy] });
    }
  }
  return out;
}

/** G5: the user's words, ids, `lean:` lines and bindings; no new blocks but telelean's own (docs/m2-plan.md 3.3). */
function markupFindings(input: RuleInput, chosen: ReadonlySet<string>, sentence: (id: string) => string): GateFinding[] {
  const { base, current } = input;
  const out: GateFinding[] = [];
  const baseIds = nodeIdsOfBlocks(base);
  const curIds = nodeIdsOfBlocks(current);
  const keyOf = (ids: Map<MarkupBlock, string>, block: MarkupBlock) => ids.get(block) ?? block.id;
  const telelean = new Set(input.teleleanBlocks);
  const B = declTables(base);
  const blocksOf = (file: ParsedFile | undefined, ids: Map<MarkupBlock, string>, key: string) => (file?.blocks ?? []).filter((b) => keyOf(ids, b) === key);
  const finding = (block: MarkupBlock, file: string, key: string, token: string, message: string, names?: string[]): GateFinding => ({
    step: 'G5',
    code: 'markup',
    message: `${where(file, block.range)}: ${message}`,
    nodeId: key,
    token,
    file,
    range: block.range,
    ...(names ? { names } : {}),
  });
  const matched = new Set<MarkupBlock>();
  const files = [...base.files.values()].sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0));
  for (const bFile of files) {
    const cFile = current.files.get(bFile.path);
    const seen = new Map<string, number>();
    for (const bBlock of bFile.blocks) {
      const key = keyOf(baseIds, bBlock);
      const k = seen.get(key) ?? 0;
      seen.set(key, k + 1);
      const sBlock = blocksOf(cFile, curIds, key)[k];
      const label = `the block ${key} (${quote(bBlock.fields.naturalName ?? sentence(key))})`;
      if (!sBlock) {
        const elsewhere = [...current.files.values()].find((f) => f.path !== bFile.path && blocksOf(f, curIds, key).length > 0);
        out.push(
          elsewhere
            ? finding(bBlock, bFile.path, key, 'moved', `${label} moved from ${bFile.path} to ${elsewhere.path}: blocks stay in their file; move it back.`)
            : finding(bBlock, bFile.path, key, 'removed', `${label} was removed: never add or delete blocks; restore it exactly.`),
        );
        continue;
      }
      matched.add(sBlock);
      const path = bFile.path;
      // the user's words and every other field, raw
      for (const field of COMPARED_FIELDS) {
        const was = raws(bBlock, field);
        const now = raws(sBlock, field);
        if (sameList(was, now)) continue;
        const show = (list: string[]) => (list.length === 0 ? '(absent)' : list.map(quote).join(', '));
        const words = field === 'natural_name' || field === 'rationale';
        out.push(
          finding(
            sBlock,
            path,
            key,
            field,
            `${label} changed its \`${field}:\` (${show(was)} → ${show(now)}): ${words ? "the person's words are the specification and stay byte-identical" : 'never change any field of a block'}; restore it.`,
          ),
        );
      }
      if (bBlock.version !== sBlock.version) out.push(finding(sBlock, path, key, 'version', `${label} changed its markup version: restore \`@@ telelean v${bBlock.version}\`.`));
      if (JSON.stringify(bBlock.extensions) !== JSON.stringify(sBlock.extensions)) out.push(finding(sBlock, path, key, 'extension', `${label} changed its extension fields: restore them.`));
      if ((bBlock.body ?? '') !== (sBlock.body ?? '')) out.push(finding(sBlock, path, key, 'body', `${label} changed its notes (after \`---\`): restore them.`));
      // ids: unchanged, or the derived id written back (TL112)
      const idWas = raws(bBlock, 'id');
      const idNow = raws(sBlock, 'id');
      const idOk = bBlock.idWritten ? sameList(idWas, idNow) : idNow.length === 0 || (idNow.length === 1 && (idNow[0] === key || idNow[0] === bBlock.id));
      if (!idOk) out.push(finding(sBlock, path, key, 'id', `${label} changed its \`id:\` line: ids are stable; restore it.`));
      // `lean:` lines: never changed or removed; added only by telelean's normalisation
      const leanWas = raws(bBlock, 'lean');
      const leanNow = raws(sBlock, 'lean');
      const bNode = base.nodes.get(key)?.node;
      const sNode = current.nodes.get(key)?.node;
      let leanFinding = false;
      if (leanWas.length > 0 && !sameList(leanWas, leanNow)) {
        leanFinding = true;
        out.push(
          finding(
            sBlock,
            path,
            key,
            'lean',
            `${label}'s \`lean:\` line changed (${leanWas.join(', ')} → ${leanNow.length > 0 ? leanNow.join(', ') : '(removed)'}): a \`lean:\` line is never changed or removed; restore it.`,
            [bNode?.lean.statement ?? leanWas[0] ?? '', sNode?.lean.statement ?? leanNow[0] ?? ''],
          ),
        );
      } else if (leanWas.length === 0 && leanNow.length > 0) {
        const pinned = sNode?.lean.statement;
        const adjacent = sBlock.binding.adjacentDecl !== undefined ? current.files.get(path)?.decls[sBlock.binding.adjacentDecl]?.fullName : undefined;
        const legal = chosen.has(key) && bBlock.binding.mode === 'none' && pinned !== undefined && pinned === adjacent && !B.known.has(pinned);
        if (!legal) {
          leanFinding = true;
          out.push(
            finding(
              sBlock,
              path,
              key,
              'lean',
              `a \`lean:\` line was added to ${label}: telelean pins a statement itself, and only for the target and the selected premises formalised in this run, naming the declaration directly below the block; remove it.`,
              ['', pinned ?? leanNow[0] ?? ''],
            ),
          );
        }
      }
      // bindings: a card formalised in B keeps its statement; unselected cards do not become formalised
      if (!leanFinding && bNode && sNode) {
        const was = bound(bNode);
        const now = bound(sNode);
        if (was !== undefined && was !== now) {
          out.push(
            finding(
              sBlock,
              path,
              key,
              'binding',
              `the card ${key} was bound to ${was} before the run and is now bound to ${now ?? 'nothing'}: a card formalised before the run keeps its statement; put any new declaration elsewhere (not directly below its block).`,
              [was, now ?? ''],
            ),
          );
        } else if (was === undefined && now !== undefined && !chosen.has(key)) {
          out.push(
            finding(
              sBlock,
              path,
              key,
              'formalised',
              `the card ${key} (${quote(sNode.naturalName)}) is not selected but is now bound to ${now}: formalise only the target and the selected premises; leave a blank line between its block and that declaration, or move the declaration.`,
              [now],
            ),
          );
        }
      }
    }
  }
  // new blocks: only telelean's adopted ghosts, exactly as written at adoption (A)
  for (const cFile of [...current.files.values()].sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0))) {
    for (const sBlock of cFile.blocks) {
      if (matched.has(sBlock)) continue;
      const key = keyOf(curIds, sBlock);
      if (telelean.has(key)) {
        const adoptedFile = input.adopted?.files.get(cFile.path);
        const adoptedIds = input.adopted ? nodeIdsOfBlocks(input.adopted) : new Map<MarkupBlock, string>();
        const original = adoptedFile ? blocksOf(adoptedFile, adoptedIds, key)[0] : undefined;
        if (original && adoptedFile && adoptedFile.text.slice(original.span.start, original.span.end) === cFile.text.slice(sBlock.span.start, sBlock.span.end)) continue;
        out.push(finding(sBlock, cFile.path, key, 'telelean', `the block ${key} that telelean wrote for an adopted suggestion was changed: leave it exactly as telelean wrote it.`));
        continue;
      }
      out.push(finding(sBlock, cFile.path, key, 'block', `a new telelean block (${key}) was added: never add or delete blocks; propose a missing premise with propose_assumption instead.`));
    }
  }
  // telelean's own blocks must not disappear either
  if (input.adopted) {
    const adoptedIds = nodeIdsOfBlocks(input.adopted);
    for (const aFile of input.adopted.files.values()) {
      for (const aBlock of aFile.blocks) {
        const key = keyOf(adoptedIds, aBlock);
        if (!telelean.has(key)) continue;
        if (blocksOf(current.files.get(aFile.path), curIds, key).length > 0) continue;
        out.push(finding(aBlock, aFile.path, key, 'telelean', `the block ${key} that telelean wrote for an adopted suggestion was removed: restore it exactly.`));
      }
    }
  }
  return out;
}

