/**
 * telelean's deterministic normalisation before every gate (docs/m2-plan.md section 3.4) and the confirmed lifecycle
 * items of a proposal (D-21). Both go through WP-markup's primitives via the edit session, so every byte outside the
 * edited lines stays as it was.
 */
import { ActionError, type FileChange } from '../actions.js';
import { EditSession } from '../edit/session.js';
import { setBlockFields } from '../markup/edits.js';
import { escapeBodyText } from '../markup/values.js';
import type { ProjectModel } from '../project/types.js';
import type { LifecycleItem } from '../run.js';

/** See `normalisationChanges` in ./index.ts. */
export function normalisation(model: ProjectModel, nodeIds: readonly string[]): FileChange[] {
  const session = new EditSession(model);
  for (const id of [...new Set(nodeIds)]) {
    const entry = model.nodes.get(id);
    if (!entry || !entry.statementDecl) continue;
    const node = entry.node;
    const statement = node.lean.statement;
    if (statement === undefined || node.lean.binding === 'none') continue;
    // D-8 pin (with the derived id written back, TL112, as every block edit does), or just the id.
    if (node.lean.binding === 'adjacent') session.setField(entry.file, entry.block, id, 'lean', [statement]);
    else if (!entry.block.idWritten) session.setField(entry.file, entry.block, id, 'id', id);
    // D-9 docstring mirror.
    const sentence = node.naturalName.trim();
    if (sentence === '') continue;
    if (entry.statementDecl.decl.docstring !== escapeBodyText(sentence).trim()) {
      session.leanOps(entry.statementDecl.file, [{ op: 'set-docstring', decl: statement, text: sentence }]);
    }
  }
  return session.changes();
}

/** See `lifecycleChanges` in ./index.ts. */
export function lifecycle(model: ProjectModel, items: readonly LifecycleItem[]): FileChange[] {
  const session = new EditSession(model);
  for (const item of items) {
    const entry = model.nodes.get(item.nodeId);
    if (item.kind !== 'change-kind') throw new ActionError('unsafe', `Unknown lifecycle item ${JSON.stringify(item.kind)}.`);
    if (!entry) throw new ActionError('unsafe', `The card "${item.nodeId}" no longer exists, so "${item.reason}" no longer applies.`);
    const node = entry.node;
    if (item.from !== 'GOAL' || item.to !== 'DERIVATION') {
      throw new ActionError('unsafe', `Only "Make Derivation" of a proved goal is applied with a proposal (got ${item.from} → ${item.to}).`);
    }
    if (node.type !== item.from) throw new ActionError('unsafe', `"${node.naturalName}" is no longer a goal (it is a ${node.type.toLowerCase()}), so it cannot be made a derivation now.`);
    if (node.status.proof.kind !== 'proved') throw new ActionError('unsafe', `"${node.naturalName}" is no longer proved, so it cannot be made a derivation now.`);
    // Only the `type:` line (06.2: "type only (already proved)"); no pin, no id line.
    const block = session.block(entry.file, entry.block);
    session.apply(entry.file, setBlockFields(session.parsed(entry.file), { ...block, idWritten: true }, [{ key: 'type', value: item.to }]));
  }
  return session.changes();
}

/**
 * D-6 ghost adoption ("I hold this", docs/m2-plan.md section 4.9): the new ASSUMPTION card Claude suggested, written
 * by telelean right before the target's block, with exactly the statement text the ghost check elaborated. The plan
 * re-parses what it would write and refuses unless the result is exactly the expected card, bound to the new
 * statement, with every other card's binding unchanged.
 */
import { ActionError, type FileChange } from '../actions.js';
import { holdsName } from '../facts.js';
import { DECL_KEYWORDS, MODIFIERS, isCommandWord } from '../markup/decls.js';
import { insertionEdit } from '../markup/edits.js';
import { deriveId } from '../markup/ids.js';
import { lexLean } from '../markup/lexer.js';
import { parseLeanFile } from '../markup/parser.js';
import { renderBlock } from '../markup/serializer.js';
import { applyTextEdits } from '../markup/edits.js';
import { Lines } from '../markup/text.js';
import { escapeBodyText } from '../markup/values.js';
import type { ProjectModel } from '../project/types.js';
import { collapseWhitespace, ghostProblems, scanForbiddenText } from './g0.js';
import type { GhostAdoptionPlan, GhostAdoptionRequest } from './types.js';

/** Words that cannot name a declaration (Lean 4 keywords and command words). */
const KEYWORDS: ReadonlySet<string> = new Set([
  ...DECL_KEYWORDS,
  ...MODIFIERS,
  'fun',
  'let',
  'have',
  'show',
  'from',
  'suffices',
  'by',
  'do',
  'then',
  'else',
  'if',
  'match',
  'with',
  'at',
  'in',
  'where',
  'forall',
  'calc',
  'nomatch',
  'nofun',
  'return',
  'for',
  'unless',
  'mut',
  'try',
  'catch',
  'finally',
  'break',
  'continue',
  'this',
  'Type',
  'Sort',
  'Prop',
  'sorry',
  'admit',
  'deriving',
  'termination_by',
  'decreasing_by',
  'using',
  'obtain',
  'rfl',
]);

/** A plain, undotted ASCII identifier that is no keyword. */
function validName(name: string): boolean {
  return /^[A-Za-z_][A-Za-z0-9_']*$/.test(name) && !KEYWORDS.has(name) && !isCommandWord(name);
}

const DATE = /^\d{4}-\d{2}-\d{2}$/;
const SESSION = /^[A-Za-z0-9][A-Za-z0-9_.:+-]*$/;

export function adoptionPlan(model: ProjectModel, request: GhostAdoptionRequest): GhostAdoptionPlan {
  const target = model.nodes.get(request.target);
  if (!target || target.node.subject !== request.subject) throw new ActionError('not-found', `No card "${request.target}" in the subject ${request.subject}.`);
  const statement = collapseWhitespace(request.leanStatement);
  const problems = ghostProblems(statement);
  if (problems.length > 0) throw new ActionError('invalid', `The suggested statement cannot be written safely: ${problems.join(' ')}`);
  const sentence = request.naturalName.trim();
  if (sentence === '' || /[\r\n]/.test(sentence)) throw new ActionError('invalid', 'The suggested sentence must be one non-empty line.');
  const rationale = request.rationale?.trim();
  if (rationale !== undefined && /[\r\n]/.test(rationale)) throw new ActionError('invalid', 'The reason must be one line.');
  if (!DATE.test(request.today)) throw new ActionError('invalid', `"${request.today}" is not a date (YYYY-MM-DD).`);
  if (!SESSION.test(request.session)) throw new ActionError('invalid', `"${request.session}" cannot be written as a session id.`);

  const path = target.file;
  const file = model.files.get(path);
  if (!file) throw new ActionError('not-found', `The target's file ${path} is not in the model.`);
  const namespace = target.block.namespace ?? [];
  const prefix = namespace.length > 0 ? `${namespace.join('.')}.` : '';

  // Names the project's code uses (a new declaration named like one would shadow it inside the namespace).
  const used = new Set<string>();
  for (const f of model.files.values()) {
    for (const token of lexLean(f.text).tokens) if (token.kind === 'ident') used.add(token.text.split('.')[0] ?? token.text);
  }
  const declared = (fq: string) => model.declFacts.has(fq) || [...model.files.values()].some((f) => f.decls.some((d) => d.fullName === fq));
  const taken = (name: string) => used.has(name) || declared(`${prefix}${name}`) || declared(`${prefix}${name}.holds`) || declared(name);
  let name: string;
  if (request.leanName !== undefined && validName(request.leanName) && !taken(request.leanName)) name = request.leanName;
  else {
    let base = deriveId(sentence, () => false).replace(/[-.]/g, '_');
    if (!/^[A-Za-z]/.test(base) || !validName(base)) base = `ghost_${base}`;
    name = base;
    for (let n = 2; taken(name); n++) name = `${base}_${n}`;
  }
  if (!validName(name)) throw new ActionError('invalid', `"${name}" is not a valid Lean name.`);

  const ids = new Set<string>(model.nodes.keys());
  for (const f of model.files.values()) for (const block of f.blocks) ids.add(block.id);
  const nodeId = deriveId(sentence, (id) => ids.has(id));
  const qualified = `${prefix}${name}`;

  const eol = file.eol;
  const blockText = renderBlock(
    {
      id: nodeId,
      type: 'ASSUMPTION',
      naturalName: sentence,
      ...(rationale ? { rationale } : {}),
      asserted: request.today,
      lean: [qualified],
      extra: [
        ['origin', 'agent'],
        ['session', request.session],
        ['worded_by', 'agent'],
      ],
    },
    eol,
  );
  const code = [`/-- ${escapeBodyText(sentence)} -/`, `abbrev ${name} : Prop := ${statement}`, `axiom ${name}.holds : ${name}`].join(eol);
  const forbidden = scanForbiddenText(path, code, { library: model.library, subject: request.subject, projectModules: new Set() });
  if (forbidden.length > 0) throw new ActionError('invalid', `The suggested statement cannot be written: ${forbidden.map((f) => f.message).join(' ')}`);

  const lines = new Lines(file.text);
  const offset = lines.start(lines.lineOf(target.block.span.start));
  const after = applyTextEdits(file.text, [insertionEdit(file.text, eol, offset, `${blockText}${eol}${code}`, lines)]);

  // The result must parse to exactly the new card, pinned to the new statement, with every other binding unchanged.
  const parsed = parseLeanFile(path, after);
  const added = parsed.blocks.filter((b) => b.id === nodeId);
  const block = added[0];
  const ok =
    added.length === 1 &&
    block !== undefined &&
    block.idWritten &&
    block.fields.type === 'ASSUMPTION' &&
    block.fields.naturalName === sentence &&
    block.fields.wordedBy === 'agent' &&
    block.fields.origin === 'agent' &&
    block.fields.session === request.session &&
    block.binding.mode === 'pinned' &&
    block.binding.statement === qualified &&
    parsed.decls.some((d) => d.fullName === qualified && d.keyword === 'abbrev') &&
    parsed.decls.some((d) => d.fullName === holdsName(qualified) && d.keyword === 'axiom') &&
    parsed.blocks.length === file.blocks.length + 1 &&
    file.blocks.every((b) => {
      const now = parsed.blocks.find((x) => x.id === b.id && x !== block);
      return now !== undefined && now.binding.mode === b.binding.mode && now.binding.statement === b.binding.statement;
    });
  if (!ok) throw new ActionError('unsafe', `telelean could not insert the suggested assumption into ${path} without changing other cards; nothing was written.`);
  const change: FileChange = { path, before: file.text, after };
  return { changes: [change], nodeId, leanName: qualified };
}

/**
 * Findings as plain board sentences (amendment A2's notices, docs/m2-plan.md section 3.5), in telelean's words. Names
 * are shown relative to the subject's namespace (`new_spyro_pg.holds`, not `Spyro.new_spyro_pg.holds`): the namespace
 * comes from the finding's file (`<library>/<S>/…`), else known Lean namespaces are kept and a leading subject-like
 * component is dropped.
 */
import { subjectOfPath } from '../paths.js';
import type { DescribeContext, GateFinding } from './types.js';

/** Namespaces of Lean itself: never treated as a subject's namespace when shortening a name. */
const LEAN_NAMESPACES: ReadonlySet<string> = new Set([
  'Classical',
  'Quot',
  'Lean',
  'Nat',
  'Int',
  'List',
  'Array',
  'String',
  'Char',
  'Bool',
  'Prop',
  'Eq',
  'And',
  'Or',
  'Not',
  'Iff',
  'Exists',
  'Decidable',
  'Nonempty',
  'Inhabited',
  'Option',
  'Std',
  'Init',
  'Function',
  'Sigma',
  'Subtype',
  'PLift',
  'ULift',
  'Fin',
  'Float',
  'IO',
  'Except',
  'Unit',
  'PUnit',
  'True',
  'False',
  'HEq',
  'Prod',
  'Sum',
  'Empty',
  'Id',
]);

const code = (text: string) => `\`${text}\``;

/** The subject namespace a finding's file belongs to (`Model/Spyro/Main.lean` -> `Spyro`). */
function namespaceOf(finding: GateFinding): string | undefined {
  const file = finding.file;
  if (file === undefined) return undefined;
  const library = file.split('/')[0];
  return library === undefined ? undefined : subjectOfPath(file, library);
}

/** A Lean name as the board shows it. */
function display(name: string, finding: GateFinding): string {
  const namespace = namespaceOf(finding);
  if (namespace !== undefined) return name.startsWith(`${namespace}.`) && name.length > namespace.length + 1 ? name.slice(namespace.length + 1) : name;
  const dot = name.indexOf('.');
  if (dot < 0) return name;
  const first = name.slice(0, dot);
  return /^[A-Z]/.test(first) && !LEAN_NAMESPACES.has(first) ? name.slice(dot + 1) : name;
}

/** `a`, `a and b`, `a, b and c`. */
function listing(items: readonly string[]): string {
  if (items.length <= 1) return items[0] ?? '';
  return `${items.slice(0, -1).join(', ')} and ${items[items.length - 1]}`;
}

/** “sentence” of a card, or its id in backticks when the board does not know it. */
function cardLabel(id: string | undefined, ctx: DescribeContext): string {
  if (id === undefined) return 'a card';
  const sentence = ctx.sentenceOf(id);
  return sentence !== undefined ? `“${sentence}”` : `the card ${code(id)}`;
}

/** ` in Model/Spyro/Main.lean line 12`, from a G0 finding's position. */
function inFile(finding: GateFinding): string {
  if (finding.file === undefined) return '';
  return finding.range ? ` in ${finding.file} line ${finding.range.start.line + 1}` : ` in ${finding.file}`;
}

/** The axioms a proof used outside the permitted set. */
function usedAxioms(finding: GateFinding, ctx: DescribeContext, brief: boolean): string {
  const names = finding.names ?? [];
  if (names.length === 0) return 'it used an axiom that is not allowed here';
  const own = names.filter((n) => finding.nodeId !== undefined && ctx.nodeOfDecl(n) === finding.nodeId);
  if (own.length > 0 && own.length === names.length) return `it used the claim it had to prove (${listing(own.map((n) => code(display(n, finding))))})`;
  const parts: string[] = [];
  let allUnselectedCards = true;
  for (const name of names) {
    const card = ctx.nodeOfDecl(name);
    const shown = code(display(name, finding));
    if (card !== undefined && !ctx.selected.includes(card)) parts.push(brief ? shown : `${cardLabel(card, ctx)} (${shown})`);
    else {
      allUnselectedCards = false;
      parts.push(shown);
    }
  }
  return `it used ${listing(parts)}, which ${allUnselectedCards ? "you didn't select" : 'the selected premises do not allow'}`;
}

/** See `describeFinding` in ./index.ts; `brief` drops card sentences (the give-up notice). */
export function describe(finding: GateFinding, ctx: DescribeContext, brief = false): string {
  const name = finding.names?.[0];
  const shown = name !== undefined ? code(display(name, finding)) : undefined;
  const token = finding.token;
  switch (finding.code) {
    case 'hash-command':
      return `it used a forbidden command (${code(token ?? '#')})${inFile(finding)}`;
    case 'metaprogramming':
      return `it used metaprogramming (${code(token ?? 'macro')})${inFile(finding)}`;
    case 'native-code':
      return `it used native code (${code(token ?? 'native_decide')})${inFile(finding)}`;
    case 'unsafe':
      return `it used a forbidden keyword (${code(token ?? 'unsafe')})${inFile(finding)}`;
    case 'set-option':
      return `it changed a Lean option (${code('set_option')})${inFile(finding)}`;
    case 'sorry':
      return `it left a gap (${code(token ?? 'sorry')}) ${shown !== undefined ? `in ${shown}` : inFile(finding).trim()}`.trimEnd();
    case 'import':
      return `it imported a module from outside the project (${code(token ?? 'import')})`;
    case 'project-file':
      return `it changed a project file (${code(finding.file ?? token ?? 'lakefile')})`;
    case 'outside-subject':
      return `it changed a file outside this subject (${code(finding.file ?? token ?? '')})`;
    case 'deleted-file':
      return `it deleted a file (${code(finding.file ?? token ?? '')})`;
    case 'bad-path':
      return `it wrote a file that is not a Lean module of this subject (${code(finding.file ?? token ?? '')})`;
    case 'build':
      if (token === 'not-built' && finding.file !== undefined) return `it added a module the library does not import (${code(finding.file)})`;
      return finding.file !== undefined ? `the files did not build (an error${inFile(finding)})` : 'the files did not build';
    case 'budget':
      return 'the build ran out of time or memory';
    case 'not-proved':
      switch (token) {
        case 'mismatch':
          return `it proved something other than the goal${shown !== undefined ? ` (${shown} does not state the goal)` : ''}`;
        case 'sorry':
          return `it left a gap (${code('sorry')}) in ${shown ?? 'the proof of the goal'}`;
        case 'conditional':
          return `its proof of the goal takes extra hypotheses${shown !== undefined ? ` (${shown})` : ''}`;
        case 'axiom':
          return `it stated the goal as an axiom instead of proving it${shown !== undefined ? ` (${shown})` : ''}`;
        case 'unchecked':
          return `Lean could not check the proof of the goal${shown !== undefined ? ` (${shown})` : ''}`;
        default:
          return `it did not prove the goal${shown !== undefined ? ` (${shown} is missing)` : ''}`;
      }
    case 'footprint':
    case 'comparator-illegal-axiom':
      return usedAxioms(finding, ctx, brief);
    case 'sorry-axiom':
      return `it left a gap (${code('sorry')}) in ${shown ?? 'a proof'}`;
    case 'new-axiom':
      if (token === 'after-freeze') return `it added ${shown !== undefined ? `vocabulary (${shown})` : 'vocabulary'} after freezing the statements`;
      return `it added an axiom${shown !== undefined ? ` (${shown})` : ''}, and only you can add beliefs`;
    case 'vocabulary-shape':
      return `it added vocabulary of a kind telelean does not allow${shown !== undefined ? ` (${shown})` : ''}`;
    case 'existing-changed':
      if (token === 'target') return `it changed the statement it had to prove (a definition the frozen statement depends on changed${shown !== undefined ? `: ${shown}` : ''})`;
      if (token === 'removed') return `it removed an existing declaration${shown !== undefined ? ` (${shown})` : ''}`;
      if (token === 'ghost') return `it changed the suggestion you adopted${shown !== undefined ? ` (${shown})` : ''}`;
      return `it changed an existing declaration${shown !== undefined ? ` (${shown})` : ''}`;
    case 'statement-changed':
    case 'comparator-definition-mismatch':
      return `it changed the statement it had to prove (a definition the frozen statement depends on changed${shown !== undefined ? `: ${shown}` : ''})`;
    case 'comparator-statement-mismatch':
      return `it changed the statement it had to prove${shown !== undefined ? ` (${shown})` : ''}`;
    case 'comparator-kind-mismatch':
      return `it changed the kind of a frozen declaration${shown !== undefined ? ` (${shown})` : ''}`;
    case 'comparator-missing':
      return `the proof of the goal is missing${shown !== undefined ? ` (${shown})` : ''}`;
    case 'comparator-kernel':
      return "Lean's kernel rejected the proof";
    case 'comparator-build':
      return 'the frozen statements did not build for the final check';
    case 'comparator-export':
      return 'telelean could not export the proof for the final check';
    case 'status-mismatch':
      return 'it said the goal was not proved but left a proof of it in the files';
    case 'not-formalised':
      return `it did not formalise ${cardLabel(finding.nodeId, ctx)}`;
    case 'missing-holds':
      return token === 'mismatch'
        ? `it did not state ${cardLabel(finding.nodeId, ctx)} correctly as an assumption${shown !== undefined ? ` (${shown})` : ''}`
        : `it did not state ${cardLabel(finding.nodeId, ctx)} as an assumption${shown !== undefined ? ` (${shown} is missing)` : ''}`;
    case 'proof-before-freeze':
      return token === 'example' ? 'it wrote an example before freezing the statements' : `it wrote a proof before freezing the statements${shown !== undefined ? ` (${shown})` : ''}`;
    case 'not-frozen':
      return 'it claimed the goal was proved without freezing the statements first';
    case 'markup': {
      const card = cardLabel(finding.nodeId, ctx);
      switch (token) {
        case 'natural_name':
        case 'rationale':
          return `it changed your words on ${card}`;
        case 'lean':
        case 'binding':
          return `it re-pointed ${card} to a different Lean statement`;
        case 'formalised':
          return `it formalised ${card}, which you didn't select`;
        case 'type':
          return `it changed the kind of ${card}`;
        case 'removed':
          return `it removed the card ${card}`;
        case 'moved':
          return `it moved the card ${card} to another file`;
        case 'block':
          return 'it added a card of its own';
        case 'telelean':
          return `it changed the suggestion you adopted, ${card}`;
        case 'id':
          return `it changed the id of ${card}`;
        default:
          return `it changed the card ${card}`;
      }
    }
    default: {
      const unknown: never = finding.code;
      return `a check failed (${String(unknown)})`;
    }
  }
}

/** See `attemptNotice` in ./index.ts. */
export function notice(findings: readonly GateFinding[], attempt: number, maxAttempts: number, ctx: DescribeContext, revertedTo?: string): string {
  const first = findings[0];
  const more = findings.length > 1 ? ` (and ${findings.length - 1} more)` : '';
  if (attempt >= maxAttempts) {
    const what = first ? `each time ${describe(first, ctx, true)}${more}` : 'the checks kept failing';
    const label = revertedTo?.trim().replace(/^[“"]|[”"]$/g, '');
    const target = label ? `“${label}”` : 'the last state that passed';
    const attempts = maxAttempts === 1 ? "Claude's attempt didn't pass the checks" : `Claude's attempts didn't pass the checks ${maxAttempts} times`;
    return `${attempts}: ${what}. telelean reverted its working copy to ${target}.`;
  }
  const what = first ? `${describe(first, ctx)}${more}` : 'the checks failed';
  return `Attempt ${attempt} didn't pass: ${what}. Asking Claude to retry.`;
}

