/**
 * AT1.5 (docs/m2-plan.md section 3.4): normalisationChanges pins, writes the derived id and mirrors the docstring for
 * a newly formalised card, idempotently and byte-stable elsewhere. AT1.7 (D-21): lifecycleChanges.
 */
import { describe, expect, it } from 'vitest';
import { ActionError, type FileChange } from '../../src/actions.js';
import { lifecycleChanges, normalisationChanges } from '../../src/gate/index.js';
import type { LifecycleItem } from '../../src/run.js';
import { BASE, edit, MAIN, model, normative, pinned, proved, TARGET_LINE, type Texts } from './helpers/spyroRun.js';

const apply = (texts: Texts, changes: readonly FileChange[]): Texts => {
  const out = { ...texts };
  for (const change of changes) {
    expect(change.before).toBe(texts[change.path]);
    if (change.after === null) delete out[change.path];
    else out[change.path] = change.after;
  }
  return out;
};

const DERIVED = 'pg-games-cannot-have-characters-with';
/** An id-less pg-no-dark-past block, formalised by Claude without a docstring. */
const IDLESS = edit(BASE, MAIN, 'id: pg-no-dark-past\n', '');
const formalisedBare = () =>
  edit(IDLESS, MAIN, 'stance: rule\nasserted: 2026-11-01\n-/\n\n', 'stance: rule\nasserted: 2026-11-01\n-/\nabbrev pg_no_dark_past : Prop := ∀ (g : Game) (c : Character), IsPG g → HasDarkPast c → ¬ GoodAddition c g\naxiom pg_no_dark_past.holds : pg_no_dark_past\n\n');

describe('AT1.5 normalisationChanges', () => {
  it('pins, writes the derived id and the docstring of a newly formalised code-less card; nothing else changes', () => {
    const texts = formalisedBare();
    const m = model(texts);
    expect(m.nodes.get(DERIVED)?.node.lean.binding).toBe('adjacent');
    const changes = normalisationChanges(m, [DERIVED]);
    expect(changes.map((c) => c.path)).toEqual([MAIN]);
    const expected = (texts[MAIN] as string).replace(
      'type: ASSUMPTION\nnatural_name: PG games cannot have characters with dark pasts\nstance: rule\nasserted: 2026-11-01\n-/\nabbrev pg_no_dark_past',
      `id: ${DERIVED}\ntype: ASSUMPTION\nnatural_name: PG games cannot have characters with dark pasts\nstance: rule\nasserted: 2026-11-01\nlean: Spyro.pg_no_dark_past\n-/\n/-- PG games cannot have characters with dark pasts -/\nabbrev pg_no_dark_past`,
    );
    expect(changes[0]?.after).toBe(expected);
    expect(changes[0]?.before).toBe(texts[MAIN]);
  });

  it('is idempotent', () => {
    const texts = formalisedBare();
    const once = apply(texts, normalisationChanges(model(texts), [DERIVED]));
    expect(normalisationChanges(model(once), [DERIVED])).toEqual([]);
  });

  it('a card with the docstring already: only the pin (the walkthrough\'s normative formalisation)', () => {
    const changes = normalisationChanges(model(normative()), ['pg-no-dark-past']);
    expect(changes).toEqual([{ path: MAIN, before: normative()[MAIN], after: pinned(normative())[MAIN] }]);
    expect(normalisationChanges(model(pinned(normative())), ['pg-no-dark-past'])).toEqual([]);
  });

  it('a docstring other than the sentence becomes the sentence (escaped)', () => {
    const texts = edit(normative(), MAIN, '/-- PG games cannot have characters with dark pasts -/', '/-- the normative reading -/');
    const [change] = normalisationChanges(model(texts), ['pg-no-dark-past']);
    expect(change?.after).toBe(pinned(normative())[MAIN]);
  });

  it('cards that are not new, code-less cards and unknown ids change nothing', () => {
    expect(normalisationChanges(model(BASE), ['cynder-dark-past', 'new-spyro-pg', 'cynder-not-good'])).toEqual([]);
    expect(normalisationChanges(model(BASE), ['pg-no-dark-past', 'nope'])).toEqual([]);
    expect(normalisationChanges(model(pinned(proved())), ['pg-no-dark-past', 'cynder-not-good'])).toEqual([]);
  });
});

const G_TO_D: LifecycleItem = { id: 'l1', kind: 'change-kind', nodeId: 'cynder-not-good', from: 'GOAL', to: 'DERIVATION', recommended: true, reason: 'Lean proved it from the selected premises' };

const refusal = (fn: () => unknown): ActionError => {
  try {
    fn();
  } catch (error) {
    if (error instanceof ActionError) return error;
    throw error;
  }
  throw new Error('expected an ActionError');
};

describe('AT1.7 lifecycleChanges', () => {
  it('G->D of the proved target changes only its `type:` line', () => {
    const texts = pinned(proved());
    expect(lifecycleChanges(model(texts), [G_TO_D])).toEqual([
      { path: MAIN, before: texts[MAIN], after: (texts[MAIN] as string).replace('id: cynder-not-good\ntype: GOAL', 'id: cynder-not-good\ntype: DERIVATION') },
    ]);
    // An adjacency-bound target without a written id: still only the `type:` line (no pin, no id).
    const bare = edit(edit(pinned(proved()), MAIN, 'id: cynder-not-good\n', ''), MAIN, 'asserted: 2026-11-01\nlean: Spyro.cynder_not_good\n-/', 'asserted: 2026-11-01\n-/');
    const id = 'cynder-would-not-be-a-good';
    expect(model(bare).nodes.get(id)?.node.status.proof.kind).toBe('proved');
    expect(lifecycleChanges(model(bare), [{ ...G_TO_D, nodeId: id }])[0]?.after).toBe((bare[MAIN] as string).replace('type: GOAL', 'type: DERIVATION'));
    expect(lifecycleChanges(model(texts), [])).toEqual([]);
  });

  it('refuses (unsafe) an item that no longer applies', () => {
    const notProved = model(pinned(normative()));
    expect(refusal(() => lifecycleChanges(notProved, [G_TO_D])).code).toBe('unsafe');
    expect(refusal(() => lifecycleChanges(notProved, [G_TO_D])).message).toMatch(/no longer proved/);
    const derivation = model(edit(pinned(proved()), MAIN, 'type: GOAL', 'type: DERIVATION'));
    expect(refusal(() => lifecycleChanges(derivation, [G_TO_D])).code).toBe('unsafe');
    expect(refusal(() => lifecycleChanges(model(pinned(proved())), [{ ...G_TO_D, nodeId: 'gone' }])).code).toBe('unsafe');
    expect(refusal(() => lifecycleChanges(model(pinned(proved())), [{ ...G_TO_D, to: 'ASSUMPTION' }])).code).toBe('unsafe');
    // The weakened-type cheat is not "proved".
    const weak = model(pinned(edit(normative(), MAIN, TARGET_LINE, `${TARGET_LINE}theorem cynder_not_good.holds : cynder_not_good ∨ True := Or.inr trivial\n`)));
    expect(refusal(() => lifecycleChanges(weak, [G_TO_D])).code).toBe('unsafe');
  });
});

/**
 * AT1.6 (docs/m2-plan.md sections 3.8 and 4.9): planGhostAdoption writes Claude's suggested premise as a new ASSUMPTION
 * card right before the target's block, with exactly the collapsed checked statement, and refuses unsafe text.
 */
import { describe, expect, it } from 'vitest';
import { ActionError } from '../../src/actions.js';
import { planGhostAdoption, type GhostAdoptionRequest } from '../../src/gate/index.js';
import { edit, literal, MAIN, model, pinned, type Texts } from './helpers/spyroRun.js';

const LITERAL = pinned(literal());
const SENTENCE = 'A character who cannot be in a game would not be a good addition to it';
const REQUEST: GhostAdoptionRequest = {
  subject: 'Spyro',
  target: 'cynder-not-good',
  naturalName: SENTENCE,
  leanStatement: '∀ (c : Character)\n    (g : Game),  ¬ InGame c g → ¬ GoodAddition c g',
  leanName: 'not_in_game_not_good',
  rationale: 'it seems obvious to me',
  session: 'rmabc123',
  today: '2026-11-02',
};
const TARGET_BLOCK = '/-\n@@ telelean v1\nid: cynder-not-good';

const refusal = (fn: () => unknown): ActionError => {
  try {
    fn();
  } catch (error) {
    if (error instanceof ActionError) return error;
    throw error;
  }
  throw new Error('expected an ActionError');
};

describe('AT1.6 planGhostAdoption', () => {
  it('inserts the card, its docstring, abbrev and .holds right before the target\'s block, statement collapsed', () => {
    const plan = planGhostAdoption(model(LITERAL), REQUEST);
    expect(plan).toMatchObject({ nodeId: 'a-character-who-cannot-be-in', leanName: 'Spyro.not_in_game_not_good' });
    const inserted = [
      '/-',
      '@@ telelean v1',
      'id: a-character-who-cannot-be-in',
      'type: ASSUMPTION',
      `natural_name: ${SENTENCE}`,
      'rationale: it seems obvious to me',
      'asserted: 2026-11-02',
      'lean: Spyro.not_in_game_not_good',
      'origin: agent',
      'session: rmabc123',
      'worded_by: agent',
      '-/',
      `/-- ${SENTENCE} -/`,
      'abbrev not_in_game_not_good : Prop := ∀ (c : Character) (g : Game), ¬ InGame c g → ¬ GoodAddition c g',
      'axiom not_in_game_not_good.holds : not_in_game_not_good',
      '',
      '',
    ].join('\n');
    expect(plan.changes).toEqual([{ path: MAIN, before: LITERAL[MAIN], after: (LITERAL[MAIN] as string).replace(TARGET_BLOCK, `${inserted}${TARGET_BLOCK}`) }]);
  });

  it('the result parses to a new ASSUMPTION card: worded by Claude, pinned, docstring = sentence, the checked statement', () => {
    const plan = planGhostAdoption(model(LITERAL), REQUEST);
    const after: Texts = { ...LITERAL, [MAIN]: plan.changes[0]?.after as string };
    const m = model(after);
    const entry = m.nodes.get(plan.nodeId);
    expect(entry?.node).toMatchObject({
      type: 'ASSUMPTION',
      naturalName: SENTENCE,
      rationale: 'it seems obvious to me',
      asserted: '2026-11-02',
      provenance: { wordedBy: 'agent', endorsed: false, origin: 'agent', session: 'rmabc123' },
      lean: { binding: 'pinned', statement: 'Spyro.not_in_game_not_good', justification: 'Spyro.not_in_game_not_good.holds', justificationKind: 'axiom' },
      status: { formal: 'formalized', proof: { kind: 'assumed' } },
    });
    expect(entry?.statementDecl?.decl.docstring).toBe(SENTENCE);
    const decl = entry?.statementDecl?.decl;
    expect(decl && after[MAIN]?.slice(decl.span.start, decl.span.end)).toBe(`/-- ${SENTENCE} -/\nabbrev not_in_game_not_good : Prop := ∀ (c : Character) (g : Game), ¬ InGame c g → ¬ GoodAddition c g`);
    // Every other card keeps its binding.
    const before = model(LITERAL);
    for (const [id, old] of before.nodes) expect(m.nodes.get(id)?.node.lean.statement, id).toBe(old.node.lean.statement);
  });

  it('a taken, keyword or invalid lean_name gives the derived name (suffixed when that is taken too)', () => {
    const nameOf = (leanName: string | undefined, texts: Texts = LITERAL) => {
      const { leanName: _drop, ...rest } = REQUEST;
      void _drop;
      return planGhostAdoption(model(texts), { ...rest, ...(leanName !== undefined ? { leanName } : {}) }).leanName;
    };
    expect(nameOf('cynder_dark_past')).toBe('Spyro.a_character_who_cannot_be_in');
    expect(nameOf('theorem')).toBe('Spyro.a_character_who_cannot_be_in');
    expect(nameOf('not valid')).toBe('Spyro.a_character_who_cannot_be_in');
    expect(nameOf('Spyro.dotted')).toBe('Spyro.a_character_who_cannot_be_in');
    expect(nameOf(undefined)).toBe('Spyro.a_character_who_cannot_be_in');
    // A name the project already uses (here a declaration) is never shadowed.
    const used = edit(LITERAL, MAIN, 'end Spyro', 'def a_character_who_cannot_be_in : Nat := 1\n\nend Spyro');
    expect(nameOf(undefined, used)).toBe('Spyro.a_character_who_cannot_be_in_2');
    expect(nameOf('GoodAddition')).toBe('Spyro.a_character_who_cannot_be_in');
  });

  it('the node id is unique in the project', () => {
    const taken = edit(LITERAL, MAIN, 'end Spyro', '/-\n@@ telelean v1\nid: a-character-who-cannot-be-in\ntype: GOAL\nnatural_name: Something else\n-/\n\nend Spyro');
    expect(planGhostAdoption(model(taken), REQUEST).nodeId).toBe('a-character-who-cannot-be-in-2');
  });

  it('refuses comment delimiters, the injected statement of fact 8, bad metadata and unknown targets', () => {
    const comment = refusal(() => planGhostAdoption(model(LITERAL), { ...REQUEST, leanStatement: 'True -/ /- evil' }));
    expect(comment.code).toBe('invalid');
    expect(comment.message).toContain('comment delimiter');
    const injected = refusal(() => planGhostAdoption(model(LITERAL), { ...REQUEST, leanStatement: 'True) → True := fun _ => trivial\naxiom evil : False\nexample : (True' }));
    expect(injected.code).toBe('invalid');
    expect(refusal(() => planGhostAdoption(model(LITERAL), { ...REQUEST, leanStatement: 'sorry' })).code).toBe('invalid');
    expect(refusal(() => planGhostAdoption(model(LITERAL), { ...REQUEST, naturalName: 'two\nlines' })).code).toBe('invalid');
    expect(refusal(() => planGhostAdoption(model(LITERAL), { ...REQUEST, rationale: 'two\nlines' })).code).toBe('invalid');
    expect(refusal(() => planGhostAdoption(model(LITERAL), { ...REQUEST, today: 'yesterday' })).code).toBe('invalid');
    expect(refusal(() => planGhostAdoption(model(LITERAL), { ...REQUEST, session: 'bad session' })).code).toBe('invalid');
    expect(refusal(() => planGhostAdoption(model(LITERAL), { ...REQUEST, target: 'nope' })).code).toBe('not-found');
    expect(refusal(() => planGhostAdoption(model(LITERAL), { ...REQUEST, subject: 'Other' })).code).toBe('not-found');
  });

  it('a sentence with comment delimiters is written escaped, so the docstring and block stay one comment each', () => {
    const plan = planGhostAdoption(model(LITERAL), { ...REQUEST, naturalName: 'Being out of a game -/ means not good' });
    const after = plan.changes[0]?.after as string;
    expect(after).toContain('natural_name: "Being out of a game -\\/ means not good"');
    expect(after).toContain('/-- Being out of a game -\\/ means not good -/');
    expect(model({ ...LITERAL, [MAIN]: after }).nodes.get(plan.nodeId)?.node.naturalName).toBe('Being out of a game -/ means not good');
  });
});

/**
 * AT1.8 (docs/m2-plan.md section 3.5, amendment A2): describeFinding and attemptNotice give the plan's sentences, for
 * findings produced by the real rules, G0 and (comparator) the runner's mapping.
 */
import { describe, expect, it } from 'vitest';
import { holdsName } from '../../src/facts.js';
import { attemptNotice, describeFinding, frozenSnapshot, scanForbidden, type DescribeContext, type GateFinding } from '../../src/gate/index.js';
import type { TlGraph } from '../../src/model.js';
import { subjectGraph } from '../../src/project/index.js';
import { BASE, edit, HONEST_PROOF, MAIN, model, normative, pinned, proved, rules, SEL, SEL_NO_PG, TARGET_LINE } from './helpers/spyroRun.js';

/** The DescribeContext the RunManager builds from the current board (the user's real files). */
function contextOf(graph: TlGraph, selected: readonly string[]): DescribeContext {
  const owner = new Map<string, string>();
  for (const node of graph.nodes) {
    if (node.lean.statement === undefined) continue;
    owner.set(node.lean.statement, node.id);
    owner.set(holdsName(node.lean.statement), node.id);
  }
  return { sentenceOf: (id) => graph.nodes.find((n) => n.id === id)?.naturalName, nodeOfDecl: (name) => owner.get(name), selected };
}

const B = model(BASE);
const N = model(normative());
const board = subjectGraph(B, 'Spyro', { version: 1, semantic: { state: 'fresh' } });
const CTX = contextOf(board, SEL.premises);
const CTX_NO_PG = contextOf(board, SEL_NO_PG.premises);
const first = (findings: readonly GateFinding[]) => findings[0] as GateFinding;

describe('AT1.8 the A2 sentences of plan 3.5', () => {
  it('an unselected premise', () => {
    const report = rules('gate-proved', 'prove', B, model(pinned(proved())), { freeze: frozenSnapshot(N, SEL_NO_PG, 1), selection: SEL_NO_PG });
    expect(describeFinding(first(report.findings), CTX_NO_PG)).toBe('it used “The new Spyro game is PG” (`new_spyro_pg.holds`), which you didn\'t select');
    expect(attemptNotice(report.findings, 1, 3, CTX_NO_PG)).toBe("Attempt 1 didn't pass: it used “The new Spyro game is PG” (`new_spyro_pg.holds`), which you didn't select. Asking Claude to retry.");
  });

  it('a gap (sorry), found by G0', () => {
    const text = (proved()[MAIN] as string).replace(HONEST_PROOF, 'theorem cynder_not_good.holds : cynder_not_good := sorry\n');
    const findings = scanForbidden(MAIN, text, { library: 'Model', subject: 'Spyro', projectModules: new Set() }, BASE[MAIN]);
    expect(attemptNotice(findings, 2, 3, CTX)).toBe("Attempt 2 didn't pass: it left a gap (`sorry`) in `cynder_not_good.holds`. Asking Claude to retry.");
  });

  it('a changed statement: the comparator\'s definition mismatch (M0 lesson 2 wording) and the weakened abbrev', () => {
    const comparator: GateFinding = { step: 'G4', code: 'comparator-definition-mismatch', message: 'lake comparator: definition mismatch for Spyro.cynder_not_good', names: ['Spyro.cynder_not_good'] };
    expect(attemptNotice([comparator], 2, 3, CTX)).toBe(
      "Attempt 2 didn't pass: it changed the statement it had to prove (a definition the frozen statement depends on changed: `cynder_not_good`). Asking Claude to retry.",
    );
    const weak = model(pinned(edit(proved(), MAIN, TARGET_LINE, 'abbrev cynder_not_good : Prop := ¬ GoodAddition cynder newSpyro ∨ True\n')));
    const report = rules('gate-proved', 'prove', B, weak, { freeze: frozenSnapshot(N, SEL, 1) });
    expect(report.findings.map((f) => f.code)).toEqual(['existing-changed', 'statement-changed']);
    expect(attemptNotice(report.findings, 2, 3, CTX)).toBe(
      "Attempt 2 didn't pass: it changed the statement it had to prove (a definition the frozen statement depends on changed: `cynder_not_good`). Asking Claude to retry.",
    );
  });

  it('a forbidden command, with its file and line', () => {
    const text = `${'-- line\n'.repeat(11)}#eval 1\n`;
    const findings = scanForbidden(MAIN, text, { library: 'Model', subject: 'Spyro', projectModules: new Set() });
    expect(attemptNotice(findings, 1, 3, CTX)).toBe("Attempt 1 didn't pass: it used a forbidden command (`#eval`) in Model/Spyro/Main.lean line 12. Asking Claude to retry.");
  });

  it('an added axiom (its footprint consequence is not counted as another problem)', () => {
    const cheat = model(edit(pinned(normative()), MAIN, 'end Spyro', 'axiom shortcut : cynder_not_good\ntheorem cynder_not_good.holds : cynder_not_good := shortcut\n\nend Spyro'));
    const report = rules('gate-proved', 'prove', B, cheat, { freeze: frozenSnapshot(N, SEL, 1) });
    expect(report.findings.map((f) => f.code)).toEqual(['new-axiom', 'footprint']);
    expect(attemptNotice(report.findings, 1, 3, CTX)).toBe("Attempt 1 didn't pass: it added an axiom (`shortcut`), and only you can add beliefs. Asking Claude to retry.");
  });

  it('the user\'s words changed', () => {
    const words = model(edit(normative(), MAIN, 'natural_name: Cynder is a character who has a dark past', 'natural_name: Cynder had a dark past'));
    const report = rules('check', 'formalise', B, words);
    expect(attemptNotice(report.findings, 1, 3, CTX)).toBe("Attempt 1 didn't pass: it changed your words on “Cynder is a character who has a dark past”. Asking Claude to retry.");
  });

  it('the give-up sentence names what kept failing and the state telelean reverted to', () => {
    const report = rules('gate-proved', 'prove', B, model(pinned(proved())), { freeze: frozenSnapshot(N, SEL_NO_PG, 1), selection: SEL_NO_PG });
    expect(attemptNotice(report.findings, 3, 3, CTX_NO_PG, 'Statements frozen (round 1)')).toBe(
      "Claude's attempts didn't pass the checks 3 times: each time it used `new_spyro_pg.holds`, which you didn't select. telelean reverted its working copy to “Statements frozen (round 1)”.",
    );
    expect(attemptNotice(report.findings, 3, 3, CTX_NO_PG, '“Statements frozen (round 1)”')).toContain('to “Statements frozen (round 1)”.');
    expect(attemptNotice(report.findings, 1, 1, CTX_NO_PG)).toBe(
      "Claude's attempt didn't pass the checks: each time it used `new_spyro_pg.holds`, which you didn't select. telelean reverted its working copy to the last state that passed.",
    );
  });

  it('the reviewer\'s additions: status mismatch, a re-pointed pin, an existing declaration changed', () => {
    const left = rules('gate-other', 'prove', B, model(pinned(proved())));
    expect(describeFinding(first(left.findings), CTX)).toBe('it said the goal was not proved but left a proof of it in the files');
    const repinned = model(edit(edit(normative(), MAIN, 'lean: Spyro.cynder_not_good\n', 'lean: Spyro.cynder_not_good_weak\n'), MAIN, 'end Spyro', 'abbrev cynder_not_good_weak : Prop := True\n\nend Spyro'));
    expect(describeFinding(first(rules('freeze', 'formalise', B, repinned).findings), CTX)).toBe('it re-pointed “Cynder would not be a good addition to the new Spyro game” to a different Lean statement');
    const redefined = model(edit(proved(), 'Model/Spyro/Vocabulary.lean', 'axiom GoodAddition : Character → Game → Prop', 'def GoodAddition (c : Character) (_g : Game) : Prop := ¬ HasDarkPast c'));
    const report = rules('gate-proved', 'prove', B, redefined, { freeze: frozenSnapshot(N, SEL, 1) });
    expect(attemptNotice(report.findings, 1, 3, CTX)).toBe("Attempt 1 didn't pass: it changed an existing declaration (`GoodAddition`). Asking Claude to retry.");
  });

  it('singular and plural', () => {
    const a: GateFinding = { step: 'G3', code: 'not-frozen', message: 'x' };
    const b: GateFinding = { step: 'G0', code: 'bad-path', message: 'y', file: 'Model/Spyro/notes.md', token: 'Model/Spyro/notes.md' };
    const c: GateFinding = { step: 'G0', code: 'project-file', message: 'z', file: 'lakefile.toml', token: 'lakefile.toml' };
    expect(attemptNotice([a, b], 1, 3, CTX)).toBe("Attempt 1 didn't pass: it claimed the goal was proved without freezing the statements first (and 1 more). Asking Claude to retry.");
    expect(attemptNotice([a, b, c], 2, 3, CTX)).toBe("Attempt 2 didn't pass: it claimed the goal was proved without freezing the statements first (and 2 more). Asking Claude to retry.");
    const two: GateFinding = { step: 'G3', code: 'footprint', message: 'w', file: MAIN, nodeId: 'cynder-not-good', names: ['Spyro.new_spyro_pg.holds', 'Spyro.cynder_dark_past.holds'] };
    expect(describeFinding(two, contextOf(board, ['pg-no-dark-past']))).toBe(
      'it used “The new Spyro game is PG” (`new_spyro_pg.holds`) and “Cynder is a character who has a dark past” (`cynder_dark_past.holds`), which you didn\'t select',
    );
    expect(describeFinding({ ...two, names: ['Spyro.shortcut'] }, CTX)).toBe('it used `shortcut`, which the selected premises do not allow');
  });

  it('every code has a sentence', () => {
    const sample = (code: GateFinding['code'], extra: Partial<GateFinding> = {}): string => describeFinding({ step: 'G3', code, message: 'm', ...extra }, CTX);
    expect(sample('project-file', { file: 'lean-toolchain' })).toBe('it changed a project file (`lean-toolchain`)');
    expect(sample('outside-subject', { file: 'Model.lean' })).toBe('it changed a file outside this subject (`Model.lean`)');
    expect(sample('deleted-file', { file: MAIN })).toBe('it deleted a file (`Model/Spyro/Main.lean`)');
    expect(sample('bad-path', { file: 'Model/Spyro/notes.md' })).toBe('it wrote a file that is not a Lean module of this subject (`Model/Spyro/notes.md`)');
    expect(sample('import', { token: 'import Lean' })).toBe('it imported a module from outside the project (`import Lean`)');
    expect(sample('build', { file: MAIN, range: { start: { line: 3, character: 0 }, end: { line: 3, character: 0 } } })).toBe('the files did not build (an error in Model/Spyro/Main.lean line 4)');
    expect(sample('budget')).toBe('the build ran out of time or memory');
    expect(sample('not-proved', { names: ['Spyro.cynder_not_good.holds'], file: MAIN, token: 'mismatch' })).toBe('it proved something other than the goal (`cynder_not_good.holds` does not state the goal)');
    expect(sample('not-proved', { names: ['Spyro.cynder_not_good.holds'], file: MAIN, token: 'missing' })).toBe('it did not prove the goal (`cynder_not_good.holds` is missing)');
    expect(sample('vocabulary-shape', { names: ['Spyro.spyro'], file: 'Model/Spyro/Vocabulary.lean' })).toBe('it added vocabulary of a kind telelean does not allow (`spyro`)');
    expect(sample('not-formalised', { nodeId: 'pg-no-dark-past' })).toBe('it did not formalise “PG games cannot have characters with dark pasts”');
    expect(sample('missing-holds', { nodeId: 'pg-no-dark-past', names: ['Spyro.pg_no_dark_past.holds'], file: MAIN })).toBe(
      'it did not state “PG games cannot have characters with dark pasts” as an assumption (`pg_no_dark_past.holds` is missing)',
    );
    expect(sample('proof-before-freeze', { names: ['Spyro.cynder_not_good.holds'], file: MAIN })).toBe('it wrote a proof before freezing the statements (`cynder_not_good.holds`)');
    expect(sample('sorry-axiom', { names: ['Spyro.helper'], file: MAIN })).toBe('it left a gap (`sorry`) in `helper`');
    expect(sample('new-axiom', { names: ['Spyro.Console'], file: MAIN, token: 'after-freeze' })).toBe('it added vocabulary (`Console`) after freezing the statements');
    expect(sample('comparator-kernel')).toBe("Lean's kernel rejected the proof");
    expect(sample('comparator-missing', { names: ['Spyro.cynder_not_good.holds'] })).toBe('the proof of the goal is missing (`cynder_not_good.holds`)');
    expect(sample('markup', { nodeId: 'pg-no-dark-past', token: 'formalised' })).toBe('it formalised “PG games cannot have characters with dark pasts”, which you didn\'t select');
    expect(sample('markup', { nodeId: 'claude-card', token: 'block' })).toBe('it added a card of its own');
    expect(sample('native-code', { token: '+native', file: MAIN, range: { start: { line: 0, character: 0 }, end: { line: 0, character: 0 } } })).toBe('it used native code (`+native`) in Model/Spyro/Main.lean line 1');
  });
});

