/**
 * M2: a Claude run ("These suffice", D-19 one-shot with an explicit freeze, amendment A2's gate loop) as the board
 * sees it, the proposal it leaves for Accept / Feedback / Discard, and the sidecar records it writes
 * (`.telelean/subjects/<S>/attempts.jsonl`, `.telelean/subjects/<S>/decisions.json`).
 *
 * FROZEN CONTRACT (M2, docs/m2-plan.md section 6). Owner after the freeze: the integrator. Builders may only add
 * OPTIONAL fields or new exports, recorded in the plan's change log (section 14).
 *
 * Who produces what:
 *   RunView       the runner's RunManager (WP3), posted by the extension (WP5) as the `run` message
 *   ProposalView  the runner's ProposalService (WP4), posted as the `proposal` message
 *   AttemptLine / DecisionsFile   written by WP4's sidecar store, read back into `TlGraph.attempts` (WP4)
 * The webview (WP6) renders them; it never computes verdicts itself.
 *
 * Provenance (D-15): every string marked "Claude's words" is shown in italics with a marker, never in the user's style.
 */
import type { NodeType, TlGraph } from './model.js';

// ---------------------------------------------------------------------------------------------
// Questions (ask_user, D-20)

/**
 * D-20 phenomenon tags. Same list, same order as `PHENOMENA` in runner/src/llm/types.ts (the tool schema the model
 * sees); the runner asserts the two agree at compile time.
 */
export const PHENOMENA = [
  'enthymeme',
  'genericity',
  'modality',
  'negation',
  'presupposition',
  'scalar',
  'vagueness',
  'evaluative-standard',
  'indexical',
  'word-sense',
  'tense',
  'granularity',
  'closed-world',
  'other',
] as const;
export type Phenomenon = (typeof PHENOMENA)[number];

export interface QuestionOptionView {
  /** Claude's words. */
  label: string;
  /** What choosing it means, in plain words (Claude's words). */
  consequence: string;
  /** Optional Lean rendering of what the option would formalise to. */
  formalPreview?: string;
}

/**
 * One question of a pending ask_user batch. Deliberately WITHOUT Claude's guess: D-20 reveals it only after the user
 * answered, so the host never sends it before (it arrives in `AnsweredQuestionView.claudesGuess`).
 */
export interface QuestionView {
  /** Index in its batch (0-2). */
  index: number;
  phenomenon: Phenomenon;
  /** Claude's words. */
  question: string;
  /** 2-4 options. The board always adds "Leave it open", free text and "Decide for me". */
  options: QuestionOptionView[];
  /** Node ids the answer affects (cards of this subject; unknown ids are dropped by the host). */
  affectedNodes: string[];
}

/** One ask_user call waiting for the user (1-3 questions). */
export interface QuestionSetView {
  /** Host-generated (`q1`, `q2`, …; `[A-Za-z0-9_.-]{1,64}`), unique within the run. */
  id: string;
  askedAt: string;
  questions: QuestionView[];
}

export type AnswerChoiceView =
  | { kind: 'option'; option: number }
  | { kind: 'free-text'; text: string }
  /** "Leave it open": keep it uninterpreted (recorded, D-20). */
  | { kind: 'leave-open' }
  /** "Decide for me": an explicit delegation; Claude lists its choice under assumed_without_asking. */
  | { kind: 'decide-for-me' };

/** D-20 scope of an answer: this run only, the affected nodes, or the whole subject. */
export type DecisionScope = 'run' | 'nodes' | 'subject';
export const DECISION_SCOPES: readonly DecisionScope[] = ['run', 'nodes', 'subject'];

/** The user's answer to one question of a batch. */
export interface QuestionAnswer {
  question: number;
  choice: AnswerChoiceView;
  scope: DecisionScope;
}

export interface AnsweredQuestionView extends QuestionView {
  setId: string;
  answer: QuestionAnswer;
  answeredAt: string;
  /** Revealed only now (D-20): Claude's own guess, as Claude worded it. */
  claudesGuess?: { option?: number; note?: string };
}

// ---------------------------------------------------------------------------------------------
// Run state

/** Where a run is. Terminal states: accepted, discarded, cancelled, failed (TERMINAL_RUN_STATES). */
export type RunState =
  /** Preflight (binary and version, sandbox, toolchain, memory), shadow creation, CLI start with its auth and hook checks. */
  | 'starting'
  /** Claude is working on a turn (see `stage`). */
  | 'working'
  /** An ask_user call waits for the user; the agent-active clock is paused. */
  | 'waiting-for-answer'
  /** Claude called finish; telelean runs the gate (G0-G5). */
  | 'gate'
  /** The turn ended: the proposal (or a "not proved" outcome) waits for Accept / Feedback / Discard. */
  | 'review'
  /** A window reload or crash ended the Claude process mid-turn; the board offers Resume / Stop. */
  | 'interrupted'
  | 'accepted'
  | 'discarded'
  | 'cancelled'
  | 'failed';

export const TERMINAL_RUN_STATES: readonly RunState[] = ['accepted', 'discarded', 'cancelled', 'failed'];

export function isTerminalRunState(state: RunState): boolean {
  return TERMINAL_RUN_STATES.includes(state);
}

/** D-19: before freeze_statements Claude formalises (proof bodies are rejected); after it, it proves the frozen statements. */
export type RunStage = 'formalise' | 'prove';

/** How a round ended (the report card, attempts.jsonl). */
export type RunVerdict =
  /** The gate passed with finish status `proved`. */
  | 'proved'
  /** The gate passed with finish status `not_proved` or `lean_errors`: nothing is claimed proved. */
  | 'not-proved'
  /** Claude claims the premises are insufficient. M2 shows it as "not proved": countermodels arrive in M3 (D-6). */
  | 'insufficient'
  /** Claude claims the premises conflict. Unverified in M2 (model finder: M3). */
  | 'inconsistent'
  /** The gate failed `maxGateAttempts` times; the shadow was reverted to the last state that passed (A2). */
  | 'gave-up'
  /** The turn or agent-active-time cap was reached; the shadow was reverted to the last state that passed. */
  | 'cap-reached'
  /** The turn ended twice without a finish call; the shadow was rev

/**
 * The prototype gate's pure rules (03 section 8.5 as cut down by the Prototype profile of 02; amendment A2; docs/m2-plan.md
 * section 3): G0 token denylist and file rules, the D-5 permitted set computed from the freeze, G3 (footprints, no
 * sorry, simple vocabulary rule, no new axioms), G5's markup half, and the readiness rules of freeze_statements.
 * Everything here works on texts and ProjectModels (core's `buildProjectModel` over the shadow's parsed files plus the
 * Lean facts the runner produced in the build mirror); nothing runs Lean. G1 (the sandboxed build) and G4 (lake
 * comparator) run in the runner (WP2), which turns their outcomes into findings of the same shape.
 *
 * FROZEN CONTRACT (M2, docs/m2-plan.md sections 0 and 3). Owner: WP1. Additive optional fields / new exports only, recorded
 * in the plan's change log (section 14).
 */
import type { Range } from '../model.js';
import type { FileChange } from '../actions.js';
import type { ProjectModel } from '../project/types.js';
import type { GateStepId, LifecycleItem, PermittedSummary } from '../run.js';

/** Why a gate step (or a check_lean / freeze_statements rule) failed. One code per kind of finding. */
export type GateFindingCode =
  // ---- G0: token denylist over the agent's changed text, and file rules (before any Lean process sees the text)
  /** `#eval`, `#exit`, `#reduce`, … (any `#` command but `#check` and `#print`). */
  | 'hash-command'
  /** `initialize`, `builtin_initialize`, `run_cmd`/`run_elab`/`run_meta`, `macro`, `macro_rules`, `syntax`, `notation`, `infix(l|r)`, `prefix`, `postfix`, `elab`, `elab_rules`, `declare_syntax_cat`. */
  | 'metaprogramming'
  /** `native_decide`, `decide +native`, `bv_decide`, `implemented_by`, `extern`, `csimp`, `ofReduceBool`, `ofReduceNat`. */
  | 'native-code'
  /** `unsafe`, `partial`. */
  | 'unsafe'
  /** Any `set_option` (limits such as maxHeartbeats, `debug.*`, `autoImplicit`, …): the prototype allows none in agent text. */
  | 'set-option'
  /** `sorry`, `admit`. */
  | 'sorry'
  /** An `import` of a module outside the project's library (e.g. `import Lean`). */
  | 'import'
  /** `lakefile.toml`, `lakefile.lean`, `lean-toolchain` or `lake-manifest.json` changed. */
  | 'project-file'
  /** A file outside `<library>/<S>/` and `<library>/<S>.lean` changed, was added or deleted. */
  | 'outside-subject'
  /** A model file was deleted. */
  | 'deleted-file'
  /** A new file that is not `<library>/<S>/<Module>.lean` with a valid module name, or not a regular file. */
  | 'bad-path'
  // ---- G1: the sandboxed build (runner)
  /** Lean reported an error (the finding carries Lean's whole message, continuation lines included). */
  | 'build'
  /** The build ran out of time (job cap) or memory (cap): counted against the agent. */
  | 'budget'
  // ---- G3: footprints, sorry, vocabulary, axioms (from the shadow's Lean facts)
  /** finish(proved) but the target's `.holds` is missing, not a theorem, conditional (takes hypotheses) or uses sorry. */
  | 'not-proved'
  /** A proof (the target's, or any theorem added in the run) rests on an axiom outside the permitted set. */
  | 'footprint'
  /** `sorryAx` in a declaration of a changed file. */
  | 'sorry-axiom'
  /** An axiom added after the freeze, or a Prop-valued axiom that is not the `.holds` of a selected ASSUMPTION/ghost. */
  | 'new-axiom'
  /** New vocabulary breaking the simple shape rule (D-3 prototype: TL111 / an `other` item). */
  | 'vocabulary-shape'
  /** A declaration that existed before the run changed (other than the target's `.holds`). */
  | 'existing-changed'
  /** A frozen statement or vocabulary declaration changed after the freeze (early warning; G4 is authoritative). */
  | 'statement-changed'
  // ---- freeze readiness / stage rules (check_lean, freeze_statements, finish)
  /** The target or a selected premise has no Prop statement abbrev bound to its block. */
  | 'not-formalised'
  /** A selected ASSUMPTION (or adopted ghost) has no `axiom n.holds : n`, or its `.holds` does not state `n`. */
  | 'missing-holds'
  /** A theorem was added in this round before freeze_statements succeeded (D-19: no proof bodies before the freeze). */
  | 'proof-before-freeze'
  /** finish(proved) in a round without a successful freeze_statements. */
  | 'not-frozen'
  // ---- G4: lake comparator against the freeze (runner maps `ComparatorVerdict` reasons)
  | 'comparator-illegal-axiom'
  | 'comparator-statement-mismatch'
