// Locating the user's own Claude Code binary (amendment 1: the CLI, not the Agent SDK).
//
// Order: explicit setting -> newest VS Code Claude Code extension binary -> PATH -> ~/.local/bin.
// Every candidate must answer `--version` (which does not contact Anthropic) with a version at
// least MIN_CLAUDE_VERSION.

import { execFile } from 'node:child_process';
import { constants as fsConstants } from 'node:fs';
import { access, readdir } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { LlmHarnessError } from './types.js';

/** 2.1.295 adds `onFailure` on hooks, which the confinement guard relies on (fail closed). */
export const MIN_CLAUDE_VERSION = '2.1.295';

export type BinarySource = 'setting' | 'vscode-extension' | 'path' | 'local-bin';

export interface BinaryCandidate {
  path: string;
  source: BinarySource;
}

export interface ResolvedBinary extends BinaryCandidate {
  version: string;
}

export interface ResolveBinaryOptions {
  /** User setting; when given it must work (no silent fallback to another binary). */
  explicitPath?: string;
  home?: string;
  pathEnv?: string;
  /** Directories holding VS Code extensions (default ~/.vscode/extensions, ~/.vscode-server/extensions). */
  extensionDirs?: string[];
  minVersion?: string;
  /** Environment for the `--version` call (defaults to a minimal one). */
  env?: Record<string, string>;
  /** Injected for tests. */
  runVersion?: (binaryPath: string) => Promise<string>;
}

export function parseClaudeVersion(output: string): string | undefined {
  return /(\d+\.\d+\.\d+)/.exec(output)?.[1];
}

export function compareVersions(a: string, b: string): number {
  const pa = a.split('.').map((x) => Number.parseInt(x, 10) || 0);
  const pb = b.split('.').map((x) => Number.parseInt(x, 10) || 0);
  for (let i = 0; i < Math.max(pa.length, pb.length); i++) {
    const d = (pa[i] ?? 0) - (pb[i] ?? 0);
    if (d !== 0) return d < 0 ? -1 : 1;
  }
  return 0;
}

async function isExecutable(p: string): Promise<boolean> {
  try {
    await access(p, fsConstants.X_OK);
    return true;
  } catch {
    return false;
  }
}

const EXTENSION_DIR_RE = /^anthropic\.claude-code-(\d+\.\d+\.\d+)(?:-.*)?$/;

/** VS Code Claude Code extension binaries, newest version first. */
export async function findExtensionBinaries(extensionDirs: string[]): Promise<BinaryCandidate[]> {
  const found: Array<{ version: string; path: string }> = [];
  for (const dir of extensionDirs) {
    let entries: string[];
    try {
      entries = await readdir(dir);
    } catch {
      continue;
    }
    for (const name of entries) {
      const m = EXTENSION_DIR_RE.exec(name);
      if (!m?.[1]) continue;
      const bin = path.join(dir, name, 'resources', 'native-binary', 'claude');
      if (await isExecutable(bin)) found.push({ version: m[1], path: bin });
    }
  }
  found.sort((x, y) => compareVersions(y.version, x.version));
  return found.map((f) => ({ path: f.path, source: 'vscode-extension' as const }));
}

export async function listCandidates(opts: ResolveBinaryOptions = {}): Promise<BinaryCandidate[]> {
  const home = opts.home ?? os.homedir();
  if (opts.explicitPath) return [{ path: opts.explicitPath, source: 'setting' }];
  const candidates: BinaryCandidate[] = [];
  const extensionDirs = opts.extensionDirs ?? [
    path.join(home, '.vscode', 'extensions'),
    path.join(home, '.vscode-server', 'extensions'),
  ];
  candidates.push(...(await findExtensionBinaries(extensionDirs)));
  for (const dir of (opts.pathEnv ?? process.env.PATH ?? '').split(path.delimiter)) {
    if (!dir) continue;
    const p = path.join(dir, 'claude');
    if (await isExecutable(p)) candidates.push({ path: p, source: 'path' });
  }
  const localBin = path.join(home, '.local', 'bin', 'claude');
  if (await isExecutable(localBin)) candidates.push({ path: localBin, source: 'local-bin' });
  // The same file can appear twice (PATH entry and ~/.local/bin).
  const seen = new Set<string>();
  return candidates.filter((c) => (seen.has(c.path) ? false : (seen.add(c.path), true)));
}

export function runClaudeVersion(binaryPath: string, env?: Record<string, string>): Promise<string> {
  return new Promise((resolve, reject) => {
    execFile(
      binaryPath,
      ['--version'],
      {
        timeout: 20_000,
        maxBuffer: 64 * 1024,
        env: env ?? { PATH: process.env.PATH ?? '/usr/bin:/bin', HOME: os.homedir() },
      },
      (err, stdout) => (err ? reject(err) : resolve(stdout)),
    );
  });
}

/** First candidate that runs and is new enough. */
export async function resolveClaudeBinary(opts: ResolveBinaryOptions = {}): Promise<ResolvedBinary> {
  const minVersion = opts.minVersion ?? MIN_CLAUDE_VERSION;
  const runVersion = opts.runVersion ?? ((p: string) => runClaudeVersion(p, opts.env));
  const candidates = await listCandidates(opts);
  const problems: string[] = [];
  for (const c of candidates) {
    let version: string | undefined;
    try {
      version = parseClaudeVersion(await runVersion(c.path));
    } catch (err) {
      problems.push(`${c.path}: --version failed (${(err as Error).message})`);
      continue;
    }
    if (!version) {
      problems.push(`${c.path}: no version in --version output`);
      continue;
    }
    if (compareVersions(version, minVersion) < 0) {
      problems.push(`${c.path}: version ${version} is older than ${minVersion}`);
      continue;
    }
    return { ...c, version };
  }
  const tried = problems.length > 0 ? ` Tried: ${problems.join('; ')}` : '';
  throw new LlmHarnessError(
    'binary',
    `No usable Claude Code binary (need ${minVersion} or newer).${tried || ' No candidates found.'}`,
  );
}

/**
 * One subject's board (docs/m1-plan.md sections 5.3 and 6.3): its nodes in column order (layout.json first, then file
 * order), the edges with both ends in the subject, its Vocabulary group and its diagnostics.
 */
import { orderByLayout } from '../layout.js';
import type { BoardDiagnostic, TlGraph, TlNode, VocabItem } from '../model.js';
import { NODE_TYPES } from '../model.js';
import { edgesOf } from './build.js';
import type { ProjectModel, SubjectGraphOptions } from './types.js';

/** Which subject a diagnostic belongs to, or undefined for project-level ones (files outside every subject). */
function subjectOfDiagnostic(model: ProjectModel, d: BoardDiagnostic, fileSubject: ReadonlyMap<string, string>, vocabSubject: ReadonlyMap<string, string>): string | undefined {
  if (d.nodeId !== undefined) {
    const node = model.nodes.get(d.nodeId);
    if (node) return node.node.subject;
  }
  if (d.vocab !== undefined) {
    const subject = vocabSubject.get(d.vocab);
    if (subject !== undefined) return subject;
  }
  if (d.file !== undefined) return fileSubject.get(d.file);
  return undefined;
}

/**
 * Items of other subjects' vocabularies that this subject's cards use (D-10 explicit imports): their `uses`,
 * `presupposes` and code references, plus the sort a used presupposition is about. Listed after the subject's own
 * items, read-only: `subject` stays the item's own subject and `shortName` is the fully-qualified name (relative to
 * this board's namespace nothing shortens it), so hover glosses and click-to-highlight work for them too.
 */
function foreignVocabulary(model: ProjectModel, subject: string, nodes: readonly TlNode[]): VocabItem[] {
  const items = new Map(model.vocabulary.map((item) => [item.name, item]));
  const wanted = new Set<string>();
  for (const node of nodes) {
    for (const name of [...(node.lean.uses ?? []), ...(node.lean.presupposes ?? []), ...(node.lean.refs ?? []).map((r) => r.name)]) wanted.add(name);
  }
  for (const name of [...wanted]) {
    const presupposed = items.get(name)?.presupposes;
    if (presupposed !== undefined) wanted.add(presupposed);
  }
  const ids = new Set(nodes.map((n) => n.id));
  return model.vocabulary
    .filter((item) => item.subject !== subject && wanted.has(item.name))
    .map((item) => ({ ...item, shortName: item.name, usedBy: item.usedBy.filter((id) => ids.has(id)) }));
}

export function buildSubjectGraph(model: ProjectModel, subject: string, options: SubjectGraphOptions): TlGraph {
  const subjectNodes: TlNode[] = [];
  for (const entry of model.nodes.values()) if (entry.node.subject === subject) subjectNodes.push(entry.node);
  const byId = new Map(subjectNodes.map((n) => [n.id, n]));
  const order = orderByLayout(subjectNodes, options.layout);
  const nodes = NODE_TYPES.flatMap((type) => order[type].map((id) => byId.get(id) as TlNode));

  const edges = edgesOf(model).edges.filter((e) => byId.has(e.source) && byId.has(e.target));

  const own = model.vocabulary.filter((item) => item.subject === subject).map((item) => ({ ...item, usedBy: item.usedBy.filter((id) => byId.has(id)) }));
  const vocabulary = [...own, ...foreignVocabulary(model, subject, subjectNodes)];

  const fileSubject = new Map<string, string>();
  for (const info of model.subjects) for (const file of info.files) fileSubject.set(file, info.name);
  const vocabSubject = new Map(model.vocabulary.map((item) => [item.name, item.subject]));
  const diagnostics = model.diagnostics.filter((d) => {
    const owner = subjectOfDiagnostic(model, d, fileSubject, vocabSubject);
    // Project-level problems (e.g. a block outside every subject, TL120) are shown on every board.
    return owner === undefined || owner === subject;
  });

  return { version: options.version, subject, nodes, edges, vocabulary, diagnostics, semantic: options.semantic };
}
