/**
 * WP2: the run's shadow workspace (docs/m2-plan.md section 4.2; layout and contracts in ./types.ts). Signatures and
 * documented behaviour are FROZEN.
 *
 * Implementation: ./workspace.ts (the ShadowWorkspace of one run directory), ./git.ts (the shadow's own history,
 * plumbing only, isolated configuration), ./paths.ts (which paths may enter the shadow).
 */
import { createHash } from 'node:crypto';
import { constants as fsConstants } from 'node:fs';
import { copyFile, lstat, mkdir, readdir, readFile, rm, stat, utimes, writeFile } from 'node:fs/promises';
import path from 'node:path';

import { TERMINAL_RUN_STATES } from '@telelean/core';

import { isValidModuleName } from '../lean/leanNames.js';
import { ShadowGit } from './git.js';
import { isModelPath, PROJECT_CONFIG_FILES } from './paths.js';
import { ShadowLayoutError, type CreateShadowOptions, type RunDirInfo, type ShadowWorkspace } from './types.js';
import { RunShadow, shadowPaths } from './workspace.js';

export * from './types.js';
export { isLeanModelPath, isModelPath, isSafeRelativePath, moduleNameOf } from './paths.js';
export { commitMessage, parseCommitMessage, scanTree, shadowPaths, SHADOW_COMMIT_KINDS } from './workspace.js';
export { SHADOW_REF } from './git.js';

/** Run ids (also runLean scope groups). */
const RUN_ID_PATTERN = /^[A-Za-z0-9_]{1,64}$/u;
/** The label of every shadow's first commit. */
export const BASE_COMMIT_LABEL = 'Your files at the start of the run';

/**
 * The directory name of a model root under `runsDir`: its folder name (characters outside `[A-Za-z0-9._-]` -> `_`)
 * plus `-` and the first 8 hex digits of sha1(the root's absolute path). Implemented with the contract.
 */
export function rootKeyOf(root: string): string {
  const abs = path.resolve(root);
  const base = path.basename(abs).replace(/[^A-Za-z0-9._-]/g, '_') || 'root';
  return `${base}-${createHash('sha1').update(abs).digest('hex').slice(0, 8)}`;
}

async function lstatOrUndefined(p: string): Promise<Awaited<ReturnType<typeof lstat>> | undefined> {
  try {
    return await lstat(p);
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT' || (error as NodeJS.ErrnoException).code === 'ENOTDIR') return undefined;
    throw error;
  }
}

async function isRealDirectory(p: string): Promise<boolean> {
  const st = await lstatOrUndefined(p);
  return st !== undefined && st.isDirectory() && !st.isSymbolicLink();
}

/**
 * Fail-closed checks of the user's model tree before anything is created (D-24): no symlink at the root's model and
 * project paths or anywhere in `<library>/` (dot-entries aside, as M1's scan skips them), and every file of the base
 * that exists on disk is a regular file. A symlinked model file would otherwise pull text from outside the model into
 * what Claude reads.
 */
async function checkSourceTree(root: string, library: string, files: readonly string[]): Promise<void> {
  const refused: string[] = [];
  for (const name of [`${library}.lean`, library, ...PROJECT_CONFIG_FILES]) {
    const st = await lstatOrUndefined(path.join(root, name));
    if (st === undefined) continue;
    if (st.isSymbolicLink()) refused.push(name);
    else if (name !== library && !st.isFile()) refused.push(name);
  }
  if (await isRealDirectory(path.join(root, library))) {
    const stack = [library];
    while (stack.length > 0) {
      const rel = stack.pop() ?? '';
      for (const entry of await readdir(path.join(root, rel), { withFileTypes: true })) {
        if (entry.name.startsWith('.')) continue;
        const childRel = `${rel}/${entry.name}`;
        if (entry.isSymbolicLink()) refused.push(childRel);
        else if (entry.isDirectory()) stack.push(childRel);
        else if (!entry.isFile() && entry.name.endsWith('.lean')) refused.push(childRel);
      }
    }
  }
  for (const rel of files) {
    const st = await lstatOrUndefined(path.join(root, rel));
    if (st !== undefined && !st.isFile()) refused.push(rel);
  }
  const unique = [...new Set(refused)].sort();
  if (unique.length > 0) {
    throw new ShadowLayoutError('not-regular', `refusing to copy a model that contains symlinks or special files: ${unique.join(', ')}`, unique);
  }
}

/** The files of the user's `.lake/build` (relative to it), or [] when there is none; any symlink or special file refuses. */
async function collectBuildSeed(root: string): Promise<string[]> {
  const lake = path.join(root, '.lake');
  const buildDir = path.join(lake, 'build');
  if (!(await isRealDirectory(lake)) || !(await isRealDirectory(buildDir))) return [];
  const files: string[] = [];
  const refused: string[] = [];
  const stack = [''];
  while (stack.length > 0) {
    const rel = stack.pop() ?? '';
    for (const entry of await readdir(path.join(buildDir, rel), { withFileTypes: true })) {
      const childRel = rel === '' ? entry.name : `${rel}/${entry.name}`;
      if (entry.isSymbolicLink()) refused.push(`.lake/build/${childRel}`);
      else if (entry.isDirectory()) stack.push(childRel);
      else if (entry.isFile()) files.push(childRel);
      else refused.push(`.lake/build/${childRel}`);
    }
  }
  if (refused.length > 0) {
    refused.sort();
    throw new ShadowLayoutError('not-regular', `refusing to seed the build mirror: .lake/build holds symlinks or special files: ${refused.join(', ')}`, refused);
  }
  return files.sort();
}

function validateRunId(runId: unknown): asserts runId is string {
  if (typeof runId !== 'string' || !RUN_ID_PATTERN.test(runId)) throw new TypeError(`runId must match ${RUN_ID_PATTERN.source}, got ${JSON.stringify(runId)}`);
}

function validateLibrary(library: unknown): asserts library is string {
  if (typeof library !== 'string' || !isValidModuleName(library) || library.includes('.')) {
    throw new TypeError(`library must be a plain Lean identifier, got ${JSON.stringify(library)}`);
  }
}

/**
 * Creates `<runsDir>/<rootKeyOf(root)>/<runId>/` (fails if it exists): writes `options.files` into ws/ and build/
 * (refusing any path that is not a model or project file, D-24), seeds build/.lake/build from the user's
 * `.lake/build` (regular files only; a symlink refuses the whole shadow), `git init` in git/ and commits the base.
 * Every refusal happens before anything is created; a failure while creating removes the run directory again.
 */
export async function createRunShadow(options: CreateShadowOptions): Promise<ShadowWorkspace> {
  if (typeof options !== 'object' || options === null) throw new TypeError('createRunShadow needs options');
  validateRunId(options.runId);
  validateLibrary(options.library);
  if (typeof options.root !== 'string' || !path.isAbsolute(options.root)) throw new TypeError('root must be an absolute path');
  if (typeof options.runsDir !== 'string' || options.runsDir === '') throw new TypeError('runsDir must be a path');
  if (!(options.files instanceof Map)) throw new TypeError('files must be a Map of path -> text');
  const root = path.resolve(options.root);
  const library = options.library;
  const paths = [...options.files.keys()];
  const bad = paths.filter((p) => !isModelPath(p, library)).sort();
  if (bad.length > 0) throw new ShadowLayoutError('bad-path', `only model and project files enter the shadow, not: ${bad.join(', ')}`, bad);
  for (const [p, text] of options.files) if (typeof text !== 'string') throw new TypeError(`the text of ${p} must be a string`);

  await checkSourceTree(root, library, paths);
  const seed = (options.copyBuild ?? true) ? await collectBuildSeed(root) : [];

  const runDir = path.join(path.resolve(options.runsDir), rootKeyOf(root), options.runId);
  if ((await lstatOrUndefined(runDir)) !== undefined) throw new ShadowLayoutError('io', `the run directory ${runDir} already exists`, [runDir]);
  await mkdir(path.dirname(runDir), { recursive: true });
  try {
    await mkdir(runDir);
  } catch (error) {
    throw new ShadowLayoutError('io', `cannot create the run directory ${runDir}: ${(error as Error).message}`, [runDir]);
  }
  const layout = shadowPaths(runDir);
  try {
    for (const dir of [layout.ws, layout.build, layout.gitDir, layout.sessionDir, layout.frozenDir, layout.gateDir, layout.scratchDir]) await mkdir(dir);
    for (const [rel, text] of [...options.files].sort(([a], [b]) => (a < b ? -1 : 1))) {
      for (const base of [layout.ws, layout.build]) {
        await mkdir(path.dirname(path.join(base, rel)), { recursive: true });
        await writeFile(path.join(base, rel), text, 'utf8');
      }
      // The mirror keeps the user's mtime when the text is what is on disk, so a seeded .lake/build stays valid.
      const source = path.join(root, rel);
      const st = await lstatOrUndefined(source);
      if (st?.isFile() && (await readFile(source, 'utf8')) === text) await utimes(path.join(layout.build, rel), st.atime, st.mtime);
    }
    const sourceBuild = path.join(root, '.lake', 'build');
    for (const rel of seed) {
      const src = path.join(sourceBuild, rel);
      const st = await lstat(src);
      if (!st.isFile()) throw new ShadowLayoutError('not-regular', `.lake/build/${rel} stopped being a regular file while it was copied`, [`.lake/build/${rel}`]);
      const dst = path.join(layout.build, '.lake', 'build', rel);
      await mkdir(path.dirname(dst), { recursive: true });
      await copyFile(src, dst, fsConstants.COPYFILE_FICLONE);
      await utimes(dst, st.atime, st.mtime);
    }
    const git = new ShadowGit(layout.gitDir, layout.runDir, options.gitPath);
    await git.init();
    const shadow = new RunShadow({ runId: options.runId, root, library, paths: layout, git, ...(options.now ? { now: options.now } : {}) });
    await shadow.commit('base', BASE_COMMIT_LABEL, 1);
    return shadow;
  } catch (error) {
    await rm(runDir, { recursive: true, force: true });
    if (error instanceof ShadowLayoutError || error instanceof TypeError) throw error;
    throw new ShadowLayoutError('io', `cannot create the shadow: ${(error as Error).message}`, [runDir]);
  }
}

/** Re-opens an existing run directory (recovery after a window reload). */
export async function openRunShadow(runDir: string, options: { root: string; library: string; gitPath?: string }): Promise<ShadowWorkspace> {
  if (typeof runDir !== 'string' || runDir === '') throw new TypeError('runDir must be a path');
  validateLibrary(options.library);
  const layout = shadowPaths(runDir);
  const runId = path.basename(layout.runDir);
  validateRunId(runId);
  for (const dir of [layout.ws, layout.build, layout.gitDir]) {
    if (!(await isRealDirectory(dir))) throw new ShadowLayoutError('io', `${dir} is missing: not a run directory`, [dir]);
  }
  const git = new ShadowGit(layout.gitDir, layout.runDir, options.gitPath);
  return new RunShadow({ runId, root: path.resolve(options.root), library: options.library, paths: layout, git });
}

/** run.json's state and update time (PersistedRun keeps them in `view`); undefined fields when unreadable. */
async function readRunState(stateFile: string): Promise<{ state?: string; updatedAt?: string }> {
  try {
    const json = JSON.parse(await readFile(stateFile, 'utf8')) as Record<string, unknown>;
    const view = typeof json['view'] === 'object' && json['view'] !== null ? (json['view'] as Record<string, unknown>) : {};
    const state = typeof view['state'] === 'string' ? view['state'] : typeof json['state'] === 'string' ? json['state'] : undefined;
    const updatedAt = typeof view['updatedAt'] === 'string' ? view['updatedAt'] : typeof json['updatedAt'] === 'string' ? json['updatedAt'] : undefined;
    return { ...(state !== undefined ? { state } : {}), ...(updatedAt !== undefined ? { updatedAt } : {}) };
  } catch {
    return {};
  }
}

/** The run directories of one root, newest first (by run.json `updatedAt`, else directory mtime). */
export async function listRunDirs(runsDir: string, root: string): Promise<RunDirInfo[]> {
  const dir = path.join(path.resolve(runsDir), rootKeyOf(root));
  let entries;
  try {
    entries = await readdir(dir, { withFileTypes: true });
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return [];
    throw error;
  }
  const found: Array<RunDirInfo & { sortKey: number }> = [];
  for (const entry of entries) {
    if (!entry.isDirectory() || entry.isSymbolicLink() || !RUN_ID_PATTERN.test(entry.name)) continue;
    const runDir = path.join(dir, entry.name);
    const info = await readRunState(path.join(runDir, 'run.json'));
    const updated = info.updatedAt !== undefined ? Date.parse(info.updatedAt) : Number.NaN;
    const mtime = (await stat(runDir).catch(() => undefined))?.mtimeMs ?? 0;
    found.push({ runId: entry.name, runDir, ...info, sortKey: Number.isFinite(updated) ? updated : mtime });
  }
  found.sort((a, b) => b.sortKey - a.sortKey || (a.runId < b.runId ? 1 : -1));
  return found.map(({ sortKey: _sortKey, ...info }) => info);
}

/**
 * Keeps the newest `keep` run directories of the root (03 section 8.4: the last 10) and deletes older ones whose
 * state is terminal (accepted, discarded, cancelled, failed) or unreadable. Never deletes `protect`ed run ids or a
 * non-terminal run. Returns the deleted run ids.
 */
export async function pruneRunDirs(runsDir: string, root: string, keep: number, protect: readonly string[] = []): Promise<string[]> {
  if (!Number.isInteger(keep) || keep < 0) throw new TypeError('keep must be a non-negative integer');
  const terminal = new Set<string>(TERMINAL_RUN_STATES);
  const deleted: string[] = [];
  for (const run of (await listRunDirs(runsDir, root)).slice(keep)) {
    if (protect.includes(run.runId)) continue;
    if (run.state !== undefined && !terminal.has(run.state)) continue;
    const st = await lstatOrUndefined(run.runDir);
    if (st === undefined || !st.isDirectory() || st.isSymbolicLink()) continue;
    await rm(run.runDir, { recursive: true, force: true });
    deleted.push(run.runId);
  }
  return deleted;
}

/**
 * The engine's pure mappings (docs/m2-plan.md sections 3.3, 3.5 and 3.6): Lean facts statuses and comparator verdicts
 * to findings or `environment` outcomes, and Lean messages to diagnostics. Nothing here runs Lean.
 *
 *   runLean / facts status          outcome
 *   ok, build-errors, check-errors  the rules decide (G1 `build` findings come from core, with a fallback here)
 *   timeout, oom                    a `budget` finding (counted against the attempt)
 *   could-not-start, low-memory,    `environment` (not the agent's fault, not counted)
 *   cancelled, unsupported-*
 *   ShadowLayoutError (unsyncable)  `environment`
 */
import type { GateFinding, GateFindingCode, LeanFacts, LeanMessageFact } from '@telelean/core';

import type { ComparatorVerdict, RejectionReason } from '../lean/comparator.js';
import type { ShadowLayoutError } from '../shadow/types.js';
import type { LeanDiagnosticView } from './types.js';

/** The G4 finding code of each comparator rejection reason (docs/m2-plan.md section 3.3). */
export const COMPARATOR_FINDING_CODES: Readonly<Record<RejectionReason, GateFindingCode>> = {
  'illegal-axiom': 'comparator-illegal-axiom',
  'statement-mismatch': 'comparator-statement-mismatch',
  'definition-mismatch': 'comparator-definition-mismatch',
  'kind-mismatch': 'comparator-kind-mismatch',
  'missing-declaration': 'comparator-missing',
  'kernel-rejected': 'comparator-kernel',
  'build-failed': 'comparator-build',
  'export-failed': 'comparator-export',
};

const seconds = (ms: number): string => `${Math.round(ms / 100) / 10} s`;

/** The `budget` finding for a Lean job that hit the per-job time limit or the memory cap. */
export function budgetFinding(kind: 'timeout' | 'oom', detail: string | undefined, leanJobMs: number, step: GateFinding['step'] = 'G1'): GateFinding {
  const what = step === 'G4' ? 'The comparator check' : 'The Lean build';
  const message =
    kind === 'timeout'
      ? `${what} did not finish within the limit of ${seconds(leanJobMs)} per Lean job${detail ? ` (${detail})` : ''}. Simplify the proof (smaller terms, fewer or cheaper tactics) and check again.`
      : `${what} ran out of memory${detail ? ` (${detail})` : ''}. Simplify the proof (smaller terms, fewer or cheaper tactics) and check again.`;
  return { step, code: 'budget', message };
}

/** Plain words for a facts status that means telelean could not run Lean. */
export function environmentMessage(status: string, detail?: string): string {
  const why = detail !== undefined && detail !== '' ? `: ${detail}` : '';
  switch (status) {
    case 'could-not-start':
      return `the Lean sandbox could not start${why}`;
    case 'low-memory':
      return `the machine is low on memory, so telelean did not start Lean${why}`;
    case 'cancelled':
      return 'the Lean job was cancelled';
    case 'unsupported-toolchain':
    case 'unsupported-project':
      return `telelean cannot check this project${why}`;
    default:
      return `Lean could not run (${status})${why}`;
  }
}

export type FactsOutcome =
  /** Lean ran: the rules decide (the build may still have errors). */
  | { kind: 'ok' }
  | { kind: 'budget'; finding: GateFinding }
  | { kind: 'environment'; message: string };

/** What a refresh's status means for a check (docs/m2-plan.md section 3.6). */
export function classifyFacts(facts: LeanFacts, leanJobMs: number): FactsOutcome {
  switch (facts.status) {
    case 'ok':
    case 'build-errors':
    case 'check-errors':
      return { kind: 'ok' };
    case 'timeout':
    case 'oom':
      return { kind: 'budget', finding: budgetFinding(facts.status, facts.detail, leanJobMs) };
    default:
      return { kind: 'environment', message: environmentMessage(facts.status, facts.detail) };
  }
}

/** The environment sentence for a working copy telelean cannot sync (a symlink, special file or dot-entry in ws/). */
export function layoutEnvironment(error: ShadowLayoutError): string {
  return `telelean could not use its working copy: ${error.message}`;
}

/** `file:line:col` of a Lean message (1-based line, as Lean prints it), or undefined without a position. */
export function messageLocation(m: LeanMessageFact): string | undefined {
  if (m.file === undefined) return undefined;
  if (m.range === undefined) return m.file;
  return `${m.file}:${m.range.start.line + 1}:${m.range.start.character}`;
}

/** Lean's build messages as diagnostics (whole messages), only those of `files` when given. */
export function diagnosticsOf(facts: LeanFacts | undefined, files?: readonly string[]): LeanDiagnosticView[] {
  if (facts === undefined) return [];
  const wanted = files !== undefined && files.length > 0 ? new Set(files) : undefined;
  return facts.build.messages
    .filter((m) => wanted === undefined || (m.file !== undefined && wanted.has(m.file)))
    .map((m) => ({
      file: m.file ?? '',
      line: (m.range?.start.line ?? 0) + 1,
      column: m.range?.start.character ?? 0,
      severity: m.severity,
      message: m.text,
    }));
}

/**
 * One G1 `build` finding per Lean error of the build (the whole message, with `file:line:col`), or one from the facts'
 * detail when the build failed without naming a position (e.g. a lakefile error). Empty when the build had no errors.
 */
export function buildErrorFindings(facts: LeanFacts): GateFinding[] {
  const errors = facts.build.messages.filter((m) => m.severity === 'error');
  const findings: GateFinding[] = errors.map((m) => {
    const where = messageLocation(m);
    return {
      step: 'G1',
      code: 'build',
      message: `${where !== undefined ? `${where}: ` : ''}error: ${m.text}`,
      ...(m.file !== undefined ? { file: m.file } : {}),
      ...(m.range !== undefined ? { range: m.range } : {}),
    };
  });
  if (findings.length === 0 && (facts.status === 'build-errors' || facts.build.failedModules.length > 0)) {
    findings.push({ step: 'G1', code: 'build', message: `The Lean build failed: ${facts.detail ?? `modules ${facts.build.failedModules.join(', ')} failed`}` });
  }
  return findings;
}

export interface ComparatorOutcome {
  findings: GateFinding[];
  /** Set when the comparator itself could not judge (not the agent's fault, not counted). */
  environment?: string;
}

/**
 * G4: a comparator verdict as findings (docs/m2-plan.md section 3.3): accepted -> none; each rejection reason -> its
 * `comparator-*` code with the names and comparator's message; `could-not-start` and a cancellation -> environment; a
 * timeout or memory cap -> `budget` (counted). The definition-mismatch wording follows M0 lesson 2.
 */
export function comparatorFindings(verdict: ComparatorVerdict, leanJobMs: number): ComparatorOutcome {
  switch (verdict.verdict) {
    case 'accepted':
      return { findings: [] };
    case 'could-not-start':
      return { findings: [], environment: `the comparator could not run: ${verdict.message}` };
    case 'incomplete':
      if (verdict.reason === 'cancelled') return { findings: [], environment: 'the comparator check was cancelled' };
      return { findings: [budgetFinding(verdict.reason, verdict.message, leanJobMs, 'G4')] };
    case 'rejected': {
      const names = [...verdict.names];
      const list = names.map((n) => `\`${n}\``).join(', ');
      let message: string;
      switch (verdict.reason) {
        case 'illegal-axiom':
          message = `lake comparator: the proof uses axioms outside the permitted set: ${list}. Use only what freeze_statements listed (the selected premises' .holds, the vocabulary, Lean's standard axioms).`;
          break;
        case 'statement-mismatch':
          message = `lake comparator: the statement of ${list} differs from the frozen one. Prove exactly the frozen statement.`;
          break;
        case 'definition-mismatch':
          message = `lake comparator: a definition the frozen statement depends on changed: ${list}. Restore it exactly as it was frozen.`;
          break;
        case 'kind-mismatch':
          message = `lake comparator: ${list} changed kind since the freeze (for example from axiom to theorem).`;
          break;
        case 'missing-declaration':
          message = `lake comparator: missing from the files, or not a theorem: ${list}.`;
          break;
        case 'kernel-rejected':
          message = `lake comparator: Lean's kernel rejected the solution: ${verdict.message}`;
          break;
        case 'build-failed':
          message = `lake comparator: the files did not build: ${verdict.message}`;
          break;
        case 'export-failed':
          message = `lake comparator: the solution could not be exported: ${verdict.message}`;
          break;
      }
      return { findings: [{ step: 'G4', code: COMPARATOR_FINDING_CODES[verdict.reason], message, ...(names.length > 0 ? { names } : {}) }] };
    }
  }
}

/** finish(proved) in a round without a successful freeze (when core's rules did not already say so). */
export function notFrozenFinding(): GateFinding {
  return {
    step: 'G3',
    code: 'not-frozen',
    message: 'finish with status proved needs a successful freeze_statements in this round: call check_lean, then freeze_statements, then prove and finish again.',
  };
}

/**
 * telelean's own scratch Lean files, fed on stdin to `lake env lean --stdin --json` in the build mirror (never written
 * into ws/ or the mirror): the ghost gap check (docs/m2-plan.md section 3.8, facts 7 and 8) and the review's statement
 * renderings (fact 4). Pure: generation and parsing only. Messages are attributed by line, and the ghost's axioms are
 * read only from the `#print axioms` message that names exactly `<S>.telelean_ghost_check`.
 */
import type { LeanMessage } from '../lean/footprint.js';
import { assertModuleName, formatDeclName } from '../lean/leanNames.js';
import type { RenderedStatement } from './types.js';

export const GHOST_STATEMENT_NAME = 'telelean_ghost_stmt';
export const GHOST_CHECK_NAME = 'telelean_ghost_check';
/** The refusal before the round's freeze (docs/m2-plan.md section 3.8). */
export const GHOST_NEEDS_FREEZE = 'freeze first; the gap is judged against the frozen statements';

const NAMESPACE = /^[A-Za-z_][A-Za-z0-9_]*$/u;

/** Every whitespace run becomes one space, trimmed: the checked text a ghost card shows and adoption writes. */
export function collapseWhitespace(text: string): string {
  return text.replace(/\s+/gu, ' ').trim();
}

export interface GhostScratch {
  readonly source: string;
  /** The fully-qualified check theorem, e.g. `Spyro.telelean_ghost_check`. */
  readonly checkName: string;
  /** 1-based line of the pinned statement abbrev. */
  readonly statementLine: number;
  /** 1-based lines of the check theorem's header and its proof (inclusive). */
  readonly proofLines: readonly [number, number];
  /** 1-based line of `#print axioms <checkName>`. */
  readonly printLine: number;
}

/**
 * The pinned ghost check (fact 7):
 *
 *   import <library>
 *   namespace <S>
 *   abbrev telelean_ghost_stmt : Prop := <statement, whitespace collapsed>
 *   theorem telelean_ghost_check : telelean_ghost_stmt → <T> :=
 *     <proof, every line indented by two spaces>
 *   end <S>
 *   #print axioms <S>.telelean_ghost_check
 *
 * Claude's statement is pinned inside a named abbreviation, so text that tries to close the declaration early turns into
 * parse errors (fact 8) instead of changing what is checked; core's single-term rule has already refused such text.
 */
export function ghostScratchSource(input: { library: string; namespace: string; targetStatement: string; statement: string; proof: string }): GhostScratch {
  assertModuleName(input.library);
  if (!NAMESPACE.test(input.namespace)) throw new TypeError(`not a usable namespace: ${JSON.stringify(input.namespace)}`);
  const target = formatDeclName(input.targetStatement);
  const statement = collapseWhitespace(input.statement);
  const proof = input.proof.split(/\r?\n/u).map((line) => `  ${line}`);
  const lines = [
    `import ${input.library}`,
    `namespace ${input.namespace}`,
    `abbrev ${GHOST_STATEMENT_NAME} : Prop := ${statement}`,
    `theorem ${GHOST_CHECK_NAME} : ${GHOST_STATEMENT_NAME} → ${target} :=`,
    ...proof,
    `end ${input.namespace}`,
  ];
  const proofEnd = lines.length - 1;
  const checkName = `${input.namespace}.${GHOST_CHECK_NAME}`;
  lines.push(`#print axioms ${checkName}`);
  return { source: `${lines.join('\n')}\n`, checkName, statementLine: 3, proofLines: [4, proofEnd], printLine: lines.length };
}

const AXIOMS_MESSAGE = /^'([^']*)' (?:depends on axioms: \[([^]*)\]|does not depend on any axioms)\s*$/u;

/** The declaration a `#print axioms` message is about and its axioms, or undefined for any other message. */
export function parseNamedAxiomsMessage(data: string): { name: string; axioms: string[] } | undefined {
  const m = AXIOMS_MESSAGE.exec(data);
  if (m === null) return undefined;
  const axioms = (m[2] ?? '')
    .split(',')
    .map((s) => s.trim())
    .filter((s) => s.length > 0);
  return { name: m[1] ?? '', axioms };
}

export interface GhostScratchResult {
  /** Every Lean error, located ("in the suggested statement", "in the proof", or a line of telelean's file). */
  errors: string[];
  /** The axioms of the check theorem, read from the message naming it (absent when Lean printed none). */
  axioms?: string[];
}

/** Reads Lean's messages for a ghost check. */
export function readGhostScratch(scratch: GhostScratch, messages: readonly LeanMessage[]): GhostScratchResult {
  const errors: string[] = [];
  let axioms: string[] | undefined;
  for (const m of messages) {
    if (m.severity === 'error') {
      const where =
        m.line === scratch.statementLine
          ? 'in the suggested statement'
          : m.line >= scratch.proofLines[0] && m.line <= scratch.proofLines[1]
            ? 'in the proof'
            : `in telelean's check file, line ${m.line}`;
      errors.push(`Lean error ${where}: ${m.data}`);
      continue;
    }
    if (m.line !== scratch.printLine) continue;
    const parsed = parseNamedAxiomsMessage(m.data);
    if (parsed !== undefined && parsed.name === scratch.checkName) axioms = parsed.axioms;
  }
  return { errors, ...(axioms !== undefined ? { axioms } : {}) };
}

/** The options of the review's explicit form (fact 4). */
export const EXPLICIT_OPTIONS = 'set_option pp.explicit true in set_option pp.notation false in set_option pp.universes true in set_option pp.coercions false in';

export interface RenderScratch {
  readonly source: string;
  /** 1-based line -> the statement and form printed there. */
  readonly lines: ReadonlyMap<number, { readonly name: string; readonly form: 'pretty' | 'explicit' }>;
  /** Names that cannot be written into Lean source, with the reason. */
  readonly unwritable: ReadonlyMap<string, string>;
}

/** `#print <name>` with default options, then the same under the explicit options, one line each. */
export function renderScratchSource(library: string, names: readonly string[]): RenderScratch {
  assertModuleName(library);
  const lines = [`import ${library}`];
  const at = new Map<number, { name: string; form: 'pretty' | 'explicit' }>();
  const unwritable = new Map<string, string>();
  for (const name of new Set(names)) {
    let written: string;
    try {
      written = formatDeclName(name);
    } catch (error) {
      unwritable.set(name, (error as Error).message);
      continue;
    }
    lines.push(`#print ${written}`);
    at.set(lines.length, { name, form: 'pretty' });
    lines.push(`${EXPLICIT_OPTIONS} #print ${written}`);
    at.set(lines.length, { name, form: 'explicit' });
  }
  return { source: `${lines.join('\n')}\n`, lines: at, unwritable };
}

/** One RenderedStatement per requested name, in order (an `error` when Lean could not print it). */
export function readRenderScratch(scratch: RenderScratch, names: readonly string[], messages: readonly LeanMessage[]): RenderedStatement[] {
  const byName = new Map<string, { pretty?: string; explicit?: string; error?: string }>();
  const headerErrors: string[] = [];
  for (const m of messages) {
    const slot = scratch.lines.get(m.line);
    if (slot === undefined) {
      if (m.severity === 'error') headerErrors.push(m.data);
      continue;
    }
    const entry = byName.get(slot.name) ?? {};
    if (m.severity === 'error') entry.error ??= m.data;
    else if (m.severity === 'information') entry[slot.form] ??= m.data.trim();
    byName.set(slot.name, entry);
  }
  return names.map((name) => {
    const why = scratch.unwritable.get(name);
    if (why !== undefined) return { name, pretty: '', explicit: '', error: why };
    const entry = byName.get(name) ?? {};
    const error =
      entry.error ??
      (headerErrors.length > 0 && (entry.pretty === undefined || entry.explicit === undefined) ? headerErrors.join('\n') : undefined) ??
      (entry.pretty === undefined || entry.explicit === undefined ? `Lean printed nothing for ${name}` : undefined);
    return { name, pretty: entry.pretty ?? '', explicit: entry.explicit ?? '', ...(error !== undefined ? { error } : {}) };
  });
}

