/**
 * Shared helpers for the WP2 tests (shadow and Lean check engine): the Spyro fixture's model files, the gate edit
 * scripts of test-fixtures/gate/, engine contexts, and simple fakes of WP1's core functions for the tests that run
 * while WP1's rules are still stubs (the [gated] tests use the real ones and skip themselves until they exist).
 */
import { copyFileSync, existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import path from 'node:path';

import * as core from '@telelean/core';
import type { FrozenSnapshot, GateFinding, PermittedAxioms, RuleInput, RuleReport, Selection } from '@telelean/core';

import type { CheckContext, EngineCore, FreezeRecord, LeanJobSettings } from '../../src/gate/index.js';
import type { ShadowWorkspace } from '../../src/shadow/index.js';
import { REPO_ROOT, SPYRO } from '../lean/helpers.js';

export { cleanupTempRoot, knownProjectsLines, makeTempRoot, MiB, processesMatching, REPO_ROOT, SPYRO } from '../lean/helpers.js';

export const GATE_FIXTURES = path.join(REPO_ROOT, 'test-fixtures', 'gate');
export const GiB = 1024 ** 3;

const PROJECT_FILES = ['lakefile.toml', 'lakefile.lean', 'lean-toolchain', 'lake-manifest.json'];

function walkFiles(dir: string, rel = ''): string[] {
  const out: string[] = [];
  for (const entry of readdirSync(path.join(dir, rel), { withFileTypes: true })) {
    const childRel = rel === '' ? entry.name : `${rel}/${entry.name}`;
    if (entry.isDirectory()) out.push(...walkFiles(dir, childRel));
    else if (entry.isFile()) out.push(childRel);
  }
  return out;
}

/** The Spyro fixture's model and project files (what ModelWorkspace.readText gives; `Check/` is not a model file). */
export function spyroModelFiles(overlay?: string): Map<string, string> {
  const files = new Map<string, string>();
  for (const rel of walkFiles(SPYRO)) {
    if (PROJECT_FILES.includes(rel) || rel === 'Model.lean' || (rel.startsWith('Model/') && rel.endsWith('.lean'))) {
      files.set(rel, readFileSync(path.join(SPYRO, rel), 'utf8'));
    }
  }
  if (overlay !== undefined) {
    const dir = path.join(GATE_FIXTURES, 'overlays', overlay);
    for (const rel of walkFiles(dir)) files.set(rel, readFileSync(path.join(dir, rel), 'utf8'));
  }
  return new Map([...files].sort(([a], [b]) => (a < b ? -1 : 1)));
}

/** A model root on disk: a scratch copy of the Spyro fixture (Check/ included, as a user's folder may hold other files) + overlay. */
export function spyroRoot(tmp: string, name: string, overlay?: string): string {
  const root = path.join(tmp, name);
  if (existsSync(root)) throw new Error(`${root} exists`);
  for (const rel of walkFiles(SPYRO)) {
    mkdirSync(path.dirname(path.join(root, rel)), { recursive: true });
    copyFileSync(path.join(SPYRO, rel), path.join(root, rel));
  }
  if (overlay !== undefined) {
    const dir = path.join(GATE_FIXTURES, 'overlays', overlay);
    for (const rel of walkFiles(dir)) {
      mkdirSync(path.dirname(path.join(root, rel)), { recursive: true });
      copyFileSync(path.join(dir, rel), path.join(root, rel));
    }
  }
  return root;
}

export interface EditStep {
  path: string;
  oldString: string | null;
  newString?: string;
  newStringFile?: string;
}

let editCache: Record<string, EditStep[]> | undefined;

/** The named edit script of test-fixtures/gate/edits.json. */
export function editScript(name: string): EditStep[] {
  editCache ??= JSON.parse(readFileSync(path.join(GATE_FIXTURES, 'edits.json'), 'utf8')) as Record<string, EditStep[]>;
  const steps = editCache[name];
  if (steps === undefined || name.startsWith('_')) throw new Error(`no edit script ${name}`);
  return steps;
}

function replacement(step: EditStep): string {
  if (step.newStringFile !== undefined) return readFileSync(path.join(GATE_FIXTURES, step.newStringFile), 'utf8');
  if (step.newString === undefined) throw new Error(`edit of ${step.path} has no new text`);
  return step.newString;
}

/** Applies edit scripts to a path -> text map (a copy). */
export function applyEdits(files: ReadonlyMap<string, string>, ...names: string[]): Map<string, string> {
  const out = new Map(files);
  for (const name of names) {
    for (const step of editScript(name)) {
      const current = out.get(step.path);
      if (step.oldString === null) {
        if (current !== undefined) throw new Error(`${name}: ${step.path} exists`);
        out.set(step.path, replacement(step));
        continue;
      }
      if (current === undefined) throw new Error(`${name}: ${step.path} is missing`);
      const count = current.split(step.oldString).length - 1;
      if (count !== 1) throw new Error(`${name}: the old text occurs ${count} times in ${step.path}`);
      out.set(step.path, current.replace(step.oldString, () => replacement(step)));
    }
  }
  return out;
}

/** Plays Claude: applies edit scripts to the files of ws/ directly (as its Edit and Write tools would). */
export function editWs(shadow: ShadowWorkspace, ...names: string[]): void {
  const touched = new Set(names.flatMap((n) => editScript(n).map((s) => s.path)));
  const before = new Map<string, string>();
  for (const rel of touched) {
    const file = path.join(shadow.paths.ws, rel);
    if (existsSync(file)) before.set(rel, readFileSync(file, 'utf8'));
  }
  const after = applyEdits(before, ...names);
  for (const [rel, text] of after) {
    mkdirSync(path.dirname(path.join(shadow.paths.ws, rel)), { recursive: true });
    writeFileSync(path.join(shadow.paths.ws, rel), text);
  }
}

/** Removes a file from ws/ (playing Claude). */
export function removeFromWs(shadow: ShadowWorkspace, rel: string): void {
  rmSync(path.join(shadow.paths.ws, rel));
}

export const SUBJECT = 'Spyro';
export const TARGET = 'cynder-not-good';
export const ALL_PREMISES = ['cynder-dark-past', 'new-spyro-pg', 'pg-no-dark-past'];

export function selection(premises: readonly string[] = ALL_PREMISES, adoptedGhosts: readonly string[] = []): Selection {
  return { subject: SUBJECT, target: TARGET, premises, adoptedGhosts };
}

/** Job settings for a test run (real memory guard at 2 GiB unless overridden). */
export function jobFor(runId: string, extra: Partial<LeanJobSettings> = {}): LeanJobSettings {
  return { runId, memoryMax: '4G', minAvailableBytes: 2 * GiB, leanJobMs: 120_000, ...extra };
}

export function contextFor(shadow: ShadowWorkspace, runId: string, over: Partial<CheckContext> = {}): CheckContext {
  return {
    shadow,
    selection: selection(),
    stage: 'formalise',
    round: 1,
    job: jobFor(runId),
    teleleanBlocks: [],
    ...over,
  };
}

// ---------------------------------------------------------------------------------------------- the D-5 sets (plan 3.2)

export const STD = ['Classical.choice', 'Quot.sound', 'propext'];
export const SIGNATURE = ['Spyro.Character', 'Spyro.Game', 'Spyro.GoodAddition', 'Spyro.HasDarkPast', 'Spyro.IsPG'];
export const PRESUPPOSITIONS = ['Spyro.Character.exists', 'Spyro.Game.exists'];
export const SELECTED_ALL = ['Spyro.cynder_dark_past.holds', 'Spyro.new_spyro_pg.holds', 'Spyro.pg_no_dark_past.holds'];
/** Spyro, normative reading, all three selected: the 13 names of plan section 3.2 (= M0's permitted(ALL_SELECTED)). */
export const PERMITTED_NORMATIVE = [...STD, ...SIGNATURE, ...PRESUPPOSITIONS, ...SELECTED_ALL].sort();

export function permittedAxioms(parts: { signature?: string[]; selected?: string[]; presuppositions?: string[] } = {}): PermittedAxioms {
  const signature = parts.signature ?? SIGNATURE;
  const selected = parts.selected ?? SELECTED_ALL;
  const presuppositions = parts.presuppositions ?? PRESUPPOSITIONS;
  return {
    standard: [...STD],
    signature: [...signature],
    selected: [...selected],
    presuppositions: [...presuppositions],
    derivationFootprints: [],
    unusable: [],
    all: [...new Set([...STD, ...signature, ...selected, ...presuppositions])].sort(),
  };
}

// ---------------------------------------------------------------------------------------------- fakes of WP1's functions

/** A naive G0: non-model added paths are `bad-path`; a `sorry` or `#eval` Claude added to a .lean file is reported. */
export function fakeCheckFileChanges(base: ReadonlyMap<string, string>, current: ReadonlyMap<string, string>): GateFinding[] {
  const findings: GateFinding[] = [];
  for (const [p, text] of current) {
    const before = base.get(p);
    if (before === text) continue;
    if (!/^Model(\/[A-Za-z_][A-Za-z0-9_]*)*\.lean$/u.test(p) && !PROJECT_FILES.includes(p)) {
      findings.push({ step: 'G0', code: 'bad-path', message: `${p} is not a module of the subject`, file: p, token: p });
      continue;
    }
    for (const token of ['sorry', '#eval']) {
      if (text.includes(token) && !(before ?? '').includes(token)) {
        findings.push({ step: 'G0', code: token === 'sorry' ? 'sorry' : 'hash-command', message: `${p}: forbidden \`${token}\``, file: p, token });
      }
    }
  }
  return findings;
}

/** Every rule holds; footprints are the facts' axioms of the theorems. */
export function passingRules(input: RuleInput): RuleReport {
  const footprints: Record<string, string[]> = {};
  for (const d of input.current.facts?.decls ?? []) if (d.kind === 'theorem' && d.axioms !== undefined) footprints[d.name] = d.axioms;
  return { findings: [], flaggedDefinitions: [], footprints, formalisedThisRun: [], declarations: { added: [], changed: [], removed: [] } };
}

/** A fake frozen snapshot of the Spyro target with the given permitted set. */
export function fakeFreezeCore(permitted: PermittedAxioms, targetStatement = 'Spyro.cynder_not_good'): Pick<EngineCore, 'computePermittedAxioms' | 'frozenSnapshot'> {
  return {
    computePermittedAxioms: () => permitted,
    frozenSnapshot: (_model, _selection, round): FrozenSnapshot => ({ round, permitted, targetStatement, declarations: {}, axioms: [] }),
  };
}

/** Core fakes for engine-mechanics tests: G0 as above, every rule passing, the given permitted set. */
export function fakeCore(permitted: PermittedAxioms = permittedAxioms(), over: Partial<EngineCore> = {}): Partial<EngineCore> {
  return {
    checkFileChanges: fakeCheckFileChanges,
    ghostTextProblems: () => [],
    evaluateRules: passingRules,
    normalisationChanges: () => [],
    ...fakeFreezeCore(permitted),
    ...over,
  };
}

/** A freeze record for tests that fake the freeze itself (no export behind it). */
export function fakeFreezeRecord(shadowCommit: FreezeRecord['commit'], permitted: PermittedAxioms, sel: Selection = selection()): FreezeRecord {
  return {
    round: 1,
    commit: shadowCommit,
    at: new Date(0).toISOString(),
    selection: sel,
    snapshot: { round: 1, permitted, targetStatement: 'Spyro.cynder_not_good', declarations: {}, axioms: [] },
    freeze: { exportPath: '/nonexistent/frozen.ndjson', challengeModule: 'Model.TeleleanChallenge', theoremNames: ['Spyro.cynder_not_good.holds'], permittedAxioms: permitted.all, definitionNames: [] },
  };
}

// ---------------------------------------------------------------------------------------------- [gated] detection

const probe = (fn: () => unknown): boolean => core.isImplemented(fn);
/** WP1's rules exist: the [gated] tests run (the integrator removes the gates). */
export const WP1_RULES =
  probe(() => core.evaluateRules({} as never)) &&
  probe(() => core.checkFileChanges(new Map(), new Map(), { library: 'Model', subject: 'Spyro', projectModules: new Set() })) &&
  probe(() => core.computePermittedAxioms({} as never, {} as never)) &&
  probe(() => core.frozenSnapshot({} as never, {} as never, 1));
export const WP1_GHOST_TEXT = probe(() => core.ghostTextProblems('True'));
export const WP1_NORMALISATION = probe(() => core.normalisationChanges({} as never, []));

/**
 * The run's shadow workspace (M2 WP2, docs/m2-plan.md section 4.2), without Lean:
 * AT2.1 layout and refusals, AT2.2 path-guard compatibility, AT2.3 (sync without a build), AT2.4 history and writes,
 * AT2.5 run directories. Git runs only inside the shadows' own git/ directories, with an isolated configuration.
 */
import { chmodSync, existsSync, lstatSync, mkdirSync, readdirSync, readFileSync, realpathSync, statSync, symlinkSync, utimesSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';

import { decide } from '../../bin/telelean-path-guard.mjs';
import { buildGuardPolicy } from '../../src/llm/confinement.js';
import {
  BASE_COMMIT_LABEL,
  createRunShadow,
  isModelPath,
  listRunDirs,
  openRunShadow,
  PASSING_COMMIT_KINDS,
  pruneRunDirs,
  rootKeyOf,
  ShadowLayoutError,
  type ShadowWorkspace,
} from '../../src/shadow/index.js';
import { cleanupTempRoot, makeTempRoot, spyroModelFiles, spyroRoot } from '../gate/helpers.js';

/** Every entry below `dir` (files and directories), as sorted relative POSIX paths. */
function entries(dir: string, rel = ''): string[] {
  const out: string[] = [];
  for (const e of readdirSync(path.join(dir, rel), { withFileTypes: true })) {
    const childRel = rel === '' ? e.name : `${rel}/${e.name}`;
    out.push(childRel);
    if (e.isDirectory() && !e.isSymbolicLink()) out.push(...entries(dir, childRel));
  }
  return out.sort();
}
const filesBelow = (dir: string): string[] => entries(dir).filter((p) => lstatSync(path.join(dir, p)).isFile());
const isInside = (p: string, dir: string): boolean => p === dir || p.startsWith(dir + path.sep);

async function expectLayoutError(promise: Promise<unknown>, code: string): Promise<ShadowLayoutError> {
  let error: unknown;
  try {
    await promise;
  } catch (e) {
    error = e;
  }
  expect(error).toBeInstanceOf(ShadowLayoutError);
  expect((error as ShadowLayoutError).code).toBe(code);
  return error as ShadowLayoutError;
}

describe('createRunShadow: layout and refusals (AT2.1)', () => {
  let tmp: string;
  beforeAll(() => {
    tmp = makeTempRoot('shadow-layout');
  });
  afterAll(() => cleanupTempRoot(tmp));

  it('ws/ holds exactly the model and project files (no dot-entry at any depth), build/ mirrors them with .lake/build seeded, one base commit, run and session dirs outside ws/', async () => {
    const root = spyroRoot(tmp, 'root');
    // What a user's folder also holds: telelean's sidecars, a .gitignore, a Lake build tree.
    mkdirSync(path.join(root, '.telelean', 'subjects', 'Spyro'), { recursive: true });
    writeFileSync(path.join(root, '.telelean', 'config.json'), '{}\n');
    writeFileSync(path.join(root, '.gitignore'), '.lake\n');
    const olean = path.join(root, '.lake', 'build', 'lib', 'lean', 'Model', 'Spyro', 'Main.olean');
    mkdirSync(path.dirname(olean), { recursive: true });
    writeFileSync(olean, 'not really an olean');
    const past = new Date('2026-01-02T03:04:05Z');
    utimesSync(olean, past, past);
    const mainOnDisk = path.join(root, 'Model', 'Spyro', 'Main.lean');
    utimesSync(mainOnDisk, past, past);

    const files = spyroModelFiles();
    const runsDir = path.join(tmp, 'runs');
    const shadow = await createRunShadow({ root, runsDir, runId: 'r_layout', library: 'Model', files });

    expect(shadow.runId).toBe('r_layout');
    expect(shadow.paths.runDir).toBe(path.join(runsDir, rootKeyOf(root), 'r_layout'));
    // ws/: exactly the given files, nothing hidden anywhere (so the guard allows Grep/Glob on the whole root).
    expect(filesBelow(shadow.paths.ws)).toEqual([...files.keys()].sort());
    expect(entries(shadow.paths.ws).filter((p) => p.split('/').some((s) => s.startsWith('.')))).toEqual([]);
    expect([...files.keys()]).not.toContain('Check/Normative.lean');
    for (const [rel, text] of files) expect(readFileSync(path.join(shadow.paths.ws, rel), 'utf8')).toBe(text);
    // build/: the same model files plus .lake/build seeded with the user's mtimes.
    expect(filesBelow(shadow.paths.build).filter((p) => !p.startsWith('.lake/'))).toEqual([...files.keys()].sort());
    const seeded = path.join(shadow.paths.build, '.lake', 'build', 'lib', 'lean', 'Model', 'Spyro', 'Main.olean');
    expect(readFileSync(seeded, 'utf8')).toBe('not really an olean');
    expect(statSync(seeded).mtimeMs).toBe(past.getTime());
    // The mirror keeps the user's mtime of a source whose text is what is on disk.
    expect(statSync(path.join(shadow.paths.build, 'Model', 'Spyro', 'Main.lean')).mtimeMs).toBe(past.getTime());
    // One base commit holding exactly the files.
    const commits = await shadow.commits();
    expect(commits.map((c) => [c.kind, c.label, c.round])).toEqual([['base', BASE_COMMIT_LABEL, 1]]);
    expect(commits[0]?.id).toMatch(/^[0-9a-f]{40}$/u);
    expect(await shadow.baseFiles()).toEqual(files);
    expect(await shadow.currentFiles()).toEqual(files);
    // Everything else lives beside ws/, never inside it.
    for (const p of [shadow.paths.runDir, shadow.paths.build, shadow.paths.gitDir, shadow.paths.sessionDir, shadow.paths.frozenDir, shadow.paths.gateDir, shadow.paths.scratchDir, shadow.paths.stateFile]) {
      expect(isInside(p, shadow.paths.ws)).toBe(false);
    }
    for (const dir of [shadow.paths.sessionDir, shadow.paths.frozenDir, shadow.paths.gateDir, shadow.paths.scratchDir]) expect(statSync(dir).isDirectory()).toBe(true);
    // The user's folder is untouched (no .git appeared there).
    expect(existsSync(path.join(root, '.git'))).toBe(false);
    // Re-opening finds the same history.
    const again = await openRunShadow(shadow.paths.runDir, { root, library: 'Model' });
    expect((await again.commits()).map((c) => c.id)).toEqual(commits.map((c) => c.id));
  });

  it('copyBuild: false seeds nothing', async () => {
    const root = spyroRoot(tmp, 'nobuild');
    mkdirSync(path.join(root, '.lake', 'build'), { recursive: true });
    writeFileSync(path.join(root, '.lake', 'build', 'x'), 'x');
    const shadow = await createRunShadow({ root, runsDir: path.join(tmp, 'runs'), runId: 'r_nobuild', library: 'Model', files: spyroModelFiles(), copyBuild: false });
    expect(existsSync(path.join(shadow.paths.build, '.lake', 'build', 'x'))).toBe(false);
  });

  it('refuses a symlink in the model tree, a symlinked model file, and a symlink in .lake/build, leaving nothing behind', async () => {
    const runsDir = path.join(tmp, 'runs-refused');
    // A symlink anywhere in the library tree.
    const linked = spyroRoot(tmp, 'linked');
    writeFileSync(path.join(tmp, 'outside.lean'), '-- outside the model\n');
    symlinkSync(path.join(tmp, 'outside.lean'), path.join(linked, 'Model', 'Spyro', 'Secret.lean'));
    const e1 = await expectLayoutError(createRunShadow({ root: linked, runsDir, runId: 'r_link', library: 'Model', files: spyroModelFiles() }), 'not-regular');
    expect(e1.paths).toEqual(['Model/Spyro/Secret.lean']);
    // A symlinked project file.
    const project = spyroRoot(tmp, 'linked-project');
    const toolchain = path.join(project, 'lean-toolchain');
    writeFileSync(path.join(tmp, 'toolchain-elsewhere'), readFileSync(toolchain));
    rmFile(toolchain);
    symlinkSync(path.join(tmp, 'toolchain-elsewhere'), toolchain);
    await expectLayoutError(createRunShadow({ root: project, runsDir, runId: 'r_link2', library: 'Model', files: spyroModelFiles() }), 'not-regular');
    // A symlink inside .lake/build.
    const lake = spyroRoot(tmp, 'linked-build');
    mkdirSync(path.join(lake, '.lake', 'build', 'lib'), { recursive: true });
    writeFileSync(path.join(lake, '.lake', 'build', 'lib', 'ok.olean'), 'x');
    symlinkSync('/etc/hostname', path.join(lake, '.lake', 'build', 'lib', 'evil.olean'));
    const e3 = await expectLayoutError(createRunShadow({ root: lake, runsDir, runId: 'r_link3', library: 'Model', files: spyroModelFiles() }), 'not-regular');
    expect(e3.paths).toEqual(['.lake/build/lib/evil.olean']);
    // Nothing was created for any of them.
    expect(existsSync(runsDir)).toBe(false);
  });

  it('refuses paths that are not model or project files, before creating anything', async () => {
    const root = spyroRoot(tmp, 'badpaths');
    const runsDir = path.join(tmp, 'runs-bad');
    for (const bad of ['Check/Normative.lean', '.gitignore', 'Model/.hidden.lean', 'Model/../x.lean', '/abs.lean', 'Model/Spyro/notes.md', 'Model//Main.lean']) {
      const files = new Map(spyroModelFiles());
      files.set(bad, 'x');
      const e = await expectLayoutError(createRunShadow({ root, runsDir, runId: 'r_bad', library: 'Model', files }), 'bad-path');
      expect(e.paths).toEqual([bad]);
    }
    expect(existsSync(runsDir)).toBe(false);
    expect(isModelPath('Model/Spyro/Main.lean', 'Model')).toBe(true);
    expect(isModelPath('lake-manifest.json', 'Model')).toBe(true);
    expect(isModelPath('Model.lean', 'Model')).toBe(true);
    expect(isModelPath('Other.lean', 'Model')).toBe(false);
  });

  it('refuses an existing run directory and invalid arguments', async () => {
    const root = spyroRoot(tmp, 'twice');
    const runsDir = path.join(tmp, 'runs-twice');
    await createRunShadow({ root, runsDir, runId: 'r_twice', library: 'Model', files: spyroModelFiles() });
    await expectLayoutError(createRunShadow({ root, runsDir, runId: 'r_twice', library: 'Model', files: spyroModelFiles() }), 'io');
    await expect(createRunShadow({ root, runsDir, runId: 'bad-id!', library: 'Model', files: spyroModelFiles() })).rejects.toThrow(TypeError);
    await expect(createRunShadow({ root: 'relative', runsDir, runId: 'r_x', library: 'Model', files: spyroModelFiles() })).rejects.toThrow(TypeError);
  });
});

function rmFile(p: string): void {
  // Small helper so the symlink test can replace a file without importing rmSync at every call site.
  writeFileSync(p, '');
  chmodSync(p, 0o644);
  require('node:fs').rmSync(p);
}

describe('path guard compatibility (AT2.2)', () => {
  let tmp: string;
  let shadow: ShadowWorkspace;
  beforeAll(async () => {
    tmp = makeTempRoot('shadow-guard');
    shadow = await createRunShadow({ root: spyroRoot(tmp, 'root'), runsDir: path.join(tmp, 'runs'), runId: 'r_guard', library: 'Model', files: spyroModelFiles() });
  });
