    const runDir = realpathSync(shadow.paths.runDir);
    for (const outside of [path.join(runDir, 'build', 'Model', 'Spyro', 'Main.lean'), path.join(runDir, 'git', 'config'), path.join(runDir, 'run.json')]) {
