    writeFileSync(path.join(shadow.paths.ws, 'Model/Spyro/Main.lean'), readFileSync(path.join(shadow.paths.ws, 'Model/Spyro/Main.lean'), 'utf8').replace('cynder_dark_past.holds\n', 'cynder_dark_past\n'));
