async freeze(ctx: CheckContext): Promise<FreezeOutcome> {
  validateContext(ctx);
  try {
    return await this.freezeNow(ctx);
  } catch (error) {
    if (!(error instanceof ShadowLayoutError)) throw error;
    const environment = layoutEnvironment(error);
    return { ok: false, refusals: [environment], report: this.envReport(environment, performance.now()), environment };
  }
}

