161	 * (auxiliary names map to their parent). Only names declared syntactically in `declared` are returned (they are what
162	 * `remove-decl` can find), in a stable order.
163	 */
164	export function removalClosure(facts: LeanFacts | undefined, declared: ReadonlySet<string>, start: string): string[] {
165	  const parentOf = new Map<string, string>();
166	  for (const d of facts?.decls ?? []) if (d.parent !== undefined) parentOf.set(d.name, d.parent);
167	  const top = (name: string): string => {
168	    let n = name;
169	    for (let i = 0; i < 16 && parentOf.has(n); i++) n = parentOf.get(n) ?? n;
170	    return n;
171	  };
172	  const users = new Map<string, Set<string>>();
173	  for (const d of facts?.decls ?? []) {
174	    const user = top(d.name);
175	    for (const ref of d.refs) {
176	      const set = users.get(ref.name) ?? new Set<string>();
177	      set.add(user);
178	      users.set(ref.name, set);
179	    }
180	  }
181	  const removed = new Set<string>([start]);
182	  const queue = [start];
183	  while (queue.length > 0) {
184	    const name = queue.shift() ?? '';
185	    for (const user of users.get(name) ?? []) {
186	      if (!removed.has(user)) {
187	        removed.add(user);
188	        queue.push(user);
189	      }
190	    }
191	  }
192	  return [...removed].filter((n) => declared.has(n)).sort();
193	}
