207	function remember<K, V>(cache: Map<K, V>, key: K, value: V, limit: number): void {
208	  cache.delete(key);
209	  cache.set(key, value);
210	  while (cache.size > limit) {
211	    const oldest = cache.keys().next();
212	    if (oldest.done === true) break;
213	    cache.delete(oldest.value);
214	  }
215	}
