218	  private readonly core: EngineCore;
219	  private readonly refreshFacts: NonNullable<LeanCheckEngineOptions['refreshFacts']>;
220	  private readonly now: () => Date;
221	  /** runDir -> filesKey of the ws/ state whose check left the mirror clean (no finding). */
