387	
388	  private envReport(environment: string, started: number, extra: Partial<CheckReport> = {}): CheckReport {
389	    return { outcome: 'environment', environment, g0: [], findings: [], diagnostics: [], ...extra, durationMs: Math.round(performance.now() - started) };
390	  }
391	
392	  /** The check behind check/freeze/gate/ghost: G0 -> sync -> build -> models -> rules. `given` = ws/ already read. */
393	  private async runCheck(ctx: CheckContext, purpose: RulePurpose, given?: ReadonlyMap<string, string>): Promise<CheckReport> {
394	    const started = performance.now();
395	    const shadow = ctx.shadow;
396	    const library = shadow.library;
397	    let files: ReadonlyMap<string, string>;
398	    try {
399	      files = given ?? (await shadow.currentFiles());
400	    } catch (error) {
401	      if (error instanceof ShadowLayoutError) return this.envReport(layoutEnvironment(error), started);
402	      throw error;
403	    }
404	    const baseId = ctx.baseCommit ?? (await this.baseCommitId(shadow));
405	    const baseFiles = await shadow.filesAt(baseId);
406	
407	    // G0: text only. Lean never elaborates text that fails it.
408	    const g0 = this.core.checkFileChanges(baseFiles, files, { library, subject: ctx.selection.subject, projectModules: projectModulesOf(files, library) });
409	    if (g0.length > 0) {
410	      return { outcome: 'problems', g0, findings: [], diagnostics: [], durationMs: Math.round(performance.now() - started) };
411	    }
412	
413	    // G1: the build mirror holds exactly ws/'s model files; one Lean job builds and checks it.
414	    this.cleanMirror.delete(shadow.paths.runDir);
415	    try {
416	      await shadow.syncMirror();
417	    } catch (error) {
418	      if (error instanceof ShadowLayoutError) return this.envReport(layoutEnvironment(error), started);
419	      throw error;
420	    }
421	    const facts = await this.refresh(shadow, ctx.job);
422	    const diagnostics = diagnosticsOf(facts, ctx.files);
423	    const build = {
424	      status: facts.status,
425	      durationMs: facts.build.durationMs + facts.check.durationMs,
426	      errorCount: facts.build.messages.filter((m) => m.severity === 'error').length,
427	    };
428	    const outcome = classifyFacts(facts, ctx.job.leanJobMs);
429	    if (outcome.kind === 'environment') return this.envReport(outcome.message, started, { diagnostics, build, facts });
430	    if (outcome.kind === 'budget') {
431	      return { outcome: 'problems', g0: [], findings: [outcome.finding], diagnostics, build, facts, durationMs: Math.round(performance.now() - started) };
432	    }
433	
434	    // G3, G5 and the stage rules, on S (fresh facts) against B (B's facts when this is the base commit), A and the round start.
435	    const current = this.model(files, library, facts);
436	    const stored = ctx.baseCommit === undefined || ctx.baseCommit === (await this.baseCommitId(shadow)) ? await this.loadBaseFacts(shadow) : undefined;
437	    const base = await this.commitModel(shadow, baseId, stored !== undefined && stored.commit === baseId ? stored.facts : undefined);
438	    const adoptCommit = await shadow.lastCommit(['adopt']);
439	    const adopted = adoptCommit !== undefined ? await this.commitModel(shadow, adoptCommit.id) : undefined;
440	    const roundStart = ctx.roundStartCommit !== undefined ? await this.commitModel(shadow, ctx.roundStartCommit) : undefined;
441	    const rules = this.core.evaluateRules({
442	      purpose,
443	      selection: ctx.selection,
444	      stage: ctx.stage,
445	      base,
446	      current,
447	      teleleanBlocks: ctx.teleleanBlocks,
448	      ...(adopted !== undefined ? { adopted } : {}),
449	      ...(roundStart !== undefined ? { roundStart } : {}),
450	      ...(ctx.freeze !== undefined ? { freeze: ctx.freeze.snapshot } : {}),
451	    });
452	    const findings = [...rules.findings];
453	    // Fail closed: a build with Lean errors never passes, even if the rules said nothing about it.
454	    if (!findings.some((f) => f.code === 'build')) findings.unshift(...buildErrorFindings(facts));
455	    const ok = findings.length === 0;
456	    if (ok) remember(this.cleanMirror, shadow.paths.runDir, filesKey(files), RUN_CACHE_SIZE);
457	    return {
458	      outcome: ok ? 'ok' : 'problems',
459	      g0: [],
460	      findings,
461	      diagnostics,
462	      build,
463	      rules,
464	      model: current,
465	      facts,
466	      durationMs: Math.round(performance.now() - started),
467	    };
468	  }
