86	async function walkTree(root: string): Promise<Walk> {
87	  const walk: Walk = { files: [], symlinks: [], irregular: [] };
88	  const stack: string[] = [''];
89	  while (stack.length > 0) {
90	    const rel = stack.pop() ?? '';
91	    const entries = await readdir(path.join(root, rel), { withFileTypes: true });
92	    for (const entry of entries) {
93	      const childRel = rel === '' ? entry.name : path.join(rel, entry.name);
94	      if (entry.isDirectory()) stack.push(childRel);
95	      else if (entry.isSymbolicLink()) walk.symlinks.push(toPosix(childRel));
96	      else if (entry.isFile()) walk.files.push(childRel);
97	      else walk.irregular.push(toPosix(childRel));
98	    }
99	  }
100	  return walk;
101	}
