47	/** Parses `lean --json` output (one JSON object per line); other lines are ignored. */
48	export function parseLeanJsonMessages(stdout: string): LeanMessage[] {
49	  const messages: LeanMessage[] = [];
50	  for (const raw of stdout.split('\n')) {
51	    const line = raw.trim();
52	    if (!line.startsWith('{')) continue;
53	    try {
54	      const m = JSON.parse(line) as {
55	        severity?: unknown;
56	        data?: unknown;
57	        pos?: { line?: unknown; column?: unknown };
58	        fileName?: unknown;
59	      };
60	      if (typeof m.severity !== 'string' || typeof m.data !== 'string') continue;
61	      messages.push({
62	        severity: m.severity,
63	        data: m.data,
64	        line: typeof m.pos?.line === 'number' ? m.pos.line : 0,
65	        column: typeof m.pos?.column === 'number' ? m.pos.column : 0,
66	        ...(typeof m.fileName === 'string' ? { fileName: m.fileName } : {}),
67	      });
68	    } catch {
69	      // not a message
70	    }
71	  }
72	  return messages;
73	}
