async function runTool<R>(
  tool: AgentToolName,
  extra: Extra,
  call: (ctx: ToolCallContext) => Promise<R>,
  render: (r: R) => string,
  meta?: (r: R) => Record<string, unknown> | undefined,
): Promise<CallToolResult> {
  activeCalls += 1;
