/**
 * What leaves the machine (docs/m2-plan.md section 5): the static system prompt (5.1, ./systemPrompt.ts), the first
 * user turn of a run (5.2, the context bundle) and the later user turns (5.3). Pure functions over the project model
 * and the board graph; the RunManager sends their results verbatim and records them in the run's transcript.
 */
import { subjectDir, subjectRootFile, type DecisionRecord, type ModelNode, type ProjectModel, type RunCaps, type TlGraph, type TlNode, type VocabItem } from '@telelean/core';

import { SYSTEM_PROMPT } from './systemPrompt.js';
import type { ContextBundleInput } from './types.js';

export { SYSTEM_PROMPT };

// ---------------------------------------------------------------------------------------------
// Small text helpers

/** Every whitespace run becomes one space (Lean wraps long values onto indented lines). */
export function collapseWhitespace(text: string): string {
  return text.replace(/\s+/g, ' ').trim();
}

const escapeRegExp = (s: string): string => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

/** Drops the subject namespace from fully-qualified names (`Spyro.GoodAddition Spyro.cynder` -> `GoodAddition cynder`). */
export function shortNames(text: string, subject: string): string {
  return text.replace(new RegExp(`(?<![A-Za-z0-9_.'!?»])${escapeRegExp(subject)}\\.`, 'gu'), '');
}

/** 1-based line of a UTF-16 offset in `text`. */
function lineOfOffset(text: string, offset: number): number {
  let line = 1;
  for (let i = 0; i < offset && i < text.length; i++) if (text.charCodeAt(i) === 10) line++;
  return line;
}

/** The budget sentence of the later turns: `<checks> Lean checks, <turns> turns, <minutes> minutes.` */
export function budgetText(caps: RunCaps): string {
  return `${caps.maxChecks} Lean checks, ${caps.maxTurns} turns, ${agentMinutes(caps)} minutes.`;
}

export function agentMinutes(caps: RunCaps): number {
  return Math.max(1, Math.round(caps.maxAgentMs / 60_000));
}

// ---------------------------------------------------------------------------------------------
// Cards and their Lean

interface StatementInfo {
  /** Fully-qualified statement name. */
  name: string;
  /** `#print` value with short names, or the source text after `:=`. */
  value: string;
  file?: string;
  /** 1-based line of the statement declaration's keyword. */
  line?: number;
}

function statementInfo(model: ProjectModel, node: TlNode, subject: string): StatementInfo | undefined {
  const name = node.lean.statement;
  if (name === undefined || node.lean.binding === 'none') return undefined;
  const entry: ModelNode | undefined = model.nodes.get(node.id);
  const decl = entry?.statementDecl;
  const facts = model.declFacts.get(name);
  let value: string | undefined = facts?.value !== undefined ? shortNames(collapseWhitespace(facts.value), subject) : undefined;
  let file: string | undefined;
  let line: number | undefined;
  if (decl !== undefined) {
    file = decl.file;
    const text = model.files.get(decl.file)?.text;
    if (text !== undefined) {
      line = lineOfOffset(text, decl.decl.keywordSpan.start);
      if (value === undefined && decl.decl.valueStart !== undefined) {
        // The source text after the top-level `:=` (the statement as written), when Lean has not checked it yet.
        const raw = text.slice(decl.decl.valueStart, decl.decl.span.end).replace(/^:=/, '');
        value = collapseWhitespace(raw);
      }
    }
  }
  return { name, value: value ?? '(not readable yet)', ...(file !== undefined ? { file } : {}), ...(line !== undefined ? { line } : {}) };
}

function blockPlace(node: TlNode): string {
  if (node.loc === undefined) return 'its block is not written yet';
  return `its block is in ${node.loc.file}, line ${node.loc.range.start.line + 1}`;
}

function targetStatus(node: TlNode): string {
  switch (node.status.proof.kind) {
    case 'proved':
      return 'Proved (re-prove from this selection).';
    case 'pending-promotion':
      return 'Promotion pending: its .holds is still an axiom.';
    default:
      return 'Not proved.';
  }
}

function premiseStatus(node: TlNode, statement: string): string {
  const holds = `${statement}.holds`;
  const proof = node.status.proof.kind;
  if (proof === 'assumed' || (node.type === 'ASSUMPTION' && node.lean.justificationKind === 'axiom')) return `assumed (axiom ${holds})`;
  if (proof === 'proved') return 'proved';
  if (proof === 'pending-promotion') return 'promotion pending';
  if (node.type === 'ASSUMPTION') return `assumed, but its axiom ${holds} is missing (add it)`;
  return 'not usable as a premise: no proof yet';
}

function quoted(sentence: string): string {
  return `"${sentence}"`;
}

// ---------------------------------------------------------------------------------------------
// The context bundle (section 5.2)

function targetLines(model: ProjectModel, node: TlNode, subject: string): string[] {
  const lines = [`- ${node.id} (${node.type}): ${quoted(node.naturalName)}`];
  const st = statementInfo(model, node, subject);
  if (st === undefined) {
    lines.push(`  No Lean yet (${blockPlace(node)}).`);
  } else {
    const where = st.file !== undefined ? ` (${st.file}${st.line !== undefined ? `, line ${st.line}` : ''})` : '';
    lines.push(`  Lean: ${st.name} := ${st.value}${where}. ${targetStatus(node)}`);
  }
  return lines;
}

function premiseLines(model: ProjectModel, node: TlNode, subject: string): string[] {
  const attrs = [node.type];
  if (node.stance !== undefined) attrs.push(`stance: ${node.stance}`);
  if (node.asserted !== undefined) attrs.push(`asserted ${node.asserted}`);
  let head = `- ${node.id} (${attrs.join(', ')}): ${quoted(node.naturalName)}`;
  if (node.rationale !== undefined && node.rationale !== '') head += ` — because: ${node.rationale}`;
  if (node.source !== undefined) head += `; source: ${node.source}`;
  const lines = [head];
  const st = statementInfo(model, node, subject);
  if (st === undefined) lines.push(`  No Lean yet (${blockPlace(node)}).`);
  else lines.push(`  Lean: ${st.name} := ${st.value}; ${premiseStatus(node, st.name)}.`);
  return lines;
}

function otherCardLine(model: ProjectModel, node: TlNode, subject: string): string {
  const st = statementInfo(model, node, subject);
  return `- ${node.id} (${node.type}): ${quoted(node.naturalName)}${st !== undefined ? ` — Lean: ${st.name} := ${st.value}` : ''}`;
}

/** The type of a vocabulary item with short names, or its source signature when Lean has not checked it. */
function vocabType(item: VocabItem, subject: string): string | undefined {
  if (item.type !== undefined) return shortNames(collapseWhitespace(item.type), subject);
  if (item.code === undefined) return undefined;
  const code = collapseWhitespace(item.code.replace(/\/--[\s\S]*?-\//g, ' '));
  const colon = code.indexOf(' : ');
  if (colon < 0) return undefined;
  const rest = code.slice(colon + 3);
  const assign = rest.indexOf(':=');
  return (assign >= 0 ? rest.slice(0, assign) : rest).trim() || undefined;
}

function vocabularyLine(item: VocabItem, subject: string): string {
  const type = vocabType(item, subject);
  const gloss = item.gloss !== undefined && item.gloss !== '' ? ` — ${collapseWhitespace(item.gloss)}` : '';
  return `- ${item.shortName}${type !== undefined ? ` : ${type}` : ''}${gloss}`;
}

function decisionLine(d: DecisionRecord): string {
  return `- [${d.phenomenon}] ${quoted(d.question)} → ${d.answerText} (${d.date.slice(0, 10)}, scope: ${d.scope})`;
}

/**
 * The cards the target and the selected premises mention in their statements (`telelean.run.contextScope =
 * neighbourhood`): sources of `lean-ref` edges into them, plus statement refs that resolve to another card.
 */
function neighbourhood(graph: TlGraph, focus: ReadonlySet<string>): Set<string> {
  const out = new Set<string>();
  for (const edge of graph.edges) {
    if (edge.type === 'lean-ref' && focus.has(edge.target) && !focus.has(edge.source)) out.add(edge.source);
  }
  for (const node of graph.nodes) {
    if (!focus.has(node.id)) continue;
    for (const ref of node.lean.refs ?? []) {
      if (ref.nodeId !== undefined && !focus.has(ref.nodeId) && ref.name === graph.nodes.find((n) => n.id === ref.nodeId)?.lean.statement) out.add(ref.nodeId);
    }
  }
  return out;
}

/** The first user turn of a run (docs/m2-plan.md section 5.2). */
export function renderContextBundle(input: ContextBundleInput): string {
  const { model, graph, library, selection, decisions, caps, scope } = input;
  const subject = selection.subject;
  const byId = new Map(graph.nodes.map((n) => [n.id, n]));
  const target = byId.get(selection.target);
  if (target === undefined) throw new TypeError(`buildContextBundle: ${selection.target} is not a card of ${subject}`);
  const premises = [...selection.premises, ...selection.adoptedGhosts];
  const premiseNodes = premises.map((id) => {
    const node = byId.get(id);
    if (node === undefined) throw new TypeError(`buildContextBundle: premise ${id} is not a card of ${subject}`);
    return node;
  });
  const focus = new Set([target.id, ...premises]);
  const near = scope === 'neighbourhood' ? neighbourhood(graph, focus) : undefined;
  const others = graph.nodes.filter((n) => !focus.has(n.id) && (near === undefined || near.has(n.id)));

  const out: string[] = [];
  out.push(
    `Run: "These suffice" for the subject ${subject} (namespace ${subject}; the subject's folder is ${subjectDir(subject, library)}/, its root module ${subjectRootFile(subject, library)}).`,
  );
  out.push('');
  out.push('TARGET');
  out.push(...targetLines(model, target, subject));
  out.push('');
  out.push('SELECTED PREMISES (prove the target from exactly these)');
  if (premiseNodes.length === 0) out.push('(none: the person asks whether the target is self-evident: provable from no premises at all.)');
  for (const node of premiseNodes) out.push(...premiseLines(model, node, subject));
  out.push('');
  out.push(
    'Allowed besides these: Lean\'s standard axioms, the vocabulary, and the existence presuppositions of the things these statements mention (for example "there is at least one character"). freeze_statements tells you the exact list.',
  );
  out.push('');
  out.push('OTHER CARDS OF THIS SUBJECT (context only; never use them as premises)');
  if (others.length === 0) out.push('(none)');
  for (const node of others) out.push(otherCardLine(model, node, subject));
  out.push('');
  out.push(`VOCABULARY (${subjectDir(subject, library)}/Vocabulary.lean and other declarations without a card)`);
  const vocabulary = graph.vocabulary.filter((v) => v.subject === subject);
  if (vocabulary.length === 0) out.push('(none)');
  for (const item of vocabulary) out.push(vocabularyLine(item, subject));
  out.push('');
  out.push('EARLIER ANSWERS IN FORCE');
  if (decisions.length === 0) out.push('(none)');
  for (const d of decisions) out.push(decisionLine(d));
  out.push('');
  out.push(
    `BUDGET: ${caps.maxChecks} Lean checks, ${caps.maxTurns} turns and ${agentMinutes(caps)} minutes of work for this run; waiting for the person's answers does not count.`,
  );
  return `${out.join('\n')}\n`;
}

// ---------------------------------------------------------------------------------------------
// Later user turns (section 5.3)

export function feedbackTurn(text: string, caps: RunCaps): string {
  return (
    `Feedback from the person on your previous result:\n"${text}"\n` +
    'This starts a new round. Your earlier changes are still in the files. If statements need to change, revise them, ' +
    'then call check_lean and freeze_statements again before proving: finish with status proved needs a freeze in this ' +
    `round. Budget for this round: ${budgetText(caps)}`
  );
}

export interface AdoptedGhostTurnInput {
  nodeId: string;
  sentence: string;
  /** Fully-qualified statement name, e.g. `Spyro.not_in_game_not_good`. */
  leanName: string;
  statement: string;
  caps: RunCaps;
}

export function adoptionTurn(g: AdoptedGhostTurnInput): string {
  return (
    `The person adopted your suggestion as an assumption:\n- ${g.nodeId} (ASSUMPTION, worded by you): ${quoted(g.sentence)}\n` +
    `  Lean: ${g.leanName} := ${g.statement}; axiom ${g.leanName}.holds (telelean wrote it right before the target's block).\n` +
    `The statements are frozen again with it selected, so you may use ${g.leanName}.holds. Prove the target now and call finish. ` +
    `Budget for this round: ${budgetText(g.caps)}`
  );
}

export function resumeTurn(frozen: boolean): string {
  return (
    "The session was interrupted (the person's editor reloaded) while you were working. Your files are as you left " +
    `them; the statements are ${frozen ? 'frozen' : 'not frozen yet'}. Continue the run from where you were.`
  );
}

export const NUDGE_TURN =
  'You ended your turn without calling finish. Call finish now: with status proved if the target is proved, otherwise with status not_proved and the gap.';

/**
 * Preflight of "These suffice" (docs/m2-plan.md section 4.1): the checks that run before anything is created,
 * declared, spawned or sent, in this order, each refusal one plain sentence:
 *   1 busy       another non-terminal run of the root
 *   2 selection  the target is a GOAL or DERIVATION card of the subject, every premise is a card of the subject,
 *                the target is not among the premises
 *   3 workspace  the ModelWorkspace implements the M2 members and the subject loads
 *   4 toolchain  lean-toolchain pins leanprover/lean4:v4.35.0 (D-7), a lakefile exists, the manifest lists no packages
 *   5 sandbox    lean.checkSandboxSupport()
 *   6 memory     MemAvailable >= the guard
 * The CLI's own checks (guard self-test, subscription login, hooks listing) come at session start, also before the
 * first prompt.
 */
import { PINNED_TOOLCHAIN_NAME, type TlGraph } from '@telelean/core';

import { checkSandboxSupport } from '../lean/runLean.js';
import { readMemAvailableBytes } from '../semantic/index.js';
import type { ModelWorkspace } from '../workspace/types.js';
import type { PreflightInput, PreflightOutcome, PreflightProblem } from './types.js';

const M2_MEMBERS = ['applyChanges', 'readText', 'modelFiles', 'library', 'projectModel', 'reloadAttempts'] as const;

const refuse = (problem: PreflightProblem, message: string): PreflightOutcome => ({ ok: false, problem, message });

function gib(bytes: number): string {
  return `${(bytes / 1024 ** 3).toFixed(1)} GB`;
}

/** The M2 members a workspace lacks (the extension's real workspace has them all). */
export function missingWorkspaceMembers(workspace: ModelWorkspace): string[] {
  return M2_MEMBERS.filter((m) => typeof (workspace as unknown as Record<string, unknown>)[m] !== 'function');
}

async function readProjectFile(input: PreflightInput, rel: string): Promise<string | null> {
  const read = input.workspace.readText;
  if (typeof read !== 'function') return null;
  try {
    return await read.call(input.workspace, rel);
  } catch {
    return null;
  }
}

function selectionProblem(input: PreflightInput, graph: TlGraph): string | undefined {
  const { target, premises, subject } = input.request;
  const byId = new Map(graph.nodes.map((n) => [n.id, n]));
  const t = byId.get(target);
  if (t === undefined) return `The target "${target}" is not a card of ${subject}.`;
  if (t.type === 'ASSUMPTION') {
    return `"${t.naturalName}" is an Assumption, something you hold: make it a Derivation first (D-11), then prove it.`;
  }
  for (const p of premises) {
    if (p === target) return `The target "${t.naturalName}" cannot also be one of its own premises.`;
    if (!byId.has(p)) return `The premise "${p}" is not a card of ${subject}.`;
  }
  return undefined;
}

async function toolchainProblem(input: PreflightInput): Promise<string | undefined> {
  const toolchain = (await readProjectFile(input, 'lean-toolchain'))?.trim();
  if (toolchain === undefined) return 'lean-toolchain is missing, so Lean cannot check this model folder.';
  if (toolchain !== PINNED_TOOLCHAIN_NAME) {
    return `lean-toolchain pins ${JSON.stringify(toolchain)}; telelean runs Claude only on ${PINNED_TOOLCHAIN_NAME} (D-7).`;
  }
  const lakefile = (await readProjectFile(input, 'lakefile.toml')) ?? (await readProjectFile(input, 'lakefile.lean'));
  if (lakefile === null) return 'the model folder has no lakefile.toml or lakefile.lean.';
  const manifest = await readProjectFile(input, 'lake-manifest.json');
  if (manifest === null) return 'lake-manifest.json is missing (the sandbox keeps the model folder read-only, so Lake cannot write one).';
  let packages: unknown;
  try {
    packages = (JSON.parse(manifest) as { packages?: unknown }).packages;
  } catch (e) {
    return `lake-manifest.json is not valid JSON: ${(e as Error).message}.`;
  }
  if (!Array.isArray(packages)) return 'lake-manifest.json has no "packages" list.';
  if (packages.length > 0) {
    const names = packages.map((p: unknown) => (typeof p === 'object' && p !== null && typeof (p as { name?: unknown }).name === 'string' ? (p as { name: string }).name : '?'));
    return `this project has Lake dependencies (${names.join(', ')}); runs support only dependency-free models (Mathlib needs an explicit opt-in, M4).`;
  }
  return undefined;
}

/** The checks of docs/m2-plan.md section 4.1 before anything is created or spent (auth and hooks come at session start). */
export async function preflight(input: PreflightInput): Promise<PreflightOutcome> {
  // 1. busy
  if (input.activeRunId !== undefined) {
    return refuse('busy', `Another Claude run of this model folder is still active (${input.activeRunId}): finish, Discard or Cancel it first.`);
  }
  // 2. selection (needs the subject's board) and 3. workspace
  let graph: TlGraph;
  try {
    graph = input.workspace.graph(input.request.subject);
  } catch (e) {
    return refuse('workspace', `The subject ${input.request.subject} could not be loaded: ${(e as Error).message}`);
  }
  const selection = selectionProblem(input, graph);
  if (selection !== undefined) return refuse('selection', selection);
  const missing = missingWorkspaceMembers(input.workspace);
  if (missing.length > 0) return refuse('workspace', `This workspace cannot run Claude yet (it lacks ${missing.join(', ')}).`);
  // 4. toolchain
  const toolchain = await toolchainProblem(input);
  if (toolchain !== undefined) return refuse('toolchain', toolchain.charAt(0).toUpperCase() + toolchain.slice(1));
  // 5. sandbox
  const sandbox = await (input.checkSandbox ?? (() => checkSandboxSupport()))();
  if (sandbox !== undefined) return refuse('sandbox', `Lean's sandbox is not available, so telelean cannot check Claude's work: ${sandbox}.`);
  // 6. memory
  const available = (input.readMemAvailable ?? readMemAvailableBytes)();
  if (available !== undefined && available < input.settings.minAvailableBytes) {
    return refuse(
      'memory',
      `Only ${gib(available)} of memory is available (telelean needs ${gib(input.settings.minAvailableBytes)} free to run Lean safely): close something and try again.`,
    );
  }
  return { ok: true };
}

/**
 * The Claude backend factory (amendment A1; docs/m2-plan.md section 8.4): resolves the user's own Claude Code binary
 * (setting -> newest VS Code Claude Code extension binary -> PATH -> ~/.local/bin; `--version` >= 2.1.295) and builds
 * the ClaudeCliBackend with an explicit guard script path, the hook runtime, the client app and the
 * `setpriv --pdeathsig KILL --` launcher (absolute path), so a SIGKILLed extension host takes the CLI down.
 * Contacts nothing but `claude --version`.
 */
import { accessSync, constants } from 'node:fs';

import { findSystemExecutable } from '../lean/systemd.js';
import { resolveClaudeBinary, type ResolveBinaryOptions, type ResolvedBinary } from '../llm/binary.js';
import { ClaudeCliBackend, NO_REAL_CLAUDE_ENV, realClaudeDisabled, type ClaudeCliBackendOptions } from '../llm/claudeCli.js';
import { defaultHookRuntime } from '../llm/confinement.js';
import { LlmHarnessError } from '../llm/types.js';
import type { ClaudeBackendSettings } from './types.js';

/** The launcher prefix: `<abs setpriv> --pdeathsig KILL -- <claude> …`. */
export const PDEATHSIG_ARGS: readonly string[] = ['--pdeathsig', 'KILL', '--'];

/** The absolute path of util-linux `setpriv`, checked to be executable. */
export function setprivLauncher(): { command: string; args: string[] } {
  const command = findSystemExecutable('setpriv');
  try {
    accessSync(command, constants.X_OK);
  } catch {
    throw new LlmHarnessError('binary', `setpriv (util-linux) was not found at ${command}; telelean needs it to tie the Claude CLI to the editor's lifetime.`);
  }
  return { command, args: [...PDEATHSIG_ARGS] };
}

export async function createClaudeBackendImpl(settings: ClaudeBackendSettings): Promise<{ backend: ClaudeCliBackend; binary: ResolvedBinary }> {
  // Quota tripwire: before resolving anything (not even `--version`), unless a test supplies fake binaries.
  if (realClaudeDisabled() && settings.resolve === undefined) {
    throw new LlmHarnessError('process', `real Claude is disabled here (${NO_REAL_CLAUDE_ENV}=1): no Claude binary was looked up or run.`);
  }
  if (typeof settings.guardScriptPath !== 'string' || settings.guardScriptPath === '') {
    throw new TypeError('createClaudeBackend needs the absolute path of telelean-path-guard.mjs (guardScriptPath)');
  }
  const resolveOptions: ResolveBinaryOptions = { ...(settings.resolve ?? {}) };
  if (settings.claudePath !== undefined && settings.claudePath.trim() !== '') resolveOptions.explicitPath = settings.claudePath.trim();
  if (settings.extensionDirs !== undefined) resolveOptions.extensionDirs = settings.extensionDirs;
  const binary = await resolveClaudeBinary(resolveOptions);
  const options: ClaudeCliBackendOptions = {
    binary: { path: binary.path, version: binary.version },
    guardScriptPath: settings.guardScriptPath,
    hookRuntime: settings.hookRuntime ?? defaultHookRuntime(),
    clientApp: settings.clientApp,
  };
  if (settings.pdeathsig ?? true) options.launcher = setprivLauncher();
  return { backend: new ClaudeCliBackend(options), binary };
}

/**
 * Persistence of runs (docs/m2-plan.md section 4.6): `run.json` (PersistedRun) rewritten atomically after every state
 * change (a temp file in the run directory, then rename), `session/transcript.jsonl` appended with every user turn,
 * event, tool call and result and state change ("exact texts saved", 03 section 14), and the scan of a root's run
 * directories for recovery.
 */
import { renameSync, writeFileSync } from 'node:fs';
import { appendFile, mkdir, readdir, readFile, rename, rm, writeFile } from 'node:fs/promises';
import path from 'node:path';

import { isTerminalRunState, type RunState } from '@telelean/core';

import { rootKeyOf } from '../shadow/index.js';
import { PERSISTED_RUN_FORMAT, type PersistedRun } from './types.js';

let tempCounter = 0;

/** Atomic replace: write a temp file next to `file`, then rename it over `file`. */
export async function writeJsonAtomic(file: string, value: unknown): Promise<void> {
  const text = `${JSON.stringify(value, null, 1)}\n`;
  await writeTextAtomic(file, text);
}

export async function writeTextAtomic(file: string, text: string): Promise<void> {
  await mkdir(path.dirname(file), { recursive: true });
  const temp = `${file}.tmp-${process.pid}-${++tempCounter}`;
  try {
    await writeFile(temp, text, { encoding: 'utf8', mode: 0o600 });
    await rename(temp, file);
  } catch (error) {
    await rm(temp, { force: true }).catch(() => undefined);
    throw error;
  }
}

/** The same, synchronously (dispose(): the window may be closing). */
export function writeTextAtomicSync(file: string, text: string): void {
  const temp = `${file}.tmp-${process.pid}-${++tempCounter}`;
  writeFileSync(temp, text, { encoding: 'utf8', mode: 0o600 });
  renameSync(temp, file);
}

export function isPersistedRun(value: unknown): value is PersistedRun {
  if (typeof value !== 'object' || value === null) return false;
  const v = value as Partial<PersistedRun>;
  return v.format === PERSISTED_RUN_FORMAT && v.version === 1 && typeof v.view === 'object' && v.view !== null && typeof v.view.runId === 'string';
}

export async function readPersistedRun(file: string): Promise<PersistedRun | undefined> {
  try {
    const parsed: unknown = JSON.parse(await readFile(file, 'utf8'));
    return isPersistedRun(parsed) ? parsed : undefined;
  } catch {
    return undefined;
  }
}

export interface ScannedRun {
  runDir: string;
  stateFile: string;
  run: PersistedRun;
}

/** The run directories of `root` under `runsDir` whose run.json is readable, newest first (by `view.updatedAt`). */
export async function scanRuns(runsDir: string, root: string): Promise<ScannedRun[]> {
  const base = path.join(runsDir, rootKeyOf(root));
  let entries: string[];
  try {
    entries = await readdir(base);
  } catch {
    return [];
  }
  const out: ScannedRun[] = [];
  for (const name of entries) {
    const runDir = path.join(base, name);
    const stateFile = path.join(runDir, 'run.json');
    const run = await readPersistedRun(stateFile);
    if (run !== undefined && path.resolve(run.root) === path.resolve(root)) out.push({ runDir, stateFile, run });
  }
  const time = (r: ScannedRun): number => Date.parse(r.run.view.updatedAt) || Date.parse(r.run.view.startedAt) || 0;
  return out.sort((a, b) => time(b) - time(a));
}

export function nonTerminal(state: RunState): boolean {
  return !isTerminalRunState(state);
}

/**
 * Serialised writes of one run's files: `run.json` snapshots (each write takes the text captured when it was
 * queued, so the file always holds a state the run really passed through) and transcript lines (in order).
 */
export class RunFiles {
  private chain: Promise<unknown> = Promise.resolve();
  private failed = false;

  constructor(
    readonly stateFile: string,
    readonly transcriptFile: string,
    private readonly log: (message: string) => void,
  ) {}

  /** Queues an atomic write of `text` to run.json; resolves when it (and everything queued before) is written. */
  writeState(text: string): Promise<void> {
    return this.enqueue(() => writeTextAtomic(this.stateFile, text));
  }

  writeStateSync(text: string): void {
    try {
      writeTextAtomicSync(this.stateFile, text);
    } catch (e) {
      this.log(`run.json could not be written: ${(e as Error).message}`);
    }
  }

  /** Queues one transcript line (JSON). */
  transcript(entry: Record<string, unknown>): Promise<void> {
    const line = `${JSON.stringify(entry)}\n`;
    return this.enqueue(async () => {
      await mkdir(path.dirname(this.transcriptFile), { recursive: true });
      await appendFile(this.transcriptFile, line, { encoding: 'utf8', mode: 0o600 });
    });
  }

  /** Resolves once every queued write has finished. */
  flush(): Promise<void> {
    return this.chain.then(() => undefined);
  }

  private enqueue(job: () => Promise<void>): Promise<void> {
    const run = this.chain.then(job, job).catch((e: unknown) => {
      if (!this.failed) this.log(`a run file could not be written: ${(e as Error).message}`);
      this.failed = true;
    });
    this.chain = run;
    return run;
  }
}

