/**
 * Scratch space and timers for the run tests (WP3). Every scratch tree lives under `$TELELEAN_TEST_TMP` (default a
 * fresh directory in the OS temp dir); git never reads the user's configuration nor looks above the scratch tree.
 * Importing this module captures the REAL timers first, so helpers can wait for events with a real timeout while a
 * test runs under vitest's fake timers.
 */
import { mkdirSync, mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

export const realSetTimeout: typeof setTimeout = globalThis.setTimeout.bind(globalThis);
export const realClearTimeout: typeof clearTimeout = globalThis.clearTimeout.bind(globalThis);
export const realSetImmediate: typeof setImmediate = globalThis.setImmediate.bind(globalThis);

export const REPO_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../../../..');
export const MENTAL_MODEL = path.join(REPO_ROOT, 'mental_model');
export const SPYRO_FIXTURE = path.join(REPO_ROOT, 'test-fixtures', 'spyro');
export const WALKTHROUGH_FIXTURES = path.join(REPO_ROOT, 'test-fixtures', 'walkthrough');
export const SPYRO_FACTS = path.join(REPO_ROOT, 'test-fixtures', 'semantic', 'recorded', 'spyro-facts.json');

export const SCRATCH = ((): string => {
  const base = process.env['TELELEAN_TEST_TMP'] ?? mkdtempSync(path.join(tmpdir(), 'telelean-run-tests-'));
  mkdirSync(base, { recursive: true });
  return path.resolve(base);
})();

process.env['GIT_CONFIG_GLOBAL'] = '/dev/null';
process.env['GIT_CONFIG_NOSYSTEM'] = '1';
process.env['GIT_CEILING_DIRECTORIES'] = SCRATCH;

export function makeTempDir(label: string): string {
  return mkdtempSync(path.join(SCRATCH, `run-${label}-`));
}

export function cleanup(dir: string | undefined): void {
  if (dir === undefined || process.env['TELELEAN_KEEP_TMP'] === '1') return;
  rmSync(dir, { recursive: true, force: true });
}

/** Lets pending I/O callbacks and microtasks run (setImmediate is never faked by these tests). */
export function flushIo(times = 3): Promise<void> {
  let p = Promise.resolve();
  for (let i = 0; i < times; i++) p = p.then(() => new Promise<void>((r) => realSetImmediate(r)));
  return p;
}

/** The timers vitest fakes in these tests (never setImmediate or nextTick, which fs and the fakes rely on). */
export const FAKE_TIMERS = { toFake: ['setTimeout', 'clearTimeout', 'setInterval', 'clearInterval', 'Date'] as const };

/**
 * A disk-backed stand-in for WP2's ShadowWorkspace, for the RunManager's own tests while `createRunShadow` is a
 * stub: the same directory layout (`<runsDir>/<rootKey>/<runId>/{ws,build,git,session,...}`), real files in ws/ (the
 * FakeBackend edits them through the path guard), and commits kept as whole-file snapshots in `git/commits.json`
 * (so `openFakeShadow` re-opens a run after a "reload"). No git, no Lean.
 */
import { createHash } from 'node:crypto';
import { lstat, mkdir, readdir, readFile, rm, writeFile } from 'node:fs/promises';
import path from 'node:path';

import type { FileChange } from '@telelean/core';

import { rootKeyOf } from '../../../src/shadow/index.js';
import {
  PASSING_COMMIT_KINDS,
  ShadowLayoutError,
  type CreateShadowOptions,
  type ShadowCommit,
  type ShadowCommitKind,
  type ShadowPaths,
  type ShadowWorkspace,
} from '../../../src/shadow/types.js';

interface StoredCommit extends ShadowCommit {
  files: Record<string, string>;
}

function pathsOf(runDir: string): ShadowPaths {
  return {
    runDir,
    ws: path.join(runDir, 'ws'),
    build: path.join(runDir, 'build'),
    gitDir: path.join(runDir, 'git'),
    sessionDir: path.join(runDir, 'session'),
    frozenDir: path.join(runDir, 'frozen'),
    gateDir: path.join(runDir, 'gate'),
    scratchDir: path.join(runDir, 'scratch'),
    stateFile: path.join(runDir, 'run.json'),
  };
}

async function walk(dir: string, rel = ''): Promise<string[]> {
  const out: string[] = [];
  let entries;
  try {
    entries = await readdir(path.join(dir, rel), { withFileTypes: true });
  } catch {
    return out;
  }
  for (const e of entries) {
    const child = rel === '' ? e.name : `${rel}/${e.name}`;
    if (e.name.startsWith('.')) throw new ShadowLayoutError('hidden-entry', `a hidden entry appeared in the working copy: ${child}`, [child]);
    if (e.isSymbolicLink()) throw new ShadowLayoutError('not-regular', `a symlink appeared in the working copy: ${child}`, [child]);
    if (e.isDirectory()) out.push(...(await walk(dir, child)));
    else if (e.isFile()) out.push(child);
    else throw new ShadowLayoutError('not-regular', `not a regular file: ${child}`, [child]);
  }
  return out;
}

export class FakeShadow implements ShadowWorkspace {
  readonly paths: ShadowPaths;
  private stored: StoredCommit[] = [];
  private seq = 0;
  /** Every method call, in order (tests assert on them). */
  readonly log: string[] = [];

  constructor(
    readonly runId: string,
    readonly root: string,
    readonly library: string,
    runDir: string,
    private readonly now: () => Date,
  ) {
    this.paths = pathsOf(runDir);
  }

  private get commitsFile(): string {
    return path.join(this.paths.gitDir, 'commits.json');
  }

  async load(): Promise<void> {
    this.stored = JSON.parse(await readFile(this.commitsFile, 'utf8')) as StoredCommit[];
    this.seq = this.stored.length;
  }

  private async persist(): Promise<void> {
    await writeFile(this.commitsFile, JSON.stringify(this.stored));
  }

  async baseFiles(): Promise<Map<string, string>> {
    return new Map(Object.entries(this.stored[0]?.files ?? {}));
  }

  async currentFiles(): Promise<Map<string, string>> {
    const out = new Map<string, string>();
    for (const rel of (await walk(this.paths.ws)).sort()) out.set(rel, await readFile(path.join(this.paths.ws, rel), 'utf8'));
    return out;
  }

  async changes(from?: string): Promise<FileChange[]> {
    const base = from === undefined ? await this.baseFiles() : await this.filesAt(from);
    const now = await this.currentFiles();
    const out: FileChange[] = [];
    for (const rel of [...new Set([...base.keys(), ...now.keys()])].sort()) {
      const before = base.get(rel) ?? null;
      const after = now.get(rel) ?? null;
      if (before !== after) out.push({ path: rel, before, after });
    }
    return out;
  }

  async syncMirror(): Promise<{ copied: string[]; removed: string[] }> {
    this.log.push('syncMirror');
    return { copied: [], removed: [] };
  }

  async writeFiles(changes: readonly FileChange[]): Promise<void> {
    this.log.push(`writeFiles:${changes.map((c) => c.path).join(',')}`);
    const now = await this.currentFiles();
    for (const c of changes) {
      if ((now.get(c.path) ?? null) !== c.before) throw new ShadowLayoutError('io', `${c.path} changed since the edit was planned`, [c.path]);
    }
    for (const c of changes) {
      const abs = path.join(this.paths.ws, c.path);
      if (c.after === null) await rm(abs, { force: true });
      else {
        await mkdir(path.dirname(abs), { recursive: true });
        await writeFile(abs, c.after);
      }
    }
  }

  async commit(kind: ShadowCommitKind, label: string, round: number): Promise<ShadowCommit> {
    this.seq += 1;
    const files = Object.fromEntries(await this.currentFiles());
    const id = createHash('sha1').update(`${this.runId}:${this.seq}:${kind}`).digest('hex');
    const c: StoredCommit = { id, kind, label, round, at: this.now().toISOString(), files };
    this.stored.push(c);
    this.log.push(`commit:${kind}`);
    await this.persist();
    const { files: _files, ...commit } = c;
    return commit;
  }

  async commits(): Promise<ShadowCommit[]> {
    return this.stored.map(({ files: _files, ...c }) => c);
  }

  async lastCommit(kinds: readonly ShadowCommitKind[] = PASSING_COMMIT_KINDS): Promise<ShadowCommit | undefined> {
    for (let i = this.stored.length - 1; i >= 0; i--) {
      const c = this.stored[i];
      if (c !== undefined && kinds.includes(c.kind)) {
        const { files: _files, ...commit } = c;
        return commit;
      }
    }
    return undefined;
  }

  async filesAt(commitId: string): Promise<Map<string, string>> {
    const c = this.stored.find((x) => x.id === commitId);
    if (c === undefined) throw new ShadowLayoutError('git', `unknown commit ${commitId}`);
    return new Map(Object.entries(c.files));
  }

  async revertTo(commitId: string, label: string, round: number): Promise<FileChange[]> {
    const target = await this.filesAt(commitId);
    const now = await this.currentFiles();
    const changes: FileChange[] = [];
    for (const rel of [...new Set([...target.keys(), ...now.keys()])].sort()) {
      const before = now.get(rel) ?? null;
      const after = target.get(rel) ?? null;
      if (before !== after) changes.push({ path: rel, before, after });
    }
    this.log.push(`revertTo:${commitId.slice(0, 8)}:${changes.length}`);
    if (changes.length === 0) return [];
    await this.writeFiles(changes);
    await this.commit('revert', label, round);
    return changes;
  }

  /** Test convenience: the kinds of every commit, oldest first. */
  kinds(): ShadowCommitKind[] {
    return this.stored.map((c) => c.kind);
  }
}

/** Registry of the shadows the fakes created, so a test can reach the one a RunManager made. */
export const createdShadows: FakeShadow[] = [];

export async function createFakeShadow(options: CreateShadowOptions): Promise<FakeShadow> {
  const runDir = path.join(options.runsDir, rootKeyOf(options.root), options.runId);
  try {
    await lstat(runDir);
    throw new ShadowLayoutError('io', `the run directory exists already: ${runDir}`);
  } catch (e) {
    if (e instanceof ShadowLayoutError) throw e;
  }
  const shadow = new FakeShadow(options.runId, options.root, options.library, runDir, options.now ?? (() => new Date()));
  for (const dir of Object.values(shadow.paths)) if (!dir.endsWith('.json')) await mkdir(dir, { recursive: true });
  for (const [rel, text] of options.files) {
    if (rel.startsWith('.') || rel.includes('/.')) throw new ShadowLayoutError('bad-path', `not a model file: ${rel}`, [rel]);
    const abs = path.join(shadow.paths.ws, rel);
    await mkdir(path.dirname(abs), { recursive: true });
    await writeFile(abs, text);
  }
  await shadow.commit('base', 'Your files at the start of the run', 1);
  createdShadows.push(shadow);
  return shadow;
}

export async function openFakeShadow(runDir: string, options: { root: string; library: string }): Promise<FakeShadow> {
  const shadow = new FakeShadow(path.basename(runDir), options.root, options.library, runDir, () => new Date());
  await shadow.load();
  createdShadows.push(shadow);
  return shadow;
}

/**
 * A scriptable LeanCheckEngine for the RunManager's tests (WP2's real engine is a stub until integration). Each
 * method records its call (with the context fields the RunManager is responsible for) and answers from a handler the
 * test may replace; the defaults behave like the real engine on an honest run:
 *   checkBase/check  ok (no findings)
 *   freeze           commits `freeze` and returns a record with the 13-name Spyro permitted set
 *   normalise        no changes
 *   gate             judges a `checkpoint` commit (GateReport.commit); `not-frozen` for finish(proved) without a freeze
 *   checkGhost       ok, statement collapsed, aloneEntails false
 *   renderStatements pretty/explicit placeholders
 */
import type { FileChange, GateFinding, PermittedAxioms } from '@telelean/core';

import type {
  CheckContext,
  CheckReport,
  FreezeOutcome,
  FreezeRecord,
  GateReport,
  GhostCheck,
  GhostCheckInput,
  LeanCheckEngine,
  RenderedStatement,
} from '../../../src/gate/types.js';
import type { FinishStatus } from '../../../src/llm/types.js';
import type { ShadowCommit } from '../../../src/shadow/types.js';

export const SPYRO_PERMITTED: PermittedAxioms = {
  standard: ['propext', 'Classical.choice', 'Quot.sound'],
  signature: ['Spyro.Character', 'Spyro.Game', 'Spyro.HasDarkPast', 'Spyro.IsPG', 'Spyro.GoodAddition'],
  selected: ['Spyro.cynder_dark_past.holds', 'Spyro.new_spyro_pg.holds', 'Spyro.pg_no_dark_past.holds'],
  presuppositions: ['Spyro.Character.exists', 'Spyro.Game.exists'],
  derivationFootprints: [],
  unusable: [],
  all: [
    'Classical.choice',
    'Quot.sound',
    'Spyro.Character',
    'Spyro.Character.exists',
    'Spyro.Game',
    'Spyro.Game.exists',
    'Spyro.GoodAddition',
    'Spyro.HasDarkPast',
    'Spyro.IsPG',
    'Spyro.cynder_dark_past.holds',
    'Spyro.new_spyro_pg.holds',
    'Spyro.pg_no_dark_past.holds',
    'propext',
  ],
};

/** What a call looked like from the RunManager's side. */
export interface EngineCall {
  method: 'checkBase' | 'check' | 'freeze' | 'normalise' | 'gate' | 'checkGhost' | 'renderStatements';
  round?: number;
  stage?: string;
  frozen?: boolean;
  freezeRound?: number;
  baseCommit?: string;
  roundStartCommit?: string;
  adoptedGhosts?: string[];
  teleleanBlocks?: string[];
  status?: FinishStatus;
  files?: string[];
  runId?: string;
  leanJobMs?: number;
  names?: string[];
  ghost?: GhostCheckInput;
}

export function okReport(extra: Partial<CheckReport> = {}): CheckReport {
  return { outcome: 'ok', g0: [], findings: [], diagnostics: [], durationMs: 1, build: { status: 'ok', durationMs: 1, errorCount: 0 }, ...extra };
}

export function finding(code: GateFinding['code'], message: string, extra: Partial<GateFinding> = {}): GateFinding {
  const step: GateFinding['step'] = code === 'build' || code === 'budget' ? 'G1' : code === 'markup' ? 'G5' : code.startsWith('comparator-') ? 'G4' : ['hash-command', 'sorry', 'set-option', 'import', 'bad-path'].includes(code) ? 'G0' : 'G3';
  return { step, code, message, ...extra };
}

type Handler<A extends unknown[], R> = (...args: A) => R | Promise<R>;

export class FakeEngine implements LeanCheckEngine {
  readonly calls: EngineCall[] = [];
  gateCalls = 0;
  checkCalls = 0;

  onCheckBase: Handler<[CheckContext], CheckReport> = () => okReport();
  onCheck: Handler<[CheckContext, number], CheckReport> = () => okReport();
  onFreeze: Handler<[CheckContext], FreezeOutcome | undefined> = () => undefined;
  onNormalise: Handler<[CheckContext], { changes: FileChange[]; commit?: ShadowCommit }> = () => ({ changes: [] });
  /** Return the findings of this gate call (default: none, or `not-frozen` for finish(proved) without a freeze). */
  onGate: Handler<[CheckContext & { status: FinishStatus }, number], Partial<GateReport> | undefined> = () => undefined;
  onCheckGhost: Handler<[CheckContext, GhostCheckInput], GhostCheck | undefined> = () => undefined;

  private record(method: EngineCall['method'], ctx: Partial<CheckContext>, extra: Partial<EngineCall> = {}): void {
    const call: EngineCall = { method, ...extra };
    if (ctx.round !== undefined) call.round = ctx.round;
    if (ctx.stage !== undefined) call.stage = ctx.stage;
    call.frozen = ctx.freeze !== undefined;
    if (ctx.freeze !== undefined) call.freezeRound = ctx.freeze.round;
    if (ctx.baseCommit !== undefined) call.baseCommit = ctx.baseCommit;
    if (ctx.roundStartCommit !== undefined) call.roundStartCommit = ctx.roundStartCommit;
    if (ctx.selection !== undefined) call.adoptedGhosts = [...ctx.selection.adoptedGhosts];
    if (ctx.teleleanBlocks !== undefined) call.teleleanBlocks = [...ctx.teleleanBlocks];
    if (ctx.files !== undefined) call.files = [...ctx.files];
    if (ctx.job !== undefined) {
      call.runId = ctx.job.runId;
      call.leanJobMs = ctx.job.leanJobMs;
    }
    this.calls.push(call);
  }

  methods(): string[] {
    return this.calls.map((c) => c.method);
  }

  async normalise(ctx: CheckContext): Promise<{ changes: FileChange[]; commit?: ShadowCommit }> {
    this.record('normalise', ctx);
    return this.onNormalise(ctx);
  }

  async checkBase(ctx: CheckContext): Promise<CheckReport> {
    this.record('checkBase', ctx);
    return this.onCheckBase(ctx);
  }

  async check(ctx: CheckContext): Promise<CheckReport> {
    this.record('check', ctx);
    this.checkCalls += 1;
    return this.onCheck(ctx, this.checkCalls);
  }

  async freeze(ctx: CheckContext): Promise<FreezeOutcome> {
    this.record('freeze', ctx);
    const custom = await this.onFreeze(ctx);
    if (custom !== undefined) return custom;
    const commit = await ctx.shadow.commit('freeze', `Statements frozen (round ${ctx.round})`, ctx.round);
    const record: FreezeRecord = {
      round: ctx.round,
      commit,
      at: new Date().toISOString(),
      selection: ctx.selection,
      snapshot: { round: ctx.round, permitted: SPYRO_PERMITTED, targetStatement: 'Spyro.cynder_not_good', declarations: {}, axioms: [] },
      freeze: { exportPath: '', challengeModule: 'Model.TeleleanChallenge', theoremNames: ['Spyro.cynder_not_good.holds'], permittedAxioms: SPYRO_PERMITTED.all, definitionNames: [] },
    };
    return { ok: true, record, report: okReport() };
  }

  async gate(ctx: CheckContext & { status: FinishStatus }): Promise<GateReport> {
    this.record('gate', ctx, { status: ctx.status });
    this.gateCalls += 1;
    const custom = (await this.onGate(ctx, this.gateCalls)) ?? {};
    let findings = custom.findings;
    if (findings === undefined) findings = ctx.status === 'proved' && ctx.freeze === undefined ? [finding('not-frozen', 'finish(proved) needs a successful freeze_statements in this round')] : [];
    if (custom.environment !== undefined) {
      return { passed: false, environment: custom.environment, findings: [], flaggedDefinitions: [], check: okReport({ outcome: 'environment', environment: custom.environment }), durationMs: 1 };
    }
    const commit = await ctx.shadow.commit('checkpoint', `Judged state (round ${ctx.round})`, ctx.round);
    return {
      passed: findings.length === 0,
      findings,
      flaggedDefinitions: custom.flaggedDefinitions ?? [],
      check: custom.check ?? okReport(findings.length > 0 ? { outcome: 'problems', findings } : {}),
      durationMs: 1,
      commit,
      ...(custom.footprint !== undefined ? { footprint: custom.footprint } : {}),
    };
  }

  async checkGhost(ctx: CheckContext, ghost: GhostCheckInput): Promise<GhostCheck> {
    this.record('checkGhost', ctx, { ghost });
    const custom = await this.onCheckGhost(ctx, ghost);
    if (custom !== undefined) return custom;
    return { ok: true, footprint: ['Spyro.pg_no_dark_past.holds'], aloneEntails: false, statement: ghost.leanStatement.replace(/\s+/g, ' ').trim() };
  }

  async renderStatements(ctx: Pick<CheckContext, 'shadow' | 'job'>, names: readonly string[]): Promise<RenderedStatement[]> {
    this.record('renderStatements', ctx, { names: [...names] });
    return names.map((name) => ({ name, pretty: `pretty ${name}`, explicit: `explicit ${name}` }));
  }
}

/**
 * Fakes for the RunManager's other collaborators (WP3 tests): the proposal service and sidecar store (WP4's are stubs
 * until integration), and an in-memory ModelWorkspace built from the Spyro fixture with core's real (M1) parser,
 * project model, board graph and planner, plus the recorded Spyro Lean facts, so the context bundle and
 * `set-premises` behave as on the real board.
 */
import { createHash } from 'node:crypto';
import { readdirSync, readFileSync, statSync } from 'node:fs';
import path from 'node:path';

import {
  buildProjectModel,
  parseLeanFile,
  planAction,
  subjectGraph,
  type ActionOutcome,
  type AttemptRecord,
  type AttemptResolution,
  type AttemptSummary,
  type BoardAction,
  type DecisionRecord,
  type DecisionsFile,
  type FileChange,
  type LeanFacts,
  type ProjectModel,
  type ProposalView,
  type TlGraph,
} from '@telelean/core';

import type { AcceptPlan, AcceptRequest, ProposalBuildInput, ProposalService, ReadRealText, RunSidecarStore } from '../../../src/proposal/types.js';
import type { ShadowWorkspace } from '../../../src/shadow/types.js';
import type { ExternalChangeSet, ModelWorkspace, WorkspaceChange } from '../../../src/workspace/types.js';
import { SPYRO_FACTS, SPYRO_FIXTURE } from './env.js';

// ---------------------------------------------------------------------------------------------
// Proposals

export interface RecordedBuild {
  input: ProposalBuildInput;
  /** ws/ at the moment the proposal was built. */
  files: Map<string, string>;
}

export class FakeProposals implements ProposalService {
  readonly builds: RecordedBuild[] = [];
  readonly plans: AcceptRequest[] = [];
  readonly applied: Array<Extract<AcceptPlan, { ok: true }>> = [];
  drift: string[] = [];
  definitions: ProposalView['definitions'] = [];
  /** Replaces the default plan (ok, no changes). */
  onPlan?: (request: AcceptRequest, call: number) => AcceptPlan | Promise<AcceptPlan>;
  applyOutcome: ActionOutcome | undefined;
  readonly log: string[];

  constructor(log: string[] = []) {
    this.log = log;
  }

  async build(input: ProposalBuildInput): Promise<ProposalView> {
    this.log.push('proposals.build');
    this.builds.push({ input, files: await input.shadow.currentFiles() });
    const target = input.selection.target;
    return {
      runId: input.runId,
      proposalId: input.proposalId,
      round: input.round,
      subject: input.selection.subject,
      graph: input.currentGraph,
      diff: { nodes: {}, vocabulary: {}, edges: { added: [], removed: [] }, counts: { added: 0, changed: 0, removed: 0, vocabularyAdded: 0 } },
      files: [],
      review: [],
      definitions: this.definitions,
      lifecycle:
        input.verdict === 'proved'
          ? [{ id: 'l1', kind: 'change-kind', nodeId: target, from: 'GOAL', to: 'DERIVATION', recommended: true, reason: 'Lean proved it from the selected premises' }]
          : [],
      ghosts: [...input.ghosts],
      report: {
        verdict: input.verdict,
        target,
        footprint: input.verdict === 'proved' ? ['cynder-dark-past', 'new-spyro-pg', 'pg-no-dark-past'] : [],
        unusedPremises: [],
        consistency: 'unchecked',
        selfEvident: false,
        ...(input.finish !== undefined ? { claudeSummary: input.finish.summary } : {}),
        assumedWithoutAsking: input.finish?.assumed_without_asking ?? [],
        gateAttempts: [...input.gateAttempts],
        usage: input.usage,
        durationMs: input.durationMs,
        agentMs: input.agentMs,
        ...(input.reverted !== undefined ? { reverted: input.reverted } : {}),
      },
      baseChanged: input.drift.length > 0,
      empty: false,
    };
  }

  async baseDrift(_shadow: ShadowWorkspace, _readReal: ReadRealText, _realFiles?: readonly string[]): Promise<string[]> {
    this.log.push('proposals.baseDrift');
    return [...this.drift];
  }

  async planAccept(request: AcceptRequest): Promise<AcceptPlan> {
    this.log.push(`proposals.planAccept${request.shownState !== undefined ? '(shownState)' : ''}`);
    this.plans.push(request);
    if (this.onPlan !== undefined) return this.onPlan(request, this.plans.length);
    const shadowState = request.shownState !== undefined ? new Map(request.shownState) : await request.shadow.currentFiles();
    return { ok: true, changes: [], label: 'These suffice → proved: Cynder would not be a good addition to the new…', nodes: [request.proposal.report.target], drift: [...this.drift], shadowState };
  }

  async apply(plan: Extract<AcceptPlan, { ok: true }>, workspace: ModelWorkspace, subject: string): Promise<ActionOutcome> {
    this.log.push('proposals.apply');
    this.applied.push(plan);
    if (this.applyOutcome !== undefined) return this.applyOutcome;
    if (workspace.applyChanges !== undefined && plan.changes.length > 0) {
      return workspace.applyChanges({ label: plan.label, action: 'accept-proposal', subject, nodes: plan.nodes, changes: plan.changes });
    }
    return { ok: true, label: plan.label, undoable: true };
  }

  async diffFiles(shadow: ShadowWorkspace): Promise<FileChange[]> {
    return shadow.changes();
  }
}

