/**
 * Wires a RunManager to the fakes (WP3 tests): FakeBackend (M0, extended) behind a tracking wrapper, FakeEngine,
 * FakeProposals, FakeSidecars, FakeWorkspace (Spyro fixture + recorded facts), FakeShadow, the real preflight with
 * sandbox/memory hooks, and fake core texts (WP1's functions are stubs until integration).
 */
import { mkdirSync, readFileSync } from 'node:fs';
import path from 'node:path';

import type { DecisionsFile, GateFinding, RunCaps, RunView } from '@telelean/core';

import { FakeBackend, type FakeScript, type FakeStep } from '../../../src/llm/fake.js';
import { playFakeScript, validateFakeScriptFile, type FakeScriptFile, type FakeScriptPlayer, type FakeScriptTurn } from '../../../src/llm/fakeScripts.js';
import type { AskUserArgs, LlmBackend, LlmSession, SessionConfig } from '../../../src/llm/types.js';
import { createRunManager, DEFAULT_RUN_SETTINGS, runPreflight } from '../../../src/run/index.js';
import type { PreflightInput, PreflightOutcome, RunCore, RunManager, RunServices, RunSettings } from '../../../src/run/types.js';
import { cleanup, makeTempDir, realClearTimeout, realSetTimeout, WALKTHROUGH_FIXTURES } from './env.js';
import { FakeEngine } from './fakeEngine.js';
import { FakeProposals, FakeSidecars, FakeWorkspace } from './fakeServices.js';
import { createFakeShadow, openFakeShadow, type FakeShadow } from './fakeShadow.js';

export const TARGET = 'cynder-not-good';
export const ALL_PREMISES = ['cynder-dark-past', 'new-spyro-pg', 'pg-no-dark-past'];

/** A FakeBackend that records every session config and every close. */
export class TrackingBackend implements LlmBackend {
  readonly id = 'fake' as const;
  readonly caps;
  readonly configs: SessionConfig[] = [];
  readonly sessions: LlmSession[] = [];
  readonly closes: Array<{ force?: boolean }> = [];
  readonly interrupts: number[] = [];
  readonly inner: FakeBackend;

  constructor(script: FakeScript) {
    this.inner = new FakeBackend(script);
    this.caps = this.inner.caps;
  }

  async startSession(cfg: SessionConfig): Promise<LlmSession> {
    this.configs.push(cfg);
    const session = await this.inner.startSession(cfg);
    const close = session.close.bind(session);
    const interrupt = session.interrupt.bind(session);
    session.close = async (opts?: { force?: boolean }) => {
      this.closes.push(opts ?? {});
      return close(opts);
    };
    session.interrupt = async () => {
      this.interrupts.push(this.sessions.indexOf(session));
      return interrupt();
    };
    this.sessions.push(session);
    return session;
  }
}

/** Fake core texts (WP1's are stubs here): recognisable, and they record their calls. */
export function fakeCore(calls: string[] = []): Partial<RunCore> & { calls: string[] } {
  return {
    calls,
    attemptNotice: (findings: readonly GateFinding[], attempt: number, max: number, _ctx, revertedTo?: string) => {
      calls.push(`attemptNotice:${attempt}/${max}`);
      return attempt >= max ? `FAKE gave up after ${max}: ${findings[0]?.code ?? '-'}; reverted to ${revertedTo ?? '?'}` : `FAKE attempt ${attempt}: ${findings[0]?.code ?? '-'}`;
    },
    describeFinding: (f: GateFinding) => `described ${f.code}`,
    proposalLabel: () => 'FAKE label',
    decisionsInForce: (file: DecisionsFile, subject: string) => file.decisions.filter((d) => d.subject === subject && d.scope === 'subject'),
  };
}

export interface HarnessOptions {
  script?: FakeScript | FakeScriptTurn[];
  backend?: RunServices['backend'];
  caps?: Partial<RunCaps>;
  settings?: Partial<RunSettings>;
  now?: () => Date;
  core?: Partial<RunCore>;
  preflight?: (input: PreflightInput) => Promise<PreflightOutcome>;
  withFacts?: boolean;
  /** Share the root and runs dir of an earlier harness (recovery tests). */
  reuse?: { dir: string; root: string; runsDir: string; workspace?: FakeWorkspace };
  log?: string[];
  cancelLean?: (runId: string) => Promise<unknown>;
}

export interface Harness {
  manager: RunManager;
  engine: FakeEngine;
  proposals: FakeProposals;
  sidecars: FakeSidecars;
  workspace: FakeWorkspace;
  backend: TrackingBackend | undefined;
  player: FakeScriptPlayer | undefined;
  dir: string;
  root: string;
  runsDir: string;
  log: string[];
  coreCalls: string[];
  cancelled: string[];
  /** Every `run` change, as `current()` returned it right then. */
  views: RunView[];
  shadows: FakeShadow[];
  shadow(): FakeShadow;
  dispose(): void;
}

export function makeHarness(options: HarnessOptions = {}): Harness {
  const dir = options.reuse?.dir ?? makeTempDir('mgr');
  const root = options.reuse?.root ?? path.join(dir, 'model');
  const runsDir = options.reuse?.runsDir ?? path.join(dir, 'runs');
  mkdirSync(root, { recursive: true });
  const log = options.log ?? [];
  const workspace = options.reuse?.workspace ?? new FakeWorkspace(root, { withFacts: options.withFacts ?? true, log });
  const engine = new FakeEngine();
  const proposals = new FakeProposals(log);
  const sidecars = new FakeSidecars();
  let player: FakeScriptPlayer | undefined;
  let backend: TrackingBackend | undefined;
  if (options.backend === undefined) {
    const script = options.script ?? [];
    let fakeScript: FakeScript;
    if (Array.isArray(script) && (script.length === 0 || !Array.isArray(script[0]))) {
      player = playFakeScript(script as FakeScriptTurn[]);
      fakeScript = player.script;
    } else fakeScript = script as FakeScript;
    backend = new TrackingBackend(fakeScript);
  }
  const shadows: FakeShadow[] = [];
  const coreCalls: string[] = [];
  const cancelled: string[] = [];
  const settings: RunSettings = {
    ...DEFAULT_RUN_SETTINGS,
    ...options.settings,
    caps: { ...DEFAULT_RUN_SETTINGS.caps, ...options.settings?.caps, ...options.caps },
  };
  const services: RunServices = {
    backend: options.backend ?? (backend as TrackingBackend),
    core: options.core ?? fakeCore(coreCalls),
    engine,
    proposals,
    sidecars,
    createShadow: async (o) => {
      log.push('createShadow');
      const s = await createFakeShadow(o);
      shadows.push(s);
      return s;
    },
    openShadow: async (runDir, o) => {
      const s = await openFakeShadow(runDir, o);
      shadows.push(s);
      return s;
    },
    preflight:
      options.preflight ??
      ((input) => runPreflight({ ...input, checkSandbox: async () => undefined, readMemAvailable: () => 32 * 1024 ** 3 })),
    cancelLean:
      options.cancelLean ??
      (async (runId) => {
        cancelled.push(runId);
      }),
    log: () => undefined,
    ...(options.now !== undefined ? { now: options.now } : {}),
  };
  const manager = createRunManager({ root, runsDir, workspace, services, settings });
  const views: RunView[] = [];
  manager.onDidChange((c) => {
    if (c.run) {
      const v = manager.current();
      if (v !== null) views.push(v);
    }
  });
  return {
    manager,
    engine,
    proposals,
    sidecars,
    workspace,
    backend,
    player,
    dir,
    root,
    runsDir,
    log,
    coreCalls,
    cancelled,
    views,
    shadows,
    shadow: () => {
      const s = shadows.at(-1);
      if (s === undefined) throw new Error('no shadow was created');
      return s;
    },
    dispose: () => {
      manager.dispose();
      if (options.reuse === undefined && process.env['TELELEAN_KEEP_TMP'] !== '1') cleanup(dir);
    },
  };
}

/** Resolves with the first view (now or after a change) that satisfies `predicate`; rejects after `timeoutMs` (real time). */
export function waitForRun(manager: RunManager, predicate: (view: RunView) => boolean, timeoutMs = 15_000, what = 'the run state'): Promise<RunView> {
  return new Promise((resolve, reject) => {
    const check = (): boolean => {
      const v = manager.current();
      if (v !== null && predicate(v)) {
        done();
        resolve(v);
        return true;
      }
      return false;
    };
    const sub = manager.onDidChange(() => void check());
    const timer = realSetTimeout(() => {
      sub.dispose();
      reject(new Error(`timed out waiting for ${what}; last view: ${JSON.stringify(manager.current()?.state)} ${JSON.stringify(manager.current()?.notices.map((n) => n.text))}`));
    }, timeoutMs);
    const done = (): void => {
      realClearTimeout(timer);
      sub.dispose();
    };
    check();
  });
}

export const state =
  (...states: RunView['state'][]) =>
  (v: RunView): boolean =>
    states.includes(v.state);

/** The reading-A question of docs/m2-plan.md section 10.2. */
export const ASK_MODALITY: AskUserArgs = {
  questions: [
    {
      phenomenon: 'modality',
      question: 'Does "cannot have" state a rule about what PG games should not include (normative), or that a PG game is unable to contain such a character (literal)?',
      options: [
        { label: 'A rule (normative)', consequence: 'A PG game with such a character breaks the rule; it says nothing about what the game contains.' },
        { label: 'Impossible (literal)', consequence: 'No PG game contains a character with a dark past at all.' },
      ],
      claudesGuess: { option: 0, note: 'rating rules are norms' },
      affectedNodes: ['pg-no-dark-past', 'no-such-card'],
    },
  ],
};

export const step = {
  usage: (messageId: string, inputTokens = 100, outputTokens = 10): FakeStep => ({ kind: 'usage', messageId, usage: { inputTokens, outputTokens, cacheReadInputTokens: 1000, cacheCreationInputTokens: 50 } }),
  ask: (args: AskUserArgs = ASK_MODALITY): FakeStep => ({ kind: 'callTool', tool: 'ask_user', args }),
  check: (files?: string[]): FakeStep => ({ kind: 'callTool', tool: 'check_lean', args: files === undefined ? {} : { files } }),
  freeze: (target = TARGET): FakeStep => ({ kind: 'callTool', tool: 'freeze_statements', args: { targets: [target] } }),
  finish: (status: 'proved' | 'not_proved' = 'proved', summary = 'Done.'): FakeStep => ({ kind: 'callTool', tool: 'finish', args: { status, summary, assumed_without_asking: [] } }),
  edit: (oldString: string, newString: string, file = 'Model/Spyro/Main.lean'): FakeStep => ({ kind: 'edit', path: file, oldString, newString }),
  text: (text: string): FakeStep => ({ kind: 'text', text }),
  result: (costEstimateUsd?: number): FakeStep => ({ kind: 'result', ...(costEstimateUsd !== undefined ? { costEstimateUsd } : {}) }),
  propose: (extra: Record<string, unknown> = {}): FakeStep => ({
    kind: 'callTool',
    tool: 'propose_assumption',
    args: {
      natural_name: 'A character who cannot be in a game would not be a good addition to it',
      lean_statement: '∀ (c : Character) (g : Game),\n   ¬ InGame c g → ¬ GoodAddition c g',
      why_needed: 'Nothing links being in a game to being a good addition to it.',
      proof: 'fun h => h cynder newSpyro (pg_no_dark_past.holds newSpyro cynder new_spyro_pg.holds cynder_dark_past.holds)',
      lean_name: 'not_in_game_not_good',
      ...extra,
    },
  }),
};

/** One turn matched to the round-1 context bundle. */
export function round1(...steps: FakeStep[]): FakeScriptTurn {
  return { match: 'Run: "These suffice"', steps };
}

export function loadWalkthrough(name: string): FakeScriptFile & Record<string, unknown> {
  return validateFakeScriptFile(JSON.parse(readFileSync(path.join(WALKTHROUGH_FIXTURES, `${name}.json`), 'utf8'))) as FakeScriptFile & Record<string, unknown>;
}

export const START = { subject: 'Spyro', target: TARGET, premises: ALL_PREMISES };

export function readJson<T = unknown>(file: string): T {
  return JSON.parse(readFileSync(file, 'utf8')) as T;
}

/**
 * AT3.1 (docs/m2-plan.md section 9, WP3): the happy path with fakes (engine, proposals, sidecars, core) and the
 * FakeBackend: start -> working -> ask_user -> waiting-for-answer (clock paused) -> answer (decision recorded, guess
 * revealed) -> freeze -> finish -> gate pass -> review with a proposal; change events in order; run.json at every
 * step; usage summed from usage events; the cost estimate is the latest result's value (0.01, then 0.03 -> 0.03).
 */
import { existsSync, readFileSync } from 'node:fs';
import path from 'node:path';

import { afterEach, describe, expect, it } from 'vitest';

import type { PersistedRun } from '../../src/run/types.js';
import { ALL_PREMISES, makeHarness, readJson, round1, START, state, step, waitForRun, type Harness } from './helpers/harness.js';

const A3_OLD = 'stance: rule\nasserted: 2026-11-01\n-/\n\n';
const A3_NEW =
  'stance: rule\nasserted: 2026-11-01\n-/\n/-- PG games cannot have characters with dark pasts -/\nabbrev pg_no_dark_past : Prop := ∀ (g : Game) (c : Character), IsPG g → HasDarkPast c → ¬ GoodAddition c g\naxiom pg_no_dark_past.holds : pg_no_dark_past\n\n';
const TARGET_LINE = 'abbrev cynder_not_good : Prop := ¬ GoodAddition cynder newSpyro\n';
const PROOF = 'theorem cynder_not_good.holds : cynder_not_good :=\n  pg_no_dark_past.holds newSpyro cynder new_spyro_pg.holds cynder_dark_past.holds\n';

let h: Harness | undefined;
afterEach(() => {
  h?.dispose();
  h = undefined;
});

/** Collapses consecutive repeats. */
function runs<T>(xs: readonly T[]): T[] {
  return xs.filter((x, i) => i === 0 || xs[i - 1] !== x);
}

describe('RunManager happy path (AT3.1)', () => {
  it('runs a round from start to review, records the answer and reveals the guess only afterwards', async () => {
    let clock = Date.parse('2026-11-01T10:00:00.000Z');
    const advance = (ms: number) => {
      clock += ms;
    };
    h = makeHarness({
      now: () => new Date(clock),
      script: [
        round1(
          step.usage('m1', 100, 10),
          step.text('Reading the subject first.'),
          { kind: 'read', path: 'Model/Spyro/Main.lean' },
          step.ask(),
          step.usage('m2', 120, 20),
          step.edit(A3_OLD, A3_NEW),
          step.check(),
          step.freeze(),
          step.edit(TARGET_LINE, TARGET_LINE + PROOF),
          step.check(['Model/Spyro/Main.lean']),
          step.finish('proved', 'Proved from the three premises under the normative reading.'),
          step.result(0.01),
        ),
        {
          match: 'Feedback from the person',
          steps: [step.usage('m3', 50, 5), step.freeze(), step.finish('proved', 'Re-proved after the feedback.'), step.result(0.03)],
        },
      ],
    });
    const { manager, sidecars, engine, proposals } = h;
    // run.json as it was at every change event (the file is written before the event fires).
    const fileStates: string[] = [];
    manager.onDidChange(() => {
      const v = manager.current();
      if (v === null) return;
      const file = path.join(h?.runsDir ?? '', ...[]);
      void file;
      const stateFile = h?.shadows.at(-1)?.paths.stateFile;
      if (stateFile !== undefined && existsSync(stateFile)) fileStates.push(readJson<PersistedRun>(stateFile).view.state);
    });

    const started = await manager.start(START);
    expect(started).toMatchObject({ ok: true });
    expect(h.workspace.performed).toEqual([]); // the declared premises are already these three

    const waiting = await waitForRun(manager, state('waiting-for-answer'));
    // D-20: no guess before the answer, unknown affected nodes dropped.
    expect(JSON.stringify(waiting)).not.toContain('claudesGuess');
    expect(JSON.stringify(waiting)).not.toContain('rating rules are norms');
    expect(waiting.pendingQuestions?.questions[0]).toMatchObject({ index: 0, phenomenon: 'modality', affectedNodes: ['pg-no-dark-past'] });
    expect(waiting.pendingQuestions?.questions[0]?.options.map((o) => o.label)).toEqual(['A rule (normative)', 'Impossible (literal)']);
    const persisted = readJson<PersistedRun>(h.shadow().paths.stateFile);
    expect(persisted.view.state).toBe('waiting-for-answer');
    expect(persisted.pendingAsk?.args.questions[0]?.claudesGuess).toEqual({ option: 0, note: 'rating rules are norms' });
    expect(JSON.stringify(persisted.view)).not.toContain('claudesGuess');

    // The agent-active clock is paused while the question waits.
    const agentBefore = manager.current()?.counters.agentMs ?? -1;
    advance(10 * 60_000);
    expect(manager.current()?.counters.agentMs).toBe(agentBefore);

    const setId = waiting.pendingQuestions?.id ?? '';
    expect(setId).toBe('q1');
    const answered = await manager.answer(waiting.runId, setId, [{ question: 0, choice: { kind: 'option', option: 0 }, scope: 'subject' }]);
    expect(answered).toMatchObject({ ok: true });
    expect(sidecars.decisions).toHaveLength(1);
    expect(sidecars.decisions[0]).toMatchObject({
      id: `${waiting.runId}.q1.0`,
      run: waiting.runId,
      subject: 'Spyro',
      phenomenon: 'modality',
      answer: { kind: 'option', option: 0 },
      answerText: 'A rule (normative)',
      scope: 'subject',
      affectedNodes: ['pg-no-dark-past'],
      decidedBy: 'user',
      wordedBy: 'agent',
      claudesGuess: { option: 0, note: 'rating rules are norms' },
    });
    const afterAnswer = manager.current();
    expect(afterAnswer?.pendingQuestions).toBeUndefined();
    expect(afterAnswer?.answered[0]).toMatchObject({ setId: 'q1', claudesGuess: { option: 0, note: 'rating rules are norms' }, answer: { question: 0, scope: 'subject' } });

    const review = await waitForRun(manager, state('review'));
    expect(review.verdict).toBe('proved');
    expect(review.round).toBe(1);
    expect(review.stage).toBe('prove');
    expect(review.frozen?.round).toBe(1);
    expect(review.frozen?.permitted.selected).toEqual(['Spyro.cynder_dark_past.holds', 'Spyro.new_spyro_pg.holds', 'Spyro.pg_no_dark_past.holds']);
    expect(review.counters).toMatchObject({ checks: 3, gateAttempts: 1, turns: 2 });
    expect(review.proposalId).toBe('p1');
    expect(manager.proposal()).toMatchObject({ proposalId: 'p1', runId: review.runId, report: { verdict: 'proved' } });
    // Claude's words in the activity feed, telelean's checks too.
    expect(review.activity.some((a) => a.kind === 'claude-text' && a.text === 'Reading the subject first.')).toBe(true);
    expect(review.activity.filter((a) => a.kind === 'check').length).toBe(2);

    // The engine saw the run's context: base check first, a freeze in round 1, then normalise + gate(proved).
    expect(engine.methods()).toEqual(['checkBase', 'check', 'freeze', 'check', 'normalise', 'gate']);
    expect(engine.calls.find((c) => c.method === 'gate')).toMatchObject({ status: 'proved', frozen: true, freezeRound: 1, stage: 'prove', runId: review.runId, leanJobMs: 120_000 });
    expect(engine.calls.filter((c) => c.method === 'check')[1]?.files).toEqual(['Model/Spyro/Main.lean']);
    // The proposal was built from the gate-pass files (the formalisation and the proof).
    const built = proposals.builds[0];
    expect(built?.input.verdict).toBe('proved');
    expect(built?.files.get('Model/Spyro/Main.lean')).toContain('theorem cynder_not_good.holds');
    expect(built?.input.selection).toEqual({ subject: 'Spyro', target: 'cynder-not-good', premises: ALL_PREMISES, adoptedGhosts: [] });
    expect(h.shadow().kinds()).toEqual(['base', 'freeze', 'checkpoint', 'gate-pass']);

    // Usage: two API responses, summed; the cost estimate is the result's figure.
    expect(review.usage).toMatchObject({ requests: 2, inputTokens: 220, outputTokens: 30, cacheReadInputTokens: 2000, cacheCreationInputTokens: 100, costEstimateUsd: 0.01 });
    // attempts.jsonl got the round.
    expect(sidecars.attempts).toHaveLength(1);
    expect(sidecars.attempts[0]).toMatchObject({ id: `${review.runId}.1`, round: 1, verdict: 'proved', premises: ALL_PREMISES, gateAttempts: 1, model: 'claude-opus-5-5', summary: 'Proved from the three premises under the normative reading.' });
    expect(h.workspace.reloaded).toContain('Spyro');

    // State changes, in order (and run.json said the same at each step).
    const states = runs(h.views.map((v) => v.state));
    expect(states).toEqual(['starting', 'working', 'waiting-for-answer', 'working', 'gate', 'working', 'review']);
    expect(runs(fileStates)).toEqual(states);

    // Feedback: round 2 resets the counters; the cost estimate becomes the latest result's 0.03 (never a sum).
    const fb = await manager.feedback(review.runId, 'Please re-check with the same premises.');
    expect(fb).toMatchObject({ ok: true });
    const r2 = await waitForRun(manager, (v) => v.state === 'review' && v.round === 2);
    expect(r2.usage.costEstimateUsd).toBe(0.03);
    expect(r2.usage.requests).toBe(3);
    expect(r2.counters).toMatchObject({ turns: 1, checks: 1, gateAttempts: 1 });
    expect(r2.proposalId).toBe('p2');
    expect(sidecars.resolutions).toEqual([expect.objectContaining({ round: 1, resolution: 'superseded' })]);
    expect(sidecars.attempts.map((a) => a.round)).toEqual([1, 2]);
    // The feedback reached Claude as a user turn, with the budget.
    expect(h.player?.played.map((p) => p.scripted)).toEqual([0, 1]);
    expect(h.player?.played[1]?.turn).toContain('Feedback from the person on your previous result:\n"Please re-check with the same premises."');
    expect(h.player?.played[1]?.turn).toContain('Budget for this round: 25 Lean checks, 80 turns, 20 minutes.');
    // Only one session: Feedback continues it.
    expect(h.backend?.sessions).toHaveLength(1);

    // The transcript holds every user turn verbatim.
    const transcript = readFileSync(path.join(h.shadow().paths.sessionDir, 'transcript.jsonl'), 'utf8');
    expect(transcript).toContain('"kind":"turn"');
    expect(transcript).toContain('Run: \\"These suffice\\" for the subject Spyro');
    expect(transcript).toContain('"kind":"tool-call","tool":"finish"');
  });

  it('sends the context bundle and the static system prompt to the session', async () => {
    h = makeHarness({ script: [round1(step.result())] });
    await h.manager.start(START);
    await waitForRun(h.manager, (v) => v.state === 'review' || v.state === 'working');
    const cfg = h.backend?.configs[0];
    expect(cfg?.systemPrompt.startsWith('You are the formalisation assistant of telelean.')).toBe(true);
    expect(cfg?.cwd).toBe(h.shadow().paths.ws);
    expect(cfg?.runDir).toBe(h.shadow().paths.sessionDir);
    expect(cfg?.maxTurns).toBe(80);
    expect(cfg?.model).toBe('claude-opus-5-5');
    expect(cfg?.effort).toBe('high');
    expect(cfg?.sessionId).toMatch(/^[0-9a-f-]{36}$/);
    expect(h.player?.played[0]?.turn.startsWith('Run: "These suffice" for the subject Spyro (namespace Spyro;')).toBe(true);
  });
});

