  expect((await postedOfType(page, 'kindChange')).map((m) => m.payload)).toEqual([
    { id: 'cynder-dark-past', from: 'ASSUMPTION', to: 'GOAL', beforeId: null, requestId: 'r1', dependents: 'rewrite' },
  ]);
});

