/**
 * Claude's words (D-15): italic, with a marker, never in the user's style. Every string the run UI shows that Claude
 * wrote (its messages, questions and options, suggestions, summaries, glosses) goes through this component, so it
 * carries `data-provenance="agent"` (test/e2e/m2-provenance.spec.ts checks that no agent text renders without it).
 *
 * `marker`: where the marker goes. `prefix` puts a small "Claude" label before the text (activity lines, questions);
 * `suffix` adds "(Claude's words)" after it (sentences and glosses, like the cards' "(Claude's wording)"); `none`
 * only inside a container that shows the marker once for all of its Claude texts (`data-agent-scope`: a question
 * card under "Claude asks", a "Claude suggests" card).
 */
export interface AgentTextProps {
  text: string;
  marker?: 'prefix' | 'suffix' | 'none';
  /** The marker's text (default "Claude" before, "(Claude's words)" after). */
  label?: string;
  className?: string;
  /** Block-level (a paragraph) instead of inline. */
  block?: boolean;
  testId?: string;
}

export function AgentText({ text, marker = 'suffix', label, className, block, testId }: AgentTextProps) {
  const Tag = block ? 'p' : 'span';
  const markerText = label ?? (marker === 'prefix' ? 'Claude' : "(Claude's words)");
  return (
    <Tag className={`tl-agent${block ? ' tl-agent--block' : ''}${className ? ` ${className}` : ''}`} data-provenance="agent" data-testid={testId}>
      {marker === 'prefix' ? <span className="tl-agent__marker tl-agent__marker--prefix">{markerText}</span> : null}
      <span className="tl-agent__text">{text}</span>
      {marker === 'suffix' ? <span className="tl-agent__marker tl-agent__marker--suffix"> {markerText}</span> : null}
    </Tag>
  );
}

/** The user's own words (their sentences, their free-text answers): plain, as on the cards. */
export function UserText({ text, className }: { text: string; className?: string }) {
  return (
    <span className={`tl-user${className ? ` ${className}` : ''}`} data-provenance="user">
      {text}
    </span>
  );
}

import { useEffect, useState } from 'react';

/** The current time (ms), refreshed every `intervalMs` while `active`: for clocks that run between host updates. */
export function useNow(active: boolean, intervalMs = 1000): number {
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    if (!active) return;
    setNow(Date.now());
    const timer = setInterval(() => setNow(Date.now()), intervalMs);
    return () => clearInterval(timer);
  }, [active, intervalMs]);
  return now;
}

/**
 * Claude's clarifying questions (ask_user, D-20), answered in place so the A|D|G box keeps working (D-16):
 *  - each question carries its phenomenon tag, Claude's options with their plain consequences, and the board's own
 *    choices: free text ("In my own words"), "Leave it open" (keep it uninterpreted; recorded) and "Decide for me"
 *    (an explicit delegation);
 *  - no answer is pre-selected, and Claude's guess is not on the board before the answer (the host never sends it:
 *    `QuestionView` has no guess); after the answer it is shown with the answered questions;
 *  - the scope of each answer: this run (default), these cards, or the whole subject.
 * One "Send" posts `answerQuestions` for the whole batch (every question exactly once).
 */
import { DECISION_SCOPES, LIMITS, type AnsweredQuestionView, type QuestionSetView, type QuestionView, type RunView } from '@telelean/core';
import { useMemo } from 'react';
import { AgentText, UserText } from '../common/AgentText';
import { PHENOMENON_LABEL } from '../labels';
import { formatTime } from '../model/format';
import { answerChoiceText, draftAnswers, draftProblem, emptyDraft, SCOPE_LABEL, type AnswerDraft } from '../model/run';
import { useBoard, useBoardActions } from '../state/context';

function Phenomenon({ question }: { question: Pick<QuestionView, 'phenomenon'> }) {
  return (
    <span className="tl-phenomenon" data-testid="phenomenon" data-phenomenon={question.phenomenon} title="What kind of reading question this is (D-20)">
      {PHENOMENON_LABEL[question.phenomenon]}
    </span>
  );
}

/** The cards an answer affects, by their sentences (the user's words). */
function Affected({ ids }: { ids: readonly string[] }) {
  const nodes = useBoard((s) => s.nodes);
  const present = ids.filter((id) => nodes[id]);
  if (present.length === 0) return null;
  return (
    <p className="tl-question__about" data-testid="question-about">
      About{' '}
      {present.map((id, i) => (
        <span key={id}>
          {i > 0 ? ', ' : null}“<UserText text={nodes[id]?.naturalName ?? id} />”
        </span>
      ))}
    </p>
  );
}

function QuestionCard({ setId, question, index, draft, disabled }: { setId: string; question: QuestionView; index: number; draft: AnswerDraft; disabled: boolean }) {
  const actions = useBoardActions();
  const name = `tl-q-${setId}-${question.index}`;
  const choose = (patch: Partial<AnswerDraft>) => actions.setAnswerDraft(setId, index, patch);
  const own = (kind: 'free-text' | 'leave-open' | 'decide-for-me', label: string, note: string) => (
    <label className="tl-option tl-option--own" data-testid={`option-${kind}`} data-selected={draft.kind === kind || undefined}>
      <input type="radio" name={name} checked={draft.kind === kind} onChange={() => choose({ kind, option: null })} />
      <span className="tl-option__body">
        <span className="tl-option__label">{label}</span>
        <span className="tl-option__note">{note}</span>
      </span>
    </label>
  );
  return (
    <fieldset className="tl-question" data-testid="question" data-index={question.index} disabled={disabled} data-agent-scope>
      <legend className="tl-question__head">
        <Phenomenon question={question} />
        <AgentText text={question.question} marker="prefix" label="Claude asks" className="tl-question__text" testId="question-text" />
      </legend>
      <Affected ids={question.affectedNodes} />
      <div className="tl-question__options" role="radiogroup" aria-label="Your answer">
        {question.options.map((option, i) => (
          <label key={i} className="tl-option" data-testid="option" data-selected={(draft.kind === 'option' && draft.option === i) || undefined}>
            <input type="radio" name={name} checked={draft.kind === 'option' && draft.option === i} onChange={() => choose({ kind: 'option', option: i })} />
            <span className="tl-option__body">
              <AgentText text={option.label} marker="none" className="tl-option__label" testId="option-label" />
              <AgentText text={option.consequence} marker="none" className="tl-option__consequence" testId="option-consequence" />
              {option.formalPreview ? <code className="tl-option__preview">{option.formalPreview}</code> : null}
            </span>
          </label>
        ))}
        {own('free-text', 'In my own words', 'write how you mean it')}
        {draft.kind === 'free-text' ? (
          <textarea
            className="tl-input tl-question__free"
            data-testid="free-text"
            aria-label="Your answer in your own words"
            placeholder="How do you mean it?"
            rows={3}
            maxLength={LIMITS.textLength}
            value={draft.text}
            onChange={(event) => choose({ text: event.target.value })}
          />
        ) : null}
        {own('leave-open', 'Leave it open', 'keep it uninterpreted (recorded as your choice)')}
        {own('decide-for-me', 'Decide for me', 'Claude chooses and lists its choice under “assumed without asking”')}
      </div>
      <div className="tl-question__scope" role="radiogroup" aria-label="Remember the answer for" data-testid="question-scope">
        <span className="tl-question__scope-label">Remember for:</span>
        {DECISION_SCOPES.map((scope) => (
          <label key={scope} className="tl-scope" data-scope={scope}>
            <input
              type="radio"
              name={`${name}-scope`}
              checked={draft.scope === scope}
              disabled={scope === 'nodes' && question.affectedNodes.length === 0}
              onChange={() => choose({ scope })}
            />
            {SCOPE_LABEL[scope]}
          </label>
        ))}
      </div>
    </fieldset>
  );
}

/** The pending ask_user batch (1-3 questions). */
export function QuestionSet({ run, set }: { run: RunView; set: QuestionSetView }) {
  const stored = useBoard((s) => s.answerDrafts[set.id]);
  const sending = useBoard((s) => s.runBusy?.action === 'answer' && s.runBusy.key === set.id);
  const actions = useBoardActions();
  const drafts = useMemo(() => set.questions.map((_, i) => stored?.[i] ?? emptyDraft()), [set.questions, stored]);
  const ready = draftAnswers(set.questions, drafts) !== null;
  const many = set.questions.length > 1;
  const problem = set.questions.map((q, i) => draftProblem(q, drafts[i])).find((p) => p !== null) ?? null;
  return (
    <section className="tl-run__section tl-questions" data-testid="question-set" data-set-id={set.id} aria-label="Claude's questions">
      <h3 className="tl-run__heading">
        <span className="codicon codicon-question" aria-hidden="true" /> {many ? `${set.questions.length} questions for you` : 'A question for you'}
        <span className="tl-run__time">{formatTime(set.askedAt)}</span>
      </h3>
      <p className="tl-run__hint">Claude waits for your answer; its working time is paused meanwhile.</p>
      {set.questions.map((question, i) => (
        <QuestionCard key={question.index} setId={set.id} question={question} index={i} draft={drafts[i] ?? emptyDraft()} disabled={sending || run.state !== 'waiting-for-answer'} />
      ))}
      <div className="tl-questions__actions">
        <button type="button" className="tl-button" data-testid="send-answers" disabled={!ready || sending || run.state !== 'waiting-for-answer'} onClick={() => actions.submitAnswers()}>
          {sending ? 'Sending…' : many ? 'Send answers' : 'Send answer'}
        </button>
        {!ready && problem ? <span className="tl-run__hint">{many ? 'Answer every question to send.' : problem}</span> : null}
      </div>
    </section>
  );
}

/** How an answer reads: Claude's option label (Claude's words), the user's free text (theirs), or the board's choice. */
function AnswerValue({ question }: { question: AnsweredQuestionView }) {
  const choice = question.answer.choice;
  if (choice.kind === 'free-text') return <UserText text={choice.text} className="tl-answered__free" />;
  if (choice.kind === 'option') return <AgentText text={answerChoiceText(choice, question)} marker="none" />;
  return <span>{answerChoiceText(choice, question)}</span>;
}

function AnsweredItem({ question }: { question: AnsweredQuestionView }) {
  const guess = question.claudesGuess;
  const guessLabel = guess?.option !== undefined ? question.options[guess.option]?.label : undefined;
  return (
    <div className="tl-answered" data-testid="answered-question" data-set-id={question.setId} data-index={question.index} data-agent-scope>
      <div className="tl-answered__head">
        <Phenomenon question={question} />
        <AgentText text={question.question} marker="prefix" label="Claude asked" />
      </div>
      <p className="tl-answered__line" data-testid="your-answer">
        <span className="tl-answered__label">Your answer:</span> <AnswerValue question={question} />{' '}
        <span className="tl-answered__scope">(for {SCOPE_LABEL[question.answer.scope]})</span>
      </p>
      <p className="tl-answered__line" data-testid="claudes-guess">
        <span className="tl-answered__label">Claude’s guess:</span>{' '}
        {guess && (guessLabel || guess.note) ? (
          <>
            {guessLabel ? <AgentText text={guessLabel} marker="none" /> : null}
            {guessLabel && guess.note ? ' · ' : null}
            {guess.note ? <AgentText text={guess.note} marker="none" /> : null}
          </>
        ) : (
          <span className="tl-run__hint">none given</span>
        )}
      </p>
    </div>
  );
}

/** Every answered question of the run, newest batch first (its guesses revealed, D-20). */
export function AnsweredQuestions({ answered }: { answered: readonly AnsweredQuestionView[] }) {
  const groups = useMemo(() => {
    const bySet = new Map<string, AnsweredQuestionView[]>();
    for (const question of answered) bySet.set(question.setId, [...(bySet.get(question.setId) ?? []), question]);
    return [...bySet.values()].reverse();
  }, [answered]);
  if (groups.length === 0) return null;
  const [latest, ...older] = groups;
  return (
    <section className="tl-run__section" data-testid="answered" aria-label="Your answers">
      <h3 className="tl-run__heading">Your answers</h3>
      {(latest ?? []).map((question) => (
        <AnsweredItem key={`${question.setId}-${question.index}`} question={question} />
      ))}
      {older.length > 0 ? (
        <details className="tl-run__more">
          <summary>Earlier answers ({older.reduce((n, g) => n + g.length, 0)})</summary>
          {older.flat().map((question) => (
            <AnsweredItem key={`${question.setId}-${question.index}`} question={question} />
          ))}
        </details>
      ) : null}
    </section>
  );
}

/**
 * The report card of a round (03 section 7; revealed after the statements, D-19): the verdict for the target, what
 * the proof rests on (cards, presuppositions, anything else), unused premises and the self-evident flag (G6, never
 * failures), "consistency unchecked" (D-6, until M3), Claude's summary, gap, conflict and every interpretive choice it
 * made without asking, each with "Ask me instead" (D-20: prefilled Feedback), Claude's suggested premises, the gate
 * attempts (A2), the changed files with their raw diff, usage and durations.
 */
import { PRESUPPOSITION_PREFIX, type ProposalView, type TlNode } from '@telelean/core';
import { useMemo } from 'react';
import { AgentText, UserText } from '../common/AgentText';
import { InlineCode } from '../common/InlineCode';
import { KIND_GLYPH } from '../labels';
import { footprintEntries, presuppositionLabel, vocabIndex } from '../model/cardData';
import { formatCost, formatDuration, formatTokens, suggestedGhosts, VERDICT_LABEL } from '../model/run';
import { useBoard, useBoardActions } from '../state/context';
import { GhostSuggestion } from './GhostSuggestion';

const VERDICT_ICON: Readonly<Record<ProposalView['report']['verdict'], string>> = {
  proved: 'pass',
  'not-proved': 'circle-slash',
  insufficient: 'circle-slash',
  inconsistent: 'warning',
  'gave-up': 'error',
  'cap-reached': 'watch',
  'no-finish': 'debug-stop',
  cancelled: 'circle-slash',
  failed: 'error',
};

/** A card of the proposal by its sentence (an adopted suggestion keeps Claude's wording style). */
function CardName({ node, id }: { node: TlNode | undefined; id: string }) {
  if (!node) return <code>{id}</code>;
  return (
    <span className="tl-report__card">
      <span className="tl-glyph" data-kind={node.type} aria-hidden="true">
        {KIND_GLYPH[node.type]}
      </span>
      {node.provenance.wordedBy === 'agent' ? <AgentText text={node.naturalName} /> : <UserText text={node.naturalName} />}
    </span>
  );
}

/** "Ask me instead" (D-20): Feedback prefilled with the assumption Claude made without asking. */
export function askInsteadText(item: string): string {
  return `You assumed this without asking: “${item}”. Please ask me about it instead of assuming it.`;
}

export function ReportCard({ proposal }: { proposal: ProposalView }) {
  const run = useBoard((s) => s.run);
  const subject = useBoard((s) => s.subject);
  const actions = useBoardActions();
  const report = proposal.report;
  const nodes = useMemo(() => Object.fromEntries(proposal.graph.nodes.map((n) => [n.id, n])), [proposal.graph.nodes]);
  const vocab = useMemo(() => vocabIndex(proposal.graph.vocabulary), [proposal.graph.vocabulary]);
  const footprint = useMemo(() => footprintEntries(report.footprint, nodes, subject, vocab), [report.footprint, nodes, subject, vocab]);
  const ghosts = useMemo(() => suggestedGhosts(run, proposal), [run, proposal]);
  const target = nodes[report.target];
  const proved = report.verdict === 'proved';

  return (
    <div className="tl-report" data-testid="report-card" data-verdict={report.verdict}>
      <p className="tl-report__verdict" data-testid="report-verdict" data-verdict={report.verdict}>
        <span className={`codicon codicon-${VERDICT_ICON[report.verdict]}`} aria-hidden="true" />
        <strong>{VERDICT_LABEL[report.verdict]}</strong>
        {target ? (
          <>
            {': '}
            <CardName node={target} id={report.target} />
          </>
        ) : null}
      </p>
      {report.reverted ? (
        <p className="tl-report__note" data-testid="report-reverted">
          <span className="codicon codicon-discard" aria-hidden="true" /> telelean reverted Claude’s working copy to “{report.reverted.label}”: <InlineCode text={report.reverted.reason} />
        </p>
      ) : null}

      {proved ? (
        <section className="tl-report__section" data-testid="report-footprint">
          <h4 className="tl-details__heading">Rests on</h4>
          {footprint.length === 0 ? <p className="tl-details__none">No assumptions at all.</p> : null}
          <ul className="tl-details__list">
            {footprint.map((entry, i) => (
              <li key={i}>
                {entry.kind === 'node' ? (
                  <CardName node={nodes[entry.id]} id={entry.id} />
                ) : entry.kind === 'presupposition' ? (
                  <span className="tl-presup" data-presup={entry.name} title={entry.name}>
                    {presuppositionLabel(entry.name, subject, vocab)}
                  </span>
                ) : entry.kind === 'axiom' ? (
                  <span className="tl-chip tl-chip--attention" title="An axiom that is neither one of your assumptions nor vocabulary">
                    axiom <code>{entry.name}</code>
                  </span>
                ) : (
                  <code>{entry.name.startsWith(PRESUPPOSITION_PREFIX) ? entry.name.slice(PRESUPPOSITION_PREFIX.length) : entry.name}</code>
                )}
              </li>
            ))}
          </ul>
        </section>
      ) : null}
      {report.selfEvident ? (
        <p className="tl-report__flag" data-testid="report-self-evident">
          <span className="codicon codicon-info" aria-hidden="true" /> Self-evident: proved without any of your premises.
        </p>
      ) : null}
      {report.unusedPremises.length > 0 ? (
        <div className="tl-report__flag" data-testid="report-unused">
          <span className="codicon codicon-info" aria-hidden="true" /> Not used by the proof:{' '}
          {report.unusedPremises.map((id, i) => (
            <span key={id}>
              {i > 0 ? ', ' : null}
              <CardName node={nodes[id]} id={id} />
            </span>
          ))}
        </div>
      ) : null}
      {proved ? (
        <p className="tl-report__flag" data-testid="report-consistency">
          <span className="codicon codicon-question" aria-hidden="true" /> Consistency unchecked: telelean has not yet checked that these premises can all hold
          together (the model finder arrives in M3).
        </p>
      ) : null}

      {report.claudeSummary ? (
        <section className="tl-report__section">
          <h4 className="tl-details__heading">Claude’s summary</h4>
          <AgentText text={report.claudeSummary} marker="prefix" block testId="report-summary" />
        </section>
      ) : null}
      {report.gap ? (
        <section className="tl-report__section">
          <h4 className="tl-details__heading">What is missing, according to Claude</h4>
          <AgentText text={report.gap} marker="prefix" block testId="report-gap" />
        </section>
      ) : null}
      {report.conflict && report.conflict.length > 0 ? (
        <section className="tl-report__section">
          <h4 className="tl-details__heading">A conflict Claude reports (unverified until M3)</h4>
          <ul className="tl-details__list">
            {report.conflict.map((item, i) => (
              <li key={i}>
                <AgentText text={item} marker="prefix" />
              </li>
            ))}
          </ul>
        </section>
      ) : null}
      <section className="tl-report__section" data-testid="assumed-without-asking">
        <h4 className="tl-details__heading">Assumed without asking</h4>
        {report.assumedWithoutAsking.length === 0 ? (
          <p className="tl-details__none">Nothing, according to Claude.</p>
        ) : (
          <ul className="tl-details__list">
            {report.assumedWithoutAsking.map((item, i) => (
              <li key={i} className="tl-report__assumed" data-testid="assumed-item">
                <AgentText text={item} marker="prefix" />
                <button type="button" className="tl-button tl-button--secondary tl-button--small" data-testid="ask-me-instead" onClick={() => actions.openFeedback(askInsteadText(item))}>
                  Ask me instead
                </button>
              </li>
            ))}
          </ul>
        )}
      </section>

      {ghosts.length > 0 ? (
        <section className="tl-report__section" data-testid="report-suggestions">
          <h4 className="tl-details__heading">Premises Claude suggests</h4>
          {ghosts.map((ghost) => (
            <GhostSuggestion key={ghost.id} ghost={ghost} variant="panel" />
          ))}
        </section>
      ) : null}

      {report.gateAttempts.length > 0 ? (
        <details className="tl-report__section tl-report__attempts" data-testid="report-gate-attempts">
          <summary>
            Gate attempts: {report.gateAttempts.filter((a) => a.passed).length} passed of {report.gateAttempts.length}
          </summary>
          <ol className="tl-details__list">
            {report.gateAttempts.map((attempt) => (
              <li key={`${attempt.round}-${attempt.attempt}`} className="tl-gate-attempt" data-passed={attempt.passed}>
                <strong>
                  Attempt {attempt.attempt}
                  {attempt.round > 1 ? ` (round ${attempt.round})` : ''}
                </strong>
                : {attempt.passed ? 'passed' : 'didn’t pass'}
                {attempt.failures.length > 0 ? (
                  <ul className="tl-gate-attempt__failures">
                    {attempt.failures.map((failure, i) => (
                      <li key={i}>
                        <code>{failure.step}</code> <InlineCode text={failure.text} />
                        {failure.detail ? (
                          <details className="tl-notice__detail">
                            <summary>What Claude was told</summary>
                            <pre>{failure.detail}</pre>
                          </details>
                        ) : null}
                      </li>
                    ))}
                  </ul>
                ) : null}
              </li>
            ))}
          </ol>
        </details>
      ) : null}

      {proposal.files.length > 0 ? (
        <section className="tl-report__section" data-testid="report-files">
          <h4 className="tl-details__heading">Files Accept would change</h4>
          <ul className="tl-details__list">
            {proposal.files.map((file) => (
              <li key={file.path} className="tl-report__file">
                <code>{file.path}</code>
                <span className="tl-report__counts">
                  {file.change === 'added' ? 'new, ' : file.change === 'deleted' ? 'deleted, ' : ''}+{file.additions} −{file.deletions}
                </span>
                <button type="button" className="tl-icon-button" title={`Open the raw diff of ${file.path}`} onClick={() => actions.openProposalDiff(file.path)}>
                  <span className="codicon codicon-diff" aria-hidden="true" /> diff
                </button>
              </li>
            ))}
          </ul>
        </section>
      ) : null}

      <p className="tl-report__usage" data-testid="report-usage">
        {report.usage.requests} requests · {formatTokens(report.usage.inputTokens)} in · {formatTokens(report.usage.outputTokens)} out ·{' '}
        <span title="Estimate at API list prices; your subscription is not billed per token.">{formatCost(report.usage.costEstimateUsd)} estimate</span> · took{' '}
        {formatDuration(report.durationMs)} (Claude working {formatDuration(report.agentMs)})
      </p>
    </div>
  );
}

/**
 * The end-of-round review (D-19, M2 minimal; docs/m2-plan.md section 6.4), a stepper in the run panel:
 *   statements (one step each: the sentence beside its Lean, a "fully explicit" toggle, the statement closure)
 *   -> new vocabulary (auto-approved, revocable: revoking is prefilled Feedback)
 *   -> definition questions (yes / no; Accept needs every "yes", a "no" opens Feedback)
 *   -> the report card (shown once the statements are done, or on "Show result": meaning before proof status)
 *   -> lifecycle items (D-21: a proved goal becomes a Derivation only when ticked; recommended ones start ticked)
 * with Accept / Feedback / Discard / Raw Lean diff always at hand.
 */
import { LIMITS, type DefinitionQuestion, type ProposalView, type StatementReview, type TlNode, type VocabKind, type VocabularyReview } from '@telelean/core';
import { useLayoutEffect, useMemo, useRef } from 'react';
import { AgentText, UserText } from '../common/AgentText';
import { KIND_GLYPH, KIND_NOUN, VOCAB_KIND_NOUN } from '../labels';
import { definitionsApproved, reviewSteps, STEP_TITLE, type ReviewStep } from '../model/run';
import { useBoard, useBoardActions } from '../state/context';
import type { ReviewUi } from '../state/store';
import { ReportCard } from './ReportCard';

const shortName = (name: string) => name.split('.').at(-1) ?? name;

function stepLabel(step: ReviewStep): string {
  if (step.kind === 'statement') return step.count > 1 ? `Statement ${step.index + 1}` : 'Statement';
  return STEP_TITLE[step.kind];
}

function Sentence({ text, wordedBy }: { text: string; wordedBy: 'user' | 'agent' }) {
  return wordedBy === 'agent' ? <AgentText text={text} /> : <UserText text={text} />;
}

function StatementStep({ step, explicit }: { step: Extract<ReviewStep, { kind: 'statement' }>; explicit: boolean }) {
  const actions = useBoardActions();
  const item: StatementReview = step.item;
  return (
    <div className="tl-statement" data-testid="statement-review" data-statement-node={item.nodeId}>
      <p className="tl-review__lead">
        Does the Lean say what the sentence says? <span className="tl-review__tag">{item.change === 'new' ? 'new statement' : 'changed statement'}</span>
      </p>
      <div className="tl-statement__pair">
        <div className="tl-statement__side" data-testid="statement-sentence">
          <h4 className="tl-details__heading">Sentence</h4>
          <p className="tl-statement__sentence">
            <Sentence text={item.sentence} wordedBy={item.wordedBy} />
          </p>
        </div>
        <div className="tl-statement__side">
          <h4 className="tl-details__heading">
            Lean <code>{shortName(item.leanName)}</code>
          </h4>
          <pre className="tl-lean" data-testid="statement-lean" data-form={explicit ? 'explicit' : 'pretty'}>
            {explicit ? item.explicit : item.pretty}
          </pre>
          <label className="tl-check" title="No notation, every argument and universe shown, no coercion arrows">
            <input type="checkbox" data-testid="explicit-toggle" checked={explicit} onChange={() => actions.toggleExplicit(item.nodeId)} />
            Fully explicit
          </label>
        </div>
      </div>
      <div className="tl-statement__closure" data-testid="statement-closure">
        <h4 className="tl-details__heading">It uses</h4>
        {item.closure.length === 0 ? (
          <p className="tl-details__none">No vocabulary.</p>
        ) : (
          <ul className="tl-details__list">
            {item.closure.map((entry) => (
              <li key={entry.name} className="tl-closure__item" data-closure={entry.name}>
                <code className="tl-closure__name">{shortName(entry.name)}</code>
                <span className="tl-closure__kind">{VOCAB_KIND_NOUN[entry.kind as VocabKind] ?? entry.kind}</span>
                {entry.type ? <code className="tl-closure__type">: {entry.type}</code> : null}
                {entry.gloss ? entry.glossBy === 'agent' ? <AgentText text={entry.gloss} /> : <UserText text={entry.gloss} className="tl-closure__gloss" /> : null}
              </li>
            ))}
          </ul>
        )}
      </div>
      <button type="button" className="tl-icon-button" onClick={() => actions.showOnBoard(item.nodeId)}>
        <span className="codicon codicon-eye" aria-hidden="true" /> Show on the board
      </button>
    </div>
  );
}

/** Revoking a new vocabulary item is Feedback (D-19: auto-approved but revocable). */
export function revokeVocabularyText(item: VocabularyReview['items'][number]): string {
  return `Please don't add the vocabulary item \`${shortName(item.name)}\`${item.gloss ? ` (“${item.gloss}”)` : ''}: `;
}

function VocabularyStep({ item }: { item: VocabularyReview }) {
  const actions = useBoardActions();
  return (
    <div data-testid="vocabulary-review">
      <p className="tl-review__lead">
        Claude added this vocabulary. Plain types, predicates and constants pass the simple vocabulary rule, so they are approved unless you revoke one
        (revoking sends Feedback).
      </p>
      <ul className="tl-details__list">
        {item.items.map((entry) => (
          <li key={entry.name} className="tl-vocab-review" data-testid="vocabulary-item" data-vocab={entry.name}>
            <div className="tl-vocab-review__head">
              <code className="tl-closure__name">{shortName(entry.name)}</code>
              <span className="tl-closure__kind">{VOCAB_KIND_NOUN[entry.vocabKind as VocabKind] ?? entry.vocabKind}</span>
              {entry.type ? <code className="tl-closure__type">: {entry.type}</code> : null}
              <span className="tl-details__spacer" />
              <button type="button" className="tl-button tl-button--secondary tl-button--small" data-testid="revoke-vocabulary" onClick={() => actions.openFeedback(revokeVocabularyText(entry))}>
                Revoke…
              </button>
            </div>
            {/* New vocabulary is Claude's: its gloss is in Claude's words. */}
            {entry.gloss ? <AgentText text={entry.gloss} /> : null}
            {entry.code ? <pre className="tl-lean">{entry.code}</pre> : null}
          </li>
        ))}
      </ul>
    </div>
  );
}

function DefinitionItem({ question, answer, nodes }: { question: DefinitionQuestion; answer: 'yes' | 'no' | undefined; nodes: Readonly<Record<string, TlNode>> }) {
  const actions = useBoardActions();
  const users = question.usedByStatementsOf.map((id) => nodes[id]).filter((n): n is TlNode => n !== undefined);
  return (
    <div className="tl-definition" data-testid="definition" data-definition-id={question.id} data-answer={answer}>
      <h4 className="tl-definition__title">
        <code>{question.name}</code> <span className="tl-closure__kind">{question.kind === 'presupposition' ? 'existence assumption' : 'definition'}</span>
      </h4>
      {question.gloss ? <AgentText text={question.gloss} block /> : null}
      <pre className="tl-lean">{question.code}</pre>
      {users.length > 0 ? (
        <p className="tl-definition__users">
          Your statements rely on it:{' '}
          {users.map((node, i) => (
            <span key={node.id}>
              {i > 0 ? ', ' : null}
              <span className="tl-glyph" data-kind={node.type} aria-hidden="true">
                {KIND_GLYPH[node.type]}
              </span>{' '}
              <Sentence text={node.naturalName} wordedBy={node.provenance.wordedBy} />
            </span>
          ))}
        </p>
      ) : null}
      <div className="tl-definition__answer" role="group" aria-label={`Do you endorse ${question.name}?`}>
        <button type="button" className="tl-choice" aria-pressed={answer === 'yes'} data-testid="definition-yes" onClick={() => actions.answerDefinition(question.id, 'yes')}>
          Yes, I endorse it
        </button>
        <button type="button" className="tl-choice" aria-pressed={answer === 'no'} data-testid="definition-no" onClick={() => actions.answerDefinition(question.id, 'no')}>
          No…
        </button>
      </div>
    </div>
  );
}

function DefinitionsStep({ proposal, review }: { proposal: ProposalView; review: ReviewUi }) {
  const nodes = useMemo(() => Object.fromEntries(proposal.graph.nodes.map((n) => [n.id, n])), [proposal.graph.nodes]);
  return (
    <div data-testid="definitions-review">
      <p className="tl-review__lead">
        Claude introduced {proposal.definitions.length === 1 ? 'this definition' : 'these definitions'}. A definition can quietly carry a belief, so Accept needs
        your yes for each; a no is Feedback for Claude.
      </p>
      {proposal.definitions.map((question) => (
        <DefinitionItem key={question.id} question={question} answer={review.definitions[question.id]} nodes={nodes} />
      ))}
    </div>
  );
}

function ResultStep({ proposal, review }: { proposal: ProposalView; review: ReviewUi }) {
  const actions = useBoardActions();
  if (!review.revealed) {
    return (
      <div className="tl-review__hidden" data-testid="result-hidden">
        <p>The result is shown after the statements, so that you judge what they mean before you see whether they were proved.</p>
        <button type="button" className="tl-button tl-button--secondary" onClick={() => actions.revealResult()}>
          Show result
        </button>
      </div>
    );
  }
  return <ReportCard proposal={proposal} />;
}

function LifecycleStep({ proposal, review }: { proposal: ProposalView; review: ReviewUi }) {
  const actions = useBoardActions();
  const nodes = useMemo(() => Object.fromEntries(proposal.graph.nodes.map((n) => [n.id, n])), [proposal.graph.nodes]);
  return (
    <div data-testid="lifecycle-review">
      <p className="tl-review__lead">Changes to cards that Accept makes too, only when ticked:</p>
      <ul className="tl-details__list">
        {proposal.lifecycle.map((item) => {
          const node = nodes[item.nodeId];
          return (
            <li key={item.id}>
              <label className="tl-check tl-lifecycle" data-testid="lifecycle-item" data-lifecycle-id={item.id}>
                <input type="checkbox" checked={review.lifecycle[item.id] === true} onChange={(event) => actions.setLifecycleTick(item.id, event.target.checked)} />
                <span>
                  Make {node ? <>“<Sentence text={node.naturalName} wordedBy={node.provenance.wordedBy} />”</> : <code>{item.nodeId}</code>} a {KIND_NOUN[item.to]}{' '}
                  <span className="tl-run__hint">
                    ({item.reason}
                    {item.recommended ? '; recommended' : ''})
                  </span>
                </span>
              </label>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

function FeedbackComposer({ review }: { review: ReviewUi }) {
  const actions = useBoardActions();
  const sending = useBoard((s) => s.runBusy?.action === 'feedback');
  const field = useRef<HTMLTextAreaElement>(null);
  useLayoutEffect(() => {
    const element = field.current;
    if (!element || review.feedbackFocus === 0) return;
    element.focus();
    element.setSelectionRange(element.value.length, element.value.length);
  }, [review.feedbackFocus]);
  const text = review.feedback.trim();
  return (
    <div className="tl-feedback" data-testid="feedback-composer">
      <label className="tl-feedback__label" htmlFor="tl-feedback-text">
        Feedback for Claude: it continues the same session in a new round (statements may change)
      </label>
      <textarea
        id="tl-feedback-text"
        ref={field}
        className="tl-input tl-feedback__text"
        data-testid="feedback-text"
        rows={4}
        maxLength={LIMITS.textLength}
        value={review.feedback}
        onChange={(event) => actions.setFeedback(event.target.value)}
        onKeyDown={(event) => {
          if (event.key === 'Enter' && (event.ctrlKey || event.metaKey)) {
            event.preventDefault();
            actions.sendFeedback();
          } else if (event.key === 'Escape') {
            event.preventDefault();
            actions.closeFeedback();
          }
        }}
      />
      <div className="tl-feedback__buttons">
        <button type="button" className="tl-button" data-testid="send-feedback" disabled={text.length === 0 || sending} onClick={() => actions.sendFeedback()}>
          {sending ? 'Sending…' : 'Send feedback'}
        </button>
        <button type="button" className="tl-button tl-button--secondary" onClick={() => actions.closeFeedback()}>
          Close
        </button>
        <span className="tl-run__hint">Ctrl+Enter sends</span>
      </div>
    </div>
  );
}

/** Accept / Feedback / Discard / Raw Lean diff (the banner has the same buttons). */
export function ReviewActions({ proposal, review }: { proposal: ProposalView; review: ReviewUi }) {
  const actions = useBoardActions();
  const busy = useBoard((s) => s.runBusy);
  const approved = definitionsApproved(proposal, review.definitions);
  return (
    <>
      <div className="tl-review__actions" data-testid="review-actions">
        <button
          type="button"
          className="tl-button"
          data-testid="accept"
          disabled={!approved || busy !== null}
          title={approved ? 'Apply the proposal to your files (one Undo step; a history entry)' : 'Answer every definition question with yes first (a no is Feedback)'}
          onClick={() => actions.acceptProposal()}
        >
          {busy?.action === 'accept' ? 'Accepting…' : 'Accept'}
        </button>
        <button type="button" className="tl-button tl-button--secondary" data-testid="feedback" disabled={busy !== null} onClick={() => actions.openFeedback()}>
          Feedback…
        </button>
        <button type="button" className="tl-button tl-button--secondary" data-testid="discard" disabled={busy !== null} title="End the run without changing your files" onClick={() => actions.discardProposal()}>
          {busy?.action === 'discard' ? 'Discarding…' : 'Discard'}
        </button>
        <button type="button" className="tl-button tl-button--secondary" data-testid="raw-diff" title="Open VS Code's diff of every file the proposal changes" onClick={() => actions.openProposalDiff()}>
          Raw Lean diff…
        </button>
      </div>
      {!approved ? (
        <p className="tl-run__hint" data-testid="accept-blocked">
          Accept needs your yes for every definition question.
        </p>
      ) : null}
      {review.feedbackOpen ? <FeedbackComposer review={review} /> : null}
    </>
  );
}

export function Review({ proposal }: { proposal: ProposalView }) {
  const review = useBoard((s) => s.review);
  const actions = useBoardActions();
  const steps = useMemo(() => reviewSteps(proposal), [proposal]);
  if (!review || review.proposalId !== proposal.proposalId) return null;
  const index = Math.min(review.step, steps.length - 1);
  const step = steps[index];
  if (!step) return null;
  return (
    <section className="tl-run__section tl-review" data-testid="review" aria-label="Review">
      <div className="tl-review__head">
        <h3 className="tl-run__heading">
          <span className="codicon codicon-checklist" aria-hidden="true" /> Review
        </h3>
        <span className="tl-review__progress" data-testid="review-progress">
          Step {index + 1} of {steps.length}: {stepLabel(step)}
        </span>
        <span className="tl-details__spacer" />
        {!review.revealed ? (
          <button type="button" className="tl-icon-button" data-testid="show-result" title="Show the proof result now" onClick={() => actions.revealResult()}>
            Show result
          </button>
        ) : null}
      </div>
      <ol className="tl-review__steps" aria-label="Review steps">
        {steps.map((s, i) => (
          <li key={i}>
            <button
              type="button"
              className="tl-review__step"
              data-step-kind={s.kind}
              aria-current={i === index ? 'step' : undefined}
              data-locked={(s.kind === 'result' && !review.revealed) || undefined}
              onClick={() => actions.reviewGo(i)}
            >
              {stepLabel(s)}
              {s.kind === 'definitions' ? ` (${proposal.definitions.length})` : ''}
            </button>
          </li>
        ))}
      </ol>
      {proposal.baseChanged ? (
        <p className="tl-review__note" data-testid="review-base-changed">
          <span className="codicon codicon-info" aria-hidden="true" /> Your files changed since the run started: Accept re-checks Claude’s changes on top of them first.
        </p>
      ) : null}
      {proposal.empty ? (
        <p className="tl-review__note" data-testid="review-empty">
          <span className="codicon codicon-info" aria-hidden="true" /> This round changed no file: Accept only records the outcome.
        </p>
      ) : null}
      <div className="tl-review__body" data-testid="review-step" data-step={step.kind}>
        {step.kind === 'statement' ? <StatementStep step={step} explicit={review.explicit[step.item.nodeId] === true} /> : null}
        {step.kind === 'vocabulary' ? <VocabularyStep item={step.item} /> : null}
        {step.kind === 'definitions' ? <DefinitionsStep proposal={proposal} review={review} /> : null}
        {step.kind === 'result' ? <ResultStep proposal={proposal} review={review} /> : null}
        {step.kind === 'lifecycle' ? <LifecycleStep proposal={proposal} review={review} /> : null}
      </div>
      <div className="tl-review__nav">
        <button type="button" className="tl-button tl-button--secondary tl-button--small" data-testid="review-back" disabled={index === 0} onClick={() => actions.reviewGo(index - 1)}>
          <span className="codicon codicon-chevron-left" aria-hidden="true" /> Back
        </button>
        <button type="button" className="tl-button tl-button--small" data-testid="review-next" disabled={index >= steps.length - 1} onClick={() => actions.reviewGo(index + 1)}>
          Next: {index < steps.length - 1 ? stepLabel(steps[index + 1] as ReviewStep) : 'done'} <span className="codicon codicon-chevron-right" aria-hidden="true" />
        </button>
      </div>
      <ReviewActions proposal={proposal} review={review} />
    </section>
  );
}

/**
 * The run panel (docs/m2-plan.md section 6.4): the board's own subject's Claude run, beside the board (below it on a
 * narrow board):
 *  - the status line: state and stage, round, checks n/25, turns n/80, agent time (paused while a question waits),
 *    gate attempts k/3, tokens, the cost "estimate" and the rate limit (D-25), with Cancel;
 *  - A2's notices (an attempt that did not pass, giving up, the revert, a cap, an environment problem);
 *  - the pending question cards, then the answered ones with Claude's guess revealed (D-20);
 *  - the review stepper with the report card and Accept / Feedback / Discard (D-19, D-21);
 *  - Resume / Stop for an interrupted run, the outcome of an ended run with Dismiss;
 *  - the activity feed, where Claude's own messages are italic with a marker (D-15).
 * Closing the panel (or the board) never stops the run; the header's run badge opens it again.
 */
import type { RunActivity, RunNotice, RunView } from '@telelean/core';
import { useLayoutEffect, useRef } from 'react';
import { AgentText, UserText } from '../common/AgentText';
import { InlineCode } from '../common/InlineCode';
import { useNow } from '../common/useNow';
import { NOTICE_ICON } from '../labels';
import { clockRuns, formatClock, runStateLabel, runStatusParts } from '../model/run';
import { useBoard, useBoardActions } from '../state/context';
import { AnsweredQuestions, QuestionSet } from './Questions';
import { Review } from './Review';

function StatusLine({ run }: { run: RunView }) {
  const now = useNow(clockRuns(run));
  const parts = runStatusParts(run, now);
  return (
    <div className="tl-run__stats" data-testid="run-stats">
      {parts.map((part) => (
        <span key={part.key} className="tl-run__stat" data-part={part.key} data-tone={part.tone} title={part.title}>
          {part.text}
        </span>
      ))}
    </div>
  );
}

function Target({ run }: { run: RunView }) {
  const nodes = useBoard((s) => s.nodes);
  const target = nodes[run.target];
  const premises = run.premises.map((id) => nodes[id]?.naturalName ?? id);
  return (
    <p className="tl-run__target" data-testid="run-target">
      <span className="tl-run__target-label">{run.premises.length === 0 ? 'Self-evident?' : 'These suffice:'}</span> “
      <UserText text={target?.naturalName ?? run.target} />”{' '}
      <span className="tl-run__hint" title={premises.join('\n')}>
        {run.premises.length === 0 ? 'from no premises at all' : `from ${run.premises.length} premise${run.premises.length === 1 ? '' : 's'}`}
      </span>
    </p>
  );
}

function Notices({ notices }: { notices: readonly RunNotice[] }) {
  if (notices.length === 0) return null;
  return (
    <section className="tl-run__section" data-testid="run-notices" aria-label="Notices">
      <ul className="tl-notices" aria-live="polite">
        {notices.map((notice) => (
          <li key={notice.id} className="tl-notice" data-testid="run-notice" data-kind={notice.kind} data-level={notice.level}>
            <span className={`codicon codicon-${NOTICE_ICON[notice.kind]}`} aria-hidden="true" />
            <div className="tl-notice__body">
              <span className="tl-notice__text">
                <InlineCode text={notice.text} />
              </span>
              {notice.detail ? (
                <details className="tl-notice__detail">
                  <summary>Details</summary>
                  <pre>{notice.detail}</pre>
                </details>
              ) : null}
            </div>
            <time className="tl-run__time" dateTime={notice.at}>
              {formatClock(notice.at)}
            </time>
          </li>
        ))}
      </ul>
    </section>
  );
}

const ACTIVITY_ICON: Readonly<Record<RunActivity['kind'], string>> = {
  'claude-text': 'comment',
  tool: 'tools',
  check: 'beaker',
  freeze: 'lock',
  gate: 'shield',
  ghost: 'lightbulb-sparkle',
  question: 'question',
  answer: 'reply',
  system: 'info',
};

/** The progress feed, newest last; it follows new lines unless the user scrolled up to read. */
function Activity({ activity, open }: { activity: readonly RunActivity[]; open: boolean }) {
  const list = useRef<HTMLOListElement>(null);
  const atEnd = useRef(true);
  useLayoutEffect(() => {
    const element = list.current;
    if (element && atEnd.current) element.scrollTop = element.scrollHeight;
  }, [activity, open]);
  return (
    <details className="tl-run__section tl-activity" data-testid="run-activity" open={open || undefined}>
      <summary className="tl-run__heading">Activity ({activity.length})</summary>
      {activity.length === 0 ? (
        <p className="tl-run__hint">Nothing yet.</p>
      ) : (
        <ol
          ref={list}
          className="tl-activity__list"
          onScroll={(event) => {
            const el = event.currentTarget;
            atEnd.current = el.scrollTop + el.clientHeight >= el.scrollHeight - 8;
          }}
        >
          {activity.map((line, i) => (
            <li key={i} className="tl-activity__item" data-testid="activity-item" data-kind={line.kind} data-ok={line.ok === undefined ? undefined : String(line.ok)}>
              <time className="tl-run__time" dateTime={line.at}>
                {formatClock(line.at)}
              </time>
              {line.kind === 'claude-text' ? (
                <AgentText text={line.text} marker="prefix" className="tl-activity__claude" />
              ) : (
                <span className="tl-activity__text">
                  <span className={`codicon codicon-${line.ok === false ? 'error' : ACTIVITY_ICON[line.kind]}`} aria-hidden="true" /> <InlineCode text={line.text} />
                </span>
              )}
            </li>
          ))}
        </ol>
      )}
    </details>
  );
}

const ENDED_TEXT: Readonly<Record<'accepted' | 'discarded' | 'cancelled' | 'failed', string>> = {
  accepted: 'Accepted: Claude’s changes are in your files. Undo (Ctrl+Z) or History reverts them.',
  discarded: 'Discarded: your files were not changed.',
  cancelled: 'Cancelled: your files were not changed. The run’s working copy and transcript are kept for the record.',
  failed: 'The run failed; your files were not changed.',
};

function Outcome({ run }: { run: RunView }) {
  const actions = useBoardActions();
  const busy = useBoard((s) => s.runBusy?.action ?? null);
  switch (run.state) {
    case 'starting':
      return (
        <p className="tl-run__progress" data-testid="run-progress">
          <span className="codicon codicon-loading codicon-modifier-spin" aria-hidden="true" /> Checking the setup, copying your model and starting Claude…
        </p>
      );
    case 'gate':
      return (
        <p className="tl-run__progress" data-testid="run-progress">
          <span className="codicon codicon-loading codicon-modifier-spin" aria-hidden="true" /> Claude says it is done: telelean checks the result (build, what it
          rests on, the statement unchanged, your words untouched)…
        </p>
      );
    case 'interrupted':
      return (
        <div className="tl-run__outcome" data-testid="run-interrupted">
          <p>The session was interrupted (the editor reloaded) while Claude was working. Your files were not changed.</p>
          {!run.canResume ? <p className="tl-run__hint">It cannot be resumed: stop it, then start again.</p> : null}
          <div className="tl-run__buttons">
            {run.canResume ? (
              <button type="button" className="tl-button" data-testid="resume-run" disabled={busy !== null} onClick={() => actions.resumeRun()}>
                {busy === 'resume' ? 'Resuming…' : 'Resume'}
              </button>
            ) : null}
            <button type="button" className="tl-button tl-button--secondary" data-testid="stop-run" disabled={busy !== null} title="End the run (like Discard)" onClick={() => actions.stopRun()}>
              {busy === 'stop' ? 'Stopping…' : 'Stop'}
            </button>
          </div>
        </div>
      );
    case 'accepted':
    case 'discarded':
    case 'cancelled':
    case 'failed':
      return (
        <div className="tl-run__outcome" data-testid="run-ended" data-tone={run.state === 'failed' ? 'error' : undefined}>
          <p>{ENDED_TEXT[run.state]}</p>
          {run.error ? (
            <p className="tl-run__error" data-testid="run-error">
              <span className="codicon codicon-error" aria-hidden="true" /> <InlineCode text={run.error} />
            </p>
          ) : null}
          <div className="tl-run__buttons">
            <button type="button" className="tl-button tl-button--secondary" data-testid="dismiss-run" onClick={() => actions.dismissRun()}>
              Dismiss
            </button>
          </div>
        </div>
      );
    default:
      return null;
  }
}

export function RunPanel() {
  const run = useBoard((s) => (s.run && s.run.subject === s.subject ? s.run : null));
  const open = useBoard((s) => s.runPanelOpen);
  const proposal = useBoard((s) => (s.proposal && s.run && s.proposal.runId === s.run.runId ? s.proposal : null));
  const revealed = useBoard((s) => s.review?.revealed ?? true);
  const cancelling = useBoard((s) => s.runBusy?.action === 'cancel');
  const actions = useBoardActions();
  if (!run || !open) return null;
  const ended = run.state === 'accepted' || run.state === 'discarded' || run.state === 'cancelled' || run.state === 'failed';
  const cancellable = !ended && run.state !== 'review' && run.state !== 'interrupted';
  const reviewing = run.state === 'review';
  return (
    <aside className="tl-run" data-testid="run-panel" data-state={run.state} data-stage={run.stage} aria-label="Claude run">
      <header className="tl-run__head">
        <span className="tl-run__title">
          <span className="codicon codicon-sparkle" aria-hidden="true" /> Claude
        </span>
        <span className="tl-run__state" data-testid="run-state" role="status">
          {runStateLabel(run, revealed)}
        </span>
        <span className="tl-details__spacer" />
        {cancellable ? (
          <button type="button" className="tl-button tl-button--secondary tl-button--small" data-testid="cancel-run" disabled={cancelling} title="Stop Claude and its Lean jobs; your files are not changed" onClick={() => actions.cancelRun()}>
            {cancelling ? 'Cancelling…' : 'Cancel'}
          </button>
        ) : null}
        <button type="button" className="tl-icon-button" aria-label="Hide the run panel" title="Hide (the run goes on; the Claude badge in the header shows it again)" onClick={() => actions.setRunPanelOpen(false)}>
          <span className="codicon codicon-close" aria-hidden="true" />
        </button>
      </header>
      <StatusLine run={run} />
      <div className="tl-run__body">
        <Target run={run} />
        <Outcome run={run} />
        {run.pendingQuestions ? <QuestionSet run={run} set={run.pendingQuestions} /> : null}
        {reviewing && proposal ? <Review proposal={proposal} /> : null}
        {reviewing && !proposal ? (
          <p className="tl-run__progress" data-testid="run-progress">
            <span className="codicon codicon-loading codicon-modifier-spin" aria-hidden="true" /> Preparing the proposal…
          </p>
        ) : null}
        <Notices notices={run.notices} />
        <AnsweredQuestions answered={run.answered} />
        {/* In review the feed is folded away: the review comes first (D-19), the history is one click away. */}
        <Activity key={reviewing || ended ? 'folded' : 'open'} activity={run.activity} open={!reviewing && !ended} />
        <p className="tl-run__backend" data-testid="run-backend">
          {run.backend.model}
          {run.backend.effort ? ` · effort ${run.backend.effort}` : ''}
          {run.backend.cliVersion ? ` · Claude Code ${run.backend.cliVersion}` : ''}
        </p>
      </div>
    </aside>
  );
}

/** Claude's words in the panel's notices come from telelean, never from Claude: they are plain (see AgentText). */
export { AgentText };

/**
 * The proposal banner (03 section 7, docs/m2-plan.md section 6.4): what Claude's proposal changes ("1 new · 2 changed
 * · +1 vocabulary"), the Current | Proposed toggle of the board, and Review… · Accept · Feedback · Discard · Raw Lean
 * diff…. Accept follows the same rule as in the review (every definition question answered yes; the ticked lifecycle
 * items). The verdict is not named here: the review shows meaning before proof status (D-19).
 */
import { definitionsApproved, diffCountsText } from '../model/run';
import { useBoard, useBoardActions } from '../state/context';
import { proposedOverlay } from '../state/store';

export function ProposalBanner() {
  const proposal = useBoard((s) => (s.proposal && s.proposal.subject === s.subject && s.run?.state === 'review' && s.run.runId === s.proposal.runId ? s.proposal : null));
  const review = useBoard((s) => s.review);
  const proposed = useBoard((s) => proposedOverlay(s) !== null);
  const busy = useBoard((s) => s.runBusy !== null);
  const actions = useBoardActions();
  if (!proposal || !review) return null;
  const approved = definitionsApproved(proposal, review.definitions);
  return (
    <div className="tl-banner tl-proposal-banner" data-testid="proposal-banner" role="region" aria-label="Claude's proposal">
      <span className="codicon codicon-git-pull-request" aria-hidden="true" />
      <span className="tl-proposal-banner__title">
        <strong>Claude’s proposal</strong> <span data-testid="proposal-counts">{diffCountsText(proposal)}</span>
      </span>
      <span className="tl-seg tl-seg--small" role="radiogroup" aria-label="Board shows" data-testid="proposal-toggle">
        <button type="button" role="radio" aria-checked={!proposed} tabIndex={proposed ? -1 : 0} onClick={() => actions.setProposedView(false)}>
          Current
        </button>
        <button type="button" role="radio" aria-checked={proposed} tabIndex={proposed ? 0 : -1} onClick={() => actions.setProposedView(true)}>
          Proposed
        </button>
      </span>
      <span className="tl-toolbar__spacer" />
      <button
        type="button"
        className="tl-button tl-button--secondary tl-button--small"
        data-testid="banner-review"
        onClick={() => {
          actions.setRunPanelOpen(true);
          actions.setProposedView(true);
        }}
      >
        Review…
      </button>
      <button
        type="button"
        className="tl-button tl-button--small"
        data-testid="banner-accept"
        disabled={!approved || busy}
        title={approved ? 'Apply the proposal to your files (one Undo step)' : 'Answer every definition question with yes first (in the review)'}
        onClick={() => actions.acceptProposal()}
      >
        Accept
      </button>
      <button type="button" className="tl-button tl-button--secondary tl-button--small" data-testid="banner-feedback" disabled={busy} onClick={() => actions.openFeedback()}>
        Feedback…
      </button>
      <button type="button" className="tl-button tl-button--secondary tl-button--small" data-testid="banner-discard" disabled={busy} onClick={() => actions.discardProposal()}>
        Discard
      </button>
      <button type="button" className="tl-button tl-button--secondary tl-button--small" data-testid="banner-raw-diff" onClick={() => actions.openProposalDiff()}>
        Raw Lean diff…
      </button>
    </div>
  );
}

/**
 * The run in the header (docs/m2-plan.md section 6.4): a badge ("Claude: working on Spyro · 3/25 checks") that opens
 * or hides the run panel, and, for a run of another subject (at most one run per model folder), a compact line under
 * the header with "Show", which switches the board to that subject.
 */
import { runBadgeText, runNeedsUser, runStateLabel } from '../model/run';
import { useBoard, useBoardActions } from '../state/context';

export function RunBadge() {
  const run = useBoard((s) => s.run);
  const subject = useBoard((s) => s.subject);
  const open = useBoard((s) => s.runPanelOpen);
  const actions = useBoardActions();
  if (!run) return null;
  const here = run.subject === subject;
  return (
    <button
      type="button"
      className="tl-run-badge"
      data-testid="run-badge"
      data-state={run.state}
      data-attention={runNeedsUser(run) || undefined}
      aria-expanded={here ? open : undefined}
      title={here ? (open ? 'Hide the run panel' : 'Show the run panel') : `Show ${run.subject}, where Claude is running`}
      onClick={() => (here ? actions.setRunPanelOpen(!open) : actions.selectSubject(run.subject))}
    >
      <span className={`codicon codicon-${runNeedsUser(run) ? 'bell-dot' : 'sparkle'}`} aria-hidden="true" />
      {runBadgeText(run)}
    </button>
  );
}

/** Another subject's run: one compact line, with "Show" (the board then switches to that subject). */
export function RunElsewhere() {
  const run = useBoard((s) => (s.run && s.subject !== '' && s.run.subject !== s.subject ? s.run : null));
  const actions = useBoardActions();
  if (!run) return null;
  return (
    <div className="tl-banner tl-run-elsewhere" data-testid="run-elsewhere" role="status">
      <span className="codicon codicon-sparkle" aria-hidden="true" />
      <span>
        Claude’s run on <strong>{run.subject}</strong>: {runStateLabel(run).toLowerCase()}.
      </span>
      <button type="button" className="tl-button tl-button--secondary tl-button--small" onClick={() => actions.selectSubject(run.subject)}>
        Show
      </button>
    </div>
  );
}

