/**
 * Gates for assertions that need another work package's change (docs/m2-plan.md section 9: "[gated]" tests run once
 * that change has landed; the integrator removes the gates, as M1 did with its `isImplemented` gates).
 */
import { kindChangeImpact } from '@telelean/core';
import { conditionalGraph } from './graphs';

/**
 * [gated: WP1, carry-over 2] Whether core already words exactly one dependent in the singular, with the texts frozen
 * in docs/m2-plan.md section 1.3 ("Either rewrite that proof to use it directly (mechanical, undoable), or keep that
 * proof and let it show as broken."). The webview's assertions of core's singular texts run only then.
 */
export const CORE_SINGULAR_TEXTS: boolean = (() => {
  try {
    return kindChangeImpact(conditionalGraph(), 'd1', 'ASSUMPTION').detail.includes('rewrite that proof to use it directly');
  } catch {
    return false;
  }
})();

export const CORE_SINGULAR_GATE = 'gated on WP1: core still words one dependent in the plural (docs/m2-plan.md section 1.3)';

