/**
 * M2 question cards (ask_user, D-20; AT6.3): phenomenon tag, Claude's options with their consequences, free text,
 * "Leave it open", "Decide for me", the scope of each answer (default: this run); "Send" posts answerQuestions; no
 * guess on the board before the answer, Claude's guess shown after the run update.
 */
import { expect, test } from '@playwright/test';
import { hostMessage, spyroGraph } from '@telelean/core';
import { workspaceState } from '../shared/graphs';
import { answeredModality, GENERIC_QUESTION, MODALITY_QUESTION, RUN_ID, runView, UPDATED, waitingRun } from '../shared/runs';
import { openBoard, postedOfType, send, shotPath, type OpenedBoard } from './helpers';

let board: OpenedBoard | undefined;

test.afterEach(async () => {
  if (board) expect(await board.problems()).toEqual([]);
  board = undefined;
});

test('AT6.3 the question card: tag, options with consequences, own words, Leave it open, Decide for me, scope; Send posts answerQuestions; the guess only afterwards', async ({ page }) => {
  board = await openBoard(page, spyroGraph(), 'dark', { workspace: workspaceState(), run: waitingRun([MODALITY_QUESTION, GENERIC_QUESTION]), clock: UPDATED });
  const set = page.getByTestId('question-set');
  const questions = set.getByTestId('question');
  await expect(questions).toHaveCount(2);
  const [q0, q1] = [questions.nth(0), questions.nth(1)];
  await expect(q0.getByTestId('phenomenon')).toHaveText('modality');
  await expect(q1.getByTestId('phenomenon')).toHaveText('genericity');
  await expect(q0.getByTestId('question-text')).toContainText('Does "cannot have" state a rule about what PG games should not include');
  await expect(q0.getByTestId('option-label')).toHaveText(['A rule (normative)', 'Impossible (literal)']);
  await expect(q0.getByTestId('option-consequence')).toHaveText([
    'A PG game with such a character breaks the rule; it says nothing about what the game contains.',
    'No PG game contains a character with a dark past at all.',
  ]);
  await expect(q1.locator('.tl-option__preview')).toHaveText('∀ c, HasDarkPast c → ¬ Abnormal c → …');
  await expect(q0.getByTestId('option-free-text')).toContainText('In my own words');
  await expect(q0.getByTestId('option-leave-open')).toContainText('Leave it open');
  await expect(q0.getByTestId('option-decide-for-me')).toContainText('Decide for me');
  await expect(q0.getByTestId('question-about')).toHaveText('About “PG games cannot have characters with dark pasts”');
  // No pre-selected answer (D-20): only the scope radios start checked, at "this run".
  for (const q of [q0, q1]) {
    await expect(q.locator('.tl-question__options input[type="radio"]:checked')).toHaveCount(0);
    await expect(q.getByTestId('question-scope').getByRole('radio', { name: 'this run' })).toBeChecked();
  }
  // No guess anywhere before the answer.
  await expect(page.getByTestId('claudes-guess')).toHaveCount(0);
  await expect(page.locator('body')).not.toContainText('guess');
  await page.screenshot({ path: shotPath('m2-questions.png') });

  const sendButton = set.getByTestId('send-answers');
  await expect(sendButton).toHaveText('Send answers');
  await expect(sendButton).toBeDisabled();
  await q0.getByTestId('option').first().click();
  await expect(sendButton).toBeDisabled(); // the second question is not answered yet
  // In my own words: a blank text does not count.
  await q1.getByTestId('option-free-text').click();
  await q1.getByTestId('free-text').fill('   ');
  await expect(sendButton).toBeDisabled();
  await q1.getByTestId('free-text').fill('Every one, but only\nfor games rated PG.');
  await q1.getByTestId('question-scope').getByRole('radio', { name: 'the whole subject' }).check();
  await q0.getByTestId('question-scope').getByRole('radio', { name: 'these cards' }).check();
  await expect(sendButton).toBeEnabled();
  await sendButton.click();
  expect((await postedOfType(page, 'answerQuestions')).map((m) => m.payload)).toEqual([
    {
      runId: RUN_ID,
      setId: 'q1',
      answers: [
        { question: 0, choice: { kind: 'option', option: 0 }, scope: 'nodes' },
        { question: 1, choice: { kind: 'free-text', text: 'Every one, but only\nfor games rated PG.' }, scope: 'subject' },
      ],
      requestId: 'r1',
    },
  ]);

  // The host's update: the batch is answered; Claude's guess is revealed beside each answer.
  const generic = { ...GENERIC_QUESTION, setId: 'q1', answer: { question: 1, choice: { kind: 'free-text' as const, text: 'Every one, but only\nfor games rated PG.' }, scope: 'subject' as const }, answeredAt: '2026-11-01T10:02:00.000Z', claudesGuess: { option: 1 } };
  await send(page, hostMessage('run', { run: runView({ answered: [answeredModality({ answer: { question: 0, choice: { kind: 'option', option: 0 }, scope: 'nodes' } }), generic] }) }));
  await expect(page.getByTestId('question-set')).toHaveCount(0);
  const answered = page.getByTestId('answered-question');
  await expect(answered).toHaveCount(2);
  await expect(answered.nth(0).getByTestId('your-answer')).toHaveText('Your answer: A rule (normative) (for these cards)');
  await expect(answered.nth(0).getByTestId('claudes-guess')).toHaveText('Claude’s guess: A rule (normative) · Ratings usually express rules about content.');
  await expect(answered.nth(1).getByTestId('your-answer')).toContainText('Every one, but only');
  await expect(answered.nth(1).getByTestId('your-answer').locator('[data-provenance="user"]')).toHaveCount(1);
  await expect(answered.nth(1).getByTestId('claudes-guess')).toHaveText('Claude’s guess: Typical ones');
  await page.screenshot({ path: shotPath('m2-questions-answered.png') });
});

test('AT6.3 "Leave it open" and "Decide for me" are answers too; the card is disabled while the answer is sent', async ({ page }) => {
  board = await openBoard(page, spyroGraph(), 'light', { workspace: workspaceState(), run: waitingRun([MODALITY_QUESTION]), clock: UPDATED, autoReply: false });
  const set = page.getByTestId('question-set');
  await expect(set.getByTestId('send-answers')).toHaveText('Send answer');
  await set.getByTestId('option-leave-open').click();
  await set.getByTestId('send-answers').click();
  // Until the host answers, the card cannot be sent twice.
  await expect(set.getByTestId('send-answers')).toHaveText('Sending…');
  await expect(set.getByTestId('send-answers')).toBeDisabled();
  await expect(set.getByTestId('question').locator('input').first()).toBeDisabled();
  await send(page, hostMessage('actionResult', { requestId: 'r1', outcome: { ok: false, code: 'conflict', error: 'The run is no longer waiting for this answer.' } }));
  await expect(page.getByTestId('toast').filter({ hasText: 'The run is no longer waiting for this answer.' })).toBeVisible();
  await expect(set.getByTestId('send-answers')).toBeEnabled();
  await set.getByTestId('option-decide-for-me').click();
  await set.getByTestId('send-answers').click();
  expect((await postedOfType(page, 'answerQuestions')).map((m) => m.payload.answers)).toEqual([
    [{ question: 0, choice: { kind: 'leave-open' }, scope: 'run' }],
    [{ question: 0, choice: { kind: 'decide-for-me' }, scope: 'run' }],
  ]);
});

/**
 * M2 end-of-round review (D-19; AT6.4): statements first (the sentence beside its Lean, the explicit toggle, the
 * closure), then new vocabulary (revocable: prefilled Feedback), definition questions (Accept disabled until every
 * one is "yes"; "no" opens Feedback), the report card (revealed after the statements, or on "Show result"; each
 * assumption made without asking has "Ask me instead"), lifecycle ticks (recommended ones pre-ticked); Accept,
 * Feedback, Discard and Raw Lean diff post their messages.
 */
import { expect, test, type Page } from '@playwright/test';
import { hostMessage, spyroGraph, type ProposalView } from '@telelean/core';
import { workspaceState } from '../shared/graphs';
import { definitionProposal, normativeProposal, reviewRun, RUN_ID, UPDATED } from '../shared/runs';
import { openBoard, postedOfType, send, shotPath, type OpenedBoard } from './helpers';

let board: OpenedBoard | undefined;

test.afterEach(async () => {
  if (board) expect(await board.problems()).toEqual([]);
  board = undefined;
});

/** Opens the current board, then delivers the run in review and its proposal (as the host does). */
async function openReview(page: Page, proposal: ProposalView, theme: 'dark' | 'light' = 'dark') {
  board = await openBoard(page, spyroGraph(), theme, { workspace: workspaceState(), clock: UPDATED });
  await send(page, hostMessage('run', { run: reviewRun(proposal) }));
  await send(page, hostMessage('proposal', { proposal }));
  return page.getByTestId('review');
}

test('AT6.4 the review runs statements -> vocabulary -> definitions -> report card -> lifecycle; Accept waits for every definition', async ({ page }) => {
  const review = await openReview(page, definitionProposal());
  const step = review.getByTestId('review-step');
  await expect(review.getByTestId('review-progress')).toHaveText('Step 1 of 6: Statement 1');
  await expect(review.locator('.tl-review__step')).toHaveText(['Statement 1', 'Statement 2', 'New vocabulary', 'Definitions (2)', 'Result', 'Card changes']);
  await expect(review.locator('.tl-review__step[data-step-kind="result"]')).toHaveAttribute('data-locked', 'true');

  // 1. The statement: the user's sentence beside the Lean, the explicit form on request, the closure.
  await expect(step).toHaveAttribute('data-step', 'statement');
  await expect(step.getByTestId('statement-sentence')).toHaveText('SentencePG games cannot have characters with dark pasts');
  await expect(step.getByTestId('statement-sentence').locator('[data-provenance="user"]')).toHaveCount(1);
  const lean = step.getByTestId('statement-lean');
  await expect(lean).toHaveText('∀ (g : Game) (c : Character), IsPG g → HasDarkPast c → ¬InGame c g');
  await step.getByTestId('explicit-toggle').check();
  await expect(lean).toHaveText('∀ (g : Spyro.Game) (c : Spyro.Character), Spyro.IsPG g → Spyro.HasDarkPast c → Not (Spyro.InGame c g)');
  await expect(step.getByTestId('statement-closure').locator('.tl-closure__name')).toHaveText(['Game', 'Character', 'IsPG', 'HasDarkPast', 'InGame']);
  // The result is not on screen yet: no report card, no verdict in the banner or the state line (D-19).
  await expect(page.getByTestId('report-card')).toHaveCount(0);
  await expect(page.getByTestId('proposal-banner')).not.toContainText('proved');
  await expect(page.getByTestId('run-state')).toHaveText('Ready for review');
  await page.screenshot({ path: shotPath('m2-review-statement.png') });

  // 2. The second statement is the adopted suggestion: Claude's wording.
  await review.getByTestId('review-next').click();
  await expect(review.getByTestId('review-progress')).toHaveText('Step 2 of 6: Statement 2');
  await expect(step.getByTestId('statement-sentence').locator('[data-provenance="agent"]')).toContainText('A character who cannot be in a game');
  await expect(step.getByTestId('statement-lean')).toHaveText('∀ (c : Character) (g : Game), ¬InGame c g → ¬GoodAddition c g'); // explicit is per statement

  // 3. New vocabulary (going past the statements reveals the result); revoking is prefilled Feedback.
  await review.getByTestId('review-next').click();
  await expect(step).toHaveAttribute('data-step', 'vocabulary');
  await expect(review.getByTestId('show-result')).toHaveCount(0);
  await expect(page.getByTestId('run-state')).toHaveText('Ready for review · proved');
  await expect(step.getByTestId('vocabulary-item')).toHaveCount(1);
  await step.getByTestId('revoke-vocabulary').click();
  const feedback = page.getByTestId('feedback-text');
  await expect(feedback).toHaveValue("Please don't add the vocabulary item `InGame` (“is in”): ");
  await expect(feedback).toBeFocused();

  // 4. Definition questions: Accept is disabled until each is "yes"; "no" opens Feedback, prefilled.
  await review.getByTestId('review-next').click();
  await expect(step).toHaveAttribute('data-step', 'definitions');
  const accept = review.getByTestId('accept');
  await expect(accept).toBeDisabled();
  await expect(page.getByTestId('banner-accept')).toBeDisabled();
  await expect(review.getByTestId('accept-blocked')).toBeVisible();
  const d1 = step.locator('[data-definition-id="d1"]');
  const d2 = step.locator('[data-definition-id="d2"]');
  await expect(d1.locator('pre')).toHaveText('/-- is in -/\ndef InGame (c : Character) (g : Game) : Prop := GoodAddition c g');
  await expect(d1).toContainText('Your statements rely on it:');
  await d1.getByTestId('definition-yes').click();
  await expect(accept).toBeDisabled();
  await d2.getByTestId('definition-no').click();
  await expect(feedback).toHaveValue("Please don't add the vocabulary item `InGame` (“is in”): \nI don't endorse the definition `Spyro.Rating.exists` (“there is at least one rating”): ");
  await expect(accept).toBeDisabled();
  await d2.getByTestId('definition-yes').click();
  await expect(accept).toBeEnabled();
  await expect(page.getByTestId('banner-accept')).toBeEnabled();
  await page.screenshot({ path: shotPath('m2-review-definitions.png') });

  // 5. The report card: verdict, footprint, Claude's words, gate attempts; "Ask me instead" per unasked choice.
  await review.getByTestId('review-next').click();
  const card = page.getByTestId('report-card');
  await expect(card.getByTestId('report-verdict')).toHaveText('proved: ACynder would not be a good addition to the new Spyro game');
  await expect(card.getByTestId('report-footprint').locator('li')).toHaveCount(6);
  await expect(card.getByTestId('report-footprint').locator('.tl-presup')).toHaveText(['assumes characters exist', 'assumes games exist']);
  await expect(card.getByTestId('report-consistency')).toContainText('Consistency unchecked');
  await expect(card.getByTestId('report-summary')).toContainText('Proved with the premise you adopted.');
  const assumed = card.getByTestId('assumed-item');
  await expect(assumed).toHaveCount(2);
  await feedback.fill('');
  await assumed.first().getByTestId('ask-me-instead').click();
  await expect(feedback).toHaveValue('You assumed this without asking: “"cannot have" read literally, as you answered”. Please ask me about it instead of assuming it.');
  await card.getByTestId('report-gate-attempts').locator('summary').click();
  await expect(card.getByTestId('report-gate-attempts')).toContainText('Attempt 1 (round 2): didn’t pass');
  await expect(card.getByTestId('report-gate-attempts')).toContainText('it left a gap (sorry) in cynder_not_good.holds');
  await page.screenshot({ path: shotPath('m2-review-report.png') });

  // 6. Lifecycle: the recommended item starts ticked, the other does not.
  await review.getByTestId('review-next').click();
  await expect(step).toHaveAttribute('data-step', 'lifecycle');
  await expect(step.locator('[data-lifecycle-id="l1"] input')).toBeChecked();
  await expect(step.locator('[data-lifecycle-id="l2"] input')).not.toBeChecked();
  await expect(step.locator('[data-lifecycle-id="l1"]')).toContainText('Make “Cynder would not be a good addition to the new Spyro game” a Derivation (Lean proved it from the selected premises; recommended)');
  await step.locator('[data-lifecycle-id="l2"] input').check();
  await expect(review.getByTestId('review-next')).toBeDisabled();

  await accept.click();
  expect((await postedOfType(page, 'acceptProposal')).map((m) => m.payload)).toEqual([
    { runId: RUN_ID, proposalId: 'p3', lifecycle: ['l1', 'l2'], definitions: ['d1', 'd2'], requestId: 'r1' },
  ]);
  expect(await postedOfType(page, 'feedback')).toEqual([]);
});

test('AT6.4 "Show result" reveals the report card early; Feedback, Discard and Raw Lean diff post their messages; an unticked item is left out', async ({ page }) => {
  const review = await openReview(page, normativeProposal(), 'light');
  await expect(review.getByTestId('review-progress')).toHaveText('Step 1 of 3: Statement');
  await review.getByTestId('show-result').click();
  await expect(review.getByTestId('show-result')).toHaveCount(0);
  await expect(review.getByTestId('review-step')).toHaveAttribute('data-step', 'statement'); // still on the statement
  await review.locator('.tl-review__step[data-step-kind="result"]').click();
  await expect(page.getByTestId('report-card').getByTestId('report-verdict')).toContainText('proved');
  await expect(page.getByTestId('report-card').getByTestId('assumed-without-asking')).toContainText('Nothing, according to Claude.');

  // Raw Lean diff: the whole proposal (review and banner) or one file.
  await review.getByTestId('raw-diff').click();
  await page.getByTestId('banner-raw-diff').click();
  await page.getByTestId('report-files').getByRole('button', { name: /diff/ }).click();
  expect((await postedOfType(page, 'openProposalDiff')).map((m) => m.payload)).toEqual([
    { runId: RUN_ID, proposalId: 'p1' },
    { runId: RUN_ID, proposalId: 'p1' },
    { runId: RUN_ID, proposalId: 'p1', file: 'Model/Spyro/Main.lean' },
  ]);

  // Feedback: a text field that keeps line breaks; Ctrl+Enter or the button sends it.
  await page.getByTestId('banner-feedback').click();
  const feedback = page.getByTestId('feedback-text');
  await expect(feedback).toBeFocused();
  await feedback.fill('Keep the rule general.\nAnd say why it applies to Cynder.');
  await page.getByTestId('send-feedback').click();
  expect((await postedOfType(page, 'feedback')).map((m) => m.payload)).toEqual([{ runId: RUN_ID, text: 'Keep the rule general.\nAnd say why it applies to Cynder.', requestId: 'r1' }]);

  // Accept with the recommended item unticked sends no lifecycle id.
  await review.locator('.tl-review__step[data-step-kind="lifecycle"]').click();
  await review.locator('[data-lifecycle-id="l1"] input').uncheck();
  await page.getByTestId('banner-accept').click();
  await review.getByTestId('discard').click();
  expect((await postedOfType(page, 'acceptProposal')).map((m) => m.payload)).toEqual([{ runId: RUN_ID, proposalId: 'p1', lifecycle: [], definitions: [], requestId: 'r2' }]);
  expect((await postedOfType(page, 'discardProposal')).map((m) => m.payload)).toEqual([{ runId: RUN_ID, requestId: 'r3' }]);

  // The host withdraws the proposal (e.g. after Feedback): the review and the banner go away.
  await send(page, hostMessage('proposal', { proposal: null }));
  await send(page, hostMessage('run', { run: reviewRun(normativeProposal(), { state: 'working', round: 2, proposalId: undefined }) }));
  await expect(page.getByTestId('review')).toHaveCount(0);
  await expect(page.getByTestId('proposal-banner')).toHaveCount(0);
});

/**
 * M2 proposal overlay (AT6.5): the Current | Proposed toggle; diff marks with a glyph, a word, a colour and a halo
 * (never colour alone); "+N new" vocabulary opened in the proposed view; the result hidden until the review reveals it
 * (D-19); translucent "Claude suggests" cards with "I hold this" (optional why) and "No". And the attempts history in
 * the expanded card (AT6.6).
 */
import { expect, test, type Locator, type Page } from '@playwright/test';
import { hostMessage, spyroGraph, type ProposalView } from '@telelean/core';
import { workspaceState } from '../shared/graphs';
import { ADOPTED_ID, adoptedProposal, attemptsGraph, literalGhost, literalProposal, reviewRun, RUN_ID, TARGET, UPDATED } from '../shared/runs';
import { card, list, openBoard, postedOfType, send, shotPath, type OpenedBoard } from './helpers';

let board: OpenedBoard | undefined;

test.afterEach(async () => {
  if (board) expect(await board.problems()).toEqual([]);
  board = undefined;
});

/** The harness's fallbacks for VS Code's git colours (board.css: --tl-diff-*). */
const ADDED = 'rgb(129, 184, 139)';
const CHANGED = 'rgb(226, 192, 141)';

async function openProposal(page: Page, proposal: ProposalView) {
  board = await openBoard(page, spyroGraph(), 'dark', { workspace: workspaceState(), clock: UPDATED });
  await send(page, hostMessage('run', { run: reviewRun(proposal) }));
  await send(page, hostMessage('proposal', { proposal }));
}

const style = (locator: Locator, property: 'color' | 'boxShadow' | 'opacity' | 'borderTopStyle' | 'fontStyle') =>
  locator.evaluate((el, p) => getComputedStyle(el)[p], property);

test('AT6.5 the overlay: Current | Proposed; diff marks with glyph, word, colour and halo; "+N new" vocabulary open; the result hidden until revealed', async ({ page }) => {
  await openProposal(page, adoptedProposal());
  const toggle = page.getByTestId('proposal-toggle');
  // A new proposal switches the board to it.
  await expect(toggle.getByRole('radio', { name: 'Proposed' })).toHaveAttribute('aria-checked', 'true');
  await expect(page.locator('.tl-board')).toHaveAttribute('data-view', 'proposed');
  await expect(page.getByTestId('proposal-counts')).toHaveText('1 new · 2 changed · +1 vocabulary');
  await expect(page.locator('[data-node-id]')).toHaveCount(5);

  // Diff marks: glyph + word + colour + halo.
  const adopted = card(page, ADOPTED_ID);
  await expect(adopted).toHaveAttribute('data-diff', 'added');
  await expect(adopted.getByTestId('diff-badge')).toHaveText('+new');
  expect(await style(adopted.getByTestId('diff-badge'), 'color')).toBe(ADDED);
  expect(await style(adopted, 'boxShadow')).toContain(ADDED);
  const rule = card(page, 'pg-no-dark-past');
  await expect(rule.getByTestId('diff-badge')).toHaveText('~changed');
  await expect(rule.getByTestId('diff-badge')).toHaveAttribute('title', 'Changed in the proposal: Lean statement, Lean binding');
  expect(await style(rule.getByTestId('diff-badge'), 'color')).toBe(CHANGED);
  expect(await style(rule, 'boxShadow')).toContain(CHANGED);
  await expect(card(page, 'cynder-dark-past')).not.toHaveAttribute('data-diff', /.*/);
  // The adopted card keeps Claude's wording style.
  expect(await style(adopted.locator('.tl-card__text'), 'fontStyle')).toBe('italic');
  await expect(adopted.locator('.tl-card__agent-marker')).toHaveText(" (Claude's wording)");

  // D-19: the target's result stays hidden (no proof chip, no verified arrows into it) until the review reveals it.
  const goal = card(page, TARGET);
  await expect(goal.locator('[data-chip="result-hidden"]')).toHaveText('result after the review');
  await expect(goal.locator('[data-chip="proved-goal"]')).toHaveCount(0);
  await expect(goal.getByTestId('diff-badge')).toHaveAttribute('title', 'Changed in the proposal');
  await expect(page.locator(`path[data-target="${TARGET}"][data-pattern="verified"]`)).toHaveCount(0);

  // "+1 new": the Vocabulary group is open in the proposed view and marks the new item.
  const vocabulary = page.getByTestId('vocabulary');
  await expect(vocabulary).not.toHaveAttribute('data-collapsed', /.*/);
  await expect(vocabulary.getByTestId('vocab-new')).toHaveText('+1 new');
  const inGame = page.locator('.tl-vocab__item[data-vocab="Spyro.InGame"]');
  await expect(inGame).toHaveAttribute('data-diff', 'added');
  await expect(inGame.getByTestId('diff-badge')).toHaveText('+new');
  await expect(inGame.locator('.tl-vocab__gloss')).toHaveAttribute('data-provenance', 'agent');
  await page.screenshot({ path: shotPath('m2-overlay-proposed.png') });

  // Read-only: a click selects nothing; the expanded card offers no edits.
  await rule.click();
  expect(await postedOfType(page, 'select')).toEqual([]);
  await rule.locator('.tl-card__chevron').click();
  await expect(rule.getByRole('button', { name: 'Delete' })).toHaveCount(0);
  await expect(rule).toContainText('This is Claude’s proposal (read-only)');

  // Current: the user's files as they are (no marks, the user's own collapsed vocabulary).
  await toggle.getByRole('radio', { name: 'Current' }).click();
  await expect(page.locator('.tl-board')).toHaveAttribute('data-view', 'current');
  await expect(page.locator('[data-node-id]')).toHaveCount(4);
  await expect(page.locator('[data-diff]')).toHaveCount(0);
  await expect(vocabulary).toHaveAttribute('data-collapsed', 'true');
  await expect(card(page, ADOPTED_ID)).toHaveCount(0);

  // Revealing the result (the review's "Show result") shows the target's proof in the proposed view.
  await page.getByTestId('show-result').click();
  await toggle.getByRole('radio', { name: 'Proposed' }).click();
  await expect(goal.locator('[data-chip="proved-goal"]')).toContainText('proved');
  await expect(goal.locator('[data-chip="result-hidden"]')).toHaveCount(0);
  await expect(page.locator(`path[data-target="${TARGET}"][data-pattern="verified"]`)).not.toHaveCount(0);
  await page.screenshot({ path: shotPath('m2-overlay-revealed.png') });
});

test('AT6.5 "Claude suggests": translucent ghost cards, "I hold this" with an optional reason posts adoptGhost, "No" posts rejectGhost', async ({ page }) => {
  const alone = literalGhost({ id: 'ghost-2', naturalName: 'Cynder would not be a good addition to it', leanStatement: '¬ GoodAddition cynder newSpyro', leanName: 'cynder_not_good_2', aloneEntails: true });
  await openProposal(page, literalProposal({ ghosts: [literalGhost(), alone] }));
  await send(page, hostMessage('run', { run: reviewRun(literalProposal(), { ghosts: [literalGhost(), alone] }) }));
  const column = list(page, 'ASSUMPTION');
  const ghost = column.locator('[data-ghost-id="ghost-1"]');
  await expect(ghost).toBeVisible();
  await expect(ghost.locator('.tl-ghost__marker')).toHaveText('Claude suggests');
  expect(Number(await style(ghost, 'opacity'))).toBeLessThan(1);
  expect(await style(ghost, 'borderTopStyle')).toBe('solid'); // dashing is reserved for declared support
  expect(await style(ghost.getByTestId('ghost-sentence'), 'fontStyle')).toBe('italic');
  await expect(ghost.getByTestId('ghost-lean')).toHaveText('∀ (c : Character) (g : Game), ¬ InGame c g → ¬ GoodAddition c g');
  await expect(ghost.locator('[data-chip="closes-gap"]')).toHaveText('closes the gap (checked)');
  await expect(ghost.locator('[data-chip="alone-entails"]')).toHaveCount(0);
  await expect(column.locator('[data-ghost-id="ghost-2"] [data-chip="alone-entails"]')).toContainText('gives the goal on its own');
  // Ghost cards are not cards of the model: no data-node-id, so no arrows attach to them.
  await expect(ghost.locator('[data-node-id]')).toHaveCount(0);
  await expect(page.locator('[data-node-id]')).toHaveCount(4);
  await page.screenshot({ path: shotPath('m2-ghosts.png') });

  // I hold this -> the optional reason -> Adopt.
  await ghost.getByRole('button', { name: 'I hold this' }).click();
  const why = ghost.getByRole('textbox', { name: 'Why do you hold it? (optional)' });
  await expect(why).toBeFocused();
  await why.fill('it seems obvious to me');
  await why.press('Enter');
  // Without a reason, from the report card's copy of the suggestion.
  await page.getByTestId('show-result').click();
  await page.getByTestId('review').locator('.tl-review__step[data-step-kind="result"]').click();
  const inReport = page.getByTestId('report-suggestions').locator('[data-ghost-id="ghost-2"]');
  await inReport.getByRole('button', { name: 'I hold this' }).click();
  await inReport.getByRole('button', { name: 'Adopt' }).click();
  expect((await postedOfType(page, 'adoptGhost')).map((m) => m.payload)).toEqual([
    { runId: RUN_ID, ghostId: 'ghost-1', rationale: 'it seems obvious to me', requestId: 'r1' },
    { runId: RUN_ID, ghostId: 'ghost-2', requestId: 'r2' },
  ]);

  await ghost.getByRole('button', { name: 'No' }).click();
  expect((await postedOfType(page, 'rejectGhost')).map((m) => m.payload)).toEqual([{ runId: RUN_ID, ghostId: 'ghost-1', requestId: 'r3' }]);
  // The host marks it rejected: its card goes.
  await send(page, hostMessage('run', { run: reviewRun(literalProposal(), { ghosts: [literalGhost({ state: 'rejected' }), alone] }) }));
  await expect(column.locator('[data-ghost-id="ghost-1"]')).toHaveCount(0);
  await expect(column.locator('[data-ghost-id="ghost-2"]')).toHaveCount(1);
  // In the Current view there are no suggestions on the board.
  await page.getByTestId('proposal-toggle').getByRole('radio', { name: 'Current' }).click();
  await expect(column.locator('[data-ghost-id]')).toHaveCount(0);
});

test('AT6.6 the expanded card lists its attempts: date, verdict, premises, resolution, Claude’s summary in italics', async ({ page }) => {
  board = await openBoard(page, attemptsGraph(), 'dark', { workspace: workspaceState(), clock: '2026-11-01T12:00:00.000Z' });
  const goal = card(page, TARGET);
  await goal.locator('.tl-card__chevron').click();
  const attempts = goal.getByTestId('attempt');
  await expect(attempts).toHaveCount(3);
  await expect(attempts.getByTestId('attempt-verdict')).toHaveText(['proved', 'not proved', "gave up: Claude's attempts kept failing the checks"]);
  await expect(attempts.getByTestId('attempt-resolution')).toHaveText(['accepted', 'continued in a later round', 'discarded']);
  const dates = await attempts.getByTestId('attempt-date').allTextContents();
  expect(dates[0]).toMatch(/^\d{2}:\d{2}$/); // today
  expect(dates[2]).toMatch(/^Oct 3[01] \d{2}:\d{2}$/);
  await expect(attempts.nth(1).getByTestId('attempt-premises')).toHaveText(
    'from “Cynder is a character who has a dark past”, “The new Spyro game is PG”, “PG games cannot have characters with dark pasts”',
  );
  await expect(attempts.nth(2).getByTestId('attempt-premises')).toHaveText('from “Cynder is a character who has a dark past”');
  const summary = attempts.first().getByTestId('attempt-summary');
  await expect(summary).toContainText('Proved with the premise you adopted.');
  await expect(summary).toHaveAttribute('data-provenance', 'agent');
  expect(await style(summary.locator('.tl-agent__text'), 'fontStyle')).toBe('italic');
  await expect(summary.locator('.tl-agent__marker')).toHaveText(" (Claude's words)");
  await page.screenshot({ path: shotPath('m2-attempts.png') });
  // Another card lists only its own attempts.
  const rule = card(page, 'pg-no-dark-past');
  await rule.locator('.tl-card__chevron').click();
  await expect(rule.getByTestId('attempt')).toHaveCount(1);
  await expect(rule.getByTestId('attempt-premises')).toHaveText('from no premises (self-evident?)');
  await expect(card(page, 'new-spyro-pg').getByTestId('attempts')).toHaveCount(0);
});

/**
 * The M1 carry-overs on the board (docs/m2-plan.md section 1.3):
 *  (1) AT6.7 "Used by" and the delete dialog list the card's users outside the board (`LeanBinding.externalUsers`);
 *      "Nothing else refers to it." only when nothing on the board and nothing outside refers to it;
 *  (2) AT6.8 the dependents dialog's own words are singular for one dependent and plural for more (core's own
 *      singular texts are asserted in m1-drag.spec.ts and store.test.ts, gated on WP1);
 *  (3) AT6.9 a kind change posts the dependents the dialog listed (`confirmedDependents`); a host that finds more
 *      re-opens the dialog with its list.
 */
import { expect, test } from '@playwright/test';
import { hostMessage, spyroProvedGraph } from '@telelean/core';
import { conditionalGraph } from '../shared/graphs';
import { externalUsersGraph, TARGET } from '../shared/runs';
import { card, columnPoint, dragCard, list, openBoard, postedOfType, replyNext, send, shotPath, type OpenedBoard } from './helpers';

let board: OpenedBoard | undefined;

test.afterEach(async () => {
  if (board) expect(await board.problems()).toEqual([]);
  board = undefined;
});

test('AT6.7 "Used by" lists users outside the board: a lemma in code font, another subject’s card by its sentence and subject', async ({ page }) => {
  board = await openBoard(page, externalUsersGraph(), 'dark');
  const dark = card(page, 'cynder-dark-past');
  await dark.locator('.tl-card__chevron').click();
  const usedBy = dark.getByTestId('used-by');
  await expect(usedBy.locator('.tl-rel__text')).toHaveText(['Cynder would not be a good addition to the new Spyro game']);
  const external = usedBy.getByTestId('external-user');
  await expect(external).toHaveCount(2);
  await expect(external.nth(0).locator('code')).toHaveText('Spyro.helper_lemma');
  await expect(external.nth(0)).toContainText('uses it in a proof');
  await expect(external.nth(1)).toHaveText('Bayonetta would not be a good addition either (subject Bayonetta)uses it in a proof');
  await expect(external.nth(1).locator('code')).toHaveCount(0);

  // The goal: no card of this board uses it, but a lemma mentions it, so it is not "Nothing uses it yet".
  const goal = card(page, TARGET);
  await goal.locator('.tl-card__chevron').click();
  await expect(goal.getByTestId('used-by')).not.toContainText('Nothing uses it yet.');
  await expect(goal.getByTestId('used-by').getByTestId('external-user')).toHaveText('Spyro.cynder_lemmamentions it in its statement');
  await page.screenshot({ path: shotPath('m2-used-by-external.png') });
});

test('AT6.7 the delete dialog lists users outside the board; "Nothing else refers to it." only when nothing does', async ({ page }) => {
  board = await openBoard(page, externalUsersGraph(), 'dark');
  const dialog = page.getByTestId('dialog-delete');
  const goal = card(page, TARGET);
  await goal.locator('.tl-card__chevron').click();
  await goal.getByRole('button', { name: 'Delete' }).click();
  await expect(dialog).toBeVisible();
  await expect(dialog).not.toContainText('Nothing else refers to it.');
  await expect(dialog.getByTestId('delete-external')).toContainText('Also used outside this board');
  await expect(dialog.getByTestId('delete-external').locator('code')).toHaveText(['Spyro.cynder_lemma']);
  await page.screenshot({ path: shotPath('m2-delete-external.png') });
  await dialog.getByRole('button', { name: 'Cancel' }).click();

  // An assumption used on the board and outside it: both are listed.
  const dark = card(page, 'cynder-dark-past');
  await dark.locator('.tl-card__chevron').click();
  await dark.getByRole('button', { name: 'Delete' }).click();
  await expect(dialog.getByTestId('delete-proofs')).toContainText('Cynder would not be a good addition to the new Spyro game');
  await expect(dialog.getByTestId('delete-external').locator('li')).toHaveText([
    'Spyro.helper_lemmauses it in a proof',
    'Bayonetta would not be a good addition either (subject Bayonetta)uses it in a proof',
  ]);
  await dialog.getByRole('button', { name: 'Cancel' }).click();

  // Nothing on the board and nothing outside: only then "Nothing else refers to it."
  await send(page, hostMessage('graph', { graph: spyroProvedGraph(99) }));
  await card(page, TARGET).getByRole('button', { name: 'Delete' }).click();
  await expect(dialog).toContainText('Nothing else refers to it.');
  await expect(dialog.getByTestId('delete-external')).toHaveCount(0);
});

test('AT6.8 the dependents dialog speaks of one dependent in the singular and of several in the plural', async ({ page }) => {
  board = await openBoard(page, spyroProvedGraph(), 'dark');
  const dialog = page.getByTestId('dialog-dependents');
  // A->G with one proof using it.
  await dragCard(page, 'cynder-dark-past', await columnPoint(page, 'GOAL'));
  await expect(dialog.getByTestId('dependents-intro')).toHaveText('This uses it:');
  await expect(dialog.getByRole('button')).toHaveText(['Rewrite that proof to take it as a hypothesis', 'Keep that proof, marked broken', 'Cancel']);
  await dialog.getByRole('button', { name: 'Cancel' }).click();
  // The host lists two: plural.
  await replyNext(page, 'kindChange', { ok: false, code: 'needs-confirmation', error: '2 proofs use new_spyro_pg.holds', dependents: [TARGET, 'Spyro.helper_lemma'] });
  const goal = card(page, TARGET);
  await goal.locator('.tl-card__chevron').click();
  await goal.getByRole('button', { name: 'Make Assumption' }).click();
  await page.getByTestId('dialog-rationale').getByRole('button', { name: 'Skip' }).click();
  await expect(dialog.getByRole('heading')).toHaveText('Make Assumption: 2 dependents need a rewrite');
  await expect(dialog.getByTestId('dependents-intro')).toHaveText('These pass it arguments:');
  await expect(dialog.getByRole('button')).toHaveText(['Rewrite them to use it directly', 'Keep them, marked broken', 'Cancel']);
  await page.screenshot({ path: shotPath('m2-dependents-plural.png') });
  await dialog.getByRole('button', { name: 'Cancel' }).click();
});

test('AT6.8 D->A with one dependent: "Rewrite that proof to use it directly", "Keep that proof, marked broken"', async ({ page }) => {
  board = await openBoard(page, conditionalGraph(), 'light');
  const d1 = card(page, 'd1');
  await d1.locator('.tl-card__chevron').click();
  await d1.getByRole('button', { name: 'Make Assumption' }).click();
  const dialog = page.getByTestId('dialog-dependents');
  await expect(dialog.getByTestId('dependents-intro')).toHaveText('This passes it arguments:');
  await expect(dialog.getByRole('button')).toHaveText(['Rewrite that proof to use it directly', 'Keep that proof, marked broken', 'Cancel']);
});

test('AT6.9 the choice names the dependents the dialog listed; a host that finds more re-opens the dialog with its list, which is posted with the next choice', async ({ page }) => {
  board = await openBoard(page, spyroProvedGraph(), 'dark');
  const dialog = page.getByTestId('dialog-dependents');
  await dragCard(page, 'cynder-dark-past', await columnPoint(page, 'GOAL'));
  await expect(dialog.getByTestId('dependents').locator('li')).toHaveText(['GCynder would not be a good addition to the new Spyro game']);
  // The host's facts know a lemma the board does not show: it refuses the choice and lists every dependent.
  await replyNext(page, 'kindChange', {
    ok: false,
    code: 'needs-confirmation',
    error: 'cynder_dark_past.holds will be removed, but 2 dependents use it: rewrite them to take it as a hypothesis, or keep them and let them show as broken.',
    dependents: [TARGET, 'Spyro.helper_lemma'],
  });
  await dialog.getByRole('button', { name: 'Rewrite that proof to take it as a hypothesis' }).click();
  await expect(dialog).toBeVisible();
  await expect(dialog.getByTestId('dependents-relisted')).toContainText('found more that uses it than this dialog listed before');
  await expect(dialog.getByTestId('dependents').locator('li')).toHaveText(['GCynder would not be a good addition to the new Spyro game', 'Spyro.helper_lemma']);
  await expect(dialog.getByRole('heading')).toHaveText('Make Goal: 2 dependents need a hypothesis rewrite');
  await expect(list(page, 'ASSUMPTION').locator('[data-node-id="cynder-dark-past"]')).toHaveCount(1); // rolled back while it asks
  await page.screenshot({ path: shotPath('m2-dependents-relisted.png') });
  await dialog.getByRole('button', { name: 'Keep them, marked broken' }).click();
  expect((await postedOfType(page, 'kindChange')).map((m) => m.payload)).toEqual([
    { id: 'cynder-dark-past', from: 'ASSUMPTION', to: 'GOAL', beforeId: null, requestId: 'r1', dependents: 'rewrite', confirmedDependents: [TARGET] },
    { id: 'cynder-dark-past', from: 'ASSUMPTION', to: 'GOAL', beforeId: null, requestId: 'r2', dependents: 'mark-broken', confirmedDependents: [TARGET, 'Spyro.helper_lemma'] },
  ]);

  // Asked again about nothing new, the board does not loop: it says why instead.
  await replyNext(page, 'kindChange', { ok: false, code: 'needs-confirmation', error: 'Still refused: the files changed meanwhile.', dependents: [TARGET] });
  await dragCard(page, 'cynder-dark-past', await columnPoint(page, 'GOAL'));
  await dialog.getByRole('button', { name: 'Keep that proof, marked broken' }).click();
  await expect(page.getByTestId('toast').filter({ hasText: 'Still refused: the files changed meanwhile.' })).toBeVisible();
  await expect(dialog).toHaveCount(0);
});

