        if (ref.range.start.line < start.line || ref.range.end.line > end.line) continue;
        const shift = (p: { line: number; character: number }) => ({
          line: p.line - start.line + lineOffset,
          character: p.line === start.line ? p.character - start.character : p.character,
        });
        refs.push({ name: ref.name, range: { start: shift(ref.range.start), end: shift(ref.range.end) }, ...(nodeRef && owner !== undefined ? { nodeId: owner } : {}) });
      }
    }
    lineOffset += end.line - start.line + 2;
  }
  lean.refs = refs;
}
draft.lean = lean;

// stale / not-checked
const declFiles = [draft.statementDecl?.file.path ?? draft.statementFacts?.file, draft.holdsDecl?.file.path ?? draft.holdsFacts?.file].filter(
  (p): p is string => p !== undefined,
);
if (declFiles.some((p) => factsIndex.files.get(p)?.hashDiffers || factsIndex.stateOf(p) === 'stale')) draft.flags.add('stale');
if (draft.statementFound && (draft.statementFacts === undefined || (draft.holdsExists && draft.holdsFacts === undefined))) draft.flags.add('not-checked');

// proof (docs/m1-plan.md section 6.3 table)
if (!draft.statementFound || draft.notProp || !statement) continue;
const short = statement.split('.').pop() ?? statement;
if (!draft.holdsExists) {
  if (draft.type === 'ASSUMPTION') {
    draft.flags.add('missing-holds');
    draft.diagnostics.push({
      code: 'TL117',
      severity: 'warning',
      message: `This assumption has no \`axiom ${short}.holds : ${short}\`, so proofs cannot use it.`,
      ...at,
    });
  }
  continue;
}
const holdsFacts = draft.holdsFacts;
if (hk === 'axiom') {
  if (draft.type === 'ASSUMPTION') draft.proof = { kind: 'assumed' };
  else if (draft.type === 'DERIVATION') {
    draft.proof = { kind: 'pending-promotion' };
    draft.flags.add('claimed');
  } else {
    draft.proof = { kind: 'assumed' };
    draft.diagnostics.push({ code: 'TL116', severity: 'warning', message: `This goal is asserted as an axiom (${draft.holds}): make it an Assumption?`, ...at });
  }
  if (holdsFacts?.type !== undefined && normalizeWhitespace(holdsFacts.type) !== statement) {
    draft.flags.add('holds-mismatch');
    draft.diagnostics.push({ code: 'TL114', severity: 'error', message: `${draft.holds} does not state ${statement} (its type is ${normalizeWhitespace(holdsFacts.type)}).`, ...at });
  }
  continue;
}
// theorem (or another kind, treated like a theorem): needs Lean's facts
if (!holdsFacts || holdsFacts.type === undefined || holdsFacts.axioms === undefined) {
  draft.flags.add('not-checked');
  continue;
}
if (holdsFacts.usesSorry || holdsFacts.axioms.includes(SORRY_AXIOM)) {
  draft.flags.add('uses-sorry');
  draft.diagnostics.push({ code: 'TL115', severity: 'warning', message: 'The proof uses `sorry`.', ...at });
  continue;
}
const type = normalizeWhitespace(holdsFacts.type);
let on: string[] | undefined;
if (type === statement) on = [];
else {
  const parts = splitTopLevelArrows(type);
  if (parts.length > 1 && parts[parts.length - 1] === statement) {
    const hyps: string[] = [];
    for (const part of parts.slice(0, -1)) {
      const owner = ownerOfDecl.get(part);
      if (owner === undefined || ownerStatement(owner) !== part) {
        hyps.length = 0;
        break;
      }
      if (!hyps.includes(owner)) hyps.push(owner);
    }
    if (hyps.length > 0) on = hyps;
  }
}
if (on === undefined) {
  draft.flags.add('holds-mismatch');
  draft.diagnostics.push({ code: 'TL114', severity: 'error', message: `${draft.holds} does not state ${statement} (its type is ${type}).`, ...at });
  continue;
}
// footprint
const nodesIn: string[] = [];
const presups: string[] = [];
const others: string[] = [];
for (const axiom of holdsFacts.axioms) {
  if (STANDARD_AXIOM_NAMES.includes(axiom)) continue;
  const owner = ownerOfDecl.get(axiom);
  const ownerStmt = owner !== undefined ? ownerStatement(owner) : undefined;
  if (owner !== undefined && ownerStmt !== undefined && axiom === holdsName(ownerStmt)) {
    if (!nodesIn.includes(owner)) nodesIn.push(owner);
    continue;
  }
  if (isPresupposition(axiom)) {
    presups.push(`${PRESUPPOSITION_PREFIX}${axiom}`);
    continue;
  }
  const item = vocab.itemOfName.get(axiom);
  const kind = item !== undefined ? vocab.kindOf.get(item) : undefined;
  const harmless = kind === 'sort' || kind === 'predicate' || ((kind === 'function' || kind === 'constant') && !vocab.declaredWithAxiom.has(item ?? ''));
  if (harmless) continue;
  others.push(`axiom:${axiom}`);
  draft.diagnostics.push({
    code: 'TL103',
    severity: 'warning',
    message: `The proof uses ${axiom}, which is neither an assumption (a card's \`.holds\`) nor vocabulary.`,
    ...at,
    ...(item !== undefined ? { vocab: item } : {}),
  });
}
const footprint = [...nodesIn, ...presups, ...others];
draft.proof = on.length > 0 ? { kind: 'conditional', on, footprint } : { kind: 'proved', footprint };
if (draft.type === 'ASSUMPTION') {
  draft.flags.add('provable-assumption');
  draft.diagnostics.push({ code: 'TL106', severity: 'info', message: 'This assumption has a proof: make it a Derivation?', ...at });
} else if (draft.type === 'GOAL') {
  draft.flags.add('proved-goal');

/**
 * Which Lean facts the board may use (docs/m1-plan.md section 6.3, "Which facts"):
 *
 *  - a FRESH file (its module is `fresh` and its hash equals the facts' `sourceSha256`) uses its facts fully;
 *  - a STALE file (the hash differs, or the module went stale during the refresh) keeps a declaration's previous facts
 *    BY NAME while the declaration's current syntactic keyword agrees with the facts' kind (positions are not used);
 *  - an UNCHECKED file (failed / dependency-failed / not-built module, a file the facts do not know, or no facts at
 *    all) uses no facts: only the syntactic keyword counts.
 */
import type { DeclFacts, LeanDeclKind, LeanFacts, ModuleFacts } from '../facts.js';
import type { DeclInfo, DeclKeyword, ParsedFile } from '../markup/types.js';

export type FileFactsState = 'fresh' | 'stale' | 'unchecked';

export interface FileFactsInfo {
  state: FileFactsState;
  module?: ModuleFacts;
  /** The file's current hash differs from the hash the facts were computed from. */
  hashDiffers: boolean;
}

/** The fact kind a syntactic keyword corresponds to. */
export function keywordKind(keyword: DeclKeyword): LeanDeclKind {
  switch (keyword) {
    case 'axiom':
      return 'axiom';
    case 'theorem':
    case 'lemma':
      return 'theorem';
    case 'def':
    case 'abbrev':
      return 'def';
    case 'opaque':
      return 'opaque';
    case 'instance':
      return 'instance';
    case 'structure':
      return 'structure';
    case 'inductive':
    case 'coinductive':
      return 'inductive';
    case 'class':
    case 'class inductive':
    case 'class abbrev':
      return 'class';
    default:
      return 'other';
  }
}

/** A stale file keeps a declaration's facts while its current keyword still says the same kind of declaration. */
export function kindsAgree(keyword: DeclKeyword, kind: LeanDeclKind | undefined): boolean {
  if (kind === undefined) return true;
  const expected = keywordKind(keyword);
  if (expected === kind) return true;
  // Lean prints instances as theorems/defs and class abbrevs as defs; the semantic layer usually fixes instances up.
  if (keyword === 'instance') return kind === 'theorem' || kind === 'def';
  if (keyword === 'class abbrev') return kind === 'def';
  if (keyword === 'class' || keyword === 'class inductive') return kind === 'structure' || kind === 'inductive';
  return false;
}

export class FactsIndex {
  /** Per model file. */
  readonly files = new Map<string, FileFactsInfo>();
  /** Usable facts by fully-qualified name (fresh files fully, stale files by name). */
  readonly usable = new Map<string, DeclFacts>();
  /** Usable facts by `file` + syntactic declaration index (also covers anonymous instances matched by start line). */
  private readonly bySyntactic = new Map<string, DeclFacts>();
  /** Facts decls of fresh files that no syntactic declaration matched (e.g. constructors), per file. */
  readonly unmatched = new Map<string, DeclFacts[]>();

  constructor(
    files: readonly ParsedFile[],
    fileHashes: Readonly<Record<string, string>>,
    readonly facts: LeanFacts | undefined,
  ) {
    const modulesByFile = new Map<string, ModuleFacts>();
    for (const module of facts?.modules ?? []) if (!modulesByFile.has(module.file)) modulesByFile.set(module.file, module);
    for (const file of files) {
      const module = facts ? modulesByFile.get(file.path) : undefined;
      if (!module) {
        this.files.set(file.path, { state: 'unchecked', hashDiffers: false });
        continue;
      }
      const hashDiffers = fileHashes[file.path] !== module.sourceSha256;
      let state: FileFactsState;
      if (module.state === 'fresh') state = hashDiffers ? 'stale' : 'fresh';
      else if (module.state === 'stale') state = 'stale';
      else state = 'unchecked';
      this.files.set(file.path, { state, module, hashDiffers });
    }

    const factsByFile = new Map<string, DeclFacts[]>();
    for (const decl of facts?.decls ?? []) {
      const list = factsByFile.get(decl.file) ?? [];
      list.push(decl);
      factsByFile.set(decl.file, list);
    }
    for (const file of files) {
      const state = this.files.get(file.path)?.state ?? 'unchecked';
      const list = factsByFile.get(file.path) ?? [];
      if (state === 'unchecked' || list.length === 0) continue;
      const byName = new Map<string, DeclFacts>();
      for (const decl of list) if (!byName.has(decl.name)) byName.set(decl.name, decl);
      const matched = new Set<DeclFacts>();
      file.decls.forEach((decl, index) => {
        let found: DeclFacts | undefined;
        if (decl.fullName) found = byName.get(decl.fullName);
        else if (state === 'fresh' && decl.keyword === 'instance') {
          // Anonymous instances: Lean names them (`instNonemptyCharacter`); match by the declaration's start line.
          found = list.find((f) => !matched.has(f) && f.range.start.line === decl.range.start.line && (f.kind === undefined || kindsAgree('instance', f.kind)));
        }
        if (!found) return;
        if (state === 'stale' && !kindsAgree(decl.keyword, found.kind)) return;
        matched.add(found);
        this.bySyntactic.set(`${file.path}#${index}`, found);
        if (!this.usable.has(found.name)) this.usable.set(found.name, found);
      });
      if (state === 'fresh') {
        const rest: DeclFacts[] = [];
        for (const decl of list) {
          if (matched.has(decl)) continue;
          if (!this.usable.has(decl.name)) this.usable.set(decl.name, decl);
          rest.push(decl);
        }
        if (rest.length > 0) this.unmatched.set(file.path, rest);
      }
    }
  }

  stateOf(path: string): FileFactsState {
    return this.files.get(path)?.state ?? 'unchecked';
  }

  isFresh(path: string): boolean {
    return this.stateOf(path) === 'fresh';
  }

  /** Usable facts for a syntactic declaration of a file. */

  /** Number of Lean build errors in the facts in use. */
  errorCount?: number;
}

export interface SubjectInfo {
  /** The subject's name: its directory under the library (`Model/<name>/`) and its namespace. */
  name: string;
  nodeCount: number;
  /** Model files of the subject (POSIX, relative to the model root). */
  files: string[];
}

/** One published state of one subject's mental model. */
export interface TlGraph {
  /**
   * Increases with every publish (03 section 2, step 6), across subjects and across re-created workspaces of one
   * extension host (the runner seeds its counter from `Date.now()`), so the webview can drop queued older graphs.
   */
  version: number;
  subject: string;
  /** Column order is the order of the nodes of each type in this array (layout.json first, then file order). */
  nodes: TlNode[];
  edges: TlEdge[];
  /** The computed Vocabulary group (D-3), in display order. */
  vocabulary: VocabItem[];
  diagnostics: BoardDiagnostic[];
  semantic: SemanticSummary;
  /**
   * M2 (D-18 attempts history, docs/m2-plan.md section 6): this subject's "These suffice" rounds from
   * `.telelean/subjects/<S>/attempts.jsonl`, newest first, with their resolutions. Attached by the runner's workspace
   * after `subjectGraph` (core never reads sidecars); the expanded card lists those whose `target` is the card.
   */
  attempts?: AttemptSummary[];
}
/**
 * `.telelean/subjects/<S>/layout.json`: the column order of one subject's board (D-12; layout only, never semantics).
 * A card's column is its node's `type:`; the layout only orders cards inside a column.
 *
 * FROZEN CONTRACT (M1, docs/m1-plan.md section 7). Implemented by the architect; owned by WP-model afterwards.
 */
import type { NodeType } from './model.js';
import { isNodeType, NODE_TYPES } from './model.js';

export interface Layout {
  format: 'telelean-layout';
  version: 1;
  /** Card order per column (ids). Ids that no longer exist, or sit in the wrong column, are ignored. */
  columns: Record<NodeType, string[]>;
  /** UI state that is worth keeping with the model. */
  collapsed?: { vocabulary?: boolean };
}

export function emptyLayout(): Layout {
  return { format: 'telelean-layout', version: 1, columns: { ASSUMPTION: [], DERIVATION: [], GOAL: [] } };
}

/** Parses layout.json leniently: anything malformed yields the empty layout (layout is never worth an error). */
export function parseLayout(json: string | null | undefined): Layout {
  if (!json) return emptyLayout();
  try {
    const raw = JSON.parse(json) as { columns?: Record<string, unknown>; collapsed?: { vocabulary?: unknown } };
    const layout = emptyLayout();
    for (const [kind, ids] of Object.entries(raw.columns ?? {})) {
      if (!isNodeType(kind) || !Array.isArray(ids)) continue;
      const seen = new Set<string>();
      for (const id of ids) {
        if (typeof id === 'string' && !seen.has(id)) {
          seen.add(id);
          layout.columns[kind].push(id);
        }
      }
    }
    if (typeof raw.collapsed?.vocabulary === 'boolean') layout.collapsed = { vocabulary: raw.collapsed.vocabulary };
    return layout;
  } catch {
    return emptyLayout();
  }
}

/** Stable serialisation (2-space indent, trailing newline), so unchanged layouts produce identical files. */
export function serializeLayout(layout: Layout): string {
  const out: Record<string, unknown> = {
    format: 'telelean-layout',
    version: 1,
    columns: { ASSUMPTION: layout.columns.ASSUMPTION, DERIVATION: layout.columns.DERIVATION, GOAL: layout.columns.GOAL },
  };
  if (layout.collapsed) out['collapsed'] = layout.collapsed;
  return `${JSON.stringify(out, null, 2)}\n`;
}

/**
 * Column order for `nodes` (given in file order): ids listed in the layout's column come first, in layout order;
 * the remaining nodes of that type follow in input order.
 */
export function orderByLayout(nodes: ReadonlyArray<{ id: string; type: NodeType }>, layout?: Layout): Record<NodeType, string[]> {
  const order: Record<NodeType, string[]> = { ASSUMPTION: [], DERIVATION: [], GOAL: [] };
  const typeOf = new Map(nodes.map((n) => [n.id, n.type]));
  const placed = new Set<string>();
  for (const kind of NODE_TYPES) {
    for (const id of layout?.columns[kind] ?? []) {
      if (typeOf.get(id) === kind && !placed.has(id)) {
        order[kind].push(id);
        placed.add(id);
      }
    }
  }
  for (const node of nodes) {
    if (!placed.has(node.id)) {
      order[node.type].push(node.id);
      placed.add(node.id);
    }
  }
  return order;
}

/**
 * Markup language v1 and Lean source text (03 section 3; 02 D-8, D-9): the types shared by the lexer, parser,
 * binder, serializer and the text-edit primitives (WP-markup), and consumed by the graph builder and the edit
 * planner (WP-model) and the runner workspace (WP-workspace).
 *
 * FROZEN CONTRACT (M1, docs/m1-plan.md section 5.2). WP-markup owns this file but may only add OPTIONAL fields or new
 * exports (record them in the plan's change log); renames/removals go through the integrator.
 *
 * Offsets (`Span`) are UTF-16 code-unit indices into `ParsedFile.text` (JavaScript string indices), end exclusive.
 * Ranges follow the LSP convention (0-based line, UTF-16 character). Paths are POSIX, relative to the model root.
 */
import type { Evidential, NodeType, Range, Severity, Stance } from '../model.js';

export interface Span {
  readonly start: number;
  readonly end: number;
}

// ---------------------------------------------------------------------------------------------
// Lexer (Lean 4.35 comment/string rules: nested `/- -/`, `--` line comments, strings, chars, raw strings, «»)

export type CommentKind =
  /** `-- ...` */
  | 'line'
  /** `/- ... -/` (the only kind that can hold a telelean block) */
  | 'block'
  /** `/-- ... -/` docstring */
  | 'doc'
  /** `/-! ... -/` module docstring */
  | 'moddoc';

export interface LeanComment {
  kind: CommentKind;
  /** From the opener to just after the closer (or EOF when unterminated). */
  span: Span;
  /** The text between opener and closer. */
  body: Span;
  unterminated: boolean;
}

export type TokenKind = 'ident' | 'string' | 'char' | 'number' | 'symbol';

/** A code token outside comments (identifiers are dotted, with «escaped» parts; symbols are single characters). */
export interface LeanToken {
  kind: TokenKind;
  span: Span;
  text: string;
}

export interface LexResult {
  comments: LeanComment[];
  tokens: LeanToken[];
}

// ---------------------------------------------------------------------------------------------
// Blocks

export const MARKUP_VERSION = 1;
/** Markup versions this build interprets (a newer block is kept and shown, with TL008). */
export const SUPPORTED_MARKUP_VERSIONS: readonly number[] = [1];

/** Field keys with a meaning in v1 (03 section 3.2). `kind` is accepted as an alias of `type` and normalised. */
export type KnownFieldKey =
  | 'id'
  | 'type'
  | 'natural_name'
  | 'rationale'
  | 'stance'
  | 'source'
  | 'asserted'
  | 'premises'
  | 'lean'
  | 'supersedes'
  | 'refines'
  | 'tags'
  | 'origin'
  | 'session'
  | 'worded_by';

/** Canonical order in which the serializer writes known fields. */
export const FIELD_ORDER: readonly KnownFieldKey[] = [
  'id',
  'type',
  'natural_name',
  'rationale',
  'stance',
  'source',
  'premises',
  'asserted',
  'lean',
  'supersedes',
  'refines',
  'tags',
  'origin',
  'session',
  'worded_by',
];

/** The interpreted values of the known fields of one block. */
export interface BlockFields {
  type?: NodeType;
  naturalName?: string;
  rationale?: string;
  stance?: Stance;
  source?: Evidential;
  /** ISO date `YYYY-MM-DD`. */
  asserted?: string;
  premises?: string[];
  /** Pinned binding: fully-qualified names as written (the first is the statement). */
  lean?: string[];
  supersedes?: string;
  refines?: string;
  tags?: string[];
  origin?: 'user' | 'agent';
  session?: string;
  wordedBy?: 'user' | 'agent';
}

/** One `key: value` line of a block, as written. */
export interface FieldLine {
  /** Normalised key (`kind` -> `type`); dotted extension keys verbatim. */
  key: string;
  /** The key as written. */
  writtenKey: string;
  /** The whole line, from its first character up to (not including) its line break. */
  span: Span;
  /** The raw value text (after `:` and surrounding spaces). */
  valueSpan: Span;
  raw: string;
}

export interface BlockBinding {
  /** `pinned`: a `lean:` field; `adjacent`: the next declaration (no blank line in between); `none`: code-less. */
  mode: 'none' | 'adjacent' | 'pinned';
  /** Fully-qualified name of the statement declaration (the first `lean:` name, or the adjacent declaration's name). */
  statement?: string;
  /** All pinned names, fully qualified (a multi-name `lean:` field). */
  pinned?: string[];
  /** Index into `ParsedFile.decls` of the adjacent declaration. */
  adjacentDecl?: number;
  /** Index into `ParsedFile.decls` of a declaration that follows after a blank line (TL013 hint). */
  gapDecl?: number;
}

export interface MarkupBlock {
  /** The node id: as written, or derived from `natural_name` when absent (`idWritten: false`, TL112). */
  id: string;
  idWritten: boolean;
  version: number;
  fields: BlockFields;
  /** Dotted extension keys and unknown keys, verbatim values, in order of appearance (round-tripped untouched). */
  extensions: Record<string, string[]>;
  /** Markdown notes after `---`, dedented, with the `-\/` and `/\-` escapes kept. */
  body?: string;
  /** The whole `/- ... -/` comment. */
  span: Span;
  range: Range;
  markerSpan: Span;
  lines: FieldLine[];
  /** From the `---` line to the end of the body. */
  bodySpan?: Span;
  binding: BlockBinding;
  /**
   * Enclosing namespace components at the block, outermost first (from the file's `namespace`/`section`/`mutual`/`end`
   * commands; pinned names resolve against them). Optional: set by `parseLeanFile`.
   */
  namespace?: string[];
}

