/**
 * Shared helpers for the WP4 proposal tests: an in-memory ShadowWorkspace (WP2's real one is built in parallel), fake
 * core functions for WP1's stubs, the Spyro run states of docs/m2-plan.md section 10.2 (exact edits), and a real Lean
 * refresh of a scratch copy (M1's semantic layer, sandboxed under runLean, one job at a time).
 * Importing this module also sets the scratch git environment of ../workspace/helpers.ts.
 */
import path from 'node:path';

import {
  buildProjectModel,
  parseLeanFile,
  PASSING_COMMIT_KINDS_PLACEHOLDER,
  subjectGraph,
  type AttemptLine,
  type AttemptSummary,
  type DecisionRecord,
  type DecisionsFile,
  type FileChange,
  type GraphDiff,
  type LeanFacts,
  type LifecycleItem,
  type ProjectModel,
  type TlGraph,
} from './coreShim.js';

export {};
