/**
 * AT4.6 Accept through a REAL ModelWorkspace (real M1 core, disk TextSource/EditApplier, history on private refs) in a
 * scratch user repository: the user's hand edits made during the run are snapshotted first ("Manual edits"), then
 * the merged proposal is applied as ONE history entry of kind `accept-proposal` and one Undo step; a Lean refresh is
 * requested; the user's index, HEAD, branches, status outside the model folder, config and hooks are untouched
 * (M1's integration assertions). WP1's proposalLabel is faked; the real one is checked in the gated block.
 */
import { execFileSync } from 'node:child_process';
import { chmodSync, mkdirSync, readdirSync, readFileSync, rmSync, statSync, writeFileSync } from 'node:fs';
import path from 'node:path';

import { afterEach, describe, expect, it } from 'vitest';

import { isImplemented, proposalLabel, type LeanFacts } from '@telelean/core';

import { createProposalService, type ProposalCore } from '../../src/proposal/index.js';
import type { RefreshRequest } from '../../src/semantic/types.js';
import { createModelWorkspace, fsTextSource, type ModelWorkspace } from '../../src/workspace/index.js';
import { cleanup, copyMentalModel, fakeFacts, freshModules, makeTempDir, read, recordingApplier, sha256, userGit, waitFor, write, type RecordingApplier } from '../workspace/helpers.js';
import { edit, fakeDiff, fakeShadow, INBOX, MAIN, normativeState, SELECTION_ALL, USAGE } from './helpers.js';

const HOOKS = ['pre-commit', 'prepare-commit-msg', 'commit-msg', 'post-commit', 'reference-transaction', 'post-index-change', 'post-checkout', 'post-rewrite', 'pre-auto-gc'];
const MODEL_DIR = 'models/my model';
const RATIONALE = 'rationale: known from gaming news';
const RATIONALE_EDITED = 'rationale: known from gaming news and the trailer';

/** Everything about the user's repository that Accept must not change (M1's history test, plan 10.4). */
function repoState(repo: string): Record<string, string> {
  const gitDir = path.join(repo, '.git');
  const index = path.join(gitDir, 'index');
  return {
    head: userGit(repo, 'rev-parse', 'HEAD'),
    symbolicHead: userGit(repo, 'symbolic-ref', 'HEAD'),
    otherRefs: userGit(repo, 'for-each-ref', '--format=%(refname) %(objectname)')
      .split('\n')
      .filter((l) => l !== '' && !l.startsWith('refs/telelean/'))
      .join('\n'),
    indexMtime: String(statSync(index).mtimeMs),
    indexHash: sha256(readFileSync(index)),
    config: readFileSync(path.join(gitDir, 'config'), 'utf8'),
    hooks: readdirSync(path.join(gitDir, 'hooks')).sort().join(','),
    status: userGit(repo, 'status', '--porcelain=v1', '--untracked-files=all', '--', '.', `:(exclude)${MODEL_DIR}`),
  };
}

interface Setup {
  tmp: string;
  repo: string;
  root: string;
  markers: string;
  ws: ModelWorkspace;
  applier: RecordingApplier;
  refreshes: RefreshRequest[];
  before: Record<string, string>;
}

/** A user repository with a commit, a dirty tree, marker hooks, and the model root nested in it; the workspace loaded. */
async function setUp(label: string): Promise<Setup> {
  const tmp = makeTempDir(label);
  const repo = path.join(tmp, 'repo');
  const markers = path.join(tmp, 'hook-markers');
  mkdirSync(markers);
  mkdirSync(path.join(repo, 'models'), { recursive: true });
  const root = copyMentalModel(path.join(repo, 'models'), 'my model');
  userGit(repo, 'init', '-q', '-b', 'main');
  write(repo, 'README.md', 'user readme\n');
  write(repo, 'notes.txt', 'v1\n');
  userGit(repo, 'add', '-A');
  userGit(repo, 'commit', '-q', '-m', 'user commit');
  write(repo, 'notes.txt', 'v2 staged\n');
  userGit(repo, 'add', 'notes.txt');
  write(repo, 'README.md', 'user readme, edited\n');
  write(repo, 'untracked.txt', 'x\n');
  for (const hook of HOOKS) {
    const file = path.join(repo, '.git', 'hooks', hook);
    writeFileSync(file, `#!/bin/sh\necho ran >> "${markers}/${hook}"\n`);
    chmodSync(file, 0o755);
    execFileSync('sh', [file]); // positive control, run directly (never through git)
  }
  expect(readdirSync(markers).sort()).toEqual([...HOOKS].sort());
  for (const marker of readdirSync(markers)) rmSync(path.join(markers, marker));
  const before = repoState(repo);
  const applier = recordingApplier(root);
  const refreshes: RefreshRequest[] = [];
  const ws = createModelWorkspace({
    root,
    text: fsTextSource(root),
    applier,
    semantic: { enabled: true, debounceMs: 0 },
    refreshFacts: async (request): Promise<LeanFacts> => {
      refreshes.push(request);
      return fakeFacts('ok', { modules: freshModules(root) });
    },
    now: () => new Date('2026-11-01T12:00:00Z'),
  });
  await ws.load();
  return { tmp, repo, root, markers, ws, applier, refreshes, before };
}

/**
 * A run on the workspace as WP3 drives it: the base read through the M2 members, Claude's normative state in the
 * shadow, hand edits during the run (Inbox.lean, and new-spyro-pg's rationale in Main.lean, far from Claude's
 * changes), then build -> baseDrift -> planAccept -> apply.
 */
async function acceptRun(s: Setup, core: Partial<ProposalCore>) {
  const ws = s.ws;
  const base = new Map<string, string>();
  for (const rel of ws.modelFiles?.() ?? []) base.set(rel, (await ws.readText?.(rel)) ?? '');
  const shown = normativeState(base);
  const shadow = fakeShadow({ runDir: path.join(s.tmp, 'runs', 'r1'), root: s.root, base, current: shown });
  const service = createProposalService({ core });
  const proposal = await service.build({
    runId: 'r1',
    round: 1,
    proposalId: 'p1',
    selection: { ...SELECTION_ALL, premises: [...SELECTION_ALL.premises], adoptedGhosts: [] },
    shadow,
    check: { outcome: 'ok', g0: [], findings: [], diagnostics: [], durationMs: 1 },
    rendered: [],
    currentGraph: ws.graph('Spyro'),
    verdict: 'proved',
    finish: { status: 'proved', summary: 'Proved.', assumed_without_asking: [] },
    ghosts: [],
    gateAttempts: [],
    flaggedDefinitions: [],
    usage: USAGE,
    durationMs: 1,
    agentMs: 1,
    drift: [],
    graphVersion: 1,
  });
  // The user keeps working during the run (on disk, unknown to the workspace until Accept).
  const inboxEdited = `${read(s.root, INBOX)}-- an idea for later\n`;
  write(s.root, INBOX, inboxEdited);
  const mainEdited = edit(read(s.root, MAIN), RATIONALE, RATIONALE_EDITED);
  write(s.root, MAIN, mainEdited);
  const readReal = (rel: string) => ws.readText?.(rel) ?? Promise.resolve(null);
  const drift = await service.baseDrift(shadow, readReal, ws.modelFiles?.());
  const plan = await service.planAccept({ proposal, shadow, lifecycle: [], readReal, today: '2026-11-01', realFiles: ws.modelFiles?.() ?? [] });
  if (!plan.ok) throw new Error(`plan refused: ${JSON.stringify(plan)}`);
  const refreshesBefore = s.refreshes.length;
  const outcome = await service.apply(plan, ws, 'Spyro');
  return { base, shown, plan, drift, outcome, inboxEdited, mainEdited, refreshesBefore };
}

const FAKE_LABEL = 'These suffice → proved: (fake label)';

describe('AT4.6 apply on a real ModelWorkspace in a scratch git repository', () => {
  let setup: Setup | undefined;
  afterEach(() => {
    setup?.ws.dispose();
    if (setup) cleanup(setup.tmp);
    setup = undefined;
  });

  it('"Manual edits" first, one accept-proposal entry, one Undo restores every file, a refresh, the repository untouched', async () => {
    const s = (setup = await setUp('proposal-apply'));
    expect((await s.ws.historyStatus()).state).toBe('ready');
    expect((await s.ws.listHistory('Spyro')).entries.map((e) => e.label)).toEqual(['Initial state']);
    const run = await acceptRun(s, { diffGraphs: () => fakeDiff(), proposalLabel: () => FAKE_LABEL });

    expect(run.drift).toEqual([INBOX, MAIN]);
    expect(run.plan.drift).toEqual([INBOX, MAIN]);
    expect(run.outcome).toEqual({ ok: true, label: FAKE_LABEL, undoable: true });
    // The merged file (Claude's formalisation and proof + the user's rationale); the Inbox keeps the user's text.
    const merged = edit(run.shown.get(MAIN) ?? '', RATIONALE, RATIONALE_EDITED);
    expect(read(s.root, MAIN)).toBe(merged);
    expect(read(s.root, INBOX)).toBe(run.inboxEdited);
    expect(s.applier.calls).toEqual([{ label: FAKE_LABEL, changes: [{ path: MAIN, before: run.mainEdited, after: merged }] }]);

    // History: the hand edits were snapshotted first, then exactly one entry for the Accept.
    const history = await s.ws.listHistory('Spyro');
    expect(history.entries.map((e) => [e.action, e.label])).toEqual([
      ['accept-proposal', FAKE_LABEL],
      ['manual', 'Manual edits'],
      ['initial', 'Initial state'],
    ]);
    expect(history.entries[0]?.nodes).toEqual(['cynder-not-good', 'pg-no-dark-past']);
    const manual = await s.ws.historyDiff('Spyro', history.entries[1]?.id ?? '', 'parent');
    expect(manual.files.map((f) => [f.path, f.after])).toEqual([
      [INBOX, run.inboxEdited],
      [MAIN, run.mainEdited],
    ]);
    const accepted = await s.ws.historyDiff('Spyro', history.entries[0]?.id ?? '', 'parent');
    expect(accepted.files).toEqual([{ path: MAIN, before: run.mainEdited, after: merged }]);
    // Neither sidecar log nor anything else rode along.
    expect(accepted.files.some((f) => f.path.includes('attempts') || f.path.includes('decisions'))).toBe(false);

    // A Lean refresh of the real files was requested; the board shows the proposal's cards.
    await waitFor(() => s.refreshes.length > run.refreshesBefore);
    expect(s.ws.graph('Spyro').nodes.find((n) => n.id === 'pg-no-dark-past')?.lean.statement).toBe('Spyro.pg_no_dark_past');
    expect((await s.ws.workspaceState('Spyro')).undo).toBe(FAKE_LABEL);

    // One Undo restores every file the Accept changed (the user's own edits stay); Redo re-applies it.
    expect(await s.ws.undo('Spyro')).toEqual({ ok: true, label: `Undo: ${FAKE_LABEL}`, undoable: false });
    expect(read(s.root, MAIN)).toBe(run.mainEdited);
    expect(read(s.root, INBOX)).toBe(run.inboxEdited);
    expect((await s.ws.listHistory('Spyro')).entries[0]).toMatchObject({ action: 'undo', label: `Undo: ${FAKE_LABEL}` });
    expect((await s.ws.redo('Spyro')).ok).toBe(true);
    expect(read(s.root, MAIN)).toBe(merged);

    // The user's repository: index, HEAD, branches, status outside the model, config, hooks: untouched.
    expect(repoState(s.repo)).toEqual(s.before);
    expect(readdirSync(s.markers)).toEqual([]);
  });

  it('applyChanges refuses changes outside the model files and changes whose before no longer matches, writing nothing', async () => {
    const s = (setup = await setUp('proposal-apply-refusals'));
    const ws = s.ws;
    const main = read(s.root, MAIN);
    const apply = ws.applyChanges?.bind(ws);
    expect(apply).toBeTypeOf('function');
    if (!apply) return;
    expect(await apply({ label: 'x', action: 'accept-proposal', subject: 'Spyro', nodes: [], changes: [{ path: '.telelean/config.json', before: null, after: '{}' }] })).toMatchObject({
      ok: false,
      code: 'unsafe',
    });
    expect(await apply({ label: 'x', action: 'accept-proposal', subject: 'Spyro', nodes: [], changes: [{ path: '../outside.lean', before: null, after: 'x' }] })).toMatchObject({
      ok: false,
      code: 'unsafe',
    });
    expect(
      await apply({
        label: 'x',
        action: 'accept-proposal',
        subject: 'Spyro',
        nodes: [],
        changes: [
          { path: MAIN, before: main, after: `${main}-- a\n` },
          { path: MAIN, before: main, after: `${main}-- b\n` },
        ],
      }),
    ).toMatchObject({ ok: false, code: 'invalid' });
    expect(await apply({ label: 'x', action: 'accept-proposal', subject: '', nodes: [], changes: [] })).toMatchObject({ ok: false, code: 'invalid' });
    // The file changed between plan and apply: the applier's `before` check -> conflict, nothing recorded.
    expect(await apply({ label: 'x', action: 'accept-proposal', subject: 'Spyro', nodes: [], changes: [{ path: MAIN, before: `${main}-- stale`, after: 'y' }] })).toMatchObject({
      ok: false,
      code: 'conflict',
    });
    // Nothing to write (an empty proposal): ok, not undoable, nothing recorded.
    expect(await apply({ label: 'These suffice → not proved: x', action: 'accept-proposal', subject: 'Spyro', nodes: [], changes: [{ path: MAIN, before: main, after: main }] })).toEqual({
      ok: true,
      label: 'These suffice → not proved: x',
      undoable: false,
    });
    expect(read(s.root, MAIN)).toBe(main);
    expect((await ws.workspaceState('Spyro')).undo).toBeNull();
    expect((await ws.listHistory('Spyro')).entries.map((e) => e.action)).toEqual(['initial']);
    expect(repoState(s.repo)).toEqual(s.before);
  });

  describe.skipIf(!isImplemented(() => proposalLabel('proved', 'x', { lifecycle: 0, adoptedGhosts: 0 })))('[gated: WP1 proposalLabel]', () => {
    it('the history entry carries the real label', async () => {
      const s = (setup = await setUp('proposal-apply-label'));
      const run = await acceptRun(s, { diffGraphs: () => fakeDiff() });
      const label = 'These suffice → proved: Cynder would not be a good addition to the new Spyro game';
      expect(run.outcome).toEqual({ ok: true, label, undoable: true });
      expect((await s.ws.listHistory('Spyro')).entries[0]).toMatchObject({ action: 'accept-proposal', label });
      expect(repoState(s.repo)).toEqual(s.before);
    });
  });
});

/**
 * AT4.8 the run sidecar store on disk: attempts.jsonl is append-only (one write per line on an O_APPEND descriptor, so
 * concurrent writers, in this process or another, never interleave), resolutions are appended lines, decisions.json is
 * replaced atomically (temp file inside `.telelean/`, then rename; a failure leaves the old file and no temp), and
 * neither file is ever part of a history snapshot or an Undo. Fake codecs now; WP1's real ones in the gated block.
 */
import { spawn } from 'node:child_process';
import { mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';

import { afterEach, beforeEach, describe, expect, it } from 'vitest';

import {
  attemptsPath,
  decisionsPath,
  isImplemented,
  parseAttemptLines,
  type AttemptRecord,
  type AttemptResolution,
  type DecisionRecord,
} from '@telelean/core';

import { createRunSidecarStore, type SidecarCore } from '../../src/proposal/index.js';
import { createModelWorkspace, fsTextSource } from '../../src/workspace/index.js';
import { fakeCore as fakeWorkspaceCore } from '../workspace/fakeCore.js';
import { cleanup, copyMentalModel, makeTempDir, read, recordingApplier, userGit, write } from '../workspace/helpers.js';
import { fakeCodecs } from './helpers.js';

function record(run: string, round: number, date: string, extra: Partial<AttemptRecord> = {}): AttemptRecord {
  return {
    format: 'telelean-attempt',
    version: 1,
    id: `${run}.${round}`,
    run,
    round,
    date,
    subject: 'Spyro',
    target: 'cynder-not-good',
    premises: ['cynder-dark-past', 'new-spyro-pg', 'pg-no-dark-past'],
    verdict: 'proved',
    footprint: ['cynder-dark-past', 'new-spyro-pg', 'pg-no-dark-past', 'presup:Spyro.Character.exists', 'presup:Spyro.Game.exists'],
    summary: 'Proved from the three premises under the normative reading.',
    gateAttempts: 1,
    model: 'claude-opus-5-5',
    effort: 'high',
    usage: { requests: 12, inputTokens: 3000, outputTokens: 800, costEstimateUsd: 0.42 },
    ...extra,
  };
}

function resolution(run: string, round: number, value: AttemptResolution['resolution'], date = '2026-11-01T12:00:00.000Z'): AttemptResolution {
  return { format: 'telelean-attempt-resolution', version: 1, run, round, date, resolution: value };
}

function decision(id: string, extra: Partial<DecisionRecord> = {}): DecisionRecord {
  return {
    id,
    run: 'r1',
    date: '2026-11-01T10:01:00.000Z',
    subject: 'Spyro',
    phenomenon: 'modality',
    question: 'Does "cannot have" state a rule (normative), or that a PG game is unable to contain such a character (literal)?',
    options: [
      { label: 'A rule (normative)', consequence: 'A PG game with such a character breaks the rule.' },
      { label: 'Impossible (literal)', consequence: 'No PG game contains a character with a dark past at all.' },
    ],
    answer: { kind: 'option', option: 0 },
    answerText: 'A rule (normative)',
    scope: 'subject',
    affectedNodes: ['pg-no-dark-past'],
    decidedBy: 'user',
    wordedBy: 'agent',
    claudesGuess: { option: 0 },
    ...extra,
  };
}

const FAKE: Partial<SidecarCore> = fakeCodecs;

describe('AT4.8 the run sidecar store', () => {
  let tmp: string;
  let root: string;
  beforeEach(() => {
    tmp = makeTempDir('sidecars');
    root = copyMentalModel(tmp);
  });
  afterEach(() => cleanup(tmp));

  const attemptsFile = (): string => path.join(root, attemptsPath('Spyro'));
  const decisionsFile = (): string => path.join(root, decisionsPath('Spyro'));
  const tempFiles = (): string[] => readdirSync(path.join(root, '.telelean')).filter((name) => name.endsWith('.tmp'));

  it('appends one line per record (creating the subject dir), resolutions as lines, read back newest first with resolutions', async () => {
    const store = createRunSidecarStore({ core: FAKE });
    await store.appendAttempt(root, record('r1', 1, '2026-11-01T10:00:00.000Z'));
    expect(readFileSync(attemptsFile(), 'utf8')).toBe(`${JSON.stringify(record('r1', 1, '2026-11-01T10:00:00.000Z'))}\n`);
    await store.resolveAttempt(root, 'Spyro', resolution('r1', 1, 'superseded'));
    await store.appendAttempt(root, record('r1', 2, '2026-11-01T11:00:00.000Z', { verdict: 'not-proved' }));
    await store.resolveAttempt(root, 'Spyro', resolution('r1', 2, 'accepted'));
    const lines = readFileSync(attemptsFile(), 'utf8').split('\n');
    expect(lines).toHaveLength(5); // four lines and the final newline
    expect(lines.at(-1)).toBe('');
    const read = await store.readAttempts(root, 'Spyro');
    expect(read.map((a) => [a.id, a.verdict, a.resolution])).toEqual([
      ['r1.2', 'not-proved', 'accepted'],
      ['r1.1', 'proved', 'superseded'],
    ]);
    expect(await store.readAttempts(root, 'Other')).toEqual([]);
  });

  it('never joins a line to a hand-edited last line without a newline', async () => {
    const store = createRunSidecarStore({ core: FAKE });
    mkdirSync(path.dirname(attemptsFile()), { recursive: true });
    writeFileSync(attemptsFile(), JSON.stringify(record('r0', 1, '2026-10-31T10:00:00.000Z'))); // no final newline
    await store.appendAttempt(root, record('r1', 1, '2026-11-01T10:00:00.000Z'));
    expect((await store.readAttempts(root, 'Spyro')).map((a) => a.id)).toEqual(['r1.1', 'r0.1']);
  });

  it('concurrent appends never interleave: two stores in this process and another process at once', async () => {
    const a = createRunSidecarStore({ core: FAKE });
    const b = createRunSidecarStore({ core: FAKE });
    const long = 'x'.repeat(5000); // lines far longer than one pipe buffer's atomic guarantee would cover
    const child = path.join(tmp, 'appender.mjs');
    // Another writer (a second telelean window, say): plain O_APPEND writes of its own lines, in a separate process.
    writeFileSync(
      child,
      [
        "import { openSync, writeSync, closeSync } from 'node:fs';",
        'const [file, count] = process.argv.slice(2);',
        'for (let i = 0; i < Number(count); i++) {',
        "  const fd = openSync(file, 'a');",
        `  writeSync(fd, JSON.stringify({ format: 'telelean-attempt-resolution', version: 1, run: 'other', round: i, date: '2026-11-01T09:00:00.000Z', resolution: 'discarded', pad: '${'y'.repeat(3000)}' }) + '\\n');`,
        '  closeSync(fd);',
        '}',
      ].join('\n'),
    );
    mkdirSync(path.dirname(attemptsFile()), { recursive: true });
    const other = new Promise<number>((resolve, reject) => {
      const proc = spawn(process.execPath, [child, attemptsFile(), '150'], { stdio: 'ignore' });
      proc.on('error', reject);
      proc.on('exit', (code) => resolve(code ?? -1));
    });
    await Promise.all(
      Array.from({ length: 150 }, (_, i) => (i % 2 === 0 ? a : b).appendAttempt(root, record(`r${i}`, 1, `2026-11-01T10:${String(i % 60).padStart(2, '0')}:00.000Z`, { summary: long }))),
    );
    expect(await other).toBe(0);
    const lines = readFileSync(attemptsFile(), 'utf8').split('\n').filter((l) => l !== '');
    expect(lines).toHaveLength(300);
    const parsed = lines.map((l) => JSON.parse(l) as { format: string; run: string; summary?: string });
    expect(parsed.filter((p) => p.format === 'telelean-attempt').map((p) => p.run).sort()).toEqual(Array.from({ length: 150 }, (_, i) => `r${i}`).sort());
    expect(parsed.filter((p) => p.format === 'telelean-attempt').every((p) => p.summary === long)).toBe(true);
    expect(parsed.filter((p) => p.run === 'other')).toHaveLength(150);
  });

  it('decisions.json: read-modify-write replaced atomically through a temp file in .telelean/, same id replaced', async () => {
    const serialized: string[] = [];
    const store = createRunSidecarStore({
      core: {
        ...FAKE,
        serializeDecisionsFile: (file) => {
          const text = fakeCodecs.serializeDecisionsFile(file);
          serialized.push(text);
          return text;
        },
      },
    });
    await store.recordDecisions(root, 'Spyro', [decision('r1.q1.0')]);
    expect(readFileSync(decisionsFile(), 'utf8')).toBe(serialized[0]);
    expect((await store.readDecisions(root, 'Spyro')).decisions.map((d) => d.id)).toEqual(['r1.q1.0']);
    await store.recordDecisions(root, 'Spyro', [decision('r1.q1.0', { answerText: 'Impossible (literal)', answer: { kind: 'option', option: 1 } }), decision('r1.q2.0')]);
    const file = await store.readDecisions(root, 'Spyro');
    expect(file.decisions.map((d) => [d.id, d.answerText])).toEqual([
      ['r1.q1.0', 'Impossible (literal)'],
      ['r1.q2.0', 'A rule (normative)'],
    ]);
    expect(tempFiles()).toEqual([]);
    expect(readdirSync(path.dirname(decisionsFile())).sort()).toEqual(['decisions.json', 'layout.json']);
  });

  it('concurrent recordDecisions calls (two stores) never lose an update', async () => {
    const a = createRunSidecarStore({ core: FAKE });
    const b = createRunSidecarStore({ core: FAKE });
    await Promise.all(Array.from({ length: 20 }, (_, i) => (i % 2 === 0 ? a : b).recordDecisions(root, 'Spyro', [decision(`r1.q${i}.0`)])));
    const ids = (await a.readDecisions(root, 'Spyro')).decisions.map((d) => d.id).sort();
    expect(ids).toEqual(Array.from({ length: 20 }, (_, i) => `r1.q${i}.0`).sort());
    expect(tempFiles()).toEqual([]);
  });

  it('a failed decisions write leaves the previous file untouched and no temp file behind', async () => {
    const store = createRunSidecarStore({ core: FAKE });
    await store.recordDecisions(root, 'Spyro', [decision('r1.q1.0')]);
    const before = readFileSync(decisionsFile(), 'utf8');
    const failing = createRunSidecarStore({
      core: {
        ...FAKE,
        serializeDecisionsFile: () => {
          throw new Error('cannot serialise');
        },
      },
    });
    await expect(failing.recordDecisions(root, 'Spyro', [decision('r1.q2.0')])).rejects.toThrow('cannot serialise');
    expect(readFileSync(decisionsFile(), 'utf8')).toBe(before);
    // The rename itself fails (the target is a directory now): the temp file is removed.
    const other = path.join(root, decisionsPath('Second'));
    mkdirSync(other, { recursive: true });
    await expect(store.recordDecisions(root, 'Second', [decision('r1.q3.0', { subject: 'Second' })])).rejects.toThrow();
    expect(tempFiles()).toEqual([]);
  });

  it('refuses bad subjects and relative roots (nothing written outside the subject sidecar dir)', async () => {
    const store = createRunSidecarStore({ core: FAKE });
    await expect(store.appendAttempt(root, record('r1', 1, '2026-11-01T10:00:00.000Z', { subject: '../escape' }))).rejects.toThrow(TypeError);
    await expect(store.resolveAttempt(root, 'spyro lower', resolution('r1', 1, 'accepted'))).rejects.toThrow(TypeError);
    await expect(store.recordDecisions('relative/root', 'Spyro', [])).rejects.toThrow(TypeError);
    expect(readdirSync(path.join(root, '.telelean', 'subjects'))).toEqual(['Spyro']);
    expect(readdirSync(path.join(root, '.telelean', 'subjects', 'Spyro'))).toEqual(['layout.json']);
  });

  it('neither file is in a history snapshot or touched by Undo or a History revert', async () => {
    userGit(root, 'init', '-q');
    const store = createRunSidecarStore({ core: FAKE });
    const ws = createModelWorkspace({ root, text: fsTextSource(root), applier: recordingApplier(root), core: fakeWorkspaceCore, semantic: { enabled: false } });
    try {
      await ws.load();
      await store.appendAttempt(root, record('r1', 1, '2026-11-01T10:00:00.000Z'));
      await store.recordDecisions(root, 'Spyro', [decision('r1.q1.0')]);
      write(root, 'Model/Spyro/Inbox.lean', `${read(root, 'Model/Spyro/Inbox.lean')}-- a hand edit\n`); // forces a "Manual edits" snapshot
      expect((await ws.perform({ kind: 'add-node', subject: 'Spyro', type: 'ASSUMPTION', naturalName: 'Spyro is a dragon' })).ok).toBe(true);
      const attempts = readFileSync(attemptsFile(), 'utf8');
      const decisions = readFileSync(decisionsFile(), 'utf8');
      const listing = await ws.listHistory('Spyro');
      expect(listing.entries.map((e) => e.action)).toEqual(['add-node', 'manual', 'initial']);
      for (const entry of listing.entries) {
        const tree = userGit(root, 'ls-tree', '--full-tree', '-r', '--name-only', entry.id).split('\n');
        expect(tree.filter((p) => p.endsWith('attempts.jsonl') || p.endsWith('decisions.json')), entry.label).toEqual([]);
      }
      expect((await ws.undo('Spyro')).ok).toBe(true);
      expect((await ws.revert('Spyro', listing.entries[2]?.id ?? '')).ok).toBe(true);
      expect(readFileSync(attemptsFile(), 'utf8')).toBe(attempts);
      expect(readFileSync(decisionsFile(), 'utf8')).toBe(decisions);
    } finally {
      ws.dispose();
    }
  });

  describe.skipIf(!isImplemented(() => parseAttemptLines('')))('[gated: WP1 codecs]', () => {
    it('the real codecs: attempts round trip with resolutions newest first; decisions add and replace', async () => {
      const store = createRunSidecarStore();
      await store.appendAttempt(root, record('r1', 1, '2026-11-01T10:00:00.000Z'));
      await store.resolveAttempt(root, 'Spyro', resolution('r1', 1, 'superseded'));
      await store.appendAttempt(root, record('r1', 2, '2026-11-01T11:00:00.000Z', { verdict: 'not-proved' }));
      await store.resolveAttempt(root, 'Spyro', resolution('r1', 2, 'discarded'));
      const read = await store.readAttempts(root, 'Spyro');
      expect(read.map((a) => [a.id, a.verdict, a.resolution])).toEqual([
        ['r1.2', 'not-proved', 'discarded'],
        ['r1.1', 'proved', 'superseded'],
      ]);
      expect(read[1]).toMatchObject(record('r1', 1, '2026-11-01T10:00:00.000Z'));
      await store.recordDecisions(root, 'Spyro', [decision('r1.q1.0')]);
      await store.recordDecisions(root, 'Spyro', [decision('r1.q1.0', { answerText: 'Leave it open', answer: { kind: 'leave-open' } }), decision('r1.q2.0')]);
      const file = await store.readDecisions(root, 'Spyro');
      expect(file.format).toBe('telelean-decisions');
      expect(file.decisions.map((d) => [d.id, d.answerText])).toEqual([
        ['r1.q1.0', 'Leave it open'],
        ['r1.q2.0', 'A rule (normative)'],
      ]);
      expect(readFileSync(decisionsFile(), 'utf8').endsWith('}\n')).toBe(true);
    });
  });
});

/**
 * AT4.7 the ModelWorkspace's M2 members (docs/m2-plan.md sections 4.2 and 7): readText (open buffers first),
 * modelFiles (model files + present project files), library, projectModel, applyChanges (the recorded write path
 * with history kind `accept-proposal`), and the attempts history: `graph(S).attempts` from
 * `.telelean/subjects/<S>/attempts.jsonl` via core's codecs (faked here; WP1's real ones in the gated block), newest
 * first with resolutions, reloaded by reloadAttempts and by invalidate.
 */
import path from 'node:path';

import { afterEach, beforeEach, describe, expect, it } from 'vitest';

import { attemptsPath, isImplemented, parseAttemptLines, type AttemptLine, type AttemptRecord, type AttemptResolution } from '@telelean/core';

import { createModelWorkspace, type ModelWorkspace, type ModelWorkspaceOptions, type WorkspaceChange } from '../../src/workspace/index.js';
import { fakeCodecs } from '../proposal/helpers.js';
import { fakeCore } from './fakeCore.js';
import { cleanup, copyMentalModel, makeTempDir, overlayTextSource, read, recordingApplier, write, type RecordingApplier } from './helpers.js';

function record(run: string, round: number, date: string, verdict: AttemptRecord['verdict'] = 'proved'): AttemptRecord {
  return {
    format: 'telelean-attempt',
    version: 1,
    id: `${run}.${round}`,
    run,
    round,
    date,
    subject: 'Spyro',
    target: 'cynder-not-good',
    premises: ['cynder-dark-past', 'new-spyro-pg', 'pg-no-dark-past'],
    verdict,
    gateAttempts: 1,
    model: 'claude-opus-5-5',
  };
}

function resolution(run: string, round: number, value: AttemptResolution['resolution']): AttemptResolution {
  return { format: 'telelean-attempt-resolution', version: 1, run, round, date: '2026-11-01T12:00:00.000Z', resolution: value };
}

const jsonl = (lines: readonly AttemptLine[]): string => lines.map((l) => `${JSON.stringify(l)}\n`).join('');

describe('AT4.7 the workspace M2 members', () => {
  let tmp: string;
  let root: string;
  let applier: RecordingApplier;
  let ws: ModelWorkspace | undefined;
  const logs: string[] = [];

  beforeEach(() => {
    tmp = makeTempDir('m2members');
    root = copyMentalModel(tmp);
    applier = recordingApplier(root);
    logs.length = 0;
  });
  afterEach(() => {
    ws?.dispose();
    ws = undefined;
    cleanup(tmp);
  });

  async function open(extra: Partial<ModelWorkspaceOptions> = {}): Promise<ModelWorkspace> {
    ws = createModelWorkspace({
      root,
      text: overlayTextSource(root),
      applier,
      core: { ...fakeCore, parseAttemptLines: fakeCodecs.parseAttemptLines, summariseAttempts: fakeCodecs.summariseAttempts },
      semantic: { enabled: false },
      git: { enabled: false },
      log: (level, message) => logs.push(`${level}: ${message}`),
      ...extra,
    });
    await ws.load();
    return ws;
  }

  it('readText reads through the TextSource (open buffers first), null when missing; paths stay inside the root', async () => {
    const text = overlayTextSource(root, new Map([['Model/Spyro/Main.lean', '-- unsaved buffer\n']]));
    const w = await open({ text });
    expect(await w.readText?.('Model/Spyro/Main.lean')).toBe('-- unsaved buffer\n');
    expect(await w.readText?.('Model/Spyro/Vocabulary.lean')).toBe(read(root, 'Model/Spyro/Vocabulary.lean'));
    expect(await w.readText?.(path.join(root, 'lean-toolchain'))).toBe(read(root, 'lean-toolchain'));
    expect(await w.readText?.('Model/Spyro/Missing.lean')).toBeNull();
    await expect(w.readText?.('../outside.lean') ?? Promise.resolve()).rejects.toThrow(TypeError);
    await expect(w.readText?.('/etc/passwd') ?? Promise.resolve()).rejects.toThrow(TypeError);
  });

  it('modelFiles lists the model files and the present project files, following invalidate', async () => {
    const w = await open();
    expect(w.modelFiles?.()).toEqual([
      'lake-manifest.json',
      'lakefile.toml',
      'lean-toolchain',
      'Model.lean',
      'Model/Spyro.lean',
      'Model/Spyro/Inbox.lean',
      'Model/Spyro/Main.lean',
      'Model/Spyro/Vocabulary.lean',
    ]);
    write(root, 'Model/Spyro/Lemmas.lean', 'namespace Spyro\nend Spyro\n');
    write(root, 'lakefile.lean', '-- a second lakefile\n');
    await w.invalidate(['Model/Spyro/Lemmas.lean', 'lakefile.lean']);
    expect(w.modelFiles?.()).toContain('Model/Spyro/Lemmas.lean');
    expect(w.modelFiles?.()).toContain('lakefile.lean');
    expect(w.modelFiles?.()).not.toContain('.gitignore');
    expect(w.modelFiles?.()).not.toContain('.telelean/config.json');
  });

  it('library and projectModel expose what the graphs are built from', async () => {
    const w = await open();
    expect(w.library?.()).toBe('Model');
    const model = w.projectModel?.();
    expect([...(model?.nodes.keys() ?? [])].sort()).toEqual(['cynder-dark-past', 'cynder-not-good', 'new-spyro-pg', 'pg-no-dark-past']);
    expect(model?.subjects.map((s) => s.name)).toEqual(['Spyro']);
  });

  it('graph(S).attempts: loaded with the board, newest first with their latest resolution', async () => {
    write(
      root,
      attemptsPath('Spyro'),
      jsonl([
        record('r1', 1, '2026-11-01T10:00:00.000Z', 'not-proved'),
        resolution('r1', 1, 'superseded'),
        record('r1', 2, '2026-11-01T11:00:00.000Z'),
        resolution('r1', 2, 'accepted'),
      ]),
