export interface CheckContext {
  shadow: ShadowWorkspace;
  selection: Selection;
  stage: RunStage;
  round: number;
  /** The round's freeze (stage `prove`). */
  freeze?: FreezeRecord;
  job: LeanJobSettings;
  /** check_lean's `files`: only scopes which diagnostics are reported (the build is always the whole library). */
  files?: readonly string[];
  /** Node ids whose blocks telelean added in this run (adopted ghosts). */
  teleleanBlocks: readonly string[];
  /** The shadow commit where the round started (round > 1). */
  roundStartCommit?: string;
  /**
   * Reviewer addition: the commit whose files are B for the rules (core `RuleInput.base`): default the shadow's `base`
   * commit. Accept's re-check after the real files drifted passes the `accept-base` commit (the user's files at
   * Accept), so the user's own edits made during the run are never judged as Claude's (docs/m2-plan.md section 7.1).
   * The engine finds `RuleInput.adopted` itself (the newest `adopt` commit).
   */
  baseCommit?: string;
}

/** A Lean diagnostic for the agent: the WHOLE message (m0-report: never only the first line). */
export interface LeanDiagnosticView {
  file: string;
  /** 1-based, as Lean prints it. */
  line: number;
  /** 0-based column. */
  column: number;
  severity: 'error' | 'warning' | 'information';
  message: string;
}

export interface CheckReport {
  /**
   * `ok`: no finding. `problems`: findings (G0 / G1 / G3 / G5 / readiness). `environment`: telelean could not run Lean
   * (sandbox could not start, low memory, the mirror could not be synced): not the agent's fault, not counted.
   */
  outcome: 'ok' | 'problems' | 'environment';
  /** For `environment`: why, in plain words. */
  environment?: string;
  /** G0 and file findings (when not empty, Lean was not started). */
  g0: GateFinding[];
  /** Everything else, from core's evaluateRules plus G1 budget findings (`budget`: timeout / oom of the build). */
  findings: GateFinding[];
  diagnostics: LeanDiagnosticView[];
  /** The build's facts status (absent when Lean did not run). */
  build?: { status: LeanFacts['status']; durationMs: number; errorCount: number };
  rules?: RuleReport;
  /** The shadow's project model with the mirror's facts (for the proposal; not serialised into tool results). */
  model?: ProjectModel;
  facts?: LeanFacts;
  durationMs: number;
}

/** What a successful freeze keeps (persisted in run.json; `freeze.exportPath` stays valid while the run dir exists). */
export interface FreezeRecord {
  round: number;
  /** The `freeze` shadow commit. */
  commit: ShadowCommit;
  at: string;
  selection: Selection;
  snapshot: FrozenSnapshot;
  /** comparator's challenge (lean/comparator.ts Freeze: export path, theorem names, permitted axioms). */
  freeze: Freeze;
}

export type FreezeOutcome =
  | { ok: true; record: FreezeRecord; report: CheckReport }
  /** `refusals`: one exact sentence per finding (the agent's freeze reply); `environment` when Lean could not run. */
  | { ok: false; refusals: string[]; report: CheckReport; environment?: string };

export interface GateReport {
  passed: boolean;
  /** telelean could not run the gate (sandbox, memory, a freeze problem): not counted as an attempt. */
  environment?: string;
  /** All failed rules, G0 first (G4 findings only when G0-G3 and G5 passed). */
  findings: GateFinding[];
  flaggedDefinitions: RuleReport['flaggedDefinitions'];
  /** `#print axioms` of the target's `.holds` (status proved). */
  footprint?: string[];
  check: CheckReport;
  comparator?: ComparatorVerdict;
  durationMs: number;
  /** Reviewer addition: the shadow commit whose files were judged (see `LeanCheckEngine.gate`). */
  commit?: ShadowCommit;
}

export interface GhostCheckInput {
  naturalName: string;
  /**
   * Claude's proposition. Reviewer change: core `ghostTextProblems(leanStatement, proof)` must be empty (else refused
   * without Lean), whitespace runs are collapsed to one space, and the scratch file pins it as
   * `abbrev telelean_ghost_stmt : Prop := <statement>` followed by
   * `theorem telelean_ghost_check : telelean_ghost_stmt → <target statement> := <proof>`, so a statement that closes
   * the declaration early can never change what is checked (docs/m2-plan.md section 3.8). Any Lean error in the
   * scratch file refuses the ghost.
   */
  leanStatement: string;
  /** A term of type `telelean_ghost_stmt → <target statement>`. */
  proof: string;
}

export type GhostCheck =
  /** `statement`: the checked (whitespace-collapsed) text, which `GhostView.leanStatement` and adoption use. */
  | { ok: true; footprint: string[]; aloneEntails: boolean; statement?: string }
  /** `problems`: exact sentences for the agent (G0 tokens, Lean errors, axioms outside the permitted set, sorry). */
  | { ok: false; problems: string[]; environment?: string };

export interface RenderedStatement {
  /** Fully-qualified statement name. */
  name: string;
  pretty: string;
  explicit: string;
  /** Lean's message when the statement could not be printed. */
  error?: string;
}

export interface LeanCheckEngine {
  /**
   * telelean's normalisation before a gate (no Lean): core `normalisationChanges` for the target, selected premises
   * and adopted ghosts whose statement is new in this run (syntactic, base vs ws/), written into ws/ and committed
   * as `normalise` when anything changed. Idempotent.
   */
  normalise(ctx: CheckContext): Promise<{ changes: FileChange[]; commit?: ShadowCommit }>;
  /**
   * Reviewer addition (docs/m2-plan.md sections 2 and 4.1): builds the shadow's `base` commit right after the shadow
   * is created, before any prompt (no G0: it is the user's own text). Lean errors anywhere in the user's files make
   * the run fail before Claude is contacted (Claude could not fix them, so every attempt would fail); otherwise the
   * facts are kept in the run dir as B's

  flaggedDefinitions: readonly FlaggedDefinition[];
  usage: RunUsage;
  durationMs: number;
  agentMs: number;
  reverted?: ReportCard['reverted'];
  /** From `baseDrift` (non-empty -> `baseChanged`). */
  drift: readonly string[];
  /** Stamped on the proposal graph (the webview keeps proposal graphs apart from board graphs). */
  graphVersion: number;
}

export interface AcceptRequest {
  proposal: ProposalView;
  shadow: ShadowWorkspace;
  /** Ids of the lifecycle items the user ticked (unknown ids: `not-found`). */
  lifecycle: readonly string[];
  readReal: ReadRealText;
  /** `YYYY-MM-DD` (not used by M2's lifecycle items; reserved). */
  today: string;
  /**
   * Reviewer addition (docs/m2-plan.md section 7.1 step 4): after a rebase that passed its re-freeze and re-gate, the
   * exact files to apply (ws/ as re-gated: path -> text, every model file). The plan is then `real -> shownState`
   * plus the ticked lifecycle items, with no patching; absent = patch base -> shown onto the real text.
   */
  shownState?: ReadonlyMap<string, string>;
  /**
   * WP4 addition (optional): the real model files now (ModelWorkspace.modelFiles()), so a file the user added during
   * the run is kept in `shadowState` (and never deleted by the re-gated state). Absent: the model root's model files on
   * disk (`<library>.lean`, `<library>/**.lean`) plus the project files, each read through `readReal`.
   */
  realFiles?: readonly string[];
  /**
   * WP4 addition (optional): the Lean facts of the state being accepted (after a re-gate: the re-gate's check
   * facts). `lifecycleChanges` needs them to see that the target is proved. Absent: the facts `build` kept for this
   * proposal (in memory, else `<runDir>/proposal-facts.json`, so Accept after a window reload still has them).
   */
  facts?: LeanFacts;
}

export type AcceptPlan =
  | {
      ok: true;
      /** Whole-file changes against the REAL files (`before` = real text now), lifecycle items included. */
      changes: FileChange[];
      /** History / undo label (core proposalLabel). */
      label: string;
      nodes: string[];
      /** Real files that differ from the run's base (they were rebased). */
      drift: string[];
      /**
       * The merged model files WITHOUT the lifecycle items (path -> text, every model file): when `drift` is not
       * empty, the RunManager writes this into ws/, re-freezes and re-runs the gate before applying (D-21).
       */
      shadowState: Map<string, string>;
    }
  | { ok: false; code: 'conflict' | 'unsafe' | 'not-found' | 'invalid'; error: string; files?: string[] };

export interface ProposalService {
  build(input: ProposalBuildInput): Promise<ProposalView>;
  /**
   * Model files whose real text (open buffer first) differs from the run's base, sorted. Reviewer addition:
   * `realFiles` = ModelWorkspace.modelFiles() (the real model files now), so files the user added or deleted during
   * the run count as drift too; absent = only the base's files are compared.
   */
  baseDrift(shadow: ShadowWorkspace, readReal: ReadRealText, realFiles?: readonly string[]): Promise<string[]>;
  planAccept(request: AcceptRequest): Promise<AcceptPlan>;
  /** Requires `ModelWorkspace.applyChanges` (M2 member); never throws for refusals. */
  apply(plan: Extract<AcceptPlan, { ok: true }>, workspace: ModelWorkspace, subject: string): Promise<ActionOutcome>;
  /** base -> the shadow state the proposal shows, for the raw diff (`vscode.changes`). */
  diffFiles(shadow: ShadowWorkspace, proposal: ProposalView): Promise<FileChange[]>;
}

/**
 * The core functions the proposal service calls (default: `@telelean/core`'s). Reviewer addition, as M1's
 * `ModelWorkspaceOptions.core`: WP4 tests inject fakes while WP1's helpers are still stubs.
 */
export interface ProposalCore {
  diffGraphs: typeof diffGraphs;
  proposalLabel: typeof proposalLabel;
  lifecycleChanges: typeof lifecycleChanges;
  parseLeanFile: typeof parseLeanFile;
  buildProjectModel: typeof buildProjectModel;
  subjectGraph: typeof subjectGraph;
}

/** The core codecs the sidecar store calls (default: `@telelean/core`'s; reviewer addition, test hook). */
export interface SidecarCore {
  parseAttemptLines: typeof parseAttemptLines;
  serializeAttemptLine: typeof serializeAttemptLine;
  summariseAttempts: typeof summariseAttempts;
  parseDecisionsFile: typeof parseDecisionsFile;
  serializeDecisionsFile: typeof serializeDecisionsFile;
  addDecisions: typeof addDecisions;
}

/** `.telelean/subjects/<S>/attempts.jsonl` and `decisions.json` (formats: core run.ts; paths: core paths.ts). */
export interface RunSidecarStore {
  /** Appends one line (O_APPEND; creates the subject's sidecar dir). */
  appendAttempt(root: string, record: AttemptRecord): Promise<void>;
  resolveAttempt(root: string, subject: string, resolution: AttemptResolution): Promise<void>;
  /** Read-modify-write with an atomic replace (temp file inside `.telelean/`, then rename). */
  recordDecisions(root: string, subject: string, records: readonly DecisionRecord[]): Promise<void>;
  readAttempts(root: string, subject: string): Promise<AttemptSummary[]>;
  readDecisions(root: string, subject: string): Promise<DecisionsFile>;
}

