const IMPLEMENTED =
  isImplemented(() => buildSystemPrompt()) && // WP3
  isImplemented(() => createLeanCheckEngine()) && // WP2
  isImplemented(() => createProposalService()) && // WP4
  isImplemented(() => createRunSidecarStore()) && // WP4
