 67	/** Reads the parts of a Lake TOML configuration that Initialize needs. Unknown syntax is ignored. */
 68	export function readLakefileToml(text: string): LakefileSummary {
 69	  const summary: LakefileSummary = { leanLibs: [], requires: [] };
 70	  let table: 'lean_lib' | 'require' | 'other' | 'root' = 'root';
 71	  for (const rawLine of text.split(/\r?\n/)) {
 72	    const line = stripTomlComment(rawLine).trim();
 73	    if (line === '') continue;
 74	    const arrayTable = /^\[\[\s*([^\]]+?)\s*\]\]$/.exec(line);
 75	    if (arrayTable) {
 76	      const name = unquoteKey(arrayTable[1] ?? '');
 77	      table = name === 'lean_lib' ? 'lean_lib' : name === 'require' ? 'require' : 'other';
 78	      if (table === 'lean_lib') summary.leanLibs.push(undefined);
 79	      if (table === 'require') summary.requires.push('?');
 80	      continue;
 81	    }
 82	    if (/^\[[^\]]*\]$/.test(line)) {
 83	      table = 'other';
 84	      continue;
 85	    }
 86	    const keyValue = /^([A-Za-z0-9_."'-]+)\s*=\s*(.*)$/.exec(line);
 87	    if (!keyValue) continue;
 88	    const key = unquoteKey(keyValue[1] ?? '');
 89	    const value = keyValue[2] ?? '';
 90	    if (table === 'root' && (key === 'require' || key.startsWith('require.'))) summary.requires.push('?');
 91	    if (key !== 'name') continue;
 92	    const name = tomlString(value);
 93	    if (table === 'lean_lib' && name !== undefined) summary.leanLibs[summary.leanLibs.length - 1] = name;
 94	    if (table === 'require' && name !== undefined) summary.requires[summary.requires.length - 1] = name;
 95	  }
 96	  return summary;
 97	}
