 99	function stripTomlComment(line: string): string {
100	  let quote: string | undefined;
101	  for (let i = 0; i < line.length; i++) {
102	    const c = line[i];
103	    if (quote) {
104	      if (c === '\\' && quote === '"') i++;
105	      else if (c === quote) quote = undefined;
106	    } else if (c === '"' || c === "'") quote = c;
107	    else if (c === '#') return line.slice(0, i);
108	  }
109	  return line;
110	}
111	
112	function unquoteKey(key: string): string {
113	  return key.trim().replace(/^"(.*)"$/, '$1').replace(/^'(.*)'$/, '$1');
114	}
