116	function tomlString(value: string): string | undefined {
117	  const match = /^"((?:[^"\\]|\\.)*)"\s*$/.exec(value.trim()) ?? /^'([^']*)'\s*$/.exec(value.trim());
118	  return match ? (match[1] ?? '') : undefined;
119	}
