 70	/**
 71	 * Walks a directory without following symlinks. `skipHidden`: dot-entries are skipped silently instead of reported
 72	 * (the build mirror's `.lake`).
 73	 */
 74	export async function scanTree(root: string, options: { skipHidden?: boolean; readText?: boolean } = {}): Promise<TreeScan> {
 75	  const scan: TreeScan = { files: new Map(), unusual: [] };
 76	  const readText = options.readText ?? true;
 77	  const stack: string[] = [''];
 78	  while (stack.length > 0) {
 79	    const rel = stack.pop() ?? '';
 80	    let entries;
 81	    try {
 82	      entries = await readdir(path.join(root, rel), { withFileTypes: true });
 83	    } catch (error) {
 84	      if (rel === '' && (error as NodeJS.ErrnoException).code === 'ENOENT') return scan;
 85	      throw error;
 86	    }
 87	    for (const entry of entries) {
 88	      const childRel = rel === '' ? entry.name : `${rel}/${entry.name}`;
 89	      if (entry.name.startsWith('.')) {
 90	        if (!options.skipHidden) scan.unusual.push({ path: childRel, why: 'hidden' });
 91	      } else if (entry.isSymbolicLink()) {
 92	        scan.unusual.push({ path: childRel, why: 'symlink' });
 93	      } else if (entry.isDirectory()) {
 94	        stack.push(childRel);
 95	      } else if (entry.isFile()) {
 96	        scan.files.set(childRel, readText ? await readFile(path.join(root, childRel), 'utf8') : '');
 97	      } else {
 98	        scan.unusual.push({ path: childRel, why: 'special' });
 99	      }
100	    }
101	  }
102	  return scan;
103	}
