31	export async function createClaudeBackendImpl(settings: ClaudeBackendSettings): Promise<{ backend: ClaudeCliBackend; binary: ResolvedBinary }> {
32	  // Quota tripwire: before resolving anything (not even `--version`), unless a test supplies fake binaries through a
33	  // scratch home AND PATH (fixer round 1: `resolve: {}` or `{ runVersion }` alone would scan the real ~/.vscode, PATH
34	  // and ~/.local/bin and run their `--version`).
35	  if (realClaudeDisabled() && (typeof settings.resolve?.home !== 'string' || typeof settings.resolve.pathEnv !== 'string')) {
36	    throw new LlmHarnessError(
37	      'process',
38	      `real Claude is disabled here (${NO_REAL_CLAUDE_ENV}=${process.env[NO_REAL_CLAUDE_ENV] ?? ''}): no Claude binary was looked up or run${settings.resolve !== undefined ? ' (a test must pass both resolve.home and resolve.pathEnv)' : ''}.`,
39	    );
40	  }
41	  if (typeof settings.guardScriptPath !== 'string' || settings.guardScriptPath === '') {
42	    throw new TypeError('createClaudeBackend needs the absolute path of telelean-path-guard.mjs (guardScriptPath)');
43	  }
44	  const resolveOptions: ResolveBinaryOptions = { ...(settings.resolve ?? {}) };
45	  if (settings.claudePath !== undefined && settings.claudePath.trim() !== '') resolveOptions.explicitPath = settings.claudePath.trim();
46	  if (settings.extensionDirs !== undefined) resolveOptions.extensionDirs = settings.extensionDirs;
47	  const binary = await resolveClaudeBinary(resolveOptions);
48	  const options: ClaudeCliBackendOptions = {
49	    binary: { path: binary.path, version: binary.version },
50	    guardScriptPath: settings.guardScriptPath,
51	    hookRuntime: settings.hookRuntime ?? defaultHookRuntime(),
52	    clientApp: settings.clientApp,
53	  };
54	  if (settings.pdeathsig ?? true) options.launcher = setprivLauncher();
55	  return { backend: new ClaudeCliBackend(options), binary };
56	}
