 62	
 63	function statementInfo(model: ProjectModel, node: TlNode, subject: string): StatementInfo | undefined {
 64	  const name = node.lean.statement;
 65	  if (name === undefined || node.lean.binding === 'none') return undefined;
 66	  const entry: ModelNode | undefined = model.nodes.get(node.id);
 67	  const decl = entry?.statementDecl;
 68	  const facts = model.declFacts.get(name);
 69	  let value: string | undefined = facts?.value !== undefined ? shortNames(collapseWhitespace(facts.value), subject) : undefined;
 70	  let file: string | undefined;
 71	  let line: number | undefined;
 72	  if (decl !== undefined) {
 73	    file = decl.file;
 74	    const text = model.files.get(decl.file)?.text;
 75	    if (text !== undefined) {
 76	      line = lineOfOffset(text, decl.decl.keywordSpan.start);
 77	      if (value === undefined && decl.decl.valueStart !== undefined) {
 78	        // The source text after the top-level `:=` (the statement as written), when Lean has not checked it yet.
 79	        const raw = text.slice(decl.decl.valueStart, decl.decl.span.end).replace(/^:=/, '');
 80	        value = collapseWhitespace(raw);
 81	      }
 82	    }
 83	  }
 84	  return { name, value: value ?? '(not readable yet)', ...(file !== undefined ? { file } : {}), ...(line !== undefined ? { line } : {}) };
 85	}
