61	export function formatDuration(ms: number): string {
62	  const total = Math.max(0, Math.floor((Number.isFinite(ms) ? ms : 0) / 1000));
63	  const hours = Math.floor(total / 3600);
64	  const minutes = Math.floor((total % 3600) / 60);
65	  const seconds = total % 60;
66	  const ss = String(seconds).padStart(2, '0');
67	  return hours > 0 ? `${hours}:${String(minutes).padStart(2, '0')}:${ss}` : `${minutes}:${ss}`;
68	}
