70	/** Token counts: "950", "12.3k", "450k", "1.2M". */
71	export function formatTokens(n: number): string {
72	  if (!Number.isFinite(n) || n < 0) return '?';
73	  if (n < 1000) return String(Math.round(n));
74	  if (n < 1_000_000) {
75	    const k = n / 1000;
76	    return `${k < 100 ? k.toFixed(1).replace(/\.0$/, '') : Math.round(k)}k`;
77	  }
78	  const m = n / 1_000_000;
79	  return `${m < 100 ? m.toFixed(1).replace(/\.0$/, '') : Math.round(m)}M`;
80	}
