     7	/**
     8	 * Scrolls the run panel's body so that `element`'s top is in view: when it is above the visible part, or starts so
     9	 * low that little of it shows, its top goes to the top of the panel. Otherwise nothing moves.
    10	 */
    11	export function revealInPanel(element: HTMLElement, margin = 6): void {
    12	  const body = element.closest<HTMLElement>('.tl-run__body');
    13	  if (!body) return;
    14	  const box = element.getBoundingClientRect();
    15	  const view = body.getBoundingClientRect();
    16	  const top = box.top - view.top - body.clientTop; // relative to the visible top of the body
    17	  const height = body.clientHeight;
    18	  if (top < 0 || top > height * 0.6) body.scrollTop = Math.max(0, body.scrollTop + top - margin);
    19	}
