.tl-legend {
  display: inline-flex;

/* ---------- board: three columns between two SVG edge layers ---------- */
/* The board area and the run panel beside it (M2; below it on a narrow board). */
.tl-workspace {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: row;
}
/* The board area (and its toasts, positioned against it). */
.tl-main {
  position: relative;
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
}
/* Below three readable columns, the board scrolls sideways (the columns keep --tl-col-min, words never break). */
.tl-board-scroll {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  overflow-x: auto;
  overflow-y: hidden;
}
.tl-board-scroll::-webkit-scrollbar { height: 10px; }
.tl-board-scroll::-webkit-scrollbar-thumb { background: var(--vscode-scrollbarSlider-background); }
.tl-board-scroll::-webkit-scrollbar-thumb:hover { background: var(--vscode-scrollbarSlider-hoverBackground); }
.tl-board {
  position: relative;
  flex: 1 0 0%;
  min-width: calc(3 * var(--tl-col-min) + 2 * var(--tl-gap) + 28px); /* 28px: the columns' side padding */
  min-height: 0;
  overflow: hidden;
}
