 49	  const transitive = options.transitive ?? true;
 50	  const decls: Array<{ name: string; file: ParsedFile; decl: DeclInfo; opened: string[] }> = [];
 51	  for (const file of model.files.values()) {
 52	    const opensAt = openedNamespaces(file);
 53	    for (const decl of file.decls) if (decl.fullName) decls.push({ name: decl.fullName, file, decl, opened: opensAt(decl.span.start) });
 54	  }
 55	  const out: string[] = [];
 56	  const found = new Set<string>(targets);
 57	  /** Dotted suffixes (two components or more) of the found names. */
 58	  const suffixes = new Set<string>();
 59	  const addSuffixes = (name: string) => {
 60	    const parts = name.split('.');
 61	    for (let i = 0; i + 2 <= parts.length; i++) suffixes.add(parts.slice(i).join('.'));
 62	  };
