 52	export async function collectOwners(userData) {
 53	  const hostPids = new Set();
 54	  const runIds = new Set();
 55	  async function walk(abs, level) {
 56	    let entries;
 57	    try {
 58	      entries = await readdir(abs, { withFileTypes: true });
 59	    } catch {
 60	      return;
 61	    }
 62	    for (const entry of entries) {
 63	      const child = path.join(abs, entry.name);
 64	      if (entry.isDirectory() && level < 5) await walk(child, level + 1);
 65	      else if (entry.isFile() && entry.name.endsWith('.log')) {
 66	        const ids = idsInLog(await readFile(child, 'utf8').catch(() => ''));
 67	        for (const pid of ids.hostPids) hostPids.add(pid);
 68	        for (const id of ids.runIds) runIds.add(id);
 69	      }
 70	    }
 71	  }
 72	  await walk(path.join(userData, 'logs'), 1);
 73	  const runsDir = path.join(userData, 'User', 'globalStorage', 'telelean.telelean', 'runs');
 74	  for (const root of await readdir(runsDir, { withFileTypes: true }).catch(() => [])) {
 75	    if (!root.isDirectory()) continue;
 76	    for (const run of await readdir(path.join(runsDir, root.name), { withFileTypes: true }).catch(() => [])) {
 77	      if (run.isDirectory() && RUN_ID.test(run.name)) runIds.add(run.name);
