 76	/** Offsets where lines start; `\r\n`, `\n` and a lone `\r` each end a line (as in VS Code's text model). */
 77	export function lineStarts(text: string): number[] {
 78	  const starts = [0];
 79	  for (let i = 0; i < text.length; i++) {
 80	    const c = text.charCodeAt(i);
 81	    if (c === 13) {
 82	      if (text.charCodeAt(i + 1) === 10) i++;
 83	      starts.push(i + 1);
 84	    } else if (c === 10) {
 85	      starts.push(i + 1);
