 92	export function positionAt(starts: readonly number[], offset: number): Position {
 93	  let low = 0;
 94	  let high = starts.length - 1;
 95	  while (low < high) {
 96	    const mid = (low + high + 1) >> 1;
 97	    if ((starts[mid] ?? 0) <= offset) low = mid;
 98	    else high = mid - 1;
 99	  }
100	  return { line: low, character: offset - (starts[low] ?? 0) };
101	}
