 35	/** Applies a batch as one `WorkspaceEdit` (text edits for changed files, create/delete for the others). */
 36	export class VscodeWorkspaceEditPort implements WorkspaceEditPort {
 37	  /**
 38	   * Opens (without showing) the documents of the files about to be edited, before the applier checks their text: a
 39	   * WorkspaceEdit carries the extension host's version of each document it has open, and VS Code refuses the edit
 40	   * when that document changed in between; for a file with no document it would edit whatever is on disk by then.
 41	   * (Applying the edit would open these documents anyway.)
 42	   */
 43	  async prepare(absPaths: readonly string[]): Promise<void> {
 44	    for (const absPath of absPaths) {
 45	      if (openDocument(absPath)) continue;
 46	      try {
 47	        await vscode.workspace.openTextDocument(vscode.Uri.file(absPath));
 48	      } catch {
 49	        // missing or unreadable: the applier's check reports it
 50	      }
 51	    }
 52	  }
 53	
 54	  async apply(operations: readonly FileOperation[], label: string): Promise<boolean> {
 55	    const edit = new vscode.WorkspaceEdit();
 56	    for (const operation of operations) {
 57	      const uri = vscode.Uri.file(operation.absPath);
 58	      switch (operation.kind) {
 59	        case 'create':
 60	          edit.createFile(uri, { overwrite: false, contents: new TextEncoder().encode(operation.text) });
 61	          break;
 62	        case 'delete':
 63	          edit.deleteFile(uri, { ignoreIfNotExists: false });
 64	          break;
 65	        case 'edit':
 66	          for (const { range, text } of operation.edits) {
 67	            edit.replace(uri, new vscode.Range(range.start.line, range.start.character, range.end.line, range.end.character), text);
 68	          }
 69	          break;
 70	      }
 71	    }
 72	    void label;
 73	    return vscode.workspace.applyEdit(edit, { isRefactoring: false });
 74	  }
 75	
 76	  async save(absPath: string): Promise<boolean> {
 77	    const doc = openDocument(absPath) ?? (await vscode.workspace.openTextDocument(vscode.Uri.file(absPath)));
 78	    if (!doc.isDirty) return true;
 79	    return doc.save();
 80	  }
 81	}
