 18	const PLAIN_SEGMENT = /^[A-Za-z_][A-Za-z0-9_'!?]*$/;
 19	// No control characters, no guillemets (they delimit escaped components), no whitespace.
 20	const FORBIDDEN = /[\u0000-\u001f\u007f-\u009f«»\s]/u;
