 22	/** A dotted declaration name such as `Spyro.cynder_not_good.holds`. Components may not contain dots. */
 23	export function isValidDeclName(name: string): boolean {
 24	  if (name.length === 0 || name.length > 1024 || FORBIDDEN.test(name)) return false;
 25	  return name.split('.').every((segment) => segment.length > 0);
 26	}
