 58	const toPosix = (rel: string): string => rel.split(path.sep).join('/');
 59	
 60	/** Collects model files under `root`, skipping dot-directories and SKIPPED_DIRS. */
 61	async function walkSources(root: string): Promise<Walk> {
 62	  const walk: Walk = { files: [], symlinks: [], irregular: [] };
 63	  const stack: string[] = [''];
 64	  while (stack.length > 0) {
 65	    const rel = stack.pop() ?? '';
 66	    const entries = await readdir(path.join(root, rel), { withFileTypes: true });
 67	    for (const entry of entries) {
 68	      const childRel = rel === '' ? entry.name : path.join(rel, entry.name);
 69	      const isCandidate = entry.name.endsWith('.lean') || (rel === '' && PROJECT_CONFIG_FILES.includes(entry.name));
 70	      if (entry.isDirectory()) {
 71	        if (!entry.name.startsWith('.') && !SKIPPED_DIRS.has(entry.name)) stack.push(childRel);
 72	      } else if (entry.isSymbolicLink()) {
 73	        // Any symlink in the model tree is refused, wherever it points.
 74	        walk.symlinks.push(toPosix(childRel));
 75	      } else if (entry.isFile()) {
 76	        if (isCandidate) walk.files.push(childRel);
 77	      } else if (isCandidate) {
 78	        walk.irregular.push(toPosix(childRel));
 79	      }
 80	    }
 81	  }
 82	  return walk;
 83	}
