 46	export function projectProblem(root: string): string | undefined {
 47	  const hasLakefile = ['lakefile.toml', 'lakefile.lean'].some((f) => {
 48	    try {
 49	      return lstatSync(path.join(root, f)).isFile();
 50	    } catch {
 51	      return false;
 52	    }
 53	  });
 54	  if (!hasLakefile) return 'the model folder has no lakefile.toml or lakefile.lean';
 55	  let text: string;
 56	  try {
 57	    text = readFileSync(path.join(root, 'lake-manifest.json'), 'utf8');
 58	  } catch (e) {
 59	    if ((e as NodeJS.ErrnoException).code === 'ENOENT') {
 60	      return 'lake-manifest.json is missing (the sandbox keeps the model folder read-only, so Lake cannot write one)';
 61	    }
 62	    return `lake-manifest.json cannot be read: ${(e as Error).message}`;
 63	  }
 64	  let manifest: unknown;
 65	  try {
 66	    manifest = JSON.parse(text);
 67	  } catch (e) {
 68	    return `lake-manifest.json is not valid JSON: ${(e as Error).message}`;
 69	  }
 70	  const packages = typeof manifest === 'object' && manifest !== null ? (manifest as { packages?: unknown }).packages : undefined;
 71	  if (!Array.isArray(packages)) return 'lake-manifest.json has no "packages" list';
 72	  if (packages.length > 0) {
 73	    const names = packages.map((p: unknown) => {
 74	      const name = typeof p === 'object' && p !== null ? (p as { name?: unknown }).name : undefined;
 75	      return typeof name === 'string' ? name : '?';
 76	    });
 77	    return `this project has Lake dependencies (${names.join(', ')}): M1 checks only dependency-free models; Mathlib needs an explicit opt-in (M4)`;
 78	  }
 79	  return undefined;
 80	}
