 89	/**
 90	 * The library's modules: `<library>.lean` and every `<library>/**.lean` (regular files only; symlinks, dot
 91	 * directories and paths that are not plain module names are skipped). Sorted by file.
 92	 */
 93	export function listModuleFiles(root: string, library: string): ModuleFile[] {
 94	  const out: ModuleFile[] = [];
 95	  const consider = (rel: string): void => {
 96	    const name = rel.slice(0, -'.lean'.length).split('/').join('.');
 97	    if (isValidModuleName(name)) out.push({ name, file: rel });
 98	  };
 99	  try {
100	    if (lstatSync(path.join(root, `${library}.lean`)).isFile()) consider(`${library}.lean`);
101	  } catch {
102	    // no root module
103	  }
104	  const stack = [library];
105	  while (stack.length > 0) {
106	    const rel = stack.pop() ?? '';
107	    let entries: Dirent[];
108	    try {
109	      entries = readdirSync(path.join(root, rel), { withFileTypes: true });
110	    } catch {
111	      continue;
112	    }
113	    for (const entry of entries) {
114	      const childRel = `${rel}/${entry.name}`;
115	      if (entry.isDirectory()) {
116	        if (!entry.name.startsWith('.')) stack.push(childRel);
117	      } else if (entry.isFile() && entry.name.endsWith('.lean')) {
118	        consider(childRel);
119	      }
120	    }
121	  }
122	  return out.sort((a, b) => (a.file < b.file ? -1 : a.file > b.file ? 1 : 0));
123	}
