 85	  }
 86	  const fileOnly = FILE_ONLY.exec(body);
 87	  if (fileOnly !== null) return { severity: open.severity, file: fileOnly[1] ?? '', text: fileOnly[2] ?? '' };
 88	  return { severity: open.severity, text: body };
 89	}
