 46	export function compareVersions(a: string, b: string): number {
 47	  const pa = a.split('.').map((x) => Number.parseInt(x, 10) || 0);
 48	  const pb = b.split('.').map((x) => Number.parseInt(x, 10) || 0);
 49	  for (let i = 0; i < Math.max(pa.length, pb.length); i++) {
 50	    const d = (pa[i] ?? 0) - (pb[i] ?? 0);
 51	    if (d !== 0) return d < 0 ? -1 : 1;
 52	  }
 53	  return 0;
 54	}
