 67	/** VS Code Claude Code extension binaries, newest version first. */
 68	export async function findExtensionBinaries(extensionDirs: string[]): Promise<BinaryCandidate[]> {
 69	  const found: Array<{ version: string; path: string }> = [];
 70	  for (const dir of extensionDirs) {
 71	    let entries: string[];
 72	    try {
 73	      entries = await readdir(dir);
 74	    } catch {
 75	      continue;
 76	    }
 77	    for (const name of entries) {
 78	      const m = EXTENSION_DIR_RE.exec(name);
 79	      if (!m?.[1]) continue;
 80	      const bin = path.join(dir, name, 'resources', 'native-binary', 'claude');
 81	      if (await isExecutable(bin)) found.push({ version: m[1], path: bin });
 82	    }
 83	  }
 84	  found.sort((x, y) => compareVersions(y.version, x.version));
 85	  return found.map((f) => ({ path: f.path, source: 'vscode-extension' as const }));
 86	}
