 88	export async function listCandidates(opts: ResolveBinaryOptions = {}): Promise<BinaryCandidate[]> {
 89	  const home = opts.home ?? os.homedir();
 90	  if (opts.explicitPath) return [{ path: opts.explicitPath, source: 'setting' }];
 91	  const candidates: BinaryCandidate[] = [];
 92	  const extensionDirs = opts.extensionDirs ?? [
 93	    path.join(home, '.vscode', 'extensions'),
 94	    path.join(home, '.vscode-server', 'extensions'),
 95	  ];
 96	  candidates.push(...(await findExtensionBinaries(extensionDirs)));
 97	  for (const dir of (opts.pathEnv ?? process.env.PATH ?? '').split(path.delimiter)) {
 98	    if (!dir) continue;
 99	    const p = path.join(dir, 'claude');
100	    if (await isExecutable(p)) candidates.push({ path: p, source: 'path' });
101	  }
102	  const localBin = path.join(home, '.local', 'bin', 'claude');
103	  if (await isExecutable(localBin)) candidates.push({ path: localBin, source: 'local-bin' });
104	  // The same file can appear twice (PATH entry and ~/.local/bin).
105	  const seen = new Set<string>();
106	  return candidates.filter((c) => (seen.has(c.path) ? false : (seen.add(c.path), true)));
107	}
