47	 */
48	export function textUsers(model: ProjectModel, targets: readonly string[], exclude: ReadonlySet<string>, options: UsersOptions = {}): string[] {
49	  const transitive = options.transitive ?? true;
50	  const decls: Array<{ name: string; file: ParsedFile; decl: DeclInfo; opened: string[] }> = [];
51	  for (const file of model.files.values()) {
52	    const opensAt = openedNamespaces(file);
53	    for (const decl of file.decls) if (decl.fullName) decls.push({ name: decl.fullName, file, decl, opened: opensAt(decl.span.start) });
54	  }
55	  const out: string[] = [];
56	  const found = new Set<string>(targets);
57	  /** Dotted suffixes (two components or more) of the found names. */
58	  const suffixes = new Set<string>();
59	  const addSuffixes = (name: string) => {
60	    const parts = name.split('.');
61	    for (let i = 0; i + 2 <= parts.length; i++) suffixes.add(parts.slice(i).join('.'));
62	  };
63	  for (const target of targets) addSuffixes(target);
64	  let grew = true;
65	  while (grew) {
66	    grew = false;
67	    for (const { name, file, decl, opened } of decls) {
68	      if (found.has(name) || exclude.has(name)) continue;
69	      const mentions = identifierTokens(declBody(file, decl)).some((t) => {
70	        let text = t.text;
71	        for (;;) {
72	          if (text.includes('.') && suffixes.has(text.startsWith('_root_.') ? text.slice('_root_.'.length) : text)) return true;
73	          if (candidatesOf(text, decl.namespace, opened).some((c) => found.has(c))) return true;
74	          if (resolveName(text, decl.namespace, (n) => found.has(n))) return true;
75	          const dot = text.lastIndexOf('.');
76	          if (dot < 0) return false;
77	          text = text.slice(0, dot);
78	        }
79	      });
80	      if (mentions) {
81	        out.push(name);
82	        if (transitive) {
83	          found.add(name);
84	          addSuffixes(name);
85	          grew = true;
86	        }
87	      }
88	    }
89	    if (!transitive) break;
90	  }
91	  return out;
92	}
