    const permitted = computePermittedAxioms(proved(), { ...ALL, premises: ['cynder-dark-past', 'pg-no-dark-past'] });
    expect(permitted.all).toHaveLength(12);
    expect(permitted.all).not.toContain('Spyro.new_spyro_pg.holds');
