39	    }
40	    offset += raw.length + 1;
41	  }
42	  if (lastImportEnd >= 0) return { span: { start: lastImportEnd, end: lastImportEnd }, newText: `${eol}import ${module}` };
43	  return { span: { start: 0, end: 0 }, newText: `import ${module}${eol}` };
