36	export function declTables(model: ProjectModel): DeclTables {
37	  const cached = cache.get(model);
38	  if (cached) return cached;
39	  const byName = new Map<string, DeclEntry>();
40	  const examples: DeclTables['examples'] = [];
41	  for (const file of [...model.files.values()].sort(byPath)) {
42	    for (const decl of file.decls) {
43	      if (decl.keyword === 'mutual') continue;
