 54	/** Ids of nodes reachable from `id` along verified (proof) edges: everything whose proof rests on `id`. */
 55	export function proofDependents(graph: Pick<TlGraph, 'edges'>, id: string): string[] {
 56	  const out: string[] = [];
 57	  const seen = new Set([id]);
 58	  const queue = [id];
 59	  while (queue.length > 0) {
 60	    const current = queue.shift() as string;
 61	    for (const edge of graph.edges) {
 62	      if (edge.type !== 'verified' || edge.source !== current || seen.has(edge.target)) continue;
 63	      seen.add(edge.target);
 64	      out.push(edge.target);
 65	      queue.push(edge.target);
 66	    }
 67	  }
 68	  return out;
 69	}
