91	  const own = new Set<string>([statement, holds, ...(index.owned.get(node.id) ?? [])]);
92	  const found = new Map<string, ExternalUser>();
93	  const visited = new Set<string>(own);
94	  // Proof users first (whatever rests on the `.holds`, also through untracked lemmas), then the remaining users of
95	  // the statement: a declaration that does both is listed once, as a proof use.
96	  for (const [start, where] of [
97	    [holds, 'proof'],
98	    [statement, 'statement'],
99	  ] as const) {
100	    const queue = [start];
101	    while (queue.length > 0) {
102	      const name = queue.shift() as string;
103	      for (const user of directUsers(index, name)) {
104	        if (visited.has(user)) continue;
105	        visited.add(user);
106	        const owner = model.ownerOfDecl.get(user);
107	        if (owner !== undefined) {
108	          const card = model.nodes.get(owner)?.node;
109	          // A card of this board is shown by the board's own edges; another subject's card is listed, and the search
110	          // stops at it (as the verified edges stop at the first card).
111	          if (card && card.subject !== subject) found.set(user, { name: user, nodeId: owner, subject: card.subject, naturalName: card.naturalName, where });
112	          continue;
113	        }
114	        found.set(user, { name: user, where });
115	        queue.push(user);
116	      }
117	    }
118	  }
119	  return [...found.values()];
120	}
