58	  for (const g of v) {
59	    if (!isRecord(g) || !isString(g.id) || !isString(g.naturalName) || typeof g.adopted !== 'boolean') return null;
60	    out.push({ id: g.id, naturalName: g.naturalName, adopted: g.adopted });
