48	function prng(seed: number): () => number {
49	  let a = seed >>> 0;
50	  return () => {
51	    a = (a + 0x6d2b79f5) >>> 0;
52	    let t = a;
53	    t = Math.imul(t ^ (t >>> 15), t | 1);
54	    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
55	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
56	  };
57	}
