import '@vscode/codicons/dist/codicon.css';
import './styles/board.css';
import { webviewMessage, type TlGraph } from '@telelean/core';
import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import { App } from './App';
import { currentEngineStats, stylesApplied, themeColors } from './board/diagnostics';
import { connectHost, reportCspViolations, type HostBridge } from './host/bridge';
import { isTextEntry, shortcutFor } from './model/format';
import { BoardStoreProvider } from './state/context';
import { createBoardStore, readSplit, type BoardStore, type PersistedState } from './state/store';

/**
 * Tells the host what is on screen once the edge engine has drawn a frame that measured this graph's cards (the
 * board's `data-graph-seq` names the graph the engine measured) with a real layout. Both can lag the graph by a
 * frame or two: the panel may still be laid out (columns 0 px tall), and if the graph arrives before zustand's React
 * subscriptions attach (they attach in passive effects, after paint), React commits the cards one frame later than
 * the engine's first measure. Gives up after about two seconds of frames and reports whatever is there. A report
 * whose graph has been replaced in the meantime is dropped (the newer graph reports for itself), so a "rendered"
 * message never describes a graph other than the one it names.
 * The report is sent from the frame callback, before the browser paints that frame: "rendered" means laid out and
 * drawn into the DOM, not necessarily visible on screen yet.
 */
function reportRendered(host: HostBridge, graph: TlGraph, seq: number, latestSeq: () => number) {
  const framesAtApply = currentEngineStats()?.frames ?? 0;
  let waited = 0;
  const tick = () => {
    if (latestSeq() !== seq) return;
    const stats = currentEngineStats();
    const settled =
      stats !== null &&
      stats.graphSeq === seq &&
      stats.frames > framesAtApply &&
      stats.minColumnHeight > 0 &&
      stats.cards === graph.nodes.length;
    if (!settled && waited++ < 120) {
      requestAnimationFrame(tick);
      return;
    }
    requestAnimationFrame(() => {
      if (latestSeq() !== seq) return;
      const cards = document.querySelectorAll('[data-node-id]').length;
      const edges = document.querySelectorAll('path[data-edge-id]').length;
      const stubs = document.querySelectorAll('path[data-edge-id][data-stub]').length;
      const lists = [...document.querySelectorAll<HTMLElement>('.tl-col__list')].map((l) => l.clientHeight).join(',');
      const engine = currentEngineStats();
      const styled = stylesApplied();
      const theme = themeColors();
      host.post(
        webviewMessage('diagnostic', {
          level: 'info',
          code: 'rendered',
          message:
            `graph v${graph.version} (#${seq}): ${cards} cards, ${edges} arrows drawn (${stubs} stubs); viewport ${innerWidth}x${innerHeight}, ` +
            `column heights ${lists}, styled ${styled}, ${document.visibilityState}; aura ${theme.aura}, kinds ${theme.kindA} ${theme.kindD} ${theme.kindG}, vocabulary ${theme.vocabulary}, highlight ${theme.highlight}; ` +
            `engine frames ${engine?.frames ?? '-'}, measures ${engine?.measures ?? '-'}, measured graph #${engine?.graphSeq ?? '-'}, ` +
            `culled ${engine?.culled ?? '-'}, missing ${engine?.missing ?? '-'}, cards measured ${engine?.cards ?? '-'}, ` +
            `lists connected ${engine?.listsConnected ?? '-'}, waited ${waited} frames`,
          data: {
            version: graph.version,
            seq,
            cards,
            edges,
            stubs,
            viewport: `${innerWidth}x${innerHeight}`,
            lists,
            styled,
            visibility: document.visibilityState,
            ...theme,
            engineFrames: engine?.frames ?? -1,
            engineMeasures: engine?.measures ?? -1,
            measuredSeq: engine?.graphSeq ?? -1,
            culled: engine?.culled ?? -1,
            missing: engine?.missing ?? -1,
            minColumnHeight: engine?.minColumnHeight ?? -1,
            cardsMeasured: engine?.cards ?? -1,
            waitedFrames: waited,
          },
        }),
      );
    });
  };
  requestAnimationFrame(tick);
}

/** The persisted per-board state, read defensively (the panel serializer or an older build may have written it). */
function readPersisted(host: HostBridge): PersistedState {
  const raw = host.readState();
  return {
    ...(typeof raw.subject === 'string' ? { subject: raw.subject } : {}),
    ...(typeof raw.vocabCollapsed === 'boolean' ? { vocabCollapsed: raw.vocabCollapsed } : {}),
    ...(typeof raw.requestCounter === 'number' && Number.isSafeInteger(raw.requestCounter) && raw.requestCounter >= 0 ? { requestCounter: raw.requestCounter } : {}),
    ...(raw.runSplit !== undefined ? { runSplit: readSplit(raw.runSplit) } : {}),
  };
}

/**
 * Ctrl/Cmd+Z and Ctrl/Cmd+Shift+Z (or Ctrl+Y) on the board post undo/redo, except while typing in a field (the
 * field's own undo applies) or while a dialog is open.
 */
function installShortcuts(store: BoardStore) {
  window.addEventListener('keydown', (event) => {
    const action = shortcutFor(event);
    if (!action || event.repeat) return;
    if (isTextEntry(event.target) || isTextEntry(document.activeElement) || document.querySelector('dialog[open]')) return;
    event.preventDefault();
    if (action === 'undo') store.getState().undo();
    else store.getState().redo();
  });
}

const host = connectHost();
reportCspViolations(host);
const store = createBoardStore(host.post, { persisted: readPersisted(host), persist: (patch) => host.updateState({ ...patch }) });
installShortcuts(store);

host.onMessage((message) => {
  if (message.type === 'graph') {
    if (store.getState().applyGraph(message.payload.graph)) reportRendered(host, message.payload.graph, store.getState().seq, () => store.getState().seq);
    return;
  }
  store.getState().receive(message);
}

/**
 * The board's confirmations (one at a time, from the store's `dialog`):
 *  - dependents: a kind change whose Lean change breaks other proofs, listing them, with core's explanation:
 *    A->G / D->G removes a `.holds` they use (rewrite them to take it as a hypothesis), D->A / G->A of a proof that
 *    takes hypotheses makes `.holds` an axiom without them (rewrite them to use it directly); the rewrite needs fresh
 *    Lean facts. Or keep them marked broken, or cancel;
 *  - rationale: the optional "Why do you hold it?" of a change to Assumption (D-14: Skip is fine);
 *  - delete: who declares it, which proofs use it, which statements mention it (D-18); delete the card with or
 *    without its Lean code (Cancel has the focus, so Delete then Enter deletes nothing). When the host refuses to
 *    delete the Lean code because other declarations use it, the dialog opens again listing them (they would stop
 *    compiling): "Delete anyway", card only, or cancel;
 *  - revert: "Revert to this" in the history dropdown (D-33).
 * The host's lists name cards by id and other declarations by their Lean names: a card shows by its sentence (this
 * subject's from the board, another subject's from the host's `dependentCards`, with its subject), anything else by
 * its Lean name in code font.
 *
 * M2 carry-overs: (1) the first delete question also lists what uses the card outside the board
 * (`LeanBinding.externalUsers`: lemmas without a card, other subjects' cards) and says "Nothing else refers to it."
 * only when nothing does; (2) the dialogs' own words are singular for one dependent ("Rewrite that proof …", "Keep
 * that proof …") and plural otherwise; (3) a kind change re-asked by the host lists the host's dependents and says
 * that it found more than the dialog showed before.
 */
import type { DependentCard } from '@telelean/core';
import { useMemo, useState } from 'react';
import { ExternalUserItem } from '../common/ExternalUser';
import { InlineCode } from '../common/InlineCode';
import { Modal } from '../common/Modal';
import { pasteOneLine } from '../common/OneLineInput';
import { KIND_GLYPH, KIND_NOUN } from '../labels';
import { deleteDependents } from '../model/cardData';
import { formatTime } from '../model/format';
import { useBoard, useBoardActions } from '../state/context';
import type { DialogState } from '../state/store';

/**
 * A dependent: a card by its sentence (a card of this board from the board itself, any other from the host's `card`,
 * then with its subject), anything else (a declaration without a card) by its Lean name.
 */
function Dependent({ id, card }: { id: string; card?: DependentCard | undefined }) {
  const node = useBoard((s) => s.nodes[id]);
  const subject = useBoard((s) => s.subject);
  const shown = node ? { type: node.type, naturalName: node.naturalName, subject: node.subject } : card;
  if (!shown) {
    return (
      <li className="tl-dialog__item" data-dependent={id}>
        <code>{id}</code>
      </li>
    );
  }
  const elsewhere = !node && shown.subject !== subject;
  return (
    <li className="tl-dialog__item" data-dependent={id} {...(elsewhere ? { 'data-subject': shown.subject } : {})}>
      <span className="tl-glyph" data-kind={shown.type} aria-hidden="true">
        {KIND_GLYPH[shown.type]}
      </span>
      {elsewhere ? (
        <span>
          {shown.naturalName} <span className="tl-dialog__from">(subject {shown.subject})</span>
        </span>
      ) : (
        shown.naturalName
      )}
    </li>
  );
}

/**
 * The dependents dialog's own words (carry-over 2): for exactly one dependent "that proof" / "it", otherwise "them".
 * Every dependent of a `.holds` is a proof (a card's or a lemma's), so "proof" fits both kinds of entry.
 */
export function dependentsTexts(to: 'ASSUMPTION' | 'DERIVATION' | 'GOAL', count: number): { intro: string; rewrite: string; keep: string } {
  const one = count === 1;
  // To Goal: `.holds` goes, so its users take the statement as a hypothesis instead. To Assumption (a proof that
  // takes hypotheses): `.holds` becomes an axiom that states it directly, so its users stop passing it arguments.
  if (to === 'ASSUMPTION') {
    return {
      intro: one ? 'This passes it arguments:' : 'These pass it arguments:',
      rewrite: one ? 'Rewrite that proof to use it directly' : 'Rewrite them to use it directly',
      keep: one ? 'Keep that proof, marked broken' : 'Keep them, marked broken',
    };
  }
  return {
    intro: one ? 'This uses it:' : 'These use it:',
    rewrite: one ? 'Rewrite that proof to take it as a hypothesis' : 'Rewrite them to take it as a hypothesis',
    keep: one ? 'Keep that proof, marked broken' : 'Keep them, marked broken',
  };
}

