  readonly nodes: ReadonlyMap<string, ModelNode>;
  readonly files: ReadonlyMap<string, ParsedFile>;
  readonly facts?: LeanFacts;
  /** Files whose current hash matches the facts (their positions and statuses are trustworthy). */
