23	/** `import <module>` added after the last import line of `text` (or first, when there is none); undefined if present. */
24	export function importEdit(text: string, module: string, eol: '\n' | '\r\n'): TextEdit | undefined {
25	  const linePattern = /^import\s+(\S+)\s*$/;
26	  let offset = 0;
27	  let lastImportEnd = -1;
28	  for (const raw of text.split('\n')) {
29	    const line = raw.endsWith('\r') ? raw.slice(0, -1) : raw;
30	    const match = linePattern.exec(line);
31	    if (match) {
32	      if (match[1] === module) return undefined;
33	      lastImportEnd = offset + line.length;
34	    } else if (line.trim() !== '' && !line.trimStart().startsWith('--')) {
35	      break;
36	    }
37	    offset += raw.length + 1;
38	  }
39	  if (lastImportEnd >= 0) return { span: { start: lastImportEnd, end: lastImportEnd }, newText: `${eol}import ${module}` };
40	  return { span: { start: 0, end: 0 }, newText: `import ${module}${eol}` };
41	}
