36	/** The text of a declaration after its name (signature and value), comments and strings blanked. */
37	function declBody(file: ParsedFile, decl: DeclInfo): string {
38	  return blankComments(file.text.slice(decl.nameSpan?.end ?? decl.keywordSpan.end, decl.span.end));
39	}
