function listWithMore(items: readonly string[]): string {
  const shown = items.slice(0, DETAIL_ITEMS).join('; ');
  return items.length > DETAIL_ITEMS ? `${shown}; … (${items.length - DETAIL_ITEMS} more)` : shown;
}

