  'abbrev a1 : Prop := Good t',
  'axiom a1.holds : a1',
  '',
  block({ id: 'a2', type: 'ASSUMPTION', name: 'A2', rationale: 'r', lean: 'S.a2' }),
  'abbrev a2 : Prop := Bad t',
  'axiom a2.holds : a2',
  '',
  block({ id: 'dt', type: 'DERIVATION', name: 'DT', premises: ['a1'], lean: 'S.dt' }),
