  '',
  block({ id: 'gt', type: 'GOAL', name: 'GT', premises: ['dt', 'a2'], lean: 'S.gt' }),
  'abbrev gt : Prop := Good t',
  'theorem gt.holds : gt := dt.holds',
  '',
  block({ id: 'both', type: 'GOAL', name: 'Both', premises: ['a1', 'a2'], lean: 'S.both' }),
