101	 * contains it). Missing files (or a missing parent directory) give null.
102	 */
103	export async function readTextFile(absPath: string): Promise<string | null> {
104	  try {
105	    const text = await readFile(absPath, 'utf8');
106	    return text.charCodeAt(0) === 0xfeff ? text.slice(1) : text;
107	  } catch (error) {
108	    const code = (error as NodeJS.ErrnoException).code;
109	    if (code === 'ENOENT' || code === 'ENOTDIR') return null;
110	    throw error;
111	  }
