  // 1. an action, then files telelean did not write
  const add = await ws.perform({ kind: 'add-node', subject: 'Spyro', type: 'GOAL', naturalName: 'A probe goal' });
  check('add-node ok', add.ok, add);
  const binary = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a, 0x00, 0xff, 0xfe, 0x80, 0x81, 0xc3, 0x28, 0x00, 0x10]);
  write(root, '.telelean/subjects/Spyro/diagram.png', binary);
  write(root, '.telelean/subjects/Spyro/notes-bom.txt', Buffer.concat([Buffer.from([0xef, 0xbb, 0xbf]), Buffer.from('notes with a BOM\n')]));
  write(root, 'Model/Spyro/Scratch.lean', '-- the user\'s own scratch file, never imported\ntheorem my_lemma : True := trivial\n');
  write(root, 'Model/Spyro/Main.lean', `${read(root, 'Model/Spyro/Main.lean')}-- hand edit after the add\n`);
  const beforeRevert = treeHashes(root);
