  if (manual) {
    const blob = Buffer.from(ugit(root, 'cat-file', 'blob', `${manual.id}:.telelean/subjects/Spyro/diagram.png`), 'latin1');
    const stored = execGitBytes(root, ['cat-file', 'blob', `${manual.id}:.telelean/subjects/Spyro/diagram.png`]);
    void blob;
    check('the Manual-edits snapshot stored the binary file byte-exactly', stored.equals(binary), { storedHex: stored.toString('hex'), originalHex: binary.toString('hex') });
    const bom = execGitBytes(root, ['cat-file', 'blob', `${manual.id}:.telelean/subjects/Spyro/notes-bom.txt`]);
    check('the Manual-edits snapshot stored the BOM file byte-exactly', bom[0] === 0xef && bom[1] === 0xbb && bom[2] === 0xbf, { firstBytes: bom.subarray(0, 4).toString('hex') });
  }

  // 3. undo the revert: everything back byte-exactly?
