  check('undo of the revert restores every file byte-exactly', differing.length === 0, differing);
  if (existsSync(path.join(root, '.telelean/subjects/Spyro/diagram.png'))) {
    const restored = readFileSync(path.join(root, '.telelean/subjects/Spyro/diagram.png'));
    check('binary sidecar file after undo equals the original', restored.equals(beforeRevertBinary), { restoredHex: restored.toString('hex'), originalHex: beforeRevertBinary.toString('hex') });
  }

