  check('an action with a stale ref lock still applies', editLocked.ok && read(root, 'Model/Spyro/Main.lean') !== mainBefore, editLocked);
  const hs = await ws.historyStatus();
  const graphDiag = ws.graph('Spyro').diagnostics.filter((d) => d.code === 'TL202').map((d) => d.message);
  check('the stale lock shows as a history error (TL202) on the board', hs.state === 'error' && graphDiag.length > 0, { hs, graphDiag });
  rmSync(lockFile);
  const editAfter = await ws.perform({ kind: 'edit-node', id: 'cynder-dark-past', field: 'naturalName', value: 'Edited after the lock was removed' });
  const hs2 = await ws.historyStatus();
  check('history recovers after the lock is removed', editAfter.ok && hs2.state === 'ready', { editAfter, hs2 });
  const labels = (await ws.listHistory('Spyro')).entries.map((e) => e.label);
  note(`history after lock episode: ${labels.slice(0, 5).join(' | ')}`);
  ws.dispose();

  // 6. git missing: actions work, history says git-missing, revert refused cleanly
  const root2 = copyModel(path.join(base, 'model2'));
  const ws2 = createModelWorkspace({ root: root2, text: fsTextSource(root2), applier: fsEditApplier(root2), semantic: { enabled: false }, git: { gitPath: path.join(base, 'no-such-git') } });
