  const add2 = await ws2.perform({ kind: 'add-node', subject: 'Spyro', type: 'ASSUMPTION', naturalName: 'Works without git' });
  const undo2 = await ws2.undo('Spyro');
  const revert2 = await ws2.revert('Spyro', 'abcdef12');
