  ws2.dispose();

  note(`warn/error log: ${log.filter((l) => !l.startsWith('info')).join(' || ') || '(none)'}`);
  const failed = results.filter((r) => !r.ok);
  console.log(`\nprobe1b: ${results.length - failed.length}/${results.length} checks passed`);
}

