function blockOf(text: string, id: string): string {
  const match = new RegExp(`/-\\n@@ telelean v1\\nid: ${id}\\n[\\s\\S]*?-/`).exec(text);
  assert.ok(match, `no block "${id}" in:\n${text}`);
  return match[0];
}

