1	/**
2	 * The read-only preview of a history entry (D-33, docs/m1-plan.md section 8 "Preview"): the runner's HistoryDiff
3	 * becomes VS Code's multi-file diff (`vscode.changes`) over documents served by a `telelean-history:` content
4	 * provider. This module holds the vscode-free part: titles, the documents' identities and a bounded store.
5	 */
6	import type { HistoryDiff } from '@telelean/core';
7	
8	export const HISTORY_SCHEME = 'telelean-history';
9	
10	/** One side of one file in a preview: `key` identifies the document (its URI query), `path` names the file. */
11	export interface PreviewDocument {
12	  key: string;
13	  path: string;
14	  text: string;
15	}
16	
17	/** One row of the multi-file diff: absent sides are a created (no left) or deleted (no right) file. */
18	export interface PreviewRow {
19	  path: string;
20	  left?: PreviewDocument;
21	  right?: PreviewDocument;
22	}
23	
24	function pad(n: number): string {
25	  return String(n).padStart(2, '0');
26	}
27	
28	/** `2026-11-01 14:05` in local time (the ISO text itself when it does not parse). */
29	export function formatEntryTime(iso: string): string {
30	  const date = new Date(iso);
31	  if (Number.isNaN(date.getTime())) return iso;
32	  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}`;
33	}
34	
35	export function previewTitle(diff: HistoryDiff): string {
36	  const against = diff.compare === 'parent' ? 'the state before it' : 'the files now';
37	  return `telelean history: ${diff.entry.label} (${formatEntryTime(diff.entry.time)}) vs ${against}`;
38	}
39	
40	/**
41	 * The rows of a preview. `compare: 'parent'` shows what the entry changed (parent on the left, entry on the right);
42	 * `compare: 'current'` shows how the files now differ from the entry (entry on the left, current on the right): the
43	 * runner's FileChange `before`/`after` already follow that order.
44	 */
45	export function previewRows(diff: HistoryDiff, previewId: string): PreviewRow[] {
46	  return diff.files.map((file) => {
47	    const side = (name: 'before' | 'after', text: string | null): PreviewDocument | undefined =>
48	      text === null ? undefined : { key: `preview=${previewId}&side=${name}&entry=${diff.entry.id}`, path: file.path, text };
49	    const left = side('before', file.before);
50	    const right = side('after', file.after);
51	    return { path: file.path, ...(left ? { left } : {}), ...(right ? { right } : {}) };
52	  });
53	}
54	
55	/** Documents of the last few previews (older ones are dropped; reopening shows a placeholder). */
56	export class PreviewStore {
57	  private readonly previews: Array<{ id: string; keys: string[] }> = [];
58	  private readonly texts = new Map<string, string>();
59	
60	  constructor(private readonly keepPreviews = 10) {}
61	
62	  add(id: string, rows: readonly PreviewRow[]): void {
63	    const keys: string[] = [];
64	    for (const row of rows) {
65	      for (const doc of [row.left, row.right]) {
66	        if (!doc) continue;
67	        this.texts.set(this.documentKey(doc.path, doc.key), doc.text);
68	        keys.push(this.documentKey(doc.path, doc.key));
69	      }
70	    }
71	    this.previews.push({ id, keys });
72	    while (this.previews.length > this.keepPreviews) {
73	      for (const key of this.previews.shift()?.keys ?? []) this.texts.delete(key);
74	    }
75	  }
76	
77	  /** The text of a preview document by its URI path (`/<file>`) and query. */
78	  get(uriPath: string, query: string): string | undefined {
79	    return this.texts.get(this.documentKey(uriPath.replace(/^\/+/, ''), query));
80	  }
81	
82	  private documentKey(path: string, query: string): string {
83	    return `${query}\u0000${path}`;
84	  }
85	}
86	
87	export const EXPIRED_PREVIEW_TEXT =
88	  '// This telelean history preview is no longer available (it was opened in an earlier session, or many previews ago).\n// Open it again from the board: History ▸ Preview.\n';
