/**
 * Imperative SVG edge overlay for three independently scrolling columns (03 section 7, "EdgeEngine").
 *
 * React renders the cards; this class owns the <path> elements and the "n linked" badges, so scrolling and
 * hovering never re-render React. At most one requestAnimationFrame runs per change:
 *   READ    card boxes and column viewports, only when the layout is dirty (ResizeObserver / MutationObserver),
 *           plus the three scrollTops every frame;
 *   COMPUTE pure geometry (geometry.ts);
 *   WRITE   reconcile a pool of <path> elements, touching an attribute only when its value changed.
 * Cards are found by `[data-node-id]` inside each column list, so nothing has to register with the engine.
 */
import type { NodeType } from '@telelean/core';
import { NODE_TYPES } from '@telelean/core';
import {
  computeFrame,
  DEFAULT_GEOMETRY,
  type BadgeDir,
  type BadgeSpec,
  type CardGeom,
  type ColumnGeom,
  type EdgeSpec,
  type FrameOutput,
  type GeometryOptions,
} from './geometry';

const SVG_NS = 'http://www.w3.org/2000/svg';

/** The board element's attribute that names the graph on screen (see `EdgeEngineStats.graphSeq`). */
export const GRAPH_SEQ_ATTRIBUTE = 'data-graph-seq';

export interface EdgeEngineElements {
  /** Positioned container; the SVG overlays fill its padding box. Carries `data-graph-seq`. */
  board: HTMLElement;
  /** The three scroll containers. Cards inside them carry `data-node-id`. */
  lists: Readonly<Record<NodeType, HTMLElement>>;
  layers: { under: SVGGElement; over: SVGGElement };
  /** Clip rectangles (one per SVG) kept to the band covered by the column lists. */
  clipRects: readonly SVGRectElement[];
  /**
   * Empty elements React renders in each column's header (`up`) and footer (`down`), outside the scrolling list.
   * The engine owns the "n linked" button inside each one; React never renders children into them.
   */
  badgeSlots: Readonly<Record<NodeType, Readonly<Record<BadgeDir, HTMLElement>>>>;
}

export interface EdgeEngineStats {
  frames: number;
  measures: number;
  /**
   * The board's `data-graph-seq` at the last measure: which applied graph the cached geometry belongs to. (A graph's
   * own version is not enough: two graphs can share one, and their DOM can have the same number of cards.)
   */
  graphSeq: number;
  /** Smallest column viewport height at the last measure (0 while the webview has no layout yet). */
  minColumnHeight: number;
  /** Cards found at the last measure. */
  cards: number;
  /** Whether the three list elements the engine watches are still in the document. */
  listsConnected: boolean;
  drawn: number;
  stubs: number;
  culled: number;
  missing: number;
  overBudget: number;
  lastFrameMs: number;
}

interface PathRecord {
  el: SVGPathElement;
  d: string;
  cls: string;
  marker: string;
  stub: string;
  pattern: string;
  conditional: boolean;
  mismatch: string;
  title: string;
  titleEl: SVGTitleElement | null;
  layer: 'under' | 'over' | null;
}

/** The arrowhead of an edge: conditional edges keep their own (hollow) head even when focused. */
export function markerVariant(edge: EdgeSpec, focused: boolean): string {
  if (edge.conditional) return focused ? 'conditional-focus' : 'conditional';
  if (focused) return 'focus';
  if (edge.mismatch) return 'mismatch';
  return edge.pattern;
}

/** Every marker variant the board defines (Board.tsx renders one <marker> per variant and layer). */
export const MARKER_VARIANTS = ['declared', 'verified', 'reference', 'focus', 'mismatch', 'conditional', 'conditional-focus'] as const;

export class EdgeEngine {
  private edges: readonly EdgeSpec[] = [];
  private focus: ReadonlySet<string> = new Set();
  private cols: Record<NodeType, ColumnGeom> | null = null;
  private cards = new Map<string, CardGeom>();
  private readonly observedCards = new Set<Element>();
  private readonly pool = new Map<string, PathRecord>();
  private readonly badgeButtons = new Map<string, HTMLButtonElement>();
  private readonly badgeTargets = new Map<string, BadgeSpec>();
  private layoutDirty = true;
  private raf = 0;
  private disposed = false;
  private readonly resizeObserver: ResizeObserver;
  private readonly mutationObserver: MutationObserver;
  private readonly onScroll = () => this.schedule();
  private readonly listeners = new Set<(stats: EdgeEngineStats) => void>();

  readonly stats: EdgeEngineStats = {
    frames: 0,
    measures: 0,
    graphSeq: 0,
    minColumnHeight: 0,
    cards: 0,
    listsConnected: false,
    drawn: 0,
    stubs: 0,
    culled: 0,
    missing: 0,
    overBudget: 0,
    lastFrameMs: 0,
  };

  constructor(
    private readonly el: EdgeEngineElements,
    private readonly opts: GeometryOptions = DEFAULT_GEOMETRY,
  ) {
    this.resizeObserver = new ResizeObserver(() => this.invalidateLayout());
    // Cards added, removed, moved between columns or expanded change offsets without resizing the lists. A new
    // graph always re-measures, even when its cards render to the same DOM as the previous graph's.
    this.mutationObserver = new MutationObserver(() => this.invalidateLayout());
    this.mutationObserver.observe(el.board, { attributes: true, attributeFilter: [GRAPH_SEQ_ATTRIBUTE] });
    this.resizeObserver.observe(el.board);
    for (const kind of NODE_TYPES) {
      const list = el.lists[kind];
      this.resizeObserver.observe(list);
      this.mutationObserver.observe(list, { childList: true, subtree: true, characterData: true });
      list.addEventListener('scroll', this.onScroll, { passive: true });
    }
    this.schedule();
  }

  setEdges(edges: readonly EdgeSpec[]): void {
    this.edges = edges;
    this.schedule();
  }

  setFocus(ids: ReadonlySet<string>): void {
    this.focus = ids;
    this.schedule();
  }

  invalidateLayout(): void {
    this.layoutDirty = true;
    this.schedule();
  }

  /** Called after each frame (diagnostics and tests). */
  onFrame(listener: (stats: EdgeEngineStats) => void): () => void {

/**
 * Pure edge-overlay geometry (no DOM): given cached card boxes, column viewports and the three scrollTops,
 * compute the SVG paths for one frame. The EdgeEngine does the DOM reads and writes around it.
 *
 * Coordinates are CSS pixels in "board space": the padding box of the board element, which is also the user
 * space of the absolutely positioned SVG overlays.
 */
import type { NodeType } from '@telelean/core';
import { NODE_TYPES } from '@telelean/core';

/**
 * Line pattern is reserved for epistemic status (D-13, D-15): dashed = declared, solid = verified. `reference` (a
 * statement mentions another node's statement) is drawn thin and solid, only while one end has focus.
 */
export type EdgePattern = 'declared' | 'verified' | 'reference';

export interface EdgeSpec {
  /** `${source}->${target}`: a declared and a verified edge between the same nodes are drawn as one. */
  id: string;
  source: string;
  target: string;
  pattern: EdgePattern;
  /** A verified edge into a conditional proof (the source is taken as a hypothesis): its own marker. */
  conditional?: boolean;
  /** D-13 declared-vs-verified mismatch: drawn in the warning colour. */
  mismatch?: 'declared-unused' | 'used-undeclared';
  /** Tooltip (conditional and mismatch arrows react to the pointer; plain arrows do not). */
  title?: string;
}

export const COLUMN_INDEX: Readonly<Record<NodeType, number>> = { ASSUMPTION: 0, DERIVATION: 1, GOAL: 2 };

/** A column's scroll viewport in board space. */
export interface ColumnGeom {
  /** Board-space position of the list's content origin when scrollTop is 0 (its padding-box corner). */
  originX: number;
  originY: number;
  /** Visible band of the list (its padding box). */
  viewTop: number;
  viewBottom: number;
  width: number;
}

/** A card's border box relative to its list's content origin, so it does not change while the list scrolls. */
export interface CardGeom {
  kind: NodeType;
  top: number;
  height: number;
  left: number;
  width: number;
}

export interface GeometryOptions {
  /** The endpoint sits min(height / 2, anchorMax) below the card's top edge, i.e. on the title line. */
  anchorMax: number;
  /** A card with fewer visible pixels than this inside its viewport counts as scrolled away. */
  minVisible: number;
  /** A visible endpoint stays at least this far inside the visible part of its card. */
  edgeInset: number;
  /** Size of the stub hook drawn when the other end is scrolled away. */
  stubDx: number;
  stubDy: number;
  /** Maximum number of drawn paths per frame (repainting SVG paths is the expensive part). */
  budget: number;
}

export const DEFAULT_GEOMETRY: GeometryOptions = {
  anchorMax: 18,
  minVisible: 8,
  edgeInset: 4,
  stubDx: 22,
  stubDy: 20,
  budget: 250,
};

export type Side = 'L' | 'R';
/** -1 = above the viewport, 0 = visible, 1 = below. */
export type Visibility = -1 | 0 | 1;

export interface Endpoint {
  id: string;
  kind: NodeType;
  x: number;
  y: number;
  vis: Visibility;
}

const clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v));
const fmt = (v: number) => String(Math.round(v * 10) / 10);

export function endpoint(
  id: string,
  card: CardGeom,
  col: ColumnGeom,
  scrollTop: number,
  side: Side,
  opts: GeometryOptions = DEFAULT_GEOMETRY,
): Endpoint {
  const top = col.originY + card.top - scrollTop;
  const bottom = top + card.height;
  const x = col.originX + card.left + (side === 'R' ? card.width : 0);
  const visTop = Math.max(top, col.viewTop);
  const visBottom = Math.min(bottom, col.viewBottom);
  if (visBottom - visTop < opts.minVisible) {
    const vis: Visibility = top + card.height / 2 < (col.viewTop + col.viewBottom) / 2 ? -1 : 1;
    return { id, kind: card.kind, x, y: vis < 0 ? col.viewTop : col.viewBottom, vis };
  }
  const inset = Math.min(opts.edgeInset, (visBottom - visTop) / 2);
  const y = clamp(top + Math.min(card.height / 2, opts.anchorMax), visTop + inset, visBottom - inset);
  return { id, kind: card.kind, x, y, vis: 0 };
}

/** Which card sides an edge leaves and enters. Same-column edges use the gutter (left of Goals, else right). */
export function sidesFor(source: NodeType, target: NodeType): { s: Side; t: Side; sameColumn: boolean } {
  const si = COLUMN_INDEX[source];
  const ti = COLUMN_INDEX[target];
  if (si === ti) {
    const side: Side = source === 'GOAL' ? 'L' : 'R';
    return { s: side, t: side, sameColumn: true };
  }
  return si < ti ? { s: 'R', t: 'L', sameColumn: false } : { s: 'L', t: 'R', sameColumn: false };
}

interface Point {
  x: number;
  y: number;
}

export function curvePath(s: Point, t: Point): string {
  const dir = t.x >= s.x ? 1 : -1;
  const dx = clamp(Math.abs(t.x - s.x) * 0.45, 30, 160) * dir;
  return `M${fmt(s.x)} ${fmt(s.y)}C${fmt(s.x + dx)} ${fmt(s.y)} ${fmt(t.x - dx)} ${fmt(t.y)} ${fmt(t.x)} ${fmt(t.y)}`;
}

export function loopPath(s: Point, t: Point, side: Side): string {
  const k = (side === 'R' ? 1 : -1) * (18 + Math.min(34, Math.abs(t.y - s.y) * 0.12));
  return `M${fmt(s.x)} ${fmt(s.y)}C${fmt(s.x + k)} ${fmt(s.y)} ${fmt(t.x + k)} ${fmt(t.y)} ${fmt(t.x)} ${fmt(t.y)}`;
}

/**
 * A short hook from the visible card's side towards the scrolled-away end: out by `hs * stubDx`, then up or down.
 * When the visible card is the edge's target, the path runs into the card so the arrowhead still lands on it.
 */
export function stubPath(v: Point, hs: 1 | -1, dir: -1 | 1, intoCard: boolean, opts: GeometryOptions = DEFAULT_GEOMETRY): string {
  const tipX = v.x + hs * opts.stubDx;
  const tipY = v.y + dir * opts.stubDy;
  const c = v.x + hs * opts.stubDx * 0.7;
  return intoCard
    ? `M${fmt(tipX)} ${fmt(tipY)}C${fmt(tipX)} ${fmt(v.y)} ${fmt(c)} ${fmt(v.y)} ${fmt(v.x)} ${fmt(v.y)}`
    : `M${fmt(v.x)} ${fmt(v.y)}C${fmt(c)} ${fmt(v.y)} ${fmt(tipX)} ${fmt(v.y)} ${fmt(tipX)} ${fmt(tipY)}`;
}

