});

/**
 * A short temporary directory for Chrome, one per Playwright run.
 *
 * Chrome creates its singleton socket and some fetcher directories under $TMPDIR, and leaves the fetcher
 * directories (com.google.Chrome.chrome_chrome_url_fetcher_*) behind when it exits. A Unix socket path must stay
 * under 108 bytes, so a long TMPDIR (such as an agent's scratchpad) stops Chrome from starting at all:
 *   FATAL:process_singleton_posix.cc:313] Socket path too long: <TMPDIR>/com.google.Chrome.XXXXXX/SingletonSocket
 * playwright.config.ts therefore points Chrome at a fresh short directory (in os.tmpdir() when that is short,
 * otherwise in /tmp), and the global teardown below deletes it with whatever Chrome left in it.
 */
import { mkdtempSync, readdirSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { basename, dirname, join, relative } from 'node:path';

const ENV = 'TL_PLAYWRIGHT_CHROME_TMPDIR';
const PREFIX = 'tl-pw-chrome-';
/** Leaves room for "/tl-pw-chrome-XXXXXX/com.google.Chrome.XXXXXX/SingletonSocket" within the 107-byte limit. */
const MAX_BASE_LENGTH = 40;

const base = () => (tmpdir().length <= MAX_BASE_LENGTH ? tmpdir() : '/tmp');

/**
 * The run's directory, created on first use. Playwright loads the config in the runner and again in each worker;
 * the workers inherit the variable from the runner, so they reuse the runner's directory instead of making their own.
 */
export function chromeTmpDir(): string {
  let dir = process.env[ENV];
  if (!dir) {
    dir = mkdtempSync(join(base(), PREFIX));
    process.env[ENV] = dir;
  }
  return dir;
}

/** Paths (relative to `root`) of the files under `dir`, at most `limit`. */
function filesUnder(root: string, dir: string, limit: number, out: string[] = []): string[] {
  let entries;
  try {
    entries = readdirSync(dir, { withFileTypes: true });
  } catch {
    return out;
  }
  for (const entry of entries) {
    if (out.length >= limit) break;
    const path = join(dir, entry.name);
    if (entry.isDirectory()) filesUnder(root, path, limit, out);
    else out.push(relative(root, path));
  }
  return out;
}

/**
 * Global teardown: says what Chrome wrote into the isolated HOME and XDG directories (evidence that it used them
 * instead of the real home folder), then removes the run's directory (only one this module created: name and parent
 * are checked).
 */
export default function removeChromeTmpDir(): void {
  const dir = process.env[ENV];
  if (!dir || !basename(dir).startsWith(PREFIX) || dirname(dir) !== base()) return;
  const written = ['home', 'xdg-config', 'xdg-cache', 'xdg-data'].flatMap((sub) => filesUnder(dir, join(dir, sub), 20));
  console.log(`isolated Chrome HOME/XDG (deleted now): ${written.length > 0 ? written.join(', ') : 'nothing written'}`);
  rmSync(dir, { recursive: true, force: true });
}
/**
 * Global setup (and, through its return value, teardown) of the Playwright run: proves that Chrome left the real
 * home folder alone (docs/m1-plan.md section 10, AT6.15).
 *
 * Chrome runs with HOME and XDG_* pointing into the run's short temp dir (playwright.config.ts), so crash reports,
 * NSS databases and caches land there and are deleted with it. This guard lists the real locations Chrome would
 * otherwise write to before the run and again after it (names, sizes, modification times; never file contents),
 * and fails the run if anything changed. Only a summary is printed: the listings are not stored anywhere.
 */
import { readdirSync, statSync } from 'node:fs';
import { homedir } from 'node:os';
import { join, relative } from 'node:path';

/**
 * Where Chrome writes in a home folder: profile and crash reports, cache, fontconfig cache, NSS certificate database
 * (Chrome 155 uses $XDG_DATA_HOME/pki/nssdb; older versions ~/.pki/nssdb).
 */
const WATCHED = ['.config/google-chrome', '.cache/google-chrome', '.cache/fontconfig', '.pki', '.local/share/pki'];

type Listing = Record<string, string[] | null>;

function walk(root: string, dir: string, out: string[]): void {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const path = join(dir, entry.name);
    const stat = statSync(path, { throwIfNoEntry: false });
    if (!stat) continue;
    out.push(`${relative(root, path)}\t${entry.isDirectory() ? 'dir' : stat.size}\t${Math.round(stat.mtimeMs)}`);
    if (entry.isDirectory() && !entry.isSymbolicLink()) walk(root, path, out);
  }
}

export function listHome(home: string = homedir()): Listing {
  const listing: Listing = {};
  for (const sub of WATCHED) {
    const root = join(home, sub);
    const stat = statSync(root, { throwIfNoEntry: false });
    if (!stat) {
      listing[sub] = null;
      continue;
    }
    const entries: string[] = [];
    walk(root, root, entries);
    listing[sub] = entries.sort();
  }
  return listing;
}

function differences(before: Listing, after: Listing): string[] {
  const out: string[] = [];
  for (const sub of WATCHED) {
    const a = before[sub] ?? null;
    const b = after[sub] ?? null;
    if (a === null && b === null) continue;
    if (a === null || b === null) {
      out.push(`${sub}: ${a === null ? 'appeared' : 'disappeared'}`);
      continue;
    }
    const setA = new Set(a);
    const setB = new Set(b);
    for (const line of b) if (!setA.has(line)) out.push(`${sub}: new or changed ${line.split('\t')[0]}`);
    for (const line of a) if (!setB.has(line)) out.push(`${sub}: removed or changed ${line.split('\t')[0]}`);
  }
  return out;
}

export default function homeGuard(): () => void {
  const before = listHome();
  return () => {
    const after = listHome();
    const changed = differences(before, after);
    if (changed.length > 0) throw new Error(`Chrome changed the real home folder:\n${changed.join('\n')}`);
    console.log(`home guard: ${WATCHED.map((sub) => `~/${sub} ${before[sub] === null ? 'absent' : `${before[sub]?.length} entries`}`).join(', ')}; unchanged`);
  };
}

