 * @param {{ profile: ReturnType<typeof makeProfile> extends Promise<infer P> ? P : never, realHome: boolean, live: boolean, extra?: Record<string, string> }} options
 */
export function instanceEnv(base, { profile, realHome, live, extra = {} }) {
  /** @type {Record<string, string>} */
  const env = {};
  for (const [name, value] of Object.entries(base)) {
    if (value === undefined) continue;
