  let rateLimited;
  const current = () => listRuns().find((r) => r.runId === runId);
  /** Waits for the run's state to satisfy `predicate`; watches the overall deadline and (live) the rate limit. */
  const waitRun = (predicate, label, timeoutMs = deadline - Date.now()) =>
