  facts?: false | FakeFactsOptions;
  mutate?: (facts: LeanFacts) => void;
}

export function model(texts: Texts, options: ModelOptions = {}): ProjectModel {
  const files = Object.entries(texts).map(([path, text]) => parseLeanFile(path, text));
