  check('A: no error toast, the delete is reported with its label', !toasts.some((t) => /stop compiling|Refused|breaks/i.test(t)) && toasts.some((t) => /Delete: Cynder is a character who has a dark past/.test(t)), toasts);
  // Lean then reports the broken users.
  await waitFor(async () => /error/i.test(await badge()), 120000, 'A: Lean reports errors', 500);
  record.A.badge = await badge();
  record.A.cards = { 'd-cond': await cardInfo('d-cond'), 'd-cond2': await cardInfo('d-cond2') };
  log('A after Lean:', JSON.stringify({ badge: record.A.badge, cards: record.A.cards }));
  check('A: Lean then reports the broken users (badge shows errors)', /error/i.test(record.A.badge), record.A.badge);
  await page.screenshot({ path: `${shots}/vc-delete-anyway.png` });
  await undoBtn().click();
