  const back = await settledSnapshot();
  check('A: Undo restores every file byte-exactly', diffSnap(S0, back).length === 0, diffSnap(S0, back));
  check('A: Lean is up to date again after the Undo', await waitUpToDate('after A undo'));
} catch (e) { check('A: scenario ran', false, String(e).slice(0, 300)); }

// ---------------------------------------------------------------------------------------------- D: D->A board impact
try {
  log('--- D: D->A on d-cond (the board asks)');
  await dismissToasts();
  await expand('d-cond');
  await card('d-cond').locator('.tl-details__actions').getByRole('button', { name: 'Make Assumption' }).click();
  const dialog = f.getByTestId('dialog-dependents');
  await dialog.waitFor({ timeout: 10000 });
  const info = await f.evaluate(() => {
    const d = document.querySelector('[data-testid="dialog-dependents"]');
    return {
      title: d?.querySelector('h2')?.textContent ?? null,
      detail: d?.querySelector('[data-testid="dependents-detail"]')?.textContent ?? null,
      paragraphs: [...(d?.querySelectorAll('p') ?? [])].map((p) => p.textContent),
