  const back = await settledSnapshot();
  check('D: Undo restores every file byte-exactly (attic entry removed too)', diffSnap(S0, back).length === 0, diffSnap(S0, back));
  await waitUpToDate('after D undo');
} catch (e) { check('D: scenario ran', false, String(e).slice(0, 300)); }

// ---------------------------------------------------------------------------------------------- E: D->A host-only
try {
  log('--- E: D->A on d-cond2 (only the host knows the untracked user)');
