    record.E.rationaleText = (await f.getByTestId('dialog-rationale').innerText()).replace(/\n+/g, ' | ');
    log('E rationale dialog:', JSON.stringify(record.E.rationaleText));
    await f.getByTestId('dialog-rationale').getByRole('button', { name: 'Skip' }).click();
  }
  const dialog = f.getByTestId('dialog-dependents');
