      title: d?.querySelector('h2')?.textContent ?? null,
      detail: d?.querySelector('[data-testid="dependents-detail"]')?.textContent ?? null,
      paragraphs: [...(d?.querySelectorAll('p') ?? [])].map((p) => p.textContent),
      items: [...(d?.querySelectorAll('[data-testid="dependents"] li') ?? [])].map((li) => li.textContent),
      buttons: [...(d?.querySelectorAll('button') ?? [])].map((b) => [b.textContent, b.disabled]),
    };
  });
  record.E.info = info;
  record.E.toasts = await toastTexts();
  log('E dialog:', JSON.stringify(info), 'toasts', JSON.stringify(record.E.toasts));
  check('E: title worded from the host\'s list', info.title === 'Make Assumption: 1 dependent needs a rewrite', info.title);
  check('E: explanation is the host\'s message (no "stays valid", no "Nothing uses it")', /d_cond2\.holds takes a hypothesis, but as an assumption it becomes/.test(info.detail ?? '') && !/stays valid|Nothing uses it/.test(info.detail ?? ''), info.detail);
  check('E: lists the untracked lemma by its Lean name; "This passes it arguments:"', info.items.includes('Spyro.helper_cond') && info.paragraphs.includes('This passes it arguments:'), { items: info.items, p: info.paragraphs });
  check('E: buttons Rewrite them to use it directly / Keep them, marked broken / Cancel', JSON.stringify(info.buttons.map((b) => b[0])) === JSON.stringify(['Rewrite them to use it directly', 'Keep them, marked broken', 'Cancel']), info.buttons);
  check('E: no error toast for the question', !record.E.toasts.some((t) => /takes a hypothesis|Refused/i.test(t)), record.E.toasts);
  check('E: nothing changed on disk before the answer', diffSnap(S0, snapshot()).length === 0, diffSnap(S0, snapshot()));
