      '/-',
      '@@ telelean v1',
      'id: rival-dark-past',
      'type: DERIVATION',
      "natural_name: Bayonetta's rival has a dark past too",
      'lean: Bayonetta.rival_dark_past',
      '-/',
      'abbrev rival_dark_past : Prop := Spyro.cynder_dark_past',
