101	export function validateGraph(graph: TlGraph): GraphProblem[] {
102	  const problems: GraphProblem[] = [];
103	  const ids = new Set<string>();
104	  for (const node of graph.nodes) {
105	    if (ids.has(node.id)) problems.push({ code: 'duplicate-id', message: `duplicate node id "${node.id}"` });
106	    ids.add(node.id);
107	  }
108	  for (const node of graph.nodes) {
109	    for (const premise of node.premises) {
110	      if (premise === node.id) problems.push({ code: 'self-premise', message: `"${node.id}" lists itself as a premise` });
111	      else if (!ids.has(premise)) {
112	        problems.push({ code: 'dangling-premise', message: `"${node.id}" lists unknown premise "${premise}"` });
113	      }
114	    }
115	  }
116	  for (const edge of graph.edges) {
117	    if (!ids.has(edge.source) || !ids.has(edge.target)) {
118	      problems.push({ code: 'dangling-edge', message: `edge ${edge.id} references an unknown node` });
119	    }
120	  }
121	  const cycle = findPremiseCycle(graph.nodes);
122	  if (cycle) problems.push({ code: 'premise-cycle', message: `premise cycle: ${cycle.join(' -> ')}` });
123	  return problems;
124	}
