/** Returned by `activate` (tests and later integrations listen to the board through it). */
export interface TeleleanApi {
  /** Every validated message the board webview sends. */
  readonly onDidReceiveBoardMessage: vscode.Event<WebviewToHostMessage>;
  /** The open board panel, if any. */
  readonly boardPanel: vscode.WebviewPanel | undefined;
}

export interface OpenBoardArgs {
  /** Which sample graph to show (M0 has no Lean-backed graph yet). Default: "spyro". */
  sample?: SampleName;
}

const SAMPLES: readonly SampleName[] = ['spyro', 'spyro-proved', 'large'];

export function activate(context: vscode.ExtensionContext): TeleleanApi {
  const log = vscode.window.createOutputChannel('telelean', { log: true });
  const messages = new vscode.EventEmitter<WebviewToHostMessage>();
  context.subscriptions.push(log, messages);

  context.subscriptions.push(
    vscode.commands.registerCommand('telelean.openBoard', (args?: OpenBoardArgs) => {
      const sample = args?.sample && SAMPLES.includes(args.sample) ? args.sample : 'spyro';
      BoardPanel.show({ extensionUri: context.extensionUri, log, messages }, sampleGraph(sample));
    }),
    { dispose: () => BoardPanel.current?.dispose() },
  );
  log.info(`telelean activated (VS Code ${vscode.version})`);

  return {
    onDidReceiveBoardMessage: messages.event,
    get boardPanel() {
      return BoardPanel.current?.panel;
    },
  };
}

export function deactivate(): void {}
