/** M0 has no Lean-backed graph yet: the board shows one of the core samples. */
export type SampleName = 'spyro' | 'spyro-proved' | 'large';

export function sampleGraph(name: SampleName): TlGraph {
  switch (name) {
    case 'spyro':
      return spyroGraph();
    case 'spyro-proved':
      return spyroProvedGraph();
    case 'large':
      return largeGraph();
  }
