  }
  return {
    aura: resolveColor('var(--tl-aura)'),
    kindA: resolveColor('var(--tl-kind-a)'),
    kindD: resolveColor('var(--tl-kind-d)'),
    kindG: resolveColor('var(--tl-kind-g)'),
    cardAura,
  };
