  it('rejects when the editor refuses the batch, and when a save fails', async () => {
    const editor = fakeEditor({ 'a.lean': 'a\n' });
    const applier = new CheckedEditApplier({ root: ROOT, text: editor.text, port: editor.port });
    editor.refuseNext();
    await expect(applier.apply([{ path: 'a.lean', before: 'a\n', after: 'b\n' }], 'x')).rejects.toMatchObject({ code: 'conflict' });

    const second = fakeEditor({ 'a.lean': 'a\n' });
    second.failSaves();
    const applier2 = new CheckedEditApplier({ root: ROOT, text: second.text, port: second.port });
    await expect(applier2.apply([{ path: 'a.lean', before: 'a\n', after: 'b\n' }], 'x')).rejects.toMatchObject({
      code: 'internal',
      message: expect.stringContaining('could not be saved'),
    });
  });

  it('refuses paths outside the root and duplicate paths before reading anything', async () => {
