                fileListsProms.push([file]);
            }
        }
        else {
            fileListsProms.push(glob(file, { cwd, ignore: ignoreGlobs }).then((l) => l.map((f) => join(cwd, f))));
        }
    }
    const files = new Set((await Promise.all(fileListsProms)).flat());
    args.ignore?.forEach((i) => files.delete(i));
    return [...files];
}
