70	  semantic?: SemanticSummary;
71	}): TlGraph {
72	  return {
73	    version: args.version,
74	    subject: args.subject,
75	    nodes: args.nodes,
76	    edges: deriveEdges(args.nodes),
77	    vocabulary: args.vocabulary ?? [],
78	    diagnostics: args.diagnostics ?? [],
79	    semantic: args.semantic ?? { state: 'unavailable' },
80	  };
