82	/**
83	 * The layout after moving `id` into `column` above `beforeId` (null = end), starting from the order the board
84	 * currently shows (`current`, e.g. from `orderByLayout`). The result lists every id of `current`, so the board's
85	 * order is pinned once the user has arranged it.
86	 */
87	export function moveInLayout(
88	  layout: Layout,
89	  current: Readonly<Record<NodeType, readonly string[]>>,
90	  id: string,
91	  column: NodeType,
92	  beforeId: string | null,
93	): Layout {
94	  const columns: Record<NodeType, string[]> = { ASSUMPTION: [], DERIVATION: [], GOAL: [] };
95	  for (const kind of NODE_TYPES) columns[kind] = current[kind].filter((x) => x !== id);
96	  const target = columns[column];
97	  const index = beforeId === null ? -1 : target.indexOf(beforeId);
98	  if (index >= 0) target.splice(index, 0, id);
99	  else target.push(id);
100	  return { ...layout, columns };
101	}
102	
103	/** The layout without the given ids (after deletes). */
104	export function withoutIds(layout: Layout, ids: Iterable<string>): Layout {
105	  const drop = new Set(ids);
106	  const columns: Record<NodeType, string[]> = { ASSUMPTION: [], DERIVATION: [], GOAL: [] };
107	  for (const kind of NODE_TYPES) columns[kind] = layout.columns[kind].filter((id) => !drop.has(id));
108	  return { ...layout, columns };
109	}
110	
111	/** The layout with `id` appended to `column` (after adds), unless it is already listed there. */
112	export function appendToLayout(layout: Layout, id: string, column: NodeType): Layout {
113	  if (layout.columns[column].includes(id)) return layout;
114	  const base = withoutIds(layout, [id]);
115	  return { ...base, columns: { ...base.columns, [column]: [...base.columns[column], id] } };
116	}
