/**
 * D-18 delete, computed before asking the user: which declarations go, which premises lose the id, and what will no
 * longer compile (proofs that use the removed `.holds` and statements that mention the removed abbrev).
 */
import { ActionError } from '../actions.js';
import { holdsName } from '../facts.js';
import type { ProjectModel } from '../project/types.js';
import { usersOf } from './dependents.js';
import type { DeletePlan, DeleteRequest } from './types.js';

export function planDel(model: ProjectModel, request: DeleteRequest): DeletePlan {
  const entry = model.nodes.get(request.id);
  if (!entry) throw new ActionError('not-found', `No card "${request.id}".`);
  const node = entry.node;
  const statement = node.lean.statement;
  const exists = (name: string) => model.declFacts.has(name) || [...model.files.values()].some((f) => f.decls.some((d) => d.fullName === name));
  const decls: string[] = [];
  if (statement && exists(statement)) {
    decls.push(statement);
    if (exists(holdsName(statement))) decls.push(holdsName(statement));
  }
  const premiseRemovals = [...model.nodes.values()].filter((n) => n.node.id !== node.id && n.node.premises.includes(node.id)).map((n) => n.node.id);
  const removeDecls = request.keepLean ? [] : decls;
  const brokenDependents = request.keepLean || decls.length === 0 ? [] : usersOf(model, decls, new Set(decls)).all;
  return {
    id: node.id,
    removeDecls,
    premiseRemovals,
    brokenDependents,
    leavesUnmarkedAxiom: request.keepLean && node.lean.justificationKind === 'axiom',
  };
}

/**
 * Planning board actions (docs/m1-plan.md section 6.2, D-18): from a BoardAction and the project model to an EditPlan
 * with whole-file Lean changes, the subject's new layout and archived declarations. Every block edit goes through
 * WP-markup's primitives (unrelated text untouched byte for byte). Every plan that edits a block also writes its
 * derived id (`id:`) and, for a node formalised by adjacency, its pinned binding (`lean:`, D-8).
 */
import { ActionError, type ArchiveEntry, type BoardAction, type EditableField, type EditPlan } from '../actions.js';
import { holdsName } from '../facts.js';
import { emptyLayout, moveInLayout, orderByLayout, withoutIds, type Layout } from '../layout.js';
import type { KnownFieldKey, LeanOp } from '../markup/types.js';
import { deriveId, escapeBodyText, renderBlock } from '../markup/api.js';
import { EVIDENTIALS, STANCES, type Evidential, type NodeType, type Stance } from '../model.js';
import { inboxPath, isSubjectName, libraryRootFile, subjectDir, subjectRootFile } from '../paths.js';
import type { ModelNode, ProjectModel } from '../project/types.js';
import { cutText } from '../project/text.js';
import { planDel } from './planDelete.js';
import { NOUN, planKind } from './planKind.js';
import { EditSession } from './session.js';
import type { PlanContext } from './types.js';
import { subjectScaffold } from './scaffold.js';

const FIELD_KEY: Readonly<Record<EditableField, KnownFieldKey>> = { naturalName: 'natural_name', rationale: 'rationale', stance: 'stance', source: 'source' };

const label = (text: string) => cutText(text, 60);

function entryOf(model: ProjectModel, id: string): ModelNode {
  const entry = model.nodes.get(id);
  if (!entry) throw new ActionError('not-found', `No card "${id}" (it may have been deleted).`);
  return entry;
}

function sentence(value: string | null | undefined): string {
  const text = (value ?? '').trim();
  if (!text) throw new ActionError('invalid', 'The sentence is empty.');
  if (/[\r\n]/.test(text)) throw new ActionError('invalid', 'A sentence is one line.');
  return text;
}

function layoutOf(ctx: PlanContext, subject: string): Layout {
  return ctx.layouts[subject] ?? emptyLayout();
}

/** The subject's column order as the board shows it (layout first, then file order). */
function currentOrder(model: ProjectModel, subject: string, layout: Layout) {
  const nodes = [...model.nodes.values()].map((e) => e.node).filter((n) => n.subject === subject);
  return orderByLayout(nodes, layout);
}

/** D-8: whenever telelean edits the block of a node formalised by adjacency, it pins the binding. */
function pin(session: EditSession, entry: ModelNode): void {
  const node = entry.node;
  if (node.lean.binding === 'adjacent' && node.status.formal === 'formalized' && node.lean.statement) {
    session.setField(entry.file, entry.block, node.id, 'lean', [node.lean.statement]);
  }
}

function archiveEntries(subject: string, nodeId: string, reason: string, archived: ReadonlyArray<{ name: string; text: string }>): ArchiveEntry[] {
  return archived.map((a) => ({ subject, nodeId, declName: a.name, text: a.text, reason }));
}

function planAddNode(model: ProjectModel, action: Extract<BoardAction, { kind: 'add-node' }>, ctx: PlanContext): EditPlan {
  const subject = action.subject;
  if (!model.subjects.some((s) => s.name === subject)) throw new ActionError('not-found', `No subject "${subject}".`);
  const text = sentence(action.naturalName);
  if (action.stance !== undefined && !STANCES.includes(action.stance)) throw new ActionError('invalid', `Unknown stance "${action.stance}".`);
  if (action.source !== undefined && !EVIDENTIALS.includes(action.source)) throw new ActionError('invalid', `Unknown source "${action.source}".`);
  const taken = new Set<string>(model.nodes.keys());
  for (const file of model.files.values()) for (const block of file.blocks) taken.add(block.id);
  const id = deriveId(text, (candidate) => taken.has(candidate));

  const library = model.library;
  const session = new EditSession(model);
  const inbox = inboxPath(subject, library);
  if (!session.exists(inbox)) {
    const scaffold = subjectScaffold(subject, library).find((f) => f.path === inbox);
    session.create(inbox, scaffold?.text ?? '');
    const subjectRoot = subjectRootFile(subject, library);
    session.addImport(session.exists(subjectRoot) ? subjectRoot : libraryRootFile(library), `${library}.${subject}.Inbox`);
  }
  const rationale = action.rationale?.trim();
  const blockText = renderBlock(
    {
      id,
      type: action.type,
      naturalName: text,
      ...(rationale ? { rationale } : {}),
      ...(action.stance ? { stance: action.stance } : {}),
      ...(action.source ? { source: action.source } : {}),
      asserted: ctx.today,
    },
    session.parsed(inbox).eol,
  );
  session.insertBlock(inbox, blockText, { kind: 'end-of-namespace', namespace: subject });
  const layout = layoutOf(ctx, subject);
  return {
    action: 'add-node',
    label: `Add ${NOUN[action.type].toLowerCase()}: ${label(text)}`,
    subject,
    nodes: [id],
    changes: session.changes(),
    layout: { subject, layout: moveInLayout(layout, currentOrder(model, subject, layout), id, action.type, null) },
    nodeId: id,
  };
}

function planEditNode(model: ProjectModel, action: Extract<BoardAction, { kind: 'edit-node' }>): EditPlan {
  const entry = entryOf(model, action.id);
  const node = entry.node;
  let value: string | null;
  switch (action.field) {
    case 'naturalName':
      value = sentence(action.value);
      break;
    case 'rationale':
      value = action.value === null || action.value.trim() === '' ? null : action.value.trim();
      break;
    case 'stance':
      if (action.value !== null && !STANCES.includes(action.value as Stance)) throw new ActionError('invalid', `Unknown stance "${action.value}".`);
      value = action.value;
      break;
    case 'source':
      if (action.value !== null && !EVIDENTIALS.includes(action.value as Evidential)) throw new ActionError('invalid', `Unknown source "${action.value}".`);
      value = action.value;
      break;
    default:
      throw new ActionError('invalid', 'This field cannot be edited on the board.');
  }
  const session = new EditSession(model);
  // D-9 docstring mirror: follow the sentence when the statement's docstring is the old sentence.
  if (action.field === 'naturalName' && value !== null && entry.statementDecl && node.lean.statement) {
    const docstring = entry.statementDecl.decl.docstring?.trim();
    if (docstring !== undefined && docstring === escapeBodyText(node.naturalName).trim()) {
      session.leanOps(entry.statementDecl.file, [{ op: 'set-docstring', decl: node.lean.statement, text: value }]);
    }
  }
  session.setField(entry.file, entry.block, node.id, FIELD_KEY[action.field], value);
  pin(session, entry);
  const shown = action.field === 'naturalName' && value !== null ? value : node.naturalName;
  const text =
    action.field === 'naturalName'
      ? `Edit sentence: ${label(shown)}`
      : action.field === 'rationale'
        ? `Edit why: ${label(shown)}`
        : `Set ${action.field}: ${value ?? 'none'} (${label(shown)})`;
  return { action: 'edit-node', label: text, subject: node.subject, nodes: [node.id], changes: session.changes() };
}

function planDeleteNode(model: ProjectModel, action: Extract<BoardAction, { kind: 'delete-node' }>, ctx: PlanContext): EditPlan {
  const entry = entryOf(model, action.id);
  const node = entry.node;
  const del = planDel(model, { id: node.id, keepLean: action.keepLean });
  const session = new EditSession(model);
  const archive: ArchiveEntry[] = [];
  if (!action.keepLean && node.lean.statement && del.removeDecls.length > 0) {
    const statement = node.lean.statement;
    const ops = new Map<string, LeanOp[]>();
    const add = (file: string, op: LeanOp) => ops.set(file, [...(ops.get(file) ?? []), op]);
    const statementFile = entry.statementDecl?.file ?? model.declFacts.get(statement)?.file;
    if (statementFile) add(statementFile, { op: 'remove-decl', name: statement, archive: false });
    if (del.removeDecls.includes(holdsName(statement))) {
      const holdsFile = entry.holdsDecl?.file ?? model.declFacts.get(holdsName(statement))?.file;
      if (holdsFile) add(holdsFile, { op: 'remove-holds', statement, archive: node.lean.justificationKind !== 'axiom' });
    }
    for (const file of [...ops.keys()].sort()) archive.push(...archiveEntries(node.subject, node.id, 'deleted', session.leanOps(file, ops.get(file) ?? [])));
  }
  session.removeBlock(entry.file, entry.block);
  for (const id of del.premiseRemovals) {
    const other = entryOf(model, id);
    const premises = other.node.premises.filter((p) => p !== node.id);
    session.setField(other.file, other.block, other.node.id, 'premises', premises.length > 0 ? premises : null);
    pin(session, other);
  }
  return {
    action: 'delete-node',
    label: `Delete: ${label(node.naturalName)}`,
    subject: node.subject,
    nodes: [node.id, ...del.premiseRemovals],
    changes: session.changes(),
    layout: { subject: node.subject, layout: withoutIds(layoutOf(ctx, node.subject), [node.id]) },
    ...(archive.length > 0 ? { archive } : {}),
  };
}

function planChangeKind(model: ProjectModel, action: Extract<BoardAction, { kind: 'change-kind' }>, ctx: PlanContext): EditPlan {
  const entry = entryOf(model, action.id);
  const node = entry.node;
  const plan = planKind(model, { id: node.id, to: action.to, ...(action.dependents ? { dependents: action.dependents } : {}) });
  const session = new EditSession(model);
  const archive: ArchiveEntry[] = [];
  const reason = `${NOUN[plan.from]} -> ${NOUN[plan.to]}`;
  for (const group of plan.leanOps) archive.push(...archiveEntries(node.subject, node.id, reason, session.leanOps(group.file, group.ops)));
  const fields = [...plan.fieldChanges];
  const rationale = action.rationale?.trim();
  if (action.to === 'ASSUMPTION' && rationale) fields.push({ key: 'rationale', value: rationale });
  for (const change of fields) session.setField(entry.file, entry.block, node.id, change.key, change.value);
  pin(session, entry);
  const layout = layoutOf(ctx, node.subject);
  const rewrote = plan.leanOps.some((g) => g.ops.some((op) => op.op === 'add-hypothesis'));
  const suffix = action.dependents === 'rewrite' && rewrote ? ' (dependents rewritten)' : action.dependents === 'mark-broken' && plan.broken.length > 0 ? ' (dependents marked broken)' : '';
  return {
    action: 'change-kind',
    label: `Make ${NOUN[action.to]}: ${label(node.naturalName)}${suffix}`,
    subject: node.subject,
    nodes: [node.id],
    changes: session.changes(),
    layout: { subject: node.subject, layout: moveInLayout(layout, currentOrder(model, node.subject, layout), node.id, action.to, action.beforeId) },
    ...(archive.length > 0 ? { archive } : {}),
  };
}

function planReorder(model: ProjectModel, action: Extract<BoardAction, { kind: 'reorder' }>, ctx: PlanContext): EditPlan {
  const entry = entryOf(model, action.id);
  const node = entry.node;
  if (action.column !== node.type) throw new ActionError('invalid', `Moving a card to the ${NOUN[action.column]} column changes its kind: drop it on a "Make ${NOUN[action.column]}" zone.`);
  if (action.beforeId === node.id) throw new ActionError('invalid', 'A card cannot be placed before itself.');
  const layout = layoutOf(ctx, node.subject);
  return {
    action: 'reorder',
    label: `Move: ${label(node.naturalName)}`,
    subject: node.subject,
    nodes: [node.id],
    changes: [],
    layout: { subject: node.subject, layout: moveInLayout(layout, currentOrder(model, node.subject, layout), node.id, action.column, action.beforeId) },
    layoutOnly: true,
  };
}

function planSetPremises(model: ProjectModel, action: Extract<BoardAction, { kind: 'set-premises' }>): EditPlan {
  const entry = entryOf(model, action.target);
  const node = entry.node;
  const premises = [...new Set(action.premises)];
  if (premises.length === 0) throw new ActionError('not-yet', 'Self-evident? arrives with Claude in M2');
  for (const id of premises) {
    if (id === node.id) throw new ActionError('invalid', 'A card cannot support itself.');
    const premise = model.nodes.get(id);
    if (!premise) throw new ActionError('invalid', `No card "${id}".`);
    if (premise.node.subject !== node.subject) throw new ActionError('invalid', `"${id}" belongs to subject ${premise.node.subject}: premises stay within one subject.`);
  }
  // No premise cycle: the target must not support (transitively) any of its new premises.
  const premisesOf = (id: string) => (id === node.id ? premises : (model.nodes.get(id)?.node.premises ?? []));
  const seen = new Set<string>();
  const stack = [...premises];
  while (stack.length > 0) {
    const id = stack.pop() as string;
    if (id === node.id) throw new ActionError('invalid', 'These premises would make a cycle: a card would (indirectly) support itself.');
    if (seen.has(id)) continue;
    seen.add(id);
    stack.push(...premisesOf(id));
  }
  const session = new EditSession(model);
  session.setField(entry.file, entry.block, node.id, 'premises', premises);
  pin(session, entry);
  return {
    action: 'set-premises',
    label: `These suffice: ${label(node.naturalName)} ← ${premises.length} premise${premises.length === 1 ? '' : 's'}`,
    subject: node.subject,
    nodes: [node.id, ...premises],
    changes: session.changes(),
  };
}

function planCreateSubject(model: ProjectModel, action: Extract<BoardAction, { kind: 'create-subject' }>): EditPlan {
  const name = action.name;
  const library = model.library;
  if (!isSubjectName(name)) throw new ActionError('invalid', `"${name}" is not a subject name: use a capitalised Lean identifier (letters, digits, "_").`);
  const dir = `${subjectDir(name, library)}/`;
  if (model.subjects.some((s) => s.name === name) || [...model.files.keys()].some((p) => p === subjectRootFile(name, library) || p.startsWith(dir))) {
    throw new ActionError('invalid', `A subject named ${name} exists already.`);
  }
  const session = new EditSession(model);
  for (const file of subjectScaffold(name, library)) session.create(file.path, file.text);
  session.addImport(libraryRootFile(library), `${library}.${name}`);
  return { action: 'create-subject', label: `New subject: ${name}`, subject: name, nodes: [], changes: session.changes(), layout: { subject: name, layout: emptyLayout() } };
}

export function plan(model: ProjectModel, action: BoardAction, ctx: PlanContext): EditPlan {
  switch (action.kind) {
    case 'add-node':
      return planAddNode(model, action, ctx);
    case 'edit-node':
      return planEditNode(model, action);
    case 'delete-node':
      return planDeleteNode(model, action, ctx);
    case 'change-kind':
      return planChangeKind(model, action, ctx);
    case 'reorder':
      return planReorder(model, action, ctx);
    case 'set-premises':
      return planSetPremises(model, action);
    case 'create-subject':
      return planCreateSubject(model, action);
    default: {
      const never: never = action;
      throw new ActionError('invalid', `Unknown action ${(never as { kind: string }).kind}.`);
    }
  }
}

export type { NodeType };

/**
 * The files of a new subject (docs/m1-plan.md section 7.1). Moved here unchanged from edit/index.ts (which re-exports
 * it) so the planner can use it without a circular import; contracts.test.ts guards the exact texts.
 */
import { ActionError } from '../actions.js';
import { isSubjectName, subjectModulePath, subjectRootFile } from '../paths.js';

/**
 * The files of a new subject, with the exact texts of docs/m1-plan.md section 7.1: `<library>/<S>.lean` (imports
 * Vocabulary, Inbox, Main), `<library>/<S>/Vocabulary.lean`, `Inbox.lean` (imports Vocabulary) and `Main.lean`
 * (imports Vocabulary and Inbox), each module a `namespace <S> … end <S>` with a one-line comment saying what
 * belongs there. Shared by `create-subject` (WP-model) and Initialize (WP-workspace) so both write identical text.
 * Does not touch `<library>.lean` or sidecars. Implemented with the contract (verified to build on Lean 4.35).
 * Throws ActionError `invalid` for a name that is not a subject name.
 */
export function subjectScaffold(subject: string, library: string): Array<{ path: string; text: string }> {
  if (!isSubjectName(subject)) throw new ActionError('invalid', `"${subject}" is not a subject name: use a capitalised Lean identifier (letters, digits, "_").`);
  if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(library)) throw new ActionError('invalid', `"${library}" is not a library name.`);
  const module = (name: string) => `${library}.${subject}.${name}`;
  return [
    {
      path: subjectRootFile(subject, library),
      text: `import ${module('Vocabulary')}\nimport ${module('Inbox')}\nimport ${module('Main')}\n`,
    },
    {
      path: subjectModulePath(subject, 'Vocabulary', library),
      text: `-- Vocabulary of ${subject}: types, predicates and constants (the board lists them in its Vocabulary group).\nnamespace ${subject}\n\nend ${subject}\n`,
    },
    {
      path: subjectModulePath(subject, 'Inbox', library),
      text: `import ${module('Vocabulary')}\n\n-- New cards typed on the telelean board are added here.\nnamespace ${subject}\n\nend ${subject}\n`,
    },
    {
      path: subjectModulePath(subject, 'Main', library),
      text: `import ${module('Vocabulary')}\nimport ${module('Inbox')}\n\n-- Formalised cards: a statement \`abbrev n : Prop := …\` and its \`n.holds\`.\nnamespace ${subject}\n\nend ${subject}\n`,
    },
  ];
}

/**
 * WP-model: planning board actions (docs/m1-plan.md sections 5.4 and 6.2). Signatures and documented behaviour are
 * FROZEN; the implementation lives in ./planAction.ts, ./planKind.ts, ./planDelete.ts and ./scaffold.ts.
 */
import type { BoardAction, EditPlan } from '../actions.js';
import type { ProjectModel } from '../project/types.js';
import { plan } from './planAction.js';
import { planDel } from './planDelete.js';
import { planKind } from './planKind.js';
import type { DeletePlan, DeleteRequest, KindChangePlan, KindChangeRequest, PlanContext } from './types.js';

export * from './types.js';
export { subjectScaffold } from './scaffold.js';

/**
 * Plans one board action against the current parsed files (pure). Throws ActionError for refusals
 * (`not-found`, `invalid`, `needs-confirmation`, `facts-stale`, `unsafe`, `not-yet`). Edits blocks only through
 * WP-markup's primitives, so unrelated text is untouched byte for byte.
 */
export function planAction(model: ProjectModel, action: BoardAction, ctx: PlanContext): EditPlan {
  return plan(model, action, ctx);
}

/**
 * D-11 with the facts: which `.holds` changes, which dependents need `(h : n)`, what breaks (docs/m1-plan.md 6.2).
 * `rewrite` throws ActionError `facts-stale` unless every touched file is fresh, and `unsafe` (listing them) when a
 * declaration in the closure of users of `n.holds` is not a `theorem` (a def/instance/abbrev cannot take a
 * hypothesis without changing its type) or, for an axiom `n.holds`, when a declaration whose `#print axioms` lists
 * it is not reached through the `.ilean` references (a use the mechanical rewrite could not find).
 */
export function planKindChange(model: ProjectModel, request: KindChangeRequest): KindChangePlan {
  return planKind(model, request);
}

/**
 * D-18: what a delete removes and breaks. `brokenDependents` covers proofs that use the removed `.holds` AND
 * statements (other nodes' or untracked) that mention the removed statement abbrev.
 */
export function planDelete(model: ProjectModel, request: DeleteRequest): DeletePlan {
  return planDel(model, request);
}

/**
 * A reference stand-in for WP-markup's text primitives (markup/api.ts), written from their frozen documentation, so
 * the planner's orchestration can be tested before WP-markup lands (`vi.mock`, see plans.fake.test.ts). The same
 * scenarios run against the real primitives in plans.wp1.test.ts (skipped until WP-markup is implemented).
 * Simplifications: LF line breaks, simple Lean only. Not used by any production code.
 */
import { FIELD_ORDER, type DeclInfo, type InsertWhere, type KnownFieldKey, type LeanOp, type LeanOpsResult, type MarkupBlock, type NewBlock, type ParsedFile, type TextEdit } from '../../../src/markup/types.js';
import { parseFixture } from '../../project/helpers/parseFixture.js';

const findDecl = (file: ParsedFile, name: string): DeclInfo | undefined => file.decls.find((d) => d.fullName === name);
function relativeName(fullName: string, namespace: readonly string[]): string {
  for (let i = namespace.length; i > 0; i--) {
    const prefix = `${namespace.slice(0, i).join('.')}.`;
    if (fullName.startsWith(prefix) && fullName.length > prefix.length) return fullName.slice(prefix.length);
  }
  return fullName;
}

export function escapeJsonValue(value: string): string {
  return JSON.stringify(value)
    .replace(/\/(?=-)/g, '\\u002f')
    .replace(/(?<=-)\//g, '\\/');
}

export function formatFieldValue(key: KnownFieldKey | string, value: string | readonly string[]): string {
  void key;
  if (typeof value !== 'string') return value.join(', ');
  // eslint-disable-next-line no-control-regex
  const needsJson = value.includes('/-') || value.includes('-/') || value.startsWith('"') || /[\u0000-\u001f]/.test(value) || value !== value.trim();
  return needsJson ? escapeJsonValue(value) : value;
}

export function escapeBodyText(body: string): string {
  return body.replace(/-\//g, '-\\/').replace(/\/-/g, '/\\-');
}

export function renderBlock(block: NewBlock, eol: '\n' | '\r\n' = '\n'): string {
  const fields: Array<[string, string | readonly string[] | undefined]> = [
    ['id', block.id],
    ['type', block.type],
    ['natural_name', block.naturalName],
    ['rationale', block.rationale],
    ['stance', block.stance],
    ['source', block.source],
    ['premises', block.premises],
    ['asserted', block.asserted],
    ['lean', block.lean],
  ];
  const lines = ['/-', '@@ telelean v1'];
  for (const [key, value] of fields) if (value !== undefined) lines.push(`${key}: ${formatFieldValue(key, value)}`);
  for (const [key, value] of block.extra ?? []) lines.push(`${key}: ${formatFieldValue(key, value)}`);
  if (block.body !== undefined) lines.push('---', escapeBodyText(block.body));
  lines.push('-/');
  return lines.join(eol);
}

function slug(text: string): string {
  return (
    text
      .toLowerCase()
      .normalize('NFKD')
      .replace(/[̀-ͯ]/g, '')
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '')
      .split('-')
      .slice(0, 6)
      .join('-') || 'n-000000'
  );
}

export function deriveId(naturalName: string, taken: (id: string) => boolean): string {
  const base = slug(naturalName);
  if (!taken(base)) return base;
  for (let n = 2; ; n++) if (!taken(`${base}-${n}`)) return `${base}-${n}`;
}

export function applyTextEdits(text: string, edits: readonly TextEdit[]): string {
  const sorted = [...edits].sort((a, b) => b.span.start - a.span.start || b.span.end - a.span.end);
  let out = text;
  let limit = Infinity;
  for (const edit of sorted) {
    if (edit.span.end > limit) throw new Error('overlapping edits');
    out = out.slice(0, edit.span.start) + edit.newText + out.slice(edit.span.end);
    limit = edit.span.start;
  }
  return out;
}

/** End of the line break after `offset` (or `offset` at EOF). */
function afterLineBreak(text: string, offset: number): number {
  if (text.startsWith('\r\n', offset)) return offset + 2;
  return text[offset] === '\n' ? offset + 1 : offset;
}

export function setBlockField(file: ParsedFile, block: MarkupBlock, key: KnownFieldKey, value: string | readonly string[] | null): TextEdit[] {
  const edits: TextEdit[] = [];
  const inserts = new Map<number, string[]>();
  const insertAfter = (offset: number, line: string) => inserts.set(offset, [...(inserts.get(offset) ?? []), line]);
  const existing = block.lines.find((l) => l.key === key);
  if (value === null) {
    if (existing) edits.push({ span: { start: existing.span.start, end: afterLineBreak(file.text, existing.span.end) }, newText: '' });
  } else {
    const line = `${key}: ${formatFieldValue(key, value)}`;
    if (existing) edits.push({ span: existing.span, newText: line });
    else {
      const order = FIELD_ORDER.indexOf(key);
      const before = block.lines.filter((l) => {
        const i = FIELD_ORDER.indexOf(l.key as KnownFieldKey);
        return i >= 0 && i < order;
      });
      const anchor = before.length > 0 ? (before[before.length - 1]?.span.end ?? block.markerSpan.end) : block.markerSpan.end;
      if (!block.idWritten && key !== 'id' && anchor === block.markerSpan.end) insertAfter(anchor, `id: ${block.id}`);
      insertAfter(anchor, line);
    }
  }
  if (!block.idWritten && key !== 'id' && !inserts.has(block.markerSpan.end)) insertAfter(block.markerSpan.end, `id: ${block.id}`);
  for (const [offset, lines] of inserts) edits.push({ span: { start: offset, end: offset }, newText: lines.map((l) => `${file.eol}${l}`).join('') });
  return edits;
}

export function removeBlockEdits(file: ParsedFile, block: MarkupBlock): TextEdit[] {
  const text = file.text;
  let end = afterLineBreak(text, block.span.end);
  const prevBlank = block.span.start === 0 || text.slice(0, block.span.start).endsWith('\n\n');
  if (prevBlank && text[end] === '\n') end += 1;
  return [{ span: { start: block.span.start, end }, newText: '' }];
}

export function insertBlockEdits(file: ParsedFile, blockText: string, where: InsertWhere): TextEdit[] {
  const text = file.text;
  const eol = file.eol;
  if (where.kind === 'end-of-namespace') {
    const lines = text.split('\n');
    let offset = 0;
    let nsLine = -1;
    const starts: number[] = [];
    lines.forEach((line, i) => {
      starts.push(offset);
      if (line === `namespace ${where.namespace}`) nsLine = i;
      offset += line.length + 1;
    });
    const endLine = lines.findIndex((line, i) => i > nsLine && line === `end ${where.namespace}`);
    if (nsLine >= 0 && endLine >= 0) {
      const endStart = starts[endLine] ?? text.length;
      const contentEnd = text.slice(0, endStart).trimEnd().length;
      return [{ span: { start: contentEnd, end: endStart }, newText: `${eol}${eol}${blockText}${eol}${eol}` }];
    }
  }
  const contentEnd = text.trimEnd().length;
  return [{ span: { start: contentEnd, end: text.length }, newText: `${eol}${eol}${blockText}${eol}` }];
}

export function applyLeanOps(file: ParsedFile, ops: readonly LeanOp[]): LeanOpsResult {
  const result: LeanOpsResult = { edits: [], archived: [], problems: [] };
  const text = file.text;
  const removal = (decl: DeclInfo): TextEdit => ({ span: { start: decl.span.start, end: afterLineBreak(text, decl.span.end) }, newText: '' });
  for (const op of ops) {
    switch (op.op) {
      case 'add-holds-axiom': {
        const decl = findDecl(file, op.statement);
        if (!decl) {
          result.problems.push(`${op.statement} not found.`);
          break;
        }
        const short = relativeName(op.statement, decl.namespace);
        result.edits.push({ span: { start: decl.span.end, end: decl.span.end }, newText: `${file.eol}axiom ${short}.holds : ${short}` });
        break;
      }
      case 'holds-theorem-to-axiom': {
        const holds = findDecl(file, `${op.statement}.holds`);
        if (!holds) {
          result.problems.push(`${op.statement}.holds not found.`);
          break;
        }
        const short = relativeName(op.statement, holds.namespace);
        result.archived.push({ name: `${op.statement}.holds`, text: text.slice(holds.span.start, holds.span.end) });
        result.edits.push({ span: holds.span, newText: `axiom ${short}.holds : ${short}` });
        break;
      }
      case 'remove-holds':
      case 'remove-decl': {
        const name = op.op === 'remove-holds' ? `${op.statement}.holds` : op.name;
        const decl = findDecl(file, name);
        if (!decl) {
          result.problems.push(`${name} not found.`);
          break;
        }
        if (op.archive) result.archived.push({ name, text: text.slice(decl.span.start, decl.span.end) });
        result.edits.push(removal(decl));
        break;
      }
      case 'add-hypothesis': {
        const decl = findDecl(file, op.decl);
        if (!decl?.nameSpan) {
          result.problems.push(`${op.decl} not found.`);
          break;
        }
        result.edits.push({ span: { start: decl.nameSpan.end, end: decl.nameSpan.end }, newText: ` (${op.hypName} : ${op.hypType})` });
        for (const span of op.replace) result.edits.push({ span, newText: op.hypName });
        break;
      }
      case 'apply-hypothesis': {
        for (const span of op.replace) {
          const start = text[span.start - 1] === '@' ? span.start - 1 : span.start;
          result.edits.push({ span: { start, end: span.end }, newText: `(${text.slice(start, span.end)} ${op.hypName})` });
        }
        break;
      }
      case 'set-docstring': {
        const decl = findDecl(file, op.decl);
        if (!decl) {
          result.problems.push(`${op.decl} not found.`);
          break;
        }
        const doc = `/-- ${escapeBodyText(op.text)} -/`;
        if (decl.docSpan) result.edits.push({ span: decl.docSpan, newText: doc });
        else result.edits.push({ span: { start: decl.span.start, end: decl.span.start }, newText: `${doc}${file.eol}` });
        break;
      }
    }
  }
  if (result.problems.length > 0) result.edits = [];
  return result;
}

export function parseLeanFile(path: string, text: string): ParsedFile {
  return parseFixture(path, text);
}

/** Everything the planner imports from markup/api.ts, faked. */
export const fakeMarkup = {
  escapeJsonValue,
  formatFieldValue,
  escapeBodyText,
  renderBlock,
  deriveId,
  applyTextEdits,
  setBlockField,
  removeBlockEdits,
  insertBlockEdits,
  applyLeanOps,
  parseLeanFile,
};

/**
 * AT2.6-AT2.8 text scenarios: the plans' exact file texts, labels, layouts and archives. Registered twice: with the
 * reference fake of WP-markup's primitives (plans.fake.test.ts, runs now) and with the real ones
 * (plans.wp1.test.ts, skipped until WP-markup is implemented; the integrator removes the gate).
 */
import { describe, expect, it } from 'vitest';
import { ActionError, type EditPlan, type FileChange } from '../../../src/actions.js';
import { planAction, type PlanContext } from '../../../src/edit/index.js';
import { emptyLayout } from '../../../src/layout.js';
import { buildProjectModel, type ProjectModel } from '../../../src/project/index.js';
import { fakeFacts, freshHashes } from '../../project/helpers/fakeFacts.js';
import { SPYRO_TEXTS, spyroInput, spyroProvedInput, type Parser } from '../../project/helpers/spyro.js';

const CTX: PlanContext = { today: '2026-11-02', now: '2026-11-02T10:00:00.000Z', layouts: {} };

const change = (plan: EditPlan, path: string): FileChange | undefined => plan.changes.find((c) => c.path === path);
const after = (plan: EditPlan, path: string): string | null | undefined => change(plan, path)?.after;

const ZELDA_VOCAB = 'namespace Zelda\n\n/-- heroes -/\naxiom Hero : Type\n\nend Zelda\n';
const ZELDA_MAIN = [
  'import Model.Zelda.Vocabulary',
  '',
  'namespace Zelda',
  '',
  '/-',
  '@@ telelean v1',
  'id: spyro-is-purple',
  'type: GOAL',
  'natural_name: Somebody else wrote this id',
  '-/',
  '',
  'end Zelda',
  '',
].join('\n');

/** A small subject `S` with an adjacently bound, id-less assumption (D-8 pinning and derived ids). */
const ADJ_VOCAB = 'namespace S\n\n/-- things -/\naxiom T : Type\n/-- is good -/\naxiom Good : T → Prop\n\nend S\n';
const ADJ_MAIN = [
  'import Model.S.Vocabulary',
  '',
  'namespace S',
  '',
  '/-',
  '@@ telelean v1',
  'type: ASSUMPTION',
  'natural_name: Everything is good',
  'asserted: 2026-11-01',
  '-/',
  '/-- Everything is good -/',
  'abbrev all_good : Prop := ∀ x : T, Good x',
  'axiom all_good.holds : all_good',
  '',
  'end S',
  '',
].join('\n');

function project(parse: Parser, texts: Record<string, string>, facts = true): ProjectModel {
  const files = Object.entries(texts).map(([path, text]) => parse(path, text));
  return buildProjectModel({ files, fileHashes: freshHashes(files), ...(facts ? { facts: fakeFacts(files) } : {}), library: 'Model' });
}

function refusal(fn: () => unknown): ActionError {
  try {
    fn();
  } catch (error) {
    if (error instanceof ActionError) return error;
    throw error;
  }
  throw new Error('expected an ActionError');
}

export function planScenarios(parse: Parser): void {
  const spyro = () => buildProjectModel(spyroInput(parse));
  const proved = () => buildProjectModel(spyroProvedInput(parse));

  describe('AT2.6 add-node', () => {
    it('creates a missing Inbox from the scaffold text, imports it from the library root (legacy layout), appends the card', () => {
      const plan = planAction(spyro(), { kind: 'add-node', subject: 'Spyro', type: 'ASSUMPTION', naturalName: '  Spyro is purple ', rationale: 'seen it', stance: 'believe' }, CTX);
      expect(plan).toMatchObject({ action: 'add-node', label: 'Add assumption: Spyro is purple', subject: 'Spyro', nodes: ['spyro-is-purple'], nodeId: 'spyro-is-purple' });
      expect(plan.changes.map((c) => [c.path, c.before === null])).toEqual([
        ['Model.lean', false],
        ['Model/Spyro/Inbox.lean', true],
      ]);
      expect(after(plan, 'Model.lean')).toBe('import Model.Spyro.Main\nimport Model.Spyro.Inbox\n');
      expect(after(plan, 'Model/Spyro/Inbox.lean')).toBe(
        [
          'import Model.Spyro.Vocabulary',
          '',
          '-- New cards typed on the telelean board are added here.',
          'namespace Spyro',
          '',
          '/-',
          '@@ telelean v1',
          'id: spyro-is-purple',
          'type: ASSUMPTION',
          'natural_name: Spyro is purple',
          'rationale: seen it',
          'stance: believe',
          'asserted: 2026-11-02',
          '-/',
          '',
          'end Spyro',
          '',
        ].join('\n'),
      );
      expect(plan.layout).toEqual({
        subject: 'Spyro',
        layout: { ...emptyLayout(), columns: { ASSUMPTION: ['pg-no-dark-past', 'cynder-dark-past', 'new-spyro-pg', 'spyro-is-purple'], DERIVATION: [], GOAL: ['cynder-not-good'] } },
      });
    });

    it('imports a created Inbox from the subject root when there is one; ids are unique across subjects', () => {
      const model = project(parse, {
        'Model.lean': 'import Model.Spyro\nimport Model.Zelda.Main\n',
        'Model/Spyro.lean': 'import Model.Spyro.Main\n',
        'Model/Spyro/Main.lean': SPYRO_TEXTS.main,
        'Model/Spyro/Vocabulary.lean': SPYRO_TEXTS.vocabulary,
        'Model/Zelda/Main.lean': ZELDA_MAIN,
        'Model/Zelda/Vocabulary.lean': ZELDA_VOCAB,
      });
      const plan = planAction(model, { kind: 'add-node', subject: 'Spyro', type: 'GOAL', naturalName: 'Spyro is purple' }, CTX);
      expect(plan.nodeId).toBe('spyro-is-purple-2');
      expect(plan.label).toBe('Add goal: Spyro is purple');
      expect(plan.changes.map((c) => c.path)).toEqual(['Model/Spyro.lean', 'Model/Spyro/Inbox.lean']);
      expect(after(plan, 'Model/Spyro.lean')).toBe('import Model.Spyro.Main\nimport Model.Spyro.Inbox\n');
    });

    it('adds to an existing Inbox at the end of its namespace, verbatim (trimmed) sentence, escaped when needed', () => {
      const inbox = 'import Model.S.Vocabulary\n\n-- New cards typed on the telelean board are added here.\nnamespace S\n\nend S\n';
      const model = project(parse, { 'Model/S/Vocabulary.lean': ADJ_VOCAB, 'Model/S/Inbox.lean': inbox, 'Model/S/Main.lean': ADJ_MAIN });
      const plan = planAction(model, { kind: 'add-node', subject: 'S', type: 'DERIVATION', naturalName: 'It follows -/ really' }, CTX);
      expect(plan.changes.map((c) => c.path)).toEqual(['Model/S/Inbox.lean']);
      expect(after(plan, 'Model/S/Inbox.lean')).toBe(
        'import Model.S.Vocabulary\n\n-- New cards typed on the telelean board are added here.\nnamespace S\n\n/-\n@@ telelean v1\nid: it-follows-really\ntype: DERIVATION\nnatural_name: "It follows -\\/ really"\nasserted: 2026-11-02\n-/\n\nend S\n',
      );
      expect(plan.layout?.layout.columns.DERIVATION).toEqual(['it-follows-really']);
      expect(refusal(() => planAction(model, { kind: 'add-node', subject: 'S', type: 'GOAL', naturalName: '   ' }, CTX)).code).toBe('invalid');
      expect(refusal(() => planAction(model, { kind: 'add-node', subject: 'Nope', type: 'GOAL', naturalName: 'x' }, CTX)).code).toBe('not-found');
    });
  });

  describe('AT2.6 edit-node', () => {
    it('the docstring mirror follows when the docstring equals the old sentence', () => {
      const plan = planAction(spyro(), { kind: 'edit-node', id: 'cynder-dark-past', field: 'naturalName', value: 'Cynder has a very dark past' }, CTX);
      expect(plan).toMatchObject({ action: 'edit-node', label: 'Edit sentence: Cynder has a very dark past', subject: 'Spyro', nodes: ['cynder-dark-past'] });
      expect(after(plan, 'Model/Spyro/Main.lean')).toBe(
        SPYRO_TEXTS.main
          .replace('natural_name: Cynder is a character who has a dark past', 'natural_name: Cynder has a very dark past')
          .replace('/-- Cynder is a character who has a dark past -/', '/-- Cynder has a very dark past -/'),
      );
    });

    it('the docstring is left alone when it differs from the old sentence', () => {
      const plan = planAction(proved(), { kind: 'edit-node', id: 'pg-no-dark-past', field: 'naturalName', value: 'PG games avoid dark pasts' }, CTX);
      expect(after(plan, 'Model/Spyro/Main.lean')).toBe(SPYRO_TEXTS.provedMain.replace('natural_name: PG games cannot have characters with dark pasts', 'natural_name: PG games avoid dark pasts'));
    });

    it('an adjacent binding gets pinned (lean:) and a derived id written (id:)', () => {
      const model = project(parse, { 'Model/S/Vocabulary.lean': ADJ_VOCAB, 'Model/S/Main.lean': ADJ_MAIN });
      const plan = planAction(model, { kind: 'edit-node', id: 'everything-is-good', field: 'rationale', value: 'I looked' }, CTX);
      expect(plan.label).toBe('Edit why: Everything is good');
      expect(after(plan, 'Model/S/Main.lean')).toBe(
        ADJ_MAIN.replace(
          '@@ telelean v1\ntype: ASSUMPTION\nnatural_name: Everything is good\nasserted: 2026-11-01\n-/',
          '@@ telelean v1\nid: everything-is-good\ntype: ASSUMPTION\nnatural_name: Everything is good\nrationale: I looked\nasserted: 2026-11-01\nlean: S.all_good\n-/',
        ),
      );
    });

    it('null removes rationale, stance or source (never the sentence); chips are validated', () => {
      const model = spyro();
      const plan = planAction(model, { kind: 'edit-node', id: 'new-spyro-pg', field: 'source', value: null }, CTX);
      expect(plan.label).toBe('Set source: none (The new Spyro game is PG)');
      expect(after(plan, 'Model/Spyro/Main.lean')).toBe(SPYRO_TEXTS.main.replace('source: reported\n', ''));
      const stance = planAction(model, { kind: 'edit-node', id: 'new-spyro-pg', field: 'stance', value: 'supposing' }, CTX);
      expect(stance.label).toBe('Set stance: supposing (The new Spyro game is PG)');
      expect(after(stance, 'Model/Spyro/Main.lean')).toBe(SPYRO_TEXTS.main.replace('rationale: known from gaming news\nsource: reported', 'rationale: known from gaming news\nstance: supposing\nsource: reported'));
      expect(refusal(() => planAction(model, { kind: 'edit-node', id: 'new-spyro-pg', field: 'naturalName', value: null }, CTX)).code).toBe('invalid');
      expect(refusal(() => planAction(model, { kind: 'edit-node', id: 'new-spyro-pg', field: 'stance', value: 'certain' }, CTX)).code).toBe('invalid');
      expect(refusal(() => planAction(model, { kind: 'edit-node', id: 'nope', field: 'rationale', value: 'x' }, CTX)).code).toBe('not-found');
    });
  });

  describe('AT2.6 set-premises and create-subject', () => {
    it('set-premises replaces premises:', () => {
      const plan = planAction(spyro(), { kind: 'set-premises', target: 'cynder-not-good', premises: ['cynder-dark-past', 'new-spyro-pg'] }, CTX);
      expect(plan).toMatchObject({ action: 'set-premises', label: 'These suffice: Cynder would not be a good addition to the new Spyro game ← 2 premises', nodes: ['cynder-not-good', 'cynder-dark-past', 'new-spyro-pg'] });
      expect(after(plan, 'Model/Spyro/Main.lean')).toBe(SPYRO_TEXTS.main.replace('premises: cynder-dark-past, new-spyro-pg, pg-no-dark-past', 'premises: cynder-dark-past, new-spyro-pg'));
    });

    it('create-subject writes the scaffold and imports the subject root after the last import of Model.lean', () => {
      const plan = planAction(spyro(), { kind: 'create-subject', name: 'Zelda' }, CTX);
      expect(plan).toMatchObject({ action: 'create-subject', label: 'New subject: Zelda', subject: 'Zelda', nodes: [], layout: { subject: 'Zelda', layout: emptyLayout() } });
      expect(plan.changes.map((c) => [c.path, c.before === null])).toEqual([
        ['Model.lean', false],
        ['Model/Zelda.lean', true],
        ['Model/Zelda/Inbox.lean', true],
        ['Model/Zelda/Main.lean', true],
        ['Model/Zelda/Vocabulary.lean', true],
      ]);
      expect(after(plan, 'Model.lean')).toBe('import Model.Spyro.Main\nimport Model.Zelda\n');
      expect(after(plan, 'Model/Zelda.lean')).toBe('import Model.Zelda.Vocabulary\nimport Model.Zelda.Inbox\nimport Model.Zelda.Main\n');
      expect(refusal(() => planAction(spyro(), { kind: 'create-subject', name: 'Spyro' }, CTX)).code).toBe('invalid');
      expect(refusal(() => planAction(spyro(), { kind: 'create-subject', name: 'zelda' }, CTX)).code).toBe('invalid');
    });
  });

  describe('AT2.7 delete-node', () => {
    it('removes the block, its statement and .holds, and the id from other premises', () => {
      const plan = planAction(spyro(), { kind: 'delete-node', id: 'cynder-dark-past', keepLean: false }, { ...CTX, layouts: { Spyro: emptyLayout() } });
      expect(plan).toMatchObject({ action: 'delete-node', label: 'Delete: Cynder is a character who has a dark past', nodes: ['cynder-dark-past', 'cynder-not-good'] });
      expect(plan.archive).toBeUndefined();
      const lines = SPYRO_TEXTS.main.split('\n');
      const expected = [...lines.slice(0, 13), ...lines.slice(27)].join('\n').replace('premises: cynder-dark-past, new-spyro-pg, pg-no-dark-past', 'premises: new-spyro-pg, pg-no-dark-past');
      expect(after(plan, 'Model/Spyro/Main.lean')).toBe(expected);
      expect(plan.layout).toEqual({ subject: 'Spyro', layout: emptyLayout() });
    });

    it('archives a theorem .holds; keepLean leaves the declarations', () => {
      const plan = planAction(proved(), { kind: 'delete-node', id: 'cynder-not-good', keepLean: false }, CTX);
      expect(plan.archive).toEqual([
        {
          subject: 'Spyro',
          nodeId: 'cynder-not-good',
          declName: 'Spyro.cynder_not_good.holds',
          text: 'theorem cynder_not_good.holds : cynder_not_good :=\n  pg_no_dark_past.holds newSpyro cynder new_spyro_pg.holds cynder_dark_past.holds',
          reason: 'deleted',
        },
      ]);
      const keep = planAction(spyro(), { kind: 'delete-node', id: 'new-spyro-pg', keepLean: true }, CTX);
      const text = after(keep, 'Model/Spyro/Main.lean') ?? '';
      expect(text).toContain('abbrev new_spyro_pg : Prop := IsPG newSpyro\naxiom new_spyro_pg.holds : new_spyro_pg');
      expect(text).not.toContain('id: new-spyro-pg');
      expect(text).toContain('premises: cynder-dark-past, pg-no-dark-past');
    });
  });

  describe('AT2.8 change-kind', () => {
    it('G->A adds the axiom and the rationale; the card moves to the Assumptions column', () => {
      const plan = planAction(spyro(), { kind: 'change-kind', id: 'cynder-not-good', to: 'ASSUMPTION', beforeId: null, rationale: 'it follows from lore' }, CTX);
      expect(plan.label).toBe('Make Assumption: Cynder would not be a good addition to the new Spyro game');
      expect(after(plan, 'Model/Spyro/Main.lean')).toBe(
        SPYRO_TEXTS.main
          .replace(
            'type: GOAL\nnatural_name: Cynder would not be a good addition to the new Spyro game\n',
            'type: ASSUMPTION\nnatural_name: Cynder would not be a good addition to the new Spyro game\nrationale: it follows from lore\n',
          )
          .replace('abbrev cynder_not_good : Prop := ¬ GoodAddition cynder newSpyro\n', 'abbrev cynder_not_good : Prop := ¬ GoodAddition cynder newSpyro\naxiom cynder_not_good.holds : cynder_not_good\n'),
      );
      expect(plan.layout?.layout.columns).toEqual({ ASSUMPTION: ['pg-no-dark-past', 'cynder-dark-past', 'new-spyro-pg', 'cynder-not-good'], DERIVATION: [], GOAL: [] });
    });

    it('G->A on a proved goal turns the theorem into the axiom and archives the proof', () => {
      const plan = planAction(proved(), { kind: 'change-kind', id: 'cynder-not-good', to: 'ASSUMPTION', beforeId: 'pg-no-dark-past' }, CTX);
      expect(after(plan, 'Model/Spyro/Main.lean')).toBe(
        SPYRO_TEXTS.provedMain
          .replace('type: GOAL', 'type: ASSUMPTION')
          .replace('theorem cynder_not_good.holds : cynder_not_good :=\n  pg_no_dark_past.holds newSpyro cynder new_spyro_pg.holds cynder_dark_past.holds', 'axiom cynder_not_good.holds : cynder_not_good'),
      );
      expect(plan.archive).toMatchObject([{ declName: 'Spyro.cynder_not_good.holds', reason: 'Goal -> Assumption', nodeId: 'cynder-not-good' }]);
      expect(plan.layout?.layout.columns.ASSUMPTION).toEqual(['cynder-not-good', 'pg-no-dark-past', 'cynder-dark-past', 'new-spyro-pg']);
    });

    it('A->G with rewrite: the dependent takes the hypothesis as its first binder and the result is conditional after re-parse', () => {
      const plan = planAction(proved(), { kind: 'change-kind', id: 'cynder-dark-past', to: 'GOAL', beforeId: null, dependents: 'rewrite' }, CTX);
      expect(plan.label).toBe('Make Goal: Cynder is a character who has a dark past (dependents rewritten)');
      const text = after(plan, 'Model/Spyro/Main.lean') ?? '';
      expect(text).toBe(
        SPYRO_TEXTS.provedMain
          .replace('id: cynder-dark-past\ntype: ASSUMPTION', 'id: cynder-dark-past\ntype: GOAL')
          .replace('axiom cynder_dark_past.holds : cynder_dark_past\n', '')
          .replace(
            'theorem cynder_not_good.holds : cynder_not_good :=\n  pg_no_dark_past.holds newSpyro cynder new_spyro_pg.holds cynder_dark_past.holds',
            'theorem cynder_not_good.holds (h_cynder_dark_past : cynder_dark_past) : cynder_not_good :=\n  pg_no_dark_past.holds newSpyro cynder new_spyro_pg.holds h_cynder_dark_past',
          ),
      );
      // Re-parse the result and let (stand-in) Lean check it: the goal is now conditional on cynder-dark-past.
      const files = [parse('Model.lean', SPYRO_TEXTS.root), parse('Model/Spyro/Main.lean', text), parse('Model/Spyro/Vocabulary.lean', SPYRO_TEXTS.vocabulary)];
      const model = buildProjectModel({ files, fileHashes: freshHashes(files), facts: fakeFacts(files), library: 'Model' });
      expect(model.nodes.get('cynder-not-good')?.node.status.proof).toMatchObject({ kind: 'conditional', on: ['cynder-dark-past'] });
      expect(model.nodes.get('cynder-dark-past')?.node.type).toBe('GOAL');
    });

    it('A->G with mark-broken removes the axiom and keeps the dependent as is', () => {
      const plan = planAction(proved(), { kind: 'change-kind', id: 'cynder-dark-past', to: 'GOAL', beforeId: null, dependents: 'mark-broken' }, CTX);
      expect(plan.label).toBe('Make Goal: Cynder is a character who has a dark past (dependents marked broken)');
      expect(after(plan, 'Model/Spyro/Main.lean')).toBe(SPYRO_TEXTS.provedMain.replace('id: cynder-dark-past\ntype: ASSUMPTION', 'id: cynder-dark-past\ntype: GOAL').replace('axiom cynder_dark_past.holds : cynder_dark_past\n', ''));
    });

    it('A->D keeps the axiom (pending promotion): only type: changes', () => {
      const plan = planAction(spyro(), { kind: 'change-kind', id: 'new-spyro-pg', to: 'DERIVATION', beforeId: null }, CTX);
      expect(plan.changes).toEqual([{ path: 'Model/Spyro/Main.lean', before: SPYRO_TEXTS.main, after: SPYRO_TEXTS.main.replace('id: new-spyro-pg\ntype: ASSUMPTION', 'id: new-spyro-pg\ntype: DERIVATION') }]);
      expect(plan.label).toBe('Make Derivation: The new Spyro game is PG');
    });
  });
}

