390	  };
391	  for (const message of input.facts?.build.messages ?? []) {
392	    const severity = SEVERITY_OF_LEAN[message.severity] ?? 'info';
393	    const where = message.file ? containing(message.file, message.range) : {};
394	    diagnostics.push({
