413	    const binding = block.binding.mode;
414	    const at = { file: draft.file.path, range: block.range, nodeId: draft.id };
415	    if (draft.type === 'ASSUMPTION' && block.fields.rationale === undefined) {
416	      draft.flags.add('no-rationale');
417	      draft.diagnostics.push({ code: 'TL011', severity: 'info', message: 'No rationale yet: why do you hold it?', ...at });
418	    }
