import { SPYRO_LEAN, spyroGraph, spyroProvedGraph, type TlNode } from '@telelean/core';
import { describe, expect, it } from 'vitest';
import {
  cardChips,
  codeSegments,
  deleteDependents,
  dependsOn,
  displayName,
  footprintEntries,
  presuppositionLabel,
  presuppositionsOf,
  usedBy,
  usesInline,
  vocabIndex,
  type RelationContext,
} from '../../src/model/cardData';
import { makeNode, mentionGraph, statusGallery } from '../shared/graphs';

const graph = spyroGraph();
const proved = spyroProvedGraph();
const vocab = vocabIndex(graph.vocabulary);
const node = (id: string, g = graph) => g.nodes.find((n) => n.id === id) as TlNode;
const byId = (g = graph) => Object.fromEntries(g.nodes.map((n) => [n.id, n]));
const ctx = (g = graph): RelationContext => {
  const order = { ASSUMPTION: [] as string[], DERIVATION: [] as string[], GOAL: [] as string[] };
  for (const n of g.nodes) order[n.type].push(n.id);
  return { edges: g.edges, nodes: byId(g), order };
};

describe('uses line (request 2)', () => {
  it('prints the first two short names, then ", …" when there are more (from lean.uses, not hard-coded)', () => {
    expect(usesInline(node('cynder-not-good').lean.uses ?? [], 'Spyro', vocab)).toBe('GoodAddition, cynder, …');
    expect(usesInline(node('cynder-dark-past').lean.uses ?? [], 'Spyro', vocab)).toBe('HasDarkPast, cynder');
    expect(usesInline(['Spyro.IsPG'], 'Spyro', vocab)).toBe('IsPG');
  });

  it('keeps names from another subject fully qualified', () => {
    expect(displayName('Bayonetta.Witch', 'Spyro', vocab)).toBe('Bayonetta.Witch');
    expect(usesInline(['Bayonetta.Witch', 'Spyro.cynder', 'Spyro.IsPG'], 'Spyro', vocab)).toBe('Bayonetta.Witch, cynder, …');
  });
});

describe('presupposition chips (D-3b)', () => {
  it('reads the sort gloss: "assumes characters exist"', () => {
    expect(presuppositionLabel('Spyro.Character.exists', 'Spyro', vocab)).toBe('assumes characters exist');
    expect(presuppositionLabel('Spyro.Game.exists', 'Spyro', vocab)).toBe('assumes games exist');
  });

  it('falls back to "assumes there is a <shortName>" without a gloss', () => {
    const bare = vocabIndex(graph.vocabulary.map((item) => (item.name === 'Spyro.Character' ? { ...item, gloss: undefined } : item)));
    expect(presuppositionLabel('Spyro.Character.exists', 'Spyro', bare)).toBe('assumes there is a Character');
    expect(presuppositionLabel('Other.Thing.exists', 'Spyro', vocabIndex([]))).toBe('assumes there is a Other.Thing');
  });

  it('collects the presuppositions of a selection, first occurrence order', () => {
    expect(presuppositionsOf(['new-spyro-pg', 'cynder-not-good', 'pg-no-dark-past'], byId())).toEqual(['Spyro.Game.exists', 'Spyro.Character.exists']);
  });
});

describe('code segments (request 4)', () => {
  it('cuts the identifiers Lean resolved out of the code at their UTF-16 ranges', () => {
    const lines = codeSegments(SPYRO_LEAN.cynderDarkPast, node('cynder-dark-past').lean.refs);
    expect(lines).toHaveLength(3);
    const refs = lines.flatMap((line) => line.filter((s) => s.ref).map((s) => [s.text, s.ref?.name, s.ref?.nodeId ?? null]));
    expect(refs).toEqual([
      ['HasDarkPast', 'Spyro.HasDarkPast', null],
      ['cynder', 'Spyro.cynder', null],
      ['cynder_dark_past', 'Spyro.cynder_dark_past', 'cynder-dark-past'],
    ]);
    expect(lines.map((line) => line.map((s) => s.text).join(''))).toEqual(SPYRO_LEAN.cynderDarkPast.split('\n'));
  });

  it('maps every ref of the proved goal (statement and proof) to its identifier', () => {
    const goal = node('cynder-not-good', proved);
    const lines = codeSegments(goal.lean.code ?? '', goal.lean.refs);
    const texts = lines.flatMap((line) => line.filter((s) => s.ref).map((s) => s.text));
    expect(texts).toEqual(['GoodAddition', 'cynder', 'newSpyro', 'cynder_not_good', 'pg_no_dark_past.holds', 'newSpyro', 'cynder', 'new_spyro_pg.holds', 'cynder_dark_past.holds']);
  });

  it('ignores refs that span lines, overlap or fall outside their line, and handles CRLF', () => {
    const ref = (line: number, from: number, to: number, endLine = line) => ({ name: 'X', range: { start: { line, character: from }, end: { line: endLine, character: to } } });
    const lines = codeSegments('abc def\r\nghi', [ref(0, 0, 3), ref(0, 1, 5), ref(0, 4, 7, 1), ref(1, 9, 12), ref(1, 0, 3)]);
    expect(lines.map((l) => l.map((s) => [s.text, Boolean(s.ref)]))).toEqual([
      [
        ['abc', true],
        [' def', false],
      ],
      [['ghi', true]],
    ]);
    expect(codeSegments('', undefined)).toEqual([[{ text: '' }]]);
  });
});

describe('card chips (AT6.3 data)', () => {
  const gallery = statusGallery();
  const nodes = byId(gallery);
  const chips = (id: string) => cardChips(nodes[id] as TlNode, nodes);
  const labels = (id: string) => chips(id).map((c) => c.label);

  it('formalised nodes get the Lean chip; a code-less assumption gets "no Lean yet" and "no source yet" (stance rule)', () => {
    expect(labels('cynder-dark-past')).toEqual(['λ Lean', 'assumed']);
    expect(labels('pg-no-dark-past')).toEqual(['λ Lean', 'assumed']); // formalised in the proved graph
    expect(cardChips(node('pg-no-dark-past'), byId())).toMatchObject([{ key: 'lean', label: 'no Lean yet' }, { key: 'no-rationale', label: 'no source yet', action: 'edit-rationale' }]);
  });

  it('one chip per ProofStatus kind and M1 flag', () => {
    expect(chips('cynder-not-good')).toEqual([
      expect.objectContaining({ key: 'lean' }),
      expect.objectContaining({ key: 'proved-goal', label: '✓ proved: make Derivation?', action: 'make-derivation' }),
    ]);
    expect(labels('d-pending')).toContain('promotion pending');
    expect(labels('d-conditional')).toContain('conditional on Cynder is not PG material');
    expect(labels('g-sorry')).toEqual(['λ Lean', 'uses sorry']);
    expect(labels('a-missing')).toEqual(['λ Lean', 'missing .holds']);
    expect(labels('g-unchecked')).toEqual(['λ Lean', 'unproved', 'not checked by Lean']);
    expect(chips('a-stale')).toEqual([
      expect.objectContaining({ key: 'lean' }),
      expect.objectContaining({ key: 'proof', label: 'assumed', dim: true }),
      expect.objectContaining({ key: 'stale', label: 'checking…' }),
    ]);
    expect(labels('a-premised')).toContain('you think this follows from those: prove it?');
  });

  it('never shows a check mark for a node Lean has not checked', () => {
    const odd = makeNode('x', 'GOAL', 'odd', { proof: { kind: 'proved', footprint: [] }, flags: ['not-checked'] });
    expect(cardChips(odd, { x: odd }).map((c) => c.label).join(' ')).not.toContain('✓');
  });

  it('ill-formed nodes say so', () => {
    const bad = makeNode('x', 'ASSUMPTION', 'bad', { formal: 'ill-formed' });
    expect(cardChips(bad, { x: bad })[0]).toMatchObject({ key: 'lean', label: 'Lean problem', tone: 'error' });
  });
});

describe('relations (Depends on / Used by, AT6.21 data)', () => {
  it('the proved goal depends on the three assumptions (declared and used by the proof)', () => {
    expect(dependsOn('cynder-not-good', ctx(proved))).toEqual([
      { id: 'pg-no-dark-past', reasons: ['declared', 'proof'] },
      { id: 'cynder-dark-past', reasons: ['declared', 'proof'] },
      { id: 'new-spyro-pg', reasons: ['declared', 'proof'] },
    ]);
    expect(usedBy('cynder-dark-past', ctx(proved))).toEqual([{ id: 'cynder-not-good', reasons: ['declared', 'proof'] }]);
    expect(usedBy('cynder-not-good', ctx(proved))).toEqual([]);
    expect(dependsOn('cynder-dark-past', ctx(proved))).toEqual([]);
  });

  it('statement mentions come from lean-ref edges', () => {
    const g = mentionGraph();
    expect(dependsOn('cynder-not-good', ctx(g)).find((r) => r.id === 'cynder-dark-past')?.reasons).toEqual(['declared', 'statement']);
    expect(usedBy('cynder-dark-past', ctx(g))).toEqual([{ id: 'cynder-not-good', reasons: ['declared', 'statement'] }]);
  });

  it('the delete dialog lists declared premises, proofs and statement mentions', () => {
    expect(deleteDependents('cynder-dark-past', ctx(proved))).toEqual({ declaredBy: ['cynder-not-good'], proofs: ['cynder-not-good'], mentions: [] });
    expect(deleteDependents('cynder-dark-past', ctx(mentionGraph()))).toEqual({ declaredBy: ['cynder-not-good'], proofs: [], mentions: ['cynder-not-good'] });
    expect(deleteDependents('cynder-not-good', ctx(proved))).toEqual({ declaredBy: [], proofs: [], mentions: [] });
  });
});

describe('footprint entries', () => {
  it('maps node ids, presuppositions and unexpected axioms', () => {
    const goal = node('cynder-not-good', proved);
    const footprint = goal.status.proof.kind === 'proved' ? goal.status.proof.footprint : [];
    expect(footprintEntries([...footprint, 'axiom:Spyro.sneaky', 'elsewhere-node'], byId(proved), 'Spyro', vocab)).toEqual([
      { kind: 'node', id: 'cynder-dark-past' },
      { kind: 'node', id: 'new-spyro-pg' },
      { kind: 'node', id: 'pg-no-dark-past' },
      { kind: 'presupposition', name: 'Spyro.Character.exists', label: 'assumes characters exist' },
      { kind: 'presupposition', name: 'Spyro.Game.exists', label: 'assumes games exist' },
      { kind: 'axiom', name: 'Spyro.sneaky' },
      { kind: 'other', name: 'elsewhere-node' },
    ]);
  });
});

import { spyroGraph, spyroProvedGraph } from '@telelean/core';
import { describe, expect, it } from 'vitest';
import { markerVariant } from '../../src/board/EdgeEngine';
import { hasFocusEdges, toDisplayEdges } from '../../src/board/edges';
import { edgeKindsGraph } from '../shared/graphs';

describe('toDisplayEdges', () => {
  it('draws one arrow per pair: solid once verified, dashed while only declared', () => {
    expect(toDisplayEdges(spyroGraph().edges).map((e) => e.pattern)).toEqual(['declared', 'declared', 'declared']);
    const proved = toDisplayEdges(spyroProvedGraph().edges);
    expect(proved).toHaveLength(3);
    expect(proved.every((e) => e.pattern === 'verified' && e.declared && e.verified && !e.conditional && !e.mismatch)).toBe(true);
  });

  it('marks conditional and mismatch arrows (with tooltips) and draws lean-ref arrows only while an end has focus', () => {
    const edges = edgeKindsGraph().edges;
    expect(hasFocusEdges(edges)).toBe(true);
    const plain = toDisplayEdges(edges);
    const byId = Object.fromEntries(plain.map((e) => [e.id, e]));
    expect(byId['pg-no-dark-past->d-hyp']).toMatchObject({ pattern: 'verified', conditional: true, title: 'Taken as a hypothesis: the proof is conditional on it' });
    expect(byId['new-spyro-pg->d-hyp']).toMatchObject({ pattern: 'declared', mismatch: 'declared-unused' });
    expect(byId['new-spyro-pg->d-hyp']?.title).toMatch(/does not use it/);
    expect(byId['cynder-dark-past->d-hyp']).toMatchObject({ pattern: 'verified', mismatch: 'used-undeclared' });
    expect(plain.some((e) => e.pattern === 'reference')).toBe(false);

    const focused = toDisplayEdges(edges, new Set(['cynder-not-good']));
    expect(focused.find((e) => e.pattern === 'reference')).toMatchObject({ id: 'ref:d-hyp->cynder-not-good', source: 'd-hyp', target: 'cynder-not-good' });
    expect(toDisplayEdges(edges, new Set(['d-hyp'])).some((e) => e.pattern === 'reference')).toBe(true);
    expect(toDisplayEdges(edges, new Set(['new-spyro-pg'])).some((e) => e.pattern === 'reference')).toBe(false);
    expect(hasFocusEdges(spyroGraph().edges)).toBe(false);
  });

  it('a lean-ref arrow is not drawn over an existing arrow between the same cards', () => {
    const base = spyroGraph().edges;
    const edges = [...base, { id: 'lean-ref:cynder-dark-past->cynder-not-good', type: 'lean-ref' as const, source: 'cynder-dark-past', target: 'cynder-not-good', origin: 'lean' as const }];
    expect(toDisplayEdges(edges, new Set(['cynder-not-good']))).toHaveLength(3);
  });

  it('chooses arrowheads: conditional keeps its hollow head, focus wins otherwise', () => {
    const spec = { id: 'a->b', source: 'a', target: 'b' };
    expect(markerVariant({ ...spec, pattern: 'verified', conditional: true }, false)).toBe('conditional');
    expect(markerVariant({ ...spec, pattern: 'verified', conditional: true }, true)).toBe('conditional-focus');
    expect(markerVariant({ ...spec, pattern: 'declared', mismatch: 'declared-unused' }, false)).toBe('mismatch');
    expect(markerVariant({ ...spec, pattern: 'declared', mismatch: 'declared-unused' }, true)).toBe('focus');
    expect(markerVariant({ ...spec, pattern: 'reference' }, false)).toBe('reference');
  });
});

import type { SemanticSummary } from '@telelean/core';
import { describe, expect, it } from 'vitest';
import { semanticBadge, whyPlaceholder } from '../../src/labels';
import { formatBytes, formatTime, oneLine, pastedLine, shortcutFor } from '../../src/model/format';

describe('formatters', () => {
  it('formats history times: HH:MM today, "Mon D HH:MM" otherwise', () => {
    const now = new Date(2026, 10, 1, 15, 0);
    expect(formatTime(new Date(2026, 10, 1, 9, 5).toISOString(), now)).toBe('09:05');
    expect(formatTime(new Date(2026, 9, 31, 18, 5).toISOString(), now)).toBe('Oct 31 18:05');
    expect(formatTime(new Date(2025, 0, 2, 7, 0).toISOString(), now)).toBe('Jan 2 2025 07:00');
    expect(formatTime('not a time', now)).toBe('not a time');
  });

  it('formats storage sizes', () => {
    expect(formatBytes(0)).toBe('0 B');
    expect(formatBytes(512)).toBe('512 B');
    expect(formatBytes(1536)).toBe('1.5 KB');
    expect(formatBytes(12 * 1024)).toBe('12 KB');
    expect(formatBytes(30 * 1024)).toBe('30 KB');
    expect(formatBytes(3.4 * 1024 * 1024)).toBe('3.4 MB');
    expect(formatBytes(-1)).toBe('?');
  });

  it('keeps the user’s sentence verbatim on one line: trims, turns line breaks into spaces, nothing else', () => {
    expect(oneLine('  Cynder   is\r\nwild \n')).toBe('Cynder   is wild');
    expect(pastedLine('a\nb\r\nc\rd')).toBe('a b c d');
  });

  it('maps Ctrl/Cmd+Z to undo and Ctrl/Cmd+Shift+Z or Ctrl+Y to redo', () => {
    const key = (k: string, mods: Partial<{ ctrlKey: boolean; metaKey: boolean; shiftKey: boolean; altKey: boolean }> = {}) => ({
      key: k,
      ctrlKey: false,
      metaKey: false,
      shiftKey: false,
      altKey: false,
      ...mods,
    });
    expect(shortcutFor(key('z', { ctrlKey: true }))).toBe('undo');
    expect(shortcutFor(key('Z', { ctrlKey: true, shiftKey: true }))).toBe('redo');
    expect(shortcutFor(key('z', { metaKey: true }))).toBe('undo');
    expect(shortcutFor(key('y', { ctrlKey: true }))).toBe('redo');
    expect(shortcutFor(key('z'))).toBeNull();
    expect(shortcutFor(key('z', { ctrlKey: true, altKey: true }))).toBeNull();
  });
});

describe('labels', () => {
  it('the why placeholder follows the stance and kind (D-14)', () => {
    expect(whyPlaceholder('ASSUMPTION', undefined)).toBe('Why do you believe it?');
    expect(whyPlaceholder('ASSUMPTION', 'believe')).toBe('Why do you believe it?');
    expect(whyPlaceholder('ASSUMPTION', 'rule')).toBe('Where does the rule come from?');
    expect(whyPlaceholder('ASSUMPTION', 'supposing')).toBe('What are you exploring?');
    expect(whyPlaceholder('DERIVATION', 'rule')).toBe('Why do you think it follows?');
    expect(whyPlaceholder('GOAL', undefined)).toBe('Why do you care?');
  });

  it('the Lean badge has a text for every SemanticSummary state', () => {
    const states: Array<[SemanticSummary, string]> = [
      [{ state: 'unavailable' }, 'Lean: not checked yet'],
      [{ state: 'checking' }, 'Lean: checking…'],
      [{ state: 'fresh' }, 'Lean: up to date'],
      [{ state: 'stale', staleFiles: ['Model/Spyro/Main.lean'] }, 'Lean: files changed'],
      [{ state: 'failed', errorCount: 2 }, 'Lean: 2 errors'],
      [{ state: 'failed', detail: 'timeout' }, 'Lean: check failed'],
      [{ state: 'paused-low-memory', detail: '1.2 GB available' }, 'Lean paused: low memory'],
      [{ state: 'unsupported-toolchain', toolchain: 'leanprover/lean4:v4.20.0' }, 'Lean: syntactic mode'],
      [{ state: 'disabled', detail: 'sandbox unavailable: bwrap missing' }, 'Lean: off'],
    ];
    for (const [summary, text] of states) expect(semanticBadge(summary).text).toBe(text);
    expect(semanticBadge({ state: 'disabled', detail: 'sandbox unavailable' }).title).toContain('sandbox unavailable');
  });
});

import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { contributedColors, vscodeColorVariable } from '../shared/vscode-theme';

// Declarations only: a name mentioned in a comment must not satisfy the checks.
const css = readFileSync(new URL('../../src/styles/board.css', import.meta.url), 'utf8').replace(/\/\*[\s\S]*?\*\//g, '');
const colors = contributedColors();
const escapeRe = (text: string) => text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

/** The colours of the M0 board. */
const M0_COLOURS = ['telelean.formalizedAura', 'telelean.kindAssumption', 'telelean.kindDerivation', 'telelean.kindGoal'];
/**
 * The colours M1 adds (docs/m1-plan.md 13.1 #19: the extension contributes them; WP5 owns the manifest). The board
 * reads them with fallbacks, so it also works with a manifest that does not contribute them yet.
 */
const M1_COLOURS = ['telelean.vocabulary', 'telelean.highlight'];

describe('contributed theme colours (packages/extension/package.json) and board.css', () => {
  it('the extension contributes the four M0 board colours, and nothing the board does not know', () => {
    const ids = colors.map((c) => c.id);
    expect(ids).toEqual(expect.arrayContaining(M0_COLOURS));
    for (const id of ids) expect([...M0_COLOURS, ...M1_COLOURS]).toContain(id);
  });

  it.each(colors.map((c) => [c.id, c] as const))(
    '%s has exactly one dot, and board.css reads it under the name VS Code gives it, with a fallback',
    (id, color) => {
      // One dot: VS Code replaces only the first dot, so any further dot would stay in the variable name.
      expect(id.split('.')).toHaveLength(2);
      expect(css).toMatch(new RegExp(`var\\(${escapeRe(vscodeColorVariable(id))}, \\S`));
      // A default that is one theme token in every theme (M0 style) is also the harness fallback; explicit
      // per-theme defaults (M1 style: no charts.* tokens) need no particular fallback.
      const defaults = new Set(Object.values(color.defaults));
      const token = color.defaults.dark;
      if (defaults.size === 1 && /^[A-Za-z][\w.]*$/.test(token)) {
        expect(css).toContain(`var(${vscodeColorVariable(id)}, var(${vscodeColorVariable(token)}`);
      }
    },
  );

  it('board.css reads the M1 colours (vocabulary, highlight) with theme-token fallbacks', () => {
    for (const id of M1_COLOURS) expect(css).toMatch(new RegExp(`var\\(${escapeRe(vscodeColorVariable(id))}, var\\(--vscode-[\\w-]+, `));
  });

  it('board.css reads no telelean colour variable that is neither contributed nor an M1 colour', () => {
    const known = new Set([...colors.map((c) => c.id), ...M1_COLOURS].map(vscodeColorVariable));
    const used = new Set(css.match(/--vscode-telelean[\w.\\-]*/g) ?? []);
    expect(used.size).toBeGreaterThan(0);
    for (const name of used) expect(known, name).toContain(name);
  });
});

