describe('AT1.1 lexLean: the research lexing cases (gen_lex_tests.py)', () => {
  for (const c of CASES) {
    it(`${c.name}: comment kinds, spans and code tokens`, () => {
      const lex = lexLean(c.text);
      expect(comments(lex)).toEqual(c.comments);
      expect(tokens(lex)).toEqual(c.tokens);
      // Spans are UTF-16 offsets into the text; comments and tokens are disjoint and sorted.
      const spans = [...lex.comments.map((x) => x.span), ...lex.tokens.map((x) => x.span)].sort((a, b) => a.start - b.start);
      for (let i = 1; i < spans.length; i++) expect(spans[i]?.start).toBeGreaterThanOrEqual(spans[i - 1]?.end ?? 0);
      for (const t of lex.tokens) expect(c.text.slice(t.span.start, t.span.end)).toBe(t.text);
    });
  }

  it('comment bodies: after `/-`, `/--` or `/-!`, up to the closer (or EOF)', () => {
    const bodies = (text: string) => lexLean(text).comments.map((x) => text.slice(x.body.start, x.body.end));
    expect(bodies('/- outer /- inner -/ still comment -/\n')).toEqual([' outer /- inner -/ still comment ']);
    expect(bodies('/--- three dashes -/')).toEqual(['- three dashes ']);
    expect(bodies('/-! module doc -/')).toEqual([' module doc ']);
    expect(bodies('-- note\r\nx')).toEqual([' note']);
    expect(bodies('def p := 1\n/- @@ telelean v1\nid: q\n')).toEqual([' @@ telelean v1\nid: q\n']);
  });

  it('token kinds: identifiers, strings, chars, numbers, symbols', () => {
    const kinds = (text: string) => lexLean(text).tokens.map((t) => `${t.kind}:${t.text}`);
    expect(kinds('def k := "𝓝"')).toEqual(['ident:def', 'ident:k', 'symbol::', 'symbol:=', 'string:"𝓝"']);
    expect(kinds("x 'a' '\\n' '\\x41' '\\u03B1' '𝓝'")).toEqual(['ident:x', "char:'a'", "char:'\\n'", "char:'\\x41'", "char:'\\u03B1'", "char:'𝓝'"]);
    expect(kinds('0x1F 0b101 0o17 1_000 1.5e-3 2e10')).toEqual(['number:0x1F', 'number:0b101', 'number:0o17', 'number:1_000', 'number:1.5e-3', 'number:2e10']);
    expect(kinds('h.1.2 [1..5]')).toEqual(['ident:h', 'symbol:.', 'number:1', 'symbol:.', 'number:2', 'symbol:[', 'number:1', 'symbol:.', 'symbol:.', 'number:5', 'symbol:]']);
  });
});

describe('lexLean: strings, chars, raw strings and «» hide comment markers', () => {
  it('a `/-` inside a string, char, raw string or «name» is not a comment', () => {
    const text = 'def s := "/- not a comment"\ndef c := \'"\'\ndef r := r#"-/ and /-"#\ndef «weird/-name» := 1\ndef h\' := 2\n';
    const lex = lexLean(text);
    expect(lex.comments).toEqual([]);
    expect(tokens(lex)).toEqual(['def', 's', ':', '=', '"/- not a comment"', 'def', 'c', ':', '=', '\'"\'', 'def', 'r', ':', '=', 'r#"-/ and /-"#', 'def', '«weird/-name»', ':', '=', '1', 'def', "h'", ':', '=', '2']);
  });

  it("an escaped quote `'\\''` is one char literal; `''` starts none", () => {
    expect(tokens(lexLean("x := '\\'' -- c"))).toEqual(['x', ':', '=', "'\\''"]);
    expect(lexLean("x := '\\'' -- c").comments.map((c) => c.kind)).toEqual(['line']);
    expect(tokens(lexLean("''a"))).toEqual(["'", "'", 'a']);
  });

  it('raw strings end at a quote followed by the same number of #', () => {
    expect(tokens(lexLean('r"a\\" b r##"x"# "#y"## z'))).toEqual(['r"a\\"', 'b', 'r##"x"# "#y"##', 'z']);
    expect(tokens(lexLean('r x'))).toEqual(['r', 'x']);
  });

  it('strings escape with backslash, may span lines, and run to EOF when unterminated', () => {
    expect(tokens(lexLean('"a\\"/-b" c'))).toEqual(['"a\\"/-b"', 'c']);
    expect(tokens(lexLean('"line1\n/- line2" d'))).toEqual(['"line1\n/- line2"', 'd']);
    expect(tokens(lexLean('x "never closed /- -/'))).toEqual(['x', '"never closed /- -/']);
  });

  it('interpolated strings: a quote inside {…} does not end them', () => {
    const lex = lexLean('def x := s!"a {f "/-" "}"} b" -- end');
    expect(tokens(lex)).toEqual(['def', 'x', ':', '=', 's!', 's!"a {f "/-" "}"} b"'.slice(2)]);
    expect(lex.comments.map((c) => c.kind)).toEqual(['line']);
    // Not after other identifiers ending in `!`, nor a qualified one.
    expect(tokens(lexLean('foo!"{" x'))).toEqual(['foo!', '"{"', 'x']);
  });

  it('identifiers: dotted, «escaped» parts, Unicode letter-like and subscripts; other characters are symbols', () => {
    expect(tokens(lexLean('Foo.«a b».c x₁ α.β 𝓝x λ'))).toEqual(['Foo.«a b».c', 'x₁', 'α.β', '𝓝x', 'λ']);
    expect(tokens(lexLean('a.b. c'))).toEqual(['a.b', '.', 'c']);
    expect(tokens(lexLean('«open x'))).toEqual(['«', 'open', 'x']);
    expect(tokens(lexLean('😀 ∀'))).toEqual(['😀', '∀']);
  });

  it('`--` and `/-` start comments right after a token; a line comment ends before CRLF', () => {
    const lex = lexLean('a--b\r\nc/-d-/e');
    expect(tokens(lex)).toEqual(['a', 'c', 'e']);
    expect(comments(lex)).toEqual([
      ['line', 1, 4],
      ['block', 7, 12],
    ]);
  });
});

describe('lexLean: where the nesting scan starts (checked with Lean 4.35)', () => {
  // Lean's `whitespace` skips the character after `/-`, and the doc tokens `/--`, `/-!` are three characters long,
  // so for every kind the scan for `/-` and `-/` starts at the fourth character. Verified with
  // ~/.elan/toolchains/leanprover--lean4---v4.35.0/bin/lean on 2026-11-01:
  //   `/-/-/` + `def a` + `#print a`        -> prints `def a` (one complete comment)
  //   `/-/- inner -/ still open? -/`         -> error at 1:14 "unexpected identifier" (closed at the first `-/`)
  //   `/--/ doc -/` + `def b` + `#print b`   -> prints `def b` (a valid docstring)
  //   `/--/-/` + `def e`                     -> error "unterminated comment"
  it('`/-/-/` is one complete comment', () => {
    expect(comments(lexLean('/-/-/\ndef a : Nat := 1\n'))).toEqual([['block', 0, 5]]);
  });
  it('`/-/- inner -/` closes at the first `-/`', () => {
    const text = '/-/- inner -/ still open? -/\n';
    expect(comments(lexLean(text))).toEqual([['block', 0, 13]]);
    expect(tokens(lexLean(text))).toEqual(['still', 'open?', '-', '/']);
  });
  it('`/--/ doc -/` is a docstring', () => {
    const lex = lexLean('/--/ doc -/\ndef b : Nat := 1\n');
    expect(comments(lex)).toEqual([['doc', 0, 11]]);
    expect(tokens(lex).slice(0, 2)).toEqual(['def', 'b']);
  });
  it('`/--/-/` is unterminated', () => {
    const text = '/--/-/\ndef e : Nat := 1\n';
    expect(comments(lexLean(text))).toEqual([['doc', 0, text.length, 'unterminated']]);
  });
});

/**
 * AT1.2 — the non-graph tests of the research prototype
 * (verbatim_prompt_log/bundle_1/subagent_reports/research_workflow/artifacts/r4-markup-lsp/proto/test_telelean_ref.py:
 * Lexing 5, Values 7, Binding 6) ported to `parseLeanFile`, under the 02/03 rule changes: `type:` is canonical and
 * `kind:` a silent alias (no TL018), there is no DEFINITION kind, a missing version marker means v1 (no TL016), and
 * `premises:` is allowed on any type (no TL012). The two Graph tests (duplicates, cycles, purity) belong to WP2.
 */
import { describe, expect, it } from 'vitest';
import { parseLeanFile, type ParsedFile } from '../../src/index.js';

/** The research helper: a block with `kind:` (the alias), a quoted sentence and a rationale. */
const B = (id: string, kind = 'ASSUMPTION', extra = '') => `/-\n@@ telelean v1\nid: ${id}\nkind: ${kind}\nnatural_name: "n ${id}"\nrationale: r\n${extra}-/\n`;

const parse = (text: string): ParsedFile => parseLeanFile('X.lean', text);
const codes = (file: ParsedFile) => file.diagnostics.map((d) => d.code);
const declOf = (file: ParsedFile, blockIndex: number) => {
  const index = file.blocks[blockIndex]?.binding.adjacentDecl;
  return index === undefined ? undefined : file.decls[index];
};

describe('AT1.2 research tests: Lexing', () => {
  it('comment markers inside strings, chars, raw strings and guillemets are ignored', () => {
    const src = 'def s := "/- not a comment"\ndef c := \'"\'\ndef r := r#"-/ and /-"#\n' + 'def «weird/-name» := 1\ndef h\' := 2\n' + B('a') + 'axiom a : True\n';
    const file = parse(src);
    expect(file.blocks.map((b) => b.id)).toEqual(['a']);
    expect(file.blocks[0]?.binding.statement).toBe('a');
  });

  it('nested comment and line comment', () => {
    const file = parse('/- outer /- inner -/ still -/\n-- /- line comment\n' + B('b') + 'axiom b : True\n');
    expect(file.blocks[0]?.binding.mode).toBe('adjacent');
  });

  it('unterminated block is reported (TL010)', () => {
    const file = parse('/-\n@@ telelean v1\nid: u\nkind: GOAL\nnatural_name: "x /- y"\n-/\n');
    expect(codes(file)).toContain('TL010');
  });

  it('CRLF', () => {
    const file = parse(B('c').replaceAll('\n', '\r\n') + 'axiom c : True\r\n');
    expect(file.eol).toBe('\r\n');
    expect(file.blocks[0]?.fields.type).toBe('ASSUMPTION');
    expect(file.blocks[0]?.fields.naturalName).toBe('n c');
    expect(file.blocks[0]?.binding.statement).toBe('c');
  });

  it('a block in a docstring is flagged (TL009), not parsed', () => {
    const file = parse('/--\n@@ telelean v1\nid: d\n-/\ndef d := 1\n');
    expect(file.blocks).toEqual([]);
    expect(codes(file)).toContain('TL009');
  });
});

describe('AT1.2 research tests: Values', () => {
  it('JSON string escapes for comment delimiters', () => {
    const file = parse('/-\n@@ telelean v1\nid: e\nkind: GOAL\nnatural_name: "A -\\/ B and C \\u002f- D"\n-/\n');
    expect(file.blocks[0]?.fields.naturalName).toBe('A -/ B and C /- D');
  });

  it('raw text values with colons, hashes and NO', () => {
    const file = parse('/-\n@@ telelean v1\nid: f\nkind: ASSUMPTION\nnatural_name: Cynder: the #1 dragon\n' + 'rationale: NO\n-/\n');
    expect(file.blocks[0]?.fields.naturalName).toBe('Cynder: the #1 dragon');
    expect(file.blocks[0]?.fields.rationale).toBe('NO');
  });

  it('lists: brackets and repetition', () => {
    const file = parse('/-\n@@ telelean v1\nid: g\nkind: GOAL\nnatural_name: x\npremises: [a, b]\n' + 'tags: t1, t2\ntags: t3\n-/\n');
    expect(file.blocks[0]?.fields.premises).toEqual(['a', 'b']);
    expect(file.blocks[0]?.fields.tags).toEqual(['t1', 't2', 't3']);
  });

  it('the body is dedented and its Markdown escapes are kept', () => {
    const file = parse('/-\n@@ telelean v1\nid: h\nkind: GOAL\nnatural_name: x\n---\n  Para one\n' + '  uses -\\/ escape\n-/\n');
    expect(file.blocks[0]?.body).toBe('Para one\nuses -\\/ escape');
  });

  it('alias, lower case, unknown field, extension, missing version (02/03: no TL016, no TL018)', () => {
    const file = parse('/-\n@@ telelean\nid: i\ntype: goal\nnatural_name: x\nfoo: 1\nmytool.prio: 3\n-/\n');
    const found = codes(file);
    expect(file.blocks[0]?.fields.type).toBe('GOAL');
    expect(file.blocks[0]?.version).toBe(1);
    expect(file.blocks[0]?.extensions).toEqual({ foo: ['1'], 'mytool.prio': ['3'] });
    expect(found).toContain('TL002');
    expect(found).toContain('TL019');
    expect(found).not.toContain('TL016');
    expect(found).not.toContain('TL018');
    // `kind:` is a silent alias of `type:`, normalised in the field lines.
    const aliased = parse('/-\n@@ telelean\nid: i\nkind: goal\nnatural_name: x\n-/\n');
    expect(aliased.blocks[0]?.fields.type).toBe('GOAL');
    expect(aliased.blocks[0]?.lines.find((l) => l.writtenKey === 'kind')?.key).toBe('type');
    expect(codes(aliased)).toEqual(['TL019']);
  });

  it('a newer version is a warning (TL008), not a failure', () => {
    const file = parse('/-\n@@ telelean v2\nid: j\nkind: GOAL\nnatural_name: x\nnewfield: y\n-/\n');
    expect(file.blocks[0]?.version).toBe(2);
    expect(file.blocks[0]?.fields.naturalName).toBe('x');
    expect(codes(file)).toContain('TL008');
  });

  it('missing required fields and bad values (TL003, TL004; no DEFINITION kind)', () => {
    const file = parse('/-\n@@ telelean v1\nid: Bad_ID\nkind: AXIOM\n-/\n');
    const found = codes(file);
    expect(found.filter((c) => c === 'TL004').length).toBeGreaterThanOrEqual(2);
    expect(found).toContain('TL003');
    expect(codes(parse('/-\n@@ telelean v1\nid: k\ntype: DEFINITION\nnatural_name: x\n-/\n'))).toContain('TL004');
  });

  it('premises are allowed on every type (no TL012)', () => {
