/**
 * WP3 (refreshLeanFacts) is implemented. Probed with an unreachable memory threshold on a missing root, so a real
 * implementation answers `low-memory` (or refuses the arguments) without spawning anything.
 */
export async function semanticImplemented(): Promise<boolean> {
  try {
    await refreshLeanFacts({ root: path.join(SCRATCH, 'no-such-root'), minAvailableBytes: Number.MAX_SAFE_INTEGER, readMemAvailable: () => 0 });
    return true;
  } catch (error) {
    return !(error instanceof NotImplementedError);
  }
}

/** Waits (up to `timeoutMs`) until MemAvailable is at least `bytes`; false when it never is (RAM rule: skip then). */
export async function waitForMemory(bytes = 12 * 1024 ** 3, timeoutMs = 120_000): Promise<boolean> {
  const deadline = Date.now() + timeoutMs;
  for (;;) {
    const available = readMemAvailableBytes();
    if (available === undefined || available >= bytes) return true;
    if (Date.now() > deadline) return false;
    await sleep(2_000);
  }
}

