/** Before a write: the scope's current state as "Initial state" (no chain yet) or "Manual edits" (hand edits since the tip). */
private async snapshotBase(scope: SnapshotScope): Promise<void> {
  const subject = scopeSubjectName(scope);
  let tip: string | undefined;
  try {
    tip = await this.history.tip(scope);
  } catch (error) {
    this.setHistoryError(`reading the history failed: ${errorMessage(error)}`);
    return;
  }
  await this.snapshotScope(
    scope,
    tip === undefined ? { label: 'Initial state', action: 'initial', subject, nodes: [] } : { label: 'Manual edits', action: 'manual', subject, nodes: [] },
  );
}

